schemas/tools/bgm_montage_lite.schema.js:
{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "$id": "openmontage/tools/bgm_montage_lite",
  "title": "BGM Montage Lite",
  "description": "Create a reference-free, full-song beat montage from one audio file and supplied video clips.",
  "type": "object",
  "required": ["audio_path", "video_paths"],
  "properties": {
    "audio_path": {"type": "string", "minLength": 1},
    "video_paths": {
      "type": "array",
      "items": {"type": "string", "minLength": 1},
      "minItems": 1,
      "maxItems": 100
    },
    "aspect_ratio": {
      "type": "string",
      "enum": ["auto", "16:9", "9:16", "4:3", "3:4", "1:1", "4:5"],
      "default": "auto"
    },
    "project_dir": {
      "type": "string",
      "description": "Optional OpenMontage project root; defaults output to its renders folder."
    },
    "output_path": {
      "type": "string",
      "description": "Optional MP4 destination; defaults beside the music file or under project_dir/renders."
    }
  }
}

schemas/tools/video_stitch.schema.json:
{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "$id": "openmontage/tools/video_stitch",
  "title": "Video Stitch Tool",
  "description": "Multi-clip assembly tool with validation, transitions, and spatial layouts.",
  "type": "object",
  "required": ["operation"],
  "properties": {
    "operation": {
      "type": "string",
      "enum": ["validate", "stitch", "preview_stitch", "spatial"],
      "description": "The operation to perform"
    },
    "clips": {
      "type": "array",
      "items": { "type": "string" },
      "minItems": 1,
      "description": "List of input video file paths"
    },
    "output_path": {
      "type": "string",
      "description": "Path for the output video file"
    },
    "transition": {
      "type": "string",
      "enum": ["cut", "crossfade", "fade"],
      "default": "cut",
      "description": "Transition type between clips. 'cut' = hard cut (concat demuxer), 'crossfade' = blend between clips, 'fade' = fade through black"
    },
    "transition_duration": {
      "type": "number",
      "minimum": 0.1,
      "maximum": 5.0,
      "default": 0.5,
      "description": "Duration of the transition in seconds (ignored for 'cut')"
    },
    "auto_normalize": {
      "type": "boolean",
      "default": false,
      "description": "Re-encode clips to a common format before concatenation if they have mismatched properties"
    },
    "target_resolution": {
      "type": "string",
      "pattern": "^\\d+x\\d+$",
      "description": "Target resolution for normalization (e.g. '1920x1080'). Defaults to first clip's resolution."
    },
    "target_fps": {
      "type": "integer",
      "minimum": 1,
      "maximum": 120,
      "description": "Target frame rate for normalization. Defaults to first clip's FPS."
    },
    "codec": {
      "type": "string",
      "default": "libx264",
      "description": "Video codec for encoding"
    },
    "crf": {
      "type": "integer",
      "minimum": 0,
      "maximum": 51,
      "default": 23,
      "description": "Constant Rate Factor for quality (lower = better)"
    },
    "preset": {
      "type": "string",
      "enum": ["ultrafast", "superfast", "veryfast", "faster", "fast", "medium", "slow", "slower", "veryslow"],
      "default": "medium",
      "description": "FFmpeg encoding preset"
    },
    "profile": {
      "type": "string",
      "description": "Media profile name from media_profiles.py (e.g. 'youtube_landscape', 'tiktok')"
    },
    "layout": {
      "type": "string",
      "enum": ["side_by_side", "vertical_stack", "picture_in_picture"],
      "description": "Spatial layout for the 'spatial' operation"
    },
    "pip_position": {
      "type": "string",
      "enum": ["top_left", "top_right", "bottom_left", "bottom_right"],
      "default": "bottom_right",
      "description": "Corner position for picture-in-picture overlay"
    },
    "pip_scale": {
      "type": "number",
      "minimum": 0.1,
      "maximum": 0.5,
      "default": 0.3,
      "description": "Scale of PiP overlay relative to base video dimensions"
    },
    "pip_margin": {
      "type": "integer",
      "minimum": 0,
      "default": 10,
      "description": "Margin in pixels for PiP overlay from edges"
    },
    "dry_run": {
      "type": "boolean",
      "default": false,
      "description": "If true, return what would be done without executing"
    }
  },
  "allOf": [
    {
      "if": { "properties": { "operation": { "const": "stitch" } } },
      "then": { "required": ["clips"] }
    },
    {
      "if": { "properties": { "operation": { "const": "validate" } } },
      "then": { "required": ["clips"] }
    },
    {
      "if": { "properties": { "operation": { "const": "preview_stitch" } } },
      "then": { "required": ["clips"] }
    },
    {
      "if": { "properties": { "operation": { "const": "spatial" } } },
      "then": { "required": ["clips", "layout"] }
    }
  ],
  "additionalProperties": false
}

schemas/styles/playbook.schema.json:
{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "$id": "openmontage/styles/playbook",
  "title": "Style Playbook",
  "description": "Visual style definition controlling all aesthetic choices in a video pipeline. Schema v2 adds chart_palette, typography scale/weight systems, and color rules.",
  "type": "object",
  "required": ["identity", "visual_language", "typography", "motion", "audio", "asset_generation", "quality_rules"],
  "properties": {
    "identity": {
      "type": "object",
      "required": ["name", "category", "mood", "pace"],
      "properties": {
        "name": { "type": "string" },
        "category": {
          "type": "string",
          "enum": ["motion-graphics", "whiteboard", "cinematic", "minimalist", "retro", "custom"]
        },
        "mood": { "type": "string" },
        "pace": {
          "type": "string",
          "enum": ["slow", "deliberate", "moderate", "fast", "rapid"]
        },
        "best_for": { "type": "string" }
      },
      "additionalProperties": false
    },
    "visual_language": {
      "type": "object",
      "required": ["color_palette", "composition", "texture"],
      "properties": {
        "color_palette": {
          "type": "object",
          "required": ["primary", "accent", "background", "text"],
          "properties": {
            "primary": { "type": "array", "items": { "type": "string" } },
            "accent": { "type": "array", "items": { "type": "string" } },
            "background": { "type": "string" },
            "text": { "type": "string" },
            "muted": { "type": "string" }
          },
          "additionalProperties": false
        },
        "composition": { "type": "string" },
        "texture": { "type": "string" }
      },
      "additionalProperties": false
    },
    "typography": {
      "type": "object",
      "required": ["headings", "body"],
      "properties": {
        "headings": { "$ref": "#/$defs/font_spec" },
        "body": { "$ref": "#/$defs/font_spec" },
        "code": { "$ref": "#/$defs/font_spec" },
        "stat_card": { "$ref": "#/$defs/font_spec" },
        "scale_system": {
          "description": "Modular type scale ratio. Named ratio or custom number.",
          "oneOf": [
            {
              "type": "string",
              "enum": ["minor_second", "major_second", "minor_third", "major_third", "perfect_fourth", "golden"]
            },
            {
              "type": "number",
              "exclusiveMinimum": 1.0
            }
          ]
        },
        "weight_matrix": {
          "description": "Font weight mapping for each typographic role.",
          "type": "object",
          "properties": {
            "title": { "type": "integer", "minimum": 100, "maximum": 900 },
            "heading": { "type": "integer", "minimum": 100, "maximum": 900 },
            "body": { "type": "integer", "minimum": 100, "maximum": 900 },
            "caption": { "type": "integer", "minimum": 100, "maximum": 900 }
          },
          "additionalProperties": false
        }
      },
      "additionalProperties": false
    },
    "motion": {
      "type": "object",
      "required": ["transitions", "animation_style", "pacing_rules"],
      "properties": {
        "transitions": {
          "type": "array",
          "items": { "type": "string" },
          "minItems": 1
        },
        "animation_style": { "type": "string" },
        "pacing_rules": {
          "type": "object",
          "properties": {
            "min_scene_hold_seconds": { "type": "number", "minimum": 0.5 },
            "max_scene_hold_seconds": { "type": "number", "minimum": 1 },
            "text_card_hold_seconds": { "type": "number", "minimum": 1 },
            "stat_card_hold_seconds": { "type": "number", "minimum": 1 },
            "transition_duration_seconds": { "type": "number", "minimum": 0.1 }
          },
          "additionalProperties": false
        },
        "entrance": { "type": "string" },
        "exit": { "type": "string" }
      },
      "additionalProperties": false
    },
    "audio": {
      "type": "object",
      "required": ["voice_style", "music_mood", "music_volume"],
      "properties": {
        "voice_style": { "type": "string" },
        "music_mood": { "type": "string" },
        "music_volume": { "type": "number", "minimum": 0, "maximum": 1 },
        "sfx_style": { "type": "string" },
        "ducking_threshold_db": { "type": "number" },
        "voice_variation_allowed": {
          "type": "boolean",
          "default": false,
          "description": "Whether voice characteristics can shift between sections for emphasis"
        },
        "hero_moment_voice_shift": {
          "type": "string",
          "description": "How the voice should change for hero moments, e.g., 'slower, more deliberate, drop pitch'"
        },
        "transition_voice_shift": {
          "type": "string",
          "description": "How the voice should change at transitions, e.g., 'brief pause, then resume at slightly higher energy'"
        }
      }
    },
    "asset_generation": {
      "type": "object",
      "required": ["image_prompt_prefix", "consistency_anchors"],
      "properties": {
        "image_prompt_prefix": { "type": "string" },
        "image_negative_prompt": { "type": "string" },
        "diagram_style": { "type": "string" },
        "consistency_anchors": {
          "type": "array",
          "items": { "type": "string" },
          "minItems": 1
        },
        "scene_type": {
          "type": "string",
          "description": "Default Remotion cut.type this style composes scenes as, e.g. 'anime_scene'. See remotion-composer/SCENE_TYPES.md."
        },
        "multi_image_per_scene": {
          "type": "boolean",
          "description": "Whether a scene is built from several stills that crossfade (the anime_scene grammar) rather than a single image."
        },
        "images_per_scene": {
          "type": "integer",
          "minimum": 1,
          "description": "How many stills to generate per scene when multi_image_per_scene is set."
        },
        "image_variation_guidance": {
          "type": "string",
          "description": "How the per-scene stills should differ from each other so the crossfade reads as motion."
        },
        "default_particles": {
          "type": "string",
          "description": "Default particle overlay for scenes in this style (maps to the renderer's particles prop)."
        },
        "default_particle_color": {
          "type": "string",
          "description": "Default particle color (maps to the renderer's particleColor prop)."
        },
        "default_vignette": {
          "type": "boolean",
          "description": "Whether scenes in this style get a vignette by default (maps to the renderer's vignette prop)."
        }
      },
      "additionalProperties": false
    },
    "overlays": {
      "description": "Per-overlay styling. Covers the in-scene overlay boxes plus the timed overlay types the Explainer composition renders (see remotion-composer/src/Explainer.tsx, `Overlay.type`).",
      "type": "object",
      "properties": {
        "stat_card": { "$ref": "#/$defs/overlay_style" },
        "key_term": { "$ref": "#/$defs/overlay_style" },
        "code_block": { "$ref": "#/$defs/overlay_style" },
        "section_title": { "$ref": "#/$defs/overlay_style" },
        "stat_reveal": { "$ref": "#/$defs/overlay_style" },
        "hero_title": { "$ref": "#/$defs/overlay_style" },
        "provider_chip": { "$ref": "#/$defs/overlay_style" }
      },
      "additionalProperties": false
    },
    "quality_rules": {
      "type": "array",
      "items": { "type": "string" },
      "minItems": 1
    },
    "taste_profile": { "$ref": "#/$defs/taste_profile" },
    "chart_palette": {
      "description": "Ordered array of hex colors for chart data series.",
      "type": "array",
      "items": {
        "type": "string",
        "pattern": "^#[0-9A-Fa-f]{6}$"
      },
      "minItems": 2
    },
    "color_rules": {
      "description": "Design intelligence rules for automated palette validation.",
      "type": "object",
      "properties": {
        "harmony_type": {
          "type": "string",
          "enum": ["complementary", "analogous", "triadic", "split-complementary"]
        },
        "contrast_validation": {
          "description": "Enable WCAG 2.1 contrast ratio checking on all text/bg pairs.",
          "type": "boolean"
        },
        "colorblind_safe": {
          "description": "Enable color-blind safety checking for palettes.",
          "type": "boolean"
        }
      }
    },
    "overrides": {
      "description": "Per-scene palette or rule exceptions. Up to 20% of scenes may intentionally deviate from the playbook for creative impact.",
      "type": "object",
      "properties": {
        "max_deviation_ratio": {
          "type": "number",
          "minimum": 0,
          "maximum": 0.5,
          "default": 0.2,
          "description": "Maximum fraction of scenes that may deviate from playbook defaults"
        },
        "scene_overrides": {
          "type": "array",
          "items": {
            "type": "object",
            "required": ["scene_id", "reason"],
            "properties": {
              "scene_id": { "type": "string" },
              "reason": { "type": "string", "description": "Why this scene deviates from the playbook" },
              "color_override": { "type": "object" },
              "typography_override": { "type": "object" },
              "motion_override": { "type": "object" }
            }
          }
        }
      }
    }
  },
  "$defs": {
    "font_spec": {
      "type": "object",
      "required": ["font"],
      "properties": {
        "font": { "type": "string" },
        "weight": { "type": "integer" },
        "tracking": { "type": "string" },
        "line_height": { "type": "number" },
        "size_multiplier": { "type": "number" }
      },
      "additionalProperties": false
    },
    "overlay_style": {
      "type": "object",
      "properties": {
        "bg": { "type": "string" },
        "border": { "type": "string" },
        "text": { "type": "string" },
        "radius": { "type": "number" },
        "shadow": { "type": "string" },
        "highlight": { "type": "string" },
        "accent": {
          "type": "string",
          "description": "Accent color for overlay types that render one (maps to the renderer's accentColor prop)."
        }
      },
      "additionalProperties": false
    },
    "taste_profile": {
      "type": "object",
      "required": ["design_read", "visual_variance", "motion_intensity", "information_density"],
      "properties": {
        "design_read": {
          "type": "string",
          "description": "Brief-specific read of what the video should feel like and why."
        },
        "visual_variance": {
          "type": "integer",
          "minimum": 1,
          "maximum": 10,
          "description": "How much scenes may vary visually while still feeling coherent."
        },
        "motion_intensity": {
          "type": "integer",
          "minimum": 1,
          "maximum": 10,
          "description": "How energetic the motion language should be."
        },
        "information_density": {
          "type": "integer",
          "minimum": 1,
          "maximum": 10,
          "description": "How much information can be on screen at once."
        },
        "palette_discipline": { "type": "string" },
        "layout_variation": { "type": "string" },
        "reference_strategy": { "type": "string" },
        "anti_patterns": {
          "type": "array",
          "items": { "type": "string" }
        },
        "quality_gates": {
          "type": "array",
          "items": { "type": "string" }
        }
      },
      "additionalProperties": false
    }
  }
}

schemas/pipelines/pipeline_manifest.sche:
{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "$id": "openmontage/pipelines/pipeline_manifest",
  "title": "Pipeline Manifest",
  "description": "Declarative pipeline definition specifying stages, artifacts, tools, and policies.",
  "type": "object",
  "required": ["name", "version", "stages"],
  "properties": {
    "name": { "type": "string" },
    "version": { "type": "string" },
    "description": { "type": "string" },
    "category": {
      "type": "string",
      "enum": ["talking_head", "generated", "hybrid", "screen_recording", "animation", "cinematic", "documentary", "custom"]
    },
    "stability": {
      "type": "string",
      "enum": ["production", "beta"],
      "description": "Whether this pipeline has been audited and is considered stable"
    },
    "compatible_playbooks": {
      "oneOf": [
        {
          "type": "array",
          "items": { "type": "string" }
        },
        {
          "type": "object",
          "properties": {
            "recommended": { "type": "array", "items": { "type": "string" } },
            "also_works": { "type": "array", "items": { "type": "string" } },
            "custom_allowed": { "type": "boolean", "default": false }
          }
        }
      ]
    },
    "required_skills": {
      "type": "array",
      "items": { "type": "string" }
    },
    "production_modes": {
      "type": "array",
      "description": "Mutually exclusive ways this pipeline can be produced. The agent picks one at the idea stage and records it in the brief; the stage director skill reads it to constrain later choices (see skills/pipelines/screen-demo/idea-director.md).",
      "items": {
        "type": "object",
        "required": ["name"],
        "properties": {
          "name": { "type": "string" },
          "description": { "type": "string" },
          "required_tools": {
            "type": "array",
            "items": { "type": "string" },
            "description": "Tools that must be available for this mode to be viable"
          },
          "optional_tools": {
            "type": "array",
            "items": { "type": "string" }
          },
          "scene_type": {
            "type": "string",
            "description": "Remotion cut.type this mode composes, when it synthesizes rather than captures"
          },
          "agent_skills": {
            "type": "array",
            "items": { "type": "string" },
            "description": "Layer 3 skills to read before producing in this mode"
          },
          "best_for": {
            "type": "array",
            "items": { "type": "string" }
          }
        },
        "additionalProperties": false
      }
    },
    "stages": {
      "type": "array",
      "items": {
        "type": "object",
        "required": ["name"],
        "properties": {
          "name": { "type": "string" },
          "agent": { "type": "string", "description": "Legacy: class name for Python-driven stages" },
          "skill": { "type": "string", "description": "Skill path for instruction-driven stages (e.g., pipelines/explainer/idea-director)" },
          "required_artifacts_in": {
            "type": "array",
            "items": { "type": "string" },
            "description": "Artifact names that must exist before this stage runs"
          },
          "optional_artifacts_in": {
            "type": "array",
            "items": { "type": "string" }
          },
          "produces": {
            "type": "array",
            "items": { "type": "string" },
            "description": "Artifact names this stage produces"
          },
          "preferred_tools": {
            "type": "array",
            "items": { "type": "string" },
            "description": "Legacy: preferred tools for Python handlers"
          },
          "fallback_tools": {
            "type": "array",
            "items": { "type": "string" }
          },
          "required_tools": {
            "type": "array",
            "items": { "type": "string" },
            "description": "Tools that must be available (or their fallback) for this stage to succeed"
          },
          "optional_tools": {
            "type": "array",
            "items": { "type": "string" },
            "description": "Tools that enhance this stage but are not required"
          },
          "tools_available": {
            "type": "array",
            "items": { "type": "string" },
            "description": "All tools the agent can use in this stage (union of required + optional)"
          },
          "review_focus": {
            "type": "array",
            "items": { "type": "string" },
            "description": "What the reviewer checks after this stage"
          },
          "checkpoint_required": { "type": "boolean", "default": true },
          "human_approval_default": { "type": "boolean", "default": false },
          "success_criteria": {
            "type": "array",
            "items": { "type": "string" }
          },
          "sub_stages": {
            "type": "array",
            "description": "Optional sub-stages within a stage (e.g., sample preview for reference-driven productions)",
            "items": {
              "type": "object",
              "required": ["name"],
              "properties": {
                "name": { "type": "string" },
                "description": { "type": "string" },
                "condition": { "type": "string", "description": "When this sub-stage activates (e.g., video_analysis_brief_exists)" },
                "human_approval_default": { "type": "boolean", "default": true },
                "tools_available": { "type": "array", "items": { "type": "string" } },
                "review_focus": { "type": "array", "items": { "type": "string" } }
              }
            }
          }
        },
        "additionalProperties": false
      },
      "minItems": 1
    },
    "default_checkpoint_policy": {
      "type": "string",
      "enum": ["guided", "manual_all", "auto_noncreative"],
      "default": "guided"
    },
    "reference_input": {
      "type": "object",
      "description": "Configuration for reference video input support",
      "properties": {
        "supported": { "type": "boolean", "default": false },
        "analysis_depth": { "type": "string", "enum": ["transcript_only", "standard", "deep"], "default": "standard" },
        "analysis_tools": { "type": "array", "items": { "type": "string" } }
      }
    },
    "metadata": { "type": "object" },
    "orchestration": {
      "type": "object",
      "description": "Executive Producer orchestration config",
      "properties": {
        "mode": { "type": "string" },
        "skill": { "type": "string" },
        "budget_default_usd": { "type": "number" },
        "max_revisions_per_stage": { "type": "integer" },
        "max_send_backs": { "type": "integer" },
        "max_wall_time_minutes": { "type": "integer" }
      },
      "additionalProperties": false
    },
    "extensions": {
      "type": "object",
      "description": "Capability extension permissions for this pipeline",
      "properties": {
        "custom_scripts": { "type": "boolean", "default": true },
        "custom_playbooks": { "type": "boolean", "default": true },
        "custom_skills": { "type": "boolean", "default": true },
        "custom_tools": { "type": "boolean", "default": false }
      },
      "additionalProperties": false
    }
  },
  "additionalProperties": false
}

schemas/checkpoints/checkpoint.schema.js:
{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "$id": "openmontage/checkpoints/checkpoint",
  "title": "Pipeline Checkpoint",
  "description": "Full resumable snapshot after each pipeline stage.",
  "type": "object",
  "required": ["version", "project_id", "pipeline_type", "stage", "status", "timestamp", "artifacts"],
  "properties": {
    "version": { "type": "string", "const": "1.0" },
    "project_id": { "type": "string" },
    "stage": {
      "type": "string",
      "description": "Stage name — validated at runtime against the pipeline manifest's stage list"
    },
    "status": {
      "type": "string",
      "enum": ["completed", "failed", "awaiting_human", "in_progress"]
    },
    "timestamp": { "type": "string", "format": "date-time" },
    "pipeline_type": { "type": "string", "description": "Pipeline manifest name" },
