schemas/artifacts/decision_log.schema.js:
{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "$id": "openmontage/artifacts/decision_log",
  "title": "Decision Log",
  "description": "Audit trail of every meaningful choice made during production. Prevents hidden system behavior, enables reviewer inspection, and guards against context drift.",
  "type": "object",
  "required": ["version", "project_id", "decisions"],
  "properties": {
    "version": { "type": "string", "const": "1.0" },
    "project_id": { "type": "string" },
    "decisions": {
      "type": "array",
      "items": {
        "type": "object",
        "required": ["decision_id", "stage", "category", "subject", "options_considered", "selected", "reason"],
        "properties": {
          "decision_id": {
            "type": "string",
            "description": "Unique ID, e.g., d-001, d-002"
          },
          "stage": {
            "type": "string",
            "description": "Pipeline stage where this decision was made"
          },
          "category": {
            "type": "string",
            "enum": [
              "pipeline_selection",
              "provider_selection",
              "renderer_family_selection",
              "render_runtime_selection",
              "composition_mode",
              "playbook_selection",
              "fallback_decision",
              "budget_tradeoff",
              "downgrade_approval",
              "music_source",
              "motion_commitment",
              "concept_selection",
              "voice_selection",
              "capability_extension",
              "playbook_override",
              "visual_accuracy_check",
              "approval_policy"
            ],
            "description": "What class of decision this is"
          },
          "subject": {
            "type": "string",
            "description": "What is being decided, e.g., 'TTS provider for narration'"
          },
          "options_considered": {
            "type": "array",
            "items": {
              "type": "object",
              "required": ["option_id", "label", "score", "reason"],
              "properties": {
                "option_id": { "type": "string" },
                "label": { "type": "string", "description": "Human-readable name" },
                "score": {
                  "type": "number",
                  "minimum": 0,
                  "maximum": 1,
                  "description": "Normalized score 0-1 (1 is best)"
                },
                "reason": { "type": "string", "description": "Why this option scored this way" },
                "rejected_because": { "type": "string", "description": "If rejected, why" }
              },
              "additionalProperties": false
            },
            "minItems": 1,
            "description": "All options evaluated (including rejected ones)"
          },
          "selected": {
            "type": "string",
            "description": "option_id of the selected option"
          },
          "reason": {
            "type": "string",
            "description": "Why this option was selected over alternatives"
          },
          "user_visible": {
            "type": "boolean",
            "default": true,
            "description": "Whether this decision was surfaced to the user"
          },
          "user_approved": {
            "type": "boolean",
            "default": false,
            "description": "Whether the user explicitly approved this decision"
          },
          "confidence": {
            "type": "number",
            "minimum": 0,
            "maximum": 1,
            "description": "Agent's confidence in this decision (0 = uncertain, 1 = certain)"
          }
        },
        "additionalProperties": false
      }
    }
  },
  "additionalProperties": false
}

{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "$id": "openmontage/artifacts/edit_decisions",
  "title": "Edit Decisions",
  "description": "Editorial decisions produced by the Edit Agent.",
  "type": "object",
  "required": ["version", "cuts", "render_runtime"],
  "properties": {
    "version": { "type": "string", "const": "1.0" },
    "cuts": {
      "type": "array",
      "items": {
        "type": "object",
        "required": ["id", "source", "in_seconds", "out_seconds"],
        "properties": {
          "id": { "type": "string" },
          "source": { "type": "string", "description": "Source file path or asset-manifest ID" },
          "in_seconds": { "type": "number", "minimum": 0 },
          "out_seconds": { "type": "number", "minimum": 0 },
          "speed": { "type": "number", "minimum": 0.1, "default": 1.0 },
          "layer": {
            "type": "string",
            "enum": ["primary", "overlay", "background"],
            "default": "primary"
          },
          "transform": {
            "type": "object",
            "properties": {
              "scale": { "type": "number", "minimum": 0, "default": 1.0 },
              "position": { "type": "string", "default": "center" },
              "animation": {
                "type": "string",
                "description": "Motion applied to still images (e.g. ken-burns-slow-zoom, pan-left, static)"
              },
              "crop": {
                "type": "object",
                "properties": {
                  "x": { "type": "number" },
                  "y": { "type": "number" },
                  "width": { "type": "number" },
                  "height": { "type": "number" }
                }
              }
            },
            "additionalProperties": false
          },
          "transition_in": {
            "type": "string",
            "description": "Transition type entering this cut (e.g. fade, dissolve, cut, wipe)"
          },
          "transition_out": {
            "type": "string",
            "description": "Transition type leaving this cut"
          },
          "transition_duration": {
            "type": "number",
            "minimum": 0,
            "description": "Duration of transition in seconds"
          },
          "backgroundColor": {
            "type": "string",
            "description": "Backing color used behind this cut by composition runtimes"
          },
          "reason": { "type": "string" }
        },
        "additionalProperties": false
      }
    },
    "overlays": {
      "type": "array",
      "items": {
        "type": "object",
        "required": ["asset_id", "start_seconds", "end_seconds", "position"],
        "properties": {
          "asset_id": { "type": "string" },
          "start_seconds": { "type": "number", "minimum": 0 },
          "end_seconds": { "type": "number", "minimum": 0 },
          "position": {
            "type": "object",
            "properties": {
              "x": { "type": "number" },
              "y": { "type": "number" },
              "width": { "type": "number" },
              "height": { "type": "number" }
            },
            "required": ["x", "y"]
          },
          "animation": { "type": "string" },
          "opacity": { "type": "number", "minimum": 0, "maximum": 1 }
        },
        "additionalProperties": false
      }
    },
    "audio": {
      "type": "object",
      "description": "Audio configuration for narration, music, and SFX.",
      "properties": {
        "narration": {
          "type": "object",
          "properties": {
            "segments": {
              "type": "array",
              "items": {
                "type": "object",
                "required": ["asset_id", "start_seconds"],
                "properties": {
                  "asset_id": { "type": "string" },
                  "start_seconds": { "type": "number", "minimum": 0 },
                  "end_seconds": { "type": "number", "minimum": 0 }
                },
                "additionalProperties": false
              }
            }
          }
        },
        "music": {
          "type": "object",
          "properties": {
            "asset_id": { "type": "string" },
            "volume": { "type": "number", "minimum": 0, "maximum": 1 },
            "fade_in_seconds": { "type": "number", "minimum": 0 },
            "fade_out_seconds": { "type": "number", "minimum": 0 },
            "ducking": {
              "oneOf": [
                { "type": "boolean" },
                {
                  "type": "object",
                  "properties": {
                    "enabled": { "type": "boolean", "default": true },
                    "threshold_db": { "type": "number" },
                    "reduction_db": { "type": "number" },
                    "attack_ms": { "type": "number", "minimum": 0 },
                    "release_ms": { "type": "number", "minimum": 0 }
                  },
                  "additionalProperties": false
                }
              ]
            }
          }
        },
        "sfx": {
          "type": "array",
          "items": {
            "type": "object",
            "properties": {
              "asset_id": { "type": "string" },
              "start_seconds": { "type": "number", "minimum": 0 },
              "volume": { "type": "number", "minimum": 0, "maximum": 1, "default": 1.0 }
            },
            "additionalProperties": false
          }
        }
      },
      "additionalProperties": false
    },
    "subtitles": {
      "type": "object",
      "properties": {
        "enabled": { "type": "boolean" },
        "style": { "type": "string", "description": "Display style: sentence, word-by-word, karaoke" },
        "source": { "type": "string", "description": "Path to subtitle file or asset ID" },
        "font": { "type": "string" },
        "font_size": { "type": "integer" },
        "color": { "type": "string", "description": "Primary text color (hex or ASS format)" },
        "outline_color": { "type": "string" },
        "background": { "type": "string", "description": "Background color with optional alpha (e.g. #00000088)" },
        "position": { "type": "string", "enum": ["top-center", "bottom-center", "center"] },
        "max_words_per_line": { "type": "integer", "minimum": 1 },
        "caption_props": { "type": "object", "description": "Remotion CaptionOverlay props passed through as-is (captionProps)" }
      },
      "additionalProperties": false
    },
    "music": {
      "type": "object",
      "description": "Legacy top-level music config. Prefer audio.music for new pipelines.",
      "properties": {
        "asset_id": { "type": "string" },
        "volume": { "type": "number", "minimum": 0, "maximum": 1 },
        "ducking": { "type": "boolean", "default": true },
        "fade_in_seconds": { "type": "number", "minimum": 0 },
        "fade_out_seconds": { "type": "number", "minimum": 0 }
      }
    },
    "transitions": {
      "type": "array",
      "description": "Global transition list. Per-cut transitions in cuts[].transition_in/out are preferred.",
      "items": {
        "type": "object",
        "properties": {
          "type": { "type": "string" },
          "at_seconds": { "type": "number" },
          "duration_seconds": { "type": "number", "minimum": 0 }
        },
        "required": ["type", "at_seconds", "duration_seconds"]
      }
    },
    "renderer_family": {
      "type": "string",
      "enum": ["explainer-data", "explainer-teacher", "cinematic-trailer", "documentary-montage", "product-reveal", "screen-demo", "presenter", "animation-first"],
      "description": "Locked at proposal stage — creative grammar for this deliverable. Preserved from proposal_packet; edit MUST NOT change without a logged decision."
    },
    "render_runtime": {
      "type": "string",
      "enum": ["remotion", "hyperframes", "ffmpeg"],
      "description": "Locked at proposal stage — technical runtime that realizes renderer_family. Edit MUST carry this forward unchanged unless a logged render_runtime_selection decision overrides it."
    },
    "composition_mode": {
      "type": "string",
      "enum": ["templated", "atelier"],
      "description": "Locked at proposal — HOW the composition is built. Edit MUST carry forward unchanged. 'atelier' routes video_compose to _render_via_atelier (no cut-schema, no stock registry); requires `bespoke` block below."
    },
    "bespoke": {
      "type": "object",
      "description": "Required when composition_mode='atelier'. Contract for the hand-authored, project-local Remotion render. See tools/video/video_compose.py → _render_via_atelier docstring.",
      "required": ["entry", "composition_id", "art_direction"],
      "properties": {
        "entry": { "type": "string", "description": "Path to the project-local Remotion entry .tsx (typically projects/<slug>/index.tsx). If outside remotion-composer/, auto-staged via directory junction/symlink at render time." },
        "composition_id": { "type": "string", "description": "id registered in that entry's Root" },
        "art_direction": { "type": "string", "description": "Short commitment to a fresh visual language (or a path to art-direction.md). REQUIRED — enforced by _run_atelier_checks." },
        "props_path": { "type": "string", "description": "Absolute path to a props JSON (Remotion --props)" },
        "public_dir": { "type": "string", "description": "Per-project public dir (avoids copying the bloated shared remotion-composer/public/)" },
        "scale": { "type": "number", "minimum": 0.1, "maximum": 1.0 },
        "crf": { "type": "integer", "minimum": 0, "maximum": 51 },
        "concurrency": { "type": "integer", "minimum": 1 }
      }
    },
    "slideshow_risk_score": {
      "type": "object",
      "description": "Slideshow risk assessment from lib/slideshow_risk.py",
      "properties": {
        "average": { "type": "number" },
        "verdict": { "type": "string", "enum": ["strong", "acceptable", "revise", "fail"] }
      }
    },
    "end_tag": {
      "type": "object",
      "description": "End-tag timing for overlay mode, recorded by the edit stage and read by compose. Omitted in concat mode. See documentary-montage edit-director.md §8b.",
      "properties": {
        "offset_seconds": { "type": "number", "minimum": 0, "description": "Body time at which the end-tag overlay starts (body_duration - tag_duration)." },
        "notes": { "type": "string" }
      },
      "additionalProperties": false
    },
    "metadata": { "type": "object" }
  },
  "additionalProperties": false
}

schemas/artifacts/final_review.schema.js:
{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "$id": "openmontage/artifacts/final_review",
  "title": "Final Review",
  "description": "Structured self-review of the rendered output. The compose stage must produce this artifact to prove the agent inspected the actual rendered video before presenting it to the user. If status is 'revise' or 'fail', the agent must not present the video as complete.",
  "type": "object",
  "required": ["version", "output_path", "status", "checks"],
  "properties": {
    "version": { "type": "string", "const": "1.0" },
    "output_path": {
      "type": "string",
      "description": "Path to the rendered output file that was reviewed"
    },
    "status": {
      "type": "string",
      "enum": ["pass", "revise", "fail"],
      "description": "pass=ready to present, revise=fixable issues found, fail=critical problems"
    },
    "checks": {
      "type": "object",
      "required": [
        "technical_probe",
        "visual_spotcheck",
        "audio_spotcheck",
        "promise_preservation",
        "subtitle_check"
      ],
      "properties": {
        "technical_probe": {
          "type": "object",
          "description": "ffprobe validation of the output file",
          "properties": {
            "valid_container": { "type": "boolean" },
            "duration_seconds": { "type": "number" },
            "resolution": { "type": "string" },
            "fps": { "type": "number" },
            "has_audio": { "type": "boolean" },
            "codec": { "type": "string" },
            "file_size_bytes": { "type": "integer" },
            "issues": {
              "type": "array",
              "items": { "type": "string" }
            }
          }
        },
        "visual_spotcheck": {
          "type": "object",
          "description": "Sample frames inspected from opening, middle, climax, ending",
          "properties": {
            "frames_sampled": { "type": "integer", "minimum": 4 },
            "frame_paths": {
              "type": "array",
              "items": { "type": "string" }
            },
            "black_frames_detected": { "type": "boolean" },
            "broken_overlays": { "type": "boolean" },
            "missing_assets": { "type": "boolean" },
            "unreadable_text": { "type": "boolean" },
            "issues": {
              "type": "array",
              "items": { "type": "string" }
            }
          }
        },
        "audio_spotcheck": {
          "type": "object",
          "description": "Audio quality verification",
          "properties": {
            "narration_present": { "type": "boolean" },
            "music_present": { "type": "boolean" },
            "unexpected_silence": { "type": "boolean" },
            "clipping_detected": { "type": "boolean" },
            "mix_intelligible": { "type": "boolean" },
            "issues": {
              "type": "array",
              "items": { "type": "string" }
            }
          }
        },
        "promise_preservation": {
          "type": "object",
          "description": "Delivery promise and renderer governance checks",
          "properties": {
            "delivery_promise_honored": { "type": "boolean" },
            "renderer_family_used": { "type": "string", "description": "Creative grammar that actually ran" },
            "render_runtime_used": {
              "type": "string",
              "enum": ["remotion", "hyperframes", "ffmpeg"],
              "description": "Technical runtime that actually executed the render. Must match the runtime locked at proposal unless a logged decision overrode it."
            },
            "runtime_swap_detected": {
              "type": "boolean",
              "description": "True if the runtime that ran differs from the runtime locked in proposal_packet. An unapproved swap is a contract violation."
            },
            "runtime_swap_check": {
              "type": "string",
              "description": "Human-readable status of the runtime-swap check: 'ok — …', 'detected — …', or 'skipped — …'. When the check was skipped, the reviewer skill is responsible for cross-artifact comparison."
            },
            "motion_ratio_actual": { "type": "number" },
            "silent_downgrade_detected": { "type": "boolean" },
            "issues": {
              "type": "array",
              "items": { "type": "string" }
            }
          }
        },
        "subtitle_check": {
          "type": "object",
          "description": "Subtitle/caption verification against source script",
          "properties": {
            "subtitles_expected": { "type": "boolean" },
            "subtitles_present": { "type": "boolean" },
            "coverage_ratio": { "type": "number", "minimum": 0, "maximum": 1 },
            "timing_drift_detected": { "type": "boolean" },
            "issues": {
              "type": "array",
              "items": { "type": "string" }
            }
          }
        },
        "transcript_comparison": {
          "type": "object",
          "description": "Optional: transcribe the output and compare to source script",
          "properties": {
            "transcript_matches_script": { "type": ["boolean", "null"] },
            "word_accuracy": { "type": ["number", "null"], "minimum": 0, "maximum": 1 },
            "issues": {
              "type": "array",
              "items": { "type": "string" }
            }
          }
        },
        "atelier": {
          "type": "object",
          "description": "Atelier-only doctrine checks (populated when composition_mode='atelier'). Generated by tools/video/video_compose.py → _run_atelier_checks.",
          "properties": {
            "stock_reuse_detected": { "type": "boolean", "description": "TRUE if the bespoke project imports from the stock creative registry — fails the render." },
            "offending_imports": {
              "type": "array",
              "description": "Files + import paths that violated the doctrine.",
              "items": {
                "type": "object",
                "properties": {
                  "file": { "type": "string" },
                  "import": { "type": "string" }
                }
              }
            },
            "art_direction_declared": { "type": "boolean" },
            "art_direction": { "type": ["string", "null"] },
            "issues": { "type": "array", "items": { "type": "string" } }
          }
        }
      },
      "additionalProperties": false
    },
    "issues_found": {
      "type": "array",
      "items": { "type": "string" },
      "description": "All issues found across all checks, summarized for the user"
    },
    "recommended_action": {
      "type": "string",
      "enum": ["present_to_user", "re_render", "revise_edit", "revise_assets", "block", "re_author"],
      "description": "What the agent should do next based on the review findings"
    },
    "metadata": { "type": "object" }
  },
  "additionalProperties": false
}

schemas/artifacts/pose_library.schema.js:
