            "type": "array",
            "items": {
              "type": "object",
              "required": ["id", "kind", "layer"],
              "properties": {
                "id": { "type": "string" },
                "kind": { "type": "string" },
                "layer": { "type": "integer" },
                "asset_path": { "type": "string" },
                "parent": { "type": "string" }
              },
              "additionalProperties": false
            }
          },
