lib/env_loader.py:
"""Environment variable loader for OpenMontage.

Loads .env file and provides typed access to environment configuration.
"""

from __future__ import annotations

import os
from pathlib import Path
from typing import Optional

from dotenv import dotenv_values


def load_env(project_root: Optional[Path] = None) -> None:
    """Load .env file from project root."""
    if project_root is None:
        project_root = Path(__file__).resolve().parent.parent
    env_path = project_root / ".env"
    if env_path.exists():
        for key, value in dotenv_values(env_path).items():
            if key and value is not None and not os.environ.get(key, "").strip():
                os.environ[key] = value


def get_env(key: str, default: Optional[str] = None) -> Optional[str]:
    """Get an environment variable with optional default."""
    return os.environ.get(key, default)


def require_env(key: str) -> str:
    """Get a required environment variable. Raises if missing."""
    value = os.environ.get(key)
    if value is None:
        raise EnvironmentError(f"Required environment variable {key!r} is not set")
    return value

lib/pipeline_loader.py:
"""Pipeline manifest loader.

Loads and validates pipeline YAML manifests from pipeline_defs/.
"""

from __future__ import annotations

import json
from pathlib import Path
from typing import Any, Optional

import yaml
import jsonschema

PIPELINE_DEFS_DIR = Path(__file__).resolve().parent.parent / "pipeline_defs"
SCHEMA_PATH = (
    Path(__file__).resolve().parent.parent
    / "schemas"
    / "pipelines"
    / "pipeline_manifest.schema.json"
)


from functools import lru_cache


@lru_cache(maxsize=1)
def _load_manifest_schema() -> dict:
    with open(SCHEMA_PATH, encoding="utf-8") as f:
        return json.load(f)


@lru_cache(maxsize=64)
def _load_pipeline_cached(name: str, defs_dir_key: str) -> dict[str, Any]:
    """Cached manifest load. Treat the returned dict as READ-ONLY."""
    return load_pipeline(name, Path(defs_dir_key) if defs_dir_key else None)


def load_pipeline_readonly(name: str, defs_dir: Optional[Path] = None) -> dict[str, Any]:
    """Load a manifest through a cache. The result MUST NOT be mutated.

    Manifests are immutable within a run; hot paths (gate checks on every
    checkpoint write, board state derivation) should use this instead of
    re-parsing YAML + re-validating the schema each call.
    """
    return _load_pipeline_cached(name, str(defs_dir) if defs_dir else "")


def load_pipeline(name: str, defs_dir: Optional[Path] = None) -> dict[str, Any]:
    """Load and validate a pipeline manifest by name.

    Args:
        name: Pipeline name (without .yaml extension).
        defs_dir: Override directory for pipeline definitions.

    Returns:
        Validated pipeline manifest dict.
    """
    defs_dir = defs_dir or PIPELINE_DEFS_DIR
    path = defs_dir / f"{name}.yaml"
    if not path.exists():
        raise FileNotFoundError(f"Pipeline manifest not found: {path}")

    with open(path, encoding="utf-8") as f:
        manifest = yaml.safe_load(f)

    schema = _load_manifest_schema()
    jsonschema.validate(instance=manifest, schema=schema)

    return manifest


def list_pipelines(defs_dir: Optional[Path] = None) -> list[str]:
    """List all available pipeline manifest names."""
    defs_dir = defs_dir or PIPELINE_DEFS_DIR
    return [p.stem for p in defs_dir.glob("*.yaml")]


def _condition_is_active(condition: Optional[str], context: Optional[dict[str, Any]]) -> bool:
    """Evaluate a simple manifest condition against runtime context."""
    if not condition:
        return True
    if not context:
        return False
    return bool(context.get(condition))


def get_reference_input_config(manifest: dict) -> dict[str, Any]:
    """Return reference-input configuration, defaulting to disabled."""
    return manifest.get("reference_input", {}) or {}


def pipeline_supports_reference_input(manifest: dict) -> bool:
    """Whether the manifest declares support for reference-video input."""
    return bool(get_reference_input_config(manifest).get("supported", False))


def get_stage_sub_stages(
    manifest: dict,
    stage_name: str,
    *,
    context: Optional[dict[str, Any]] = None,
    include_inactive: bool = True,
) -> list[dict[str, Any]]:
    """Return sub-stage definitions for a stage.

    By default this returns all declared sub-stages so agents can inspect the
    full workflow shape. Pass ``include_inactive=False`` with context to filter
    to active sub-stages only.
    """
    for stage in manifest["stages"]:
        if stage["name"] != stage_name:
            continue
        sub_stages = list(stage.get("sub_stages", []))
        if include_inactive:
            return sub_stages
        return [
            sub_stage
            for sub_stage in sub_stages
            if _condition_is_active(sub_stage.get("condition"), context)
        ]
    return []


def get_stage_order(
    manifest: dict,
    *,
    include_sub_stages: bool = False,
    context: Optional[dict[str, Any]] = None,
) -> list[str]:
    """Extract the ordered list of stage names from a manifest.

    ``include_sub_stages=True`` exposes declarative sample/preview units to the
    agent without turning them into mandatory checkpoint stages. Sub-stages are
    emitted as ``<stage>.<sub_stage>``.
    """
    order: list[str] = []
    for stage in manifest["stages"]:
        order.append(stage["name"])
        if not include_sub_stages:
            continue
        for sub_stage in get_stage_sub_stages(
            manifest,
            stage["name"],
            context=context,
            include_inactive=context is None,
        ):
            order.append(f"{stage['name']}.{sub_stage['name']}")
    return order


def get_required_tools(manifest: dict) -> set[str]:
    """Collect tools across stages, sub-stages, and reference-input analysis."""
    tools: set[str] = set()
    for stage in manifest["stages"]:
        tools.update(stage.get("preferred_tools", []))
        tools.update(stage.get("fallback_tools", []))
        tools.update(stage.get("tools_available", []))
        for sub_stage in stage.get("sub_stages", []):
            tools.update(sub_stage.get("tools_available", []))
    tools.update(get_reference_input_config(manifest).get("analysis_tools", []))
    return tools


def get_stage_tools(manifest: dict, stage_name: str) -> set[str]:
    """Collect every tool a stage or one of its sub-stages declares."""
    tool_fields = (
        "required_tools",
        "optional_tools",
        "preferred_tools",
        "fallback_tools",
        "tools_available",
    )
    for stage in manifest["stages"]:
        if stage["name"] != stage_name:
            continue
        tools: set[str] = set()
        for field in tool_fields:
            tools.update(stage.get(field, []))
        for sub_stage in stage.get("sub_stages", []):
            for field in tool_fields:
                tools.update(sub_stage.get(field, []))
        return tools
    return set()


def get_stage_skill(manifest: dict, stage_name: str) -> Optional[str]:
    """Get the skill path for an instruction-driven stage."""
    for stage in manifest["stages"]:
        if stage["name"] == stage_name:
            return stage.get("skill")
    return None


def get_stage_human_approval_default(manifest: dict, stage_name: str) -> Optional[bool]:
    """Whether a stage gates on human approval. None if the stage isn't declared.

    This is the single lookup used by gate enforcement (lib/checkpoint.py)
    and the Backlot board — keep them reading the same field the same way.
    """
    for stage in manifest["stages"]:
        if stage["name"] == stage_name:
            return bool(stage.get("human_approval_default", False))
    return None


def get_stage_review_focus(manifest: dict, stage_name: str) -> list[str]:
    """Get the review focus items for a stage."""
    for stage in manifest["stages"]:
        if stage["name"] == stage_name:
            return stage.get("review_focus", [])
    return []


# ---------------------------------------------------------------------------
# Capability-Extension Enforcement
# ---------------------------------------------------------------------------

class ExtensionNotPermitted(PermissionError):
    """Raised when a capability extension is used but not permitted by the pipeline."""


def check_extension_permitted(
    manifest: dict,
    extension_type: str,
) -> None:
    """Enforce that a capability extension is permitted by the pipeline manifest.

    Args:
        manifest: Loaded pipeline manifest dict.
        extension_type: One of 'custom_scripts', 'custom_playbooks',
                        'custom_skills', 'custom_tools'.

    Raises:
        ExtensionNotPermitted: If the extension is not allowed.
    """
    valid_extensions = {"custom_scripts", "custom_playbooks", "custom_skills", "custom_tools"}
    if extension_type not in valid_extensions:
        raise ValueError(
            f"Unknown extension type {extension_type!r}. "
            f"Valid types: {sorted(valid_extensions)}"
        )

    extensions = manifest.get("extensions", {})
    if not extensions.get(extension_type, False):
        raise ExtensionNotPermitted(
            f"Pipeline {manifest.get('name', 'unknown')!r} does not permit "
            f"{extension_type}. Set extensions.{extension_type}: true in the "
            f"pipeline manifest to allow this."
        )


def get_permitted_extensions(manifest: dict) -> dict[str, bool]:
    """Return the extension permission flags for a pipeline."""
    defaults = {
        "custom_scripts": False,
        "custom_playbooks": False,
        "custom_skills": False,
        "custom_tools": False,
    }
    extensions = manifest.get("extensions", {})
    return {k: extensions.get(k, v) for k, v in defaults.items()}

lib/slideshow_risk.py:
"""Slideshow risk scorer.

Scores a video plan across 6 dimensions that reliably predict whether
the output will feel like a slideshow rather than directed video.

Each dimension is scored 0-5 (lower is better):
  - repetition: same layouts/backgrounds/scene grammar recurring
  - decorative_visuals: scenes decorate instead of communicate
  - weak_motion: motion exists but has no narrative purpose
  - weak_shot_intent: no explicit reason for framing or reveal rhythm
  - typography_overreliance: too much of the video is text-first
  - unsupported_cinematic_claims: cinematic label without structure

Verdict:
  < 2.0: strong
  < 3.0: acceptable
  < 4.0: revise
  >= 4.0: fail — should not proceed to compose
"""

from __future__ import annotations

from typing import Any


def score_slideshow_risk(
    scenes: list[dict[str, Any]],
    edit_decisions: dict[str, Any] | None = None,
    renderer_family: str | None = None,
    render_runtime: str | None = None,
) -> dict[str, Any]:
    """Score slideshow risk across 6 dimensions.

    Args:
        scenes: Scene list from scene_plan artifact.
        edit_decisions: Optional edit_decisions artifact for transition analysis.
        renderer_family: Optional renderer family for cinematic claim verification.
        render_runtime: Optional render runtime (remotion/hyperframes/ffmpeg).
            Passed through so dimension scoring can reason about runtime-specific
            indicators when it's useful. Scoring logic is currently
            runtime-neutral — a text-heavy HyperFrames composition is just as
            slideshow-y as a text-heavy Remotion one — but the parameter is
            part of the contract so callers record runtime alongside family.

    Returns:
        {
            "average": float,
            "verdict": str,
            "dimensions": {dimension_name: {"score": float, "reason": str}},
            "render_runtime": str | None,
        }
    """
    if not scenes:
        return {
            "average": 5.0,
            "verdict": "fail",
            "dimensions": {},
            "render_runtime": render_runtime,
        }

    dimensions = {
        "repetition": _score_repetition(scenes),
        "decorative_visuals": _score_decorative(scenes),
        "weak_motion": _score_weak_motion(scenes),
        "weak_shot_intent": _score_weak_intent(scenes),
        "typography_overreliance": _score_typography(scenes),
        "unsupported_cinematic_claims": _score_cinematic_claims(scenes, renderer_family),
    }

    scores = [d["score"] for d in dimensions.values()]
    average = sum(scores) / len(scores)

    if average < 2.0:
        verdict = "strong"
    elif average < 3.0:
        verdict = "acceptable"
    elif average < 4.0:
        verdict = "revise"
    else:
        verdict = "fail"

    return {
        "average": round(average, 2),
        "verdict": verdict,
        "dimensions": dimensions,
        "render_runtime": render_runtime,
    }


def _score_repetition(scenes: list[dict]) -> dict[str, Any]:
    """Score visual repetition across scenes."""
    if len(scenes) < 3:
        return {"score": 0.0, "reason": "Too few scenes to assess repetition"}

    # Check for repeated scene types
    from collections import Counter
    types = Counter(s.get("type", "unknown") for s in scenes)
    most_common_type, most_common_count = types.most_common(1)[0]
    type_ratio = most_common_count / len(scenes)

    # Check for repeated descriptions (crude similarity)
    descriptions = [s.get("description", "").lower()[:50] for s in scenes]
    unique_desc_ratio = len(set(descriptions)) / len(descriptions)

    # Check shot size repetition
    sizes = [s.get("shot_language", {}).get("shot_size", "none") for s in scenes]
    size_ratio = Counter(sizes).most_common(1)[0][1] / len(scenes)

    score = 0.0
    reasons = []

    if type_ratio > 0.7:
        score += 2.0
        reasons.append(f"Scene type '{most_common_type}' dominates at {type_ratio:.0%}")
    if unique_desc_ratio < 0.6:
        score += 1.5
        reasons.append(f"Only {unique_desc_ratio:.0%} unique descriptions")
    if size_ratio > 0.6:
        score += 1.5
        reasons.append(f"Same shot size in {size_ratio:.0%} of scenes")

    return {"score": min(5.0, score), "reason": "; ".join(reasons) or "Good variety"}


def _score_decorative(scenes: list[dict]) -> dict[str, Any]:
    """Score whether scenes are decorative vs communicative."""
    decorative_count = 0
    for scene in scenes:
        has_info_role = bool(scene.get("information_role"))
        has_narrative_role = bool(scene.get("narrative_role"))
        has_intent = bool(scene.get("shot_intent"))

        # A scene with no role or intent is likely decorative
        if not has_info_role and not has_narrative_role and not has_intent:
            decorative_count += 1

    ratio = decorative_count / len(scenes)
    score = min(5.0, ratio * 5.0)

    if ratio > 0.5:
        reason = f"{decorative_count}/{len(scenes)} scenes have no stated purpose (no information_role, narrative_role, or shot_intent)"
    elif ratio > 0.2:
        reason = f"{decorative_count}/{len(scenes)} scenes lack stated purpose"
    else:
        reason = "Most scenes have clear communicative purpose"

    return {"score": round(score, 1), "reason": reason}


def _score_weak_motion(scenes: list[dict]) -> dict[str, Any]:
    """Score whether camera movement is purposeful."""
    total_moving = 0
    purposeless_moving = 0

    for scene in scenes:
        sl = scene.get("shot_language", {})
        movement = sl.get("camera_movement", "static")
        if movement not in ("static", "unspecified", None):
            total_moving += 1
            # Movement without shot_intent suggests arbitrary motion
            if not scene.get("shot_intent"):
                purposeless_moving += 1

    if total_moving == 0:
        # No movement at all is fine for some styles, but scores moderate
        return {"score": 1.5, "reason": "No camera movement defined (may be intentional for static style)"}

    ratio = purposeless_moving / total_moving
    score = min(5.0, ratio * 4.0)

    if ratio > 0.5:
        reason = f"{purposeless_moving}/{total_moving} moving shots lack shot_intent"
    else:
        reason = "Camera movement appears purposeful"

    return {"score": round(score, 1), "reason": reason}


def _score_weak_intent(scenes: list[dict]) -> dict[str, Any]:
    """Score shot intent completeness."""
    with_intent = sum(1 for s in scenes if s.get("shot_intent"))
    ratio = with_intent / len(scenes)

    # Invert: more intent = lower score
    score = min(5.0, (1.0 - ratio) * 5.0)

    if ratio < 0.3:
        reason = f"Only {with_intent}/{len(scenes)} scenes have shot_intent — most shots lack purpose"
    elif ratio < 0.6:
        reason = f"{with_intent}/{len(scenes)} scenes have shot_intent"
    else:
        reason = "Strong shot intent coverage"

    return {"score": round(score, 1), "reason": reason}


def _score_typography(scenes: list[dict]) -> dict[str, Any]:
    """Score text-first overreliance."""
    text_scenes = sum(
        1 for s in scenes
        if s.get("type") in ("text_card", "stat_card", "kpi_grid")
    )
    ratio = text_scenes / len(scenes)

    if ratio > 0.6:
        score = 4.0
        reason = f"{text_scenes}/{len(scenes)} scenes are text/stat cards — video feels like animated slides"
    elif ratio > 0.4:
        score = 2.5
        reason = f"{text_scenes}/{len(scenes)} scenes are text-based — consider balancing with visual scenes"
    elif ratio > 0.2:
        score = 1.0
        reason = "Balanced text and visual content"
    else:
        score = 0.0
        reason = "Visual-first approach"

    return {"score": score, "reason": reason}


def _score_cinematic_claims(
    scenes: list[dict],
    renderer_family: str | None,
) -> dict[str, Any]:
    """Score whether cinematic claims are backed by cinematic structure."""
    is_cinematic = renderer_family and "cinematic" in renderer_family.lower()

    if not is_cinematic:
        return {"score": 0.0, "reason": "Not claiming cinematic treatment"}

    issues = []

    # Cinematic should have: varied shot sizes, intentional movement, hero moments
    hero_count = sum(1 for s in scenes if s.get("hero_moment"))
    if hero_count == 0:
        issues.append("Claims cinematic but has no hero_moment defined")

    # Same non-moving values as _score_weak_motion: "unspecified" and an explicit
    # null are not camera movement, so they must not back a cinematic claim.
    has_movement = sum(
        1 for s in scenes
        if s.get("shot_language", {}).get("camera_movement", "static")
        not in ("static", "unspecified", None)
    )
    if has_movement < len(scenes) * 0.3:
        issues.append(f"Claims cinematic but only {has_movement}/{len(scenes)} scenes have camera movement")

    has_lighting = sum(
        1 for s in scenes
        if s.get("shot_language", {}).get("lighting_key")
    )
    if has_lighting < len(scenes) * 0.3:
        issues.append(f"Claims cinematic but only {has_lighting}/{len(scenes)} scenes define lighting")

    score = min(5.0, len(issues) * 1.8)
    reason = "; ".join(issues) if issues else "Cinematic claims supported by structure"

    return {"score": round(score, 1), "reason": reason}

lib/source_media_review.py:
"""Source media review helper.

Standardizes inspection of user-supplied media files so pipelines stop
reinventing partial checks. Uses existing analysis tools (audio_probe,
frame_sampler, scene_detect, transcriber) to produce a normalized
source_media_review artifact.

The contract: if user-supplied media exists, source_media_review is
REQUIRED before the first planning stage that depends on creative
assumptions. Never claim a file was reviewed unless a real probe ran.
"""

from __future__ import annotations

import json
import logging
from pathlib import Path
from typing import Any, Optional

logger = logging.getLogger(__name__)


# Media type detection by extension
_VIDEO_EXTENSIONS = frozenset({".mp4", ".mov", ".webm", ".avi", ".mkv", ".m4v"})
_AUDIO_EXTENSIONS = frozenset({".mp3", ".wav", ".aac", ".flac", ".ogg", ".m4a", ".opus"})
_IMAGE_EXTENSIONS = frozenset({".jpg", ".jpeg", ".png", ".webp", ".bmp", ".tiff", ".svg"})


def detect_media_type(path: Path) -> Optional[str]:
    """Classify a file as video, audio, or image by extension."""
    ext = path.suffix.lower()
    if ext in _VIDEO_EXTENSIONS:
        return "video"
    if ext in _AUDIO_EXTENSIONS:
        return "audio"
    if ext in _IMAGE_EXTENSIONS:
        return "image"
    return None


def _probe_video(path: Path, tool_registry: Any) -> dict[str, Any]:
    """Probe a video file using audio_probe (ffprobe wrapper) and frame_sampler."""
    result: dict[str, Any] = {"technical_probe": {}, "representative_frames": [], "quality_risks": []}

    # Technical probe via audio_probe or ffprobe
    try:
        audio_probe = tool_registry.get("audio_probe")
        if audio_probe:
            probe_result = audio_probe.execute({"input_path": str(path)})
            if probe_result.success:
                result["technical_probe"] = probe_result.data
    except Exception as e:
        logger.warning("audio_probe failed for %s: %s", path, e)

    # audio_probe reports audio detail only, under a nested "audio" object, and
    # carries no resolution/fps/video-codec. The summary built in
    # review_source_media() reads flat "resolution"/"audio_codec"/"channels"
    # keys, so without this ffprobe pass every video is reported as
    # "unknown resolution, without audio". Merge rather than replace so the
    # richer audio_probe fields survive.
    if not result["technical_probe"].get("resolution"):
        try:
            import subprocess
            cmd = [
                "ffprobe", "-v", "quiet", "-print_format", "json",
                "-show_format", "-show_streams", str(path),
            ]
            proc = subprocess.run(cmd, capture_output=True, text=True, timeout=30)
            if proc.returncode == 0:
                probe_data = json.loads(proc.stdout)
                fmt = probe_data.get("format", {})
                streams = probe_data.get("streams", [])
                video_stream = next((s for s in streams if s.get("codec_type") == "video"), {})
                audio_stream = next((s for s in streams if s.get("codec_type") == "audio"), {})
                result["technical_probe"].update({
                    "duration_seconds": float(fmt.get("duration", 0)),
                    "resolution": f"{video_stream.get('width', '?')}x{video_stream.get('height', '?')}",
                    "fps": _parse_fps(video_stream.get("r_frame_rate", "0/1")),
                    "codec": video_stream.get("codec_name", "unknown"),
                    "audio_codec": audio_stream.get("codec_name", ""),
                    "sample_rate": int(audio_stream.get("sample_rate", 0)) if audio_stream else 0,
                    "channels": int(audio_stream.get("channels", 0)) if audio_stream else 0,
                    "file_size_bytes": int(fmt.get("size", 0)),
                    "bitrate_kbps": round(int(fmt.get("bit_rate", 0)) / 1000, 1),
                })
        except Exception as e:
            logger.warning("ffprobe failed for %s: %s", path, e)
            result["quality_risks"].append(f"Could not probe file: {e}")

    # Sample frames
    try:
        frame_sampler = tool_registry.get("frame_sampler")
        if frame_sampler:
            duration = result["technical_probe"].get("duration_seconds", 0)
            timestamps = _sample_timestamps(duration, count=4)
            sample_result = frame_sampler.execute({
                "input_path": str(path),
                "strategy": "timestamps",
                "timestamps": timestamps,
                # Namespaced per source file: the tool writes a fixed
                # frame_NNNN.jpg set, so a shared directory lets each video
                # overwrite the previous one's frames.
                "output_dir": str(path.parent / f".source_review_frames_{path.stem}"),
            })
            if sample_result.success:
                # The frame list lives under "frames" (not "frame_paths"), as
                # objects of {"path", "timestamp_seconds", "index"}. The
                # artifact schema declares representative_frames as an array
                # of path strings, so unwrap to paths or the artifact fails
                # validation.
                frames = sample_result.data.get("frames", [])
                result["representative_frames"] = [
                    str(frame["path"])
                    for frame in frames
                    if isinstance(frame, dict) and frame.get("path")
                ]
    except Exception as e:
        logger.warning("frame_sampler failed for %s: %s", path, e)

    # Quality risk assessment
    probe = result["technical_probe"]
    if probe:
        res = probe.get("resolution", "")
        if res and "x" in res:
            try:
                w, h = res.split("x")
                if int(w) < 720 or int(h) < 480:
                    result["quality_risks"].append(f"Low resolution ({res}) — may appear pixelated in final output")
            except ValueError:
                pass
        if probe.get("channels", 0) == 1:
            result["quality_risks"].append("Mono audio — consider if stereo output is expected")
        if probe.get("duration_seconds", 0) < 3:
            result["quality_risks"].append("Very short clip (<3s) — limited usability")

    return result


def _probe_audio(path: Path, tool_registry: Any) -> dict[str, Any]:
    """Probe an audio file using audio_probe."""
    result: dict[str, Any] = {"technical_probe": {}, "quality_risks": []}

    try:
        audio_probe = tool_registry.get("audio_probe")
        if audio_probe:
            probe_result = audio_probe.execute({"input_path": str(path)})
            if probe_result.success:
                result["technical_probe"] = probe_result.data
    except Exception as e:
        logger.warning("audio_probe failed for %s: %s", path, e)

    # Fallback ffprobe
    if not result["technical_probe"]:
        try:
            import subprocess
            cmd = [
                "ffprobe", "-v", "quiet", "-print_format", "json",
                "-show_format", "-show_streams", str(path),
            ]
            proc = subprocess.run(cmd, capture_output=True, text=True, timeout=30)
            if proc.returncode == 0:
                probe_data = json.loads(proc.stdout)
                fmt = probe_data.get("format", {})
                stream = next(
                    (s for s in probe_data.get("streams", []) if s.get("codec_type") == "audio"),
                    {},
                )
                result["technical_probe"] = {
                    "duration_seconds": float(fmt.get("duration", 0)),
                    "audio_codec": stream.get("codec_name", "unknown"),
                    "sample_rate": int(stream.get("sample_rate", 0)),
                    "channels": int(stream.get("channels", 0)),
                    "file_size_bytes": int(fmt.get("size", 0)),
                    "bitrate_kbps": round(int(fmt.get("bit_rate", 0)) / 1000, 1),
                }
        except Exception as e:
            logger.warning("ffprobe failed for audio %s: %s", path, e)
            result["quality_risks"].append(f"Could not probe audio: {e}")

    return result


def _probe_image(path: Path) -> dict[str, Any]:
    """Probe an image file for basic metadata."""
    result: dict[str, Any] = {"technical_probe": {}, "quality_risks": []}

    try:
        from PIL import Image
        img = Image.open(path)
        w, h = img.size
        result["technical_probe"] = {
            "resolution": f"{w}x{h}",
            "file_size_bytes": path.stat().st_size,
            "codec": img.format or "unknown",
        }
        if w < 640 or h < 480:
            result["quality_risks"].append(f"Low resolution ({w}x{h}) — may need upscaling")
    except ImportError:
        # PIL not available — use file size as minimal probe
        result["technical_probe"] = {
            "file_size_bytes": path.stat().st_size,
        }
    except Exception as e:
        result["quality_risks"].append(f"Could not probe image: {e}")

    return result


def _transcribe_if_available(
    path: Path, media_type: str, tool_registry: Any
) -> Optional[str]:
    """Attempt transcription for video/audio files."""
    if media_type not in ("video", "audio"):
        return None

    try:
        transcriber = tool_registry.get("transcriber")
        if transcriber and transcriber.get_status().value == "available":
            result = transcriber.execute({"input_path": str(path)})
            if result.success:
                text = result.data.get("text", "")
                if text:
                    # Return summary, not full transcript
                    words = text.split()
                    if len(words) > 100:
                        return f"{' '.join(words[:100])}... ({len(words)} words total)"
                    return text
    except Exception as e:
        logger.warning("Transcription failed for %s: %s", path, e)

    return None


def review_source_media(
    files: list[Path],
    context: dict[str, Any],
    tool_registry: Any = None,
) -> dict[str, Any]:
    """Review user-supplied media files and produce a source_media_review artifact.

    Args:
        files: Paths to user-supplied media files.
        context: Dict with optional keys like 'pipeline_type', 'project_dir'.
        tool_registry: The tool registry instance (for accessing analysis tools).

    Returns:
        Schema-valid source_media_review artifact dict.

    Must never claim a file was reviewed unless a real probe/sampling/transcription ran.
    """
    if tool_registry is None:
        try:
            from tools.tool_registry import registry
            registry.ensure_discovered()
            tool_registry = registry
        except Exception:
            pass

    reviewed_files: list[dict[str, Any]] = []
    all_implications: list[str] = []
    summaries: list[str] = []

    for file_path in files:
        media_type = detect_media_type(file_path)
        if media_type is None:
            logger.warning("Skipping unrecognized file type: %s", file_path)
            continue

        if not file_path.exists():
            logger.warning("File does not exist: %s", file_path)
            continue

        entry: dict[str, Any] = {
            "path": str(file_path),
            "media_type": media_type,
            "reviewed": True,
        }

        # Probe based on media type
        if media_type == "video":
            probe_data = _probe_video(file_path, tool_registry)
        elif media_type == "audio":
            probe_data = _probe_audio(file_path, tool_registry)
        else:
            probe_data = _probe_image(file_path)

        entry["technical_probe"] = probe_data.get("technical_probe", {})
        entry["quality_risks"] = probe_data.get("quality_risks", [])
        entry["representative_frames"] = probe_data.get("representative_frames", [])

        # Attempt transcription for audio/video
        transcript = _transcribe_if_available(file_path, media_type, tool_registry)
        if transcript:
            entry["transcript_summary"] = transcript

        # Build content summary
        probe = entry["technical_probe"]
        if media_type == "video":
            dur = probe.get("duration_seconds", 0)
            res = probe.get("resolution", "unknown")
            has_audio = bool(probe.get("audio_codec"))
            entry["content_summary"] = (
                f"Video file: {dur:.1f}s at {res}, "
                f"{'with' if has_audio else 'without'} audio"
            )
            entry["usable_for"] = _infer_video_usability(probe, transcript)
        elif media_type == "audio":
            dur = probe.get("duration_seconds", 0)
            entry["content_summary"] = f"Audio file: {dur:.1f}s, {probe.get('audio_codec', 'unknown')}"
            entry["usable_for"] = _infer_audio_usability(probe, transcript)
        else:
            res = probe.get("resolution", "unknown")
            entry["content_summary"] = f"Image file: {res}"
            entry["usable_for"] = ["visual asset", "reference image"]

        summaries.append(f"{file_path.name}: {entry['content_summary']}")
        reviewed_files.append(entry)

        # Derive planning implications from quality risks
        for risk in entry.get("quality_risks", []):
            all_implications.append(f"Quality risk in {file_path.name}: {risk}")

    # Build overall summary
    if not reviewed_files:
        summary = "No user-supplied media files could be reviewed."
        all_implications.append("No source media available — production is fully generated.")
    else:
        summary = "; ".join(summaries)

    # Add media-type implications
    has_video = any(f["media_type"] == "video" for f in reviewed_files)
    has_audio = any(f["media_type"] == "audio" for f in reviewed_files)
    has_images = any(f["media_type"] == "image" for f in reviewed_files)

    if has_video:
        all_implications.append("Source video available — consider source-led or hybrid production approach")
    if has_audio and not has_video:
        all_implications.append("Audio-only source — production needs visual assets to accompany audio")
    if has_images and not has_video:
        all_implications.append("Image-only source — motion must come from animation or video generation")

    if not all_implications:
        all_implications.append("No specific constraints identified from source media.")

    return {
        "version": "1.0",
        "files": reviewed_files,
        "summary": summary,
        "planning_implications": all_implications,
    }


# ---------------------------------------------------------------------------
# Helpers
# ---------------------------------------------------------------------------

def _parse_fps(fps_str: str) -> float:
    """Parse ffprobe fps string like '30/1' or '24000/1001'."""
    try:
        if "/" in fps_str:
            num, den = fps_str.split("/")
            return round(int(num) / max(int(den), 1), 2)
        return float(fps_str)
    except (ValueError, ZeroDivisionError):
        return 0.0


def _sample_timestamps(duration: float, count: int = 4) -> list[float]:
    """Generate evenly-spaced sample timestamps for a given duration."""
    if duration <= 0:
        return [0.0]
    if count <= 1:
        return [duration / 2]
    step = duration / (count + 1)
    return [round(step * (i + 1), 2) for i in range(count)]


def _infer_video_usability(probe: dict, transcript: Optional[str]) -> list[str]:
    """Infer what a video file can be used for."""
    uses = []
    dur = probe.get("duration_seconds", 0)
    if dur > 10:
        uses.append("hero footage")
    if dur > 3:
        uses.append("b-roll")
    if transcript:
        uses.append("source dialogue")
    if probe.get("audio_codec"):
        uses.append("source audio")
    return uses or ["short clip"]


def _infer_audio_usability(probe: dict, transcript: Optional[str]) -> list[str]:
    """Infer what an audio file can be used for."""
    uses = []
    dur = probe.get("duration_seconds", 0)
    if transcript:
        uses.append("narration source")
    if dur > 30:
        uses.append("background music candidate")
    if dur > 5:
        uses.append("sound effect or ambient")
    return uses or ["audio clip"]


def has_user_media(project_dir: Path) -> bool:
    """Check if a project directory contains user-supplied media files."""
    if not project_dir.exists():
        return False
    for ext_set in (_VIDEO_EXTENSIONS, _AUDIO_EXTENSIONS, _IMAGE_EXTENSIONS):
        for ext in ext_set:
            if list(project_dir.glob(f"*{ext}")):
                return True
    return False

lib/variation_checker.py:
"""Scene plan variation checker.

Analyzes a scene plan for repetitive patterns that make videos feel
like slideshows. Catches problems before asset generation begins.

This is a structural check, not a creative judgment — it flags concrete
patterns that reliably produce generic-feeling output.
"""

from __future__ import annotations

from collections import Counter
from typing import Any


# Generic language patterns that signal lazy scene descriptions
GENERIC_PHRASES = {
    "a person", "a beautiful", "modern", "futuristic", "cutting-edge",
    "in today's world", "sleek design", "innovative", "state-of-the-art",
    "next-generation", "revolutionary", "a professional", "dynamic",
    "vibrant", "stunning", "breathtaking", "amazing", "incredible",
    "powerful", "seamless", "elegant solution",
}


def check_scene_variation(scenes: list[dict[str, Any]]) -> dict[str, Any]:
    """Analyze a scene plan for repetitive patterns.

    Returns:
        {
            "score": float (0-5, lower is better),
            "verdict": "strong" | "acceptable" | "revise" | "fail",
            "violations": list of specific issues,
            "suggestions": list of improvement suggestions,
        }
    """
    if not scenes:
        return {"score": 5.0, "verdict": "fail", "violations": ["No scenes to check"], "suggestions": []}

    violations: list[str] = []
    suggestions: list[str] = []

    # --- Check 1: Shot size variety ---
    shot_sizes = [
        s.get("shot_language", {}).get("shot_size", "unspecified")
        for s in scenes
    ]
    size_counts = Counter(shot_sizes)
    if len(scenes) >= 4:
        most_common_size, most_common_count = size_counts.most_common(1)[0]
        if most_common_count / len(scenes) > 0.5:
            violations.append(
                f"Shot size '{most_common_size}' used in {most_common_count}/{len(scenes)} scenes "
                f"({most_common_count/len(scenes):.0%}). Vary shot sizes for visual interest."
            )
            suggestions.append("Mix wide establishing shots with close-ups for visual rhythm.")

    # --- Check 2: Consecutive same-size shots ---
    # Track the longest actual run of identical shot sizes. Summing every equal
    # adjacent pair across the whole plan would count non-consecutive groups
    # (e.g. wide,wide,cu,cu,med,med -> 3 pairs) as a single "3 consecutive" run.
    longest_run = 1 if shot_sizes else 0
    current_run = 1
    for i in range(1, len(shot_sizes)):
        if shot_sizes[i] == shot_sizes[i-1] and shot_sizes[i] != "unspecified":
            current_run += 1
            longest_run = max(longest_run, current_run)
        else:
            current_run = 1
    if longest_run >= 3:
        violations.append(
            f"{longest_run} consecutive same-size shots. "
            f"Vary shot sizes between scenes for editorial rhythm."
        )

    # --- Check 3: Static shot overuse ---
    movements = [
        s.get("shot_language", {}).get("camera_movement", "unspecified")
        for s in scenes
    ]
    static_count = sum(1 for m in movements if m in ("static", "unspecified"))
    if len(scenes) >= 4 and static_count / len(scenes) > 0.6:
        violations.append(
            f"{static_count}/{len(scenes)} scenes are static or unspecified movement. "
            f"Add intentional camera movement to at least 40% of scenes."
        )
        suggestions.append("Consider dolly_in for emphasis, tracking for energy, or crane for scale.")

    # --- Check 4: Lighting variety ---
    lightings = {
        s.get("shot_language", {}).get("lighting_key")
        for s in scenes
        if s.get("shot_language", {}).get("lighting_key")
    }
    if len(scenes) >= 4 and len(lightings) <= 1:
        violations.append(
            f"Only {len(lightings)} unique lighting setup(s) across {len(scenes)} scenes. "
            f"Vary lighting to create mood shifts."
        )

    # --- Check 5: Hero moment exists and is visually distinct ---
    hero_scenes = [s for s in scenes if s.get("hero_moment")]
    if len(scenes) >= 4 and not hero_scenes:
        violations.append(
            "No hero_moment flagged. Every video should have at least one visual peak."
        )
        suggestions.append("Mark the most impactful scene as hero_moment=true.")

    if hero_scenes:
        for hero in hero_scenes:
            hero_idx = scenes.index(hero)
            hero_size = hero.get("shot_language", {}).get("shot_size")
            # Check neighbors
            for offset in (-1, 1):
                neighbor_idx = hero_idx + offset
                if 0 <= neighbor_idx < len(scenes):
                    neighbor_size = scenes[neighbor_idx].get("shot_language", {}).get("shot_size")
                    if hero_size and neighbor_size and hero_size == neighbor_size:
                        violations.append(
                            f"Hero scene '{hero.get('id')}' has same shot size as neighbor. "
                            f"Hero moments should be visually distinct from surrounding scenes."
                        )

    # --- Check 6: Description specificity ---
    generic_count = 0
    for scene in scenes:
        desc = scene.get("description", "").lower()
        for phrase in GENERIC_PHRASES:
            if phrase in desc:
                generic_count += 1
                break
    if generic_count >= len(scenes) * 0.3:
        violations.append(
            f"{generic_count}/{len(scenes)} scenes use generic language. "
            f"Replace vague descriptions with specific visual details."
        )
        suggestions.append(
            "Instead of 'a beautiful cityscape', try 'rain-slicked Tokyo intersection "
            "at night, neon reflections in puddles, pedestrians with translucent umbrellas'."
        )

    # --- Check 7: Texture keywords presence ---
    textured = sum(1 for s in scenes if s.get("texture_keywords"))
    if len(scenes) >= 4 and textured < len(scenes) * 0.3:
        violations.append(
            f"Only {textured}/{len(scenes)} scenes have texture_keywords. "
            f"Add texture descriptors to visual scenes for richer generation prompts."
        )

    # --- Check 8: Shot intent completeness ---
    intented = sum(1 for s in scenes if s.get("shot_intent"))
    if len(scenes) >= 4 and intented < len(scenes) * 0.5:
        violations.append(
            f"Only {intented}/{len(scenes)} scenes have shot_intent. "
            f"Every scene should explain WHY it exists in the video."
        )

    # --- Score ---
    # Each violation category adds ~0.6 to score
    score = min(5.0, len(violations) * 0.6)

    if score < 2.0:
        verdict = "strong"
    elif score < 3.0:
        verdict = "acceptable"
    elif score < 4.0:
        verdict = "revise"
    else:
        verdict = "fail"

    return {
        "score": round(score, 1),
        "verdict": verdict,
        "violations": violations,
        "suggestions": suggestions,
    }

tools/fal_media.py:
"""Schema-backed fal media jobs with explicit endpoint selection and resume."""

from __future__ import annotations

import json
import os
from abc import abstractmethod
from pathlib import Path
from urllib.parse import urlparse

from jsonschema import Draft202012Validator

from tools.provider_pricing import PriceQuoteRequired

from tools.base_tool import (
    BaseTool,
    ToolTier,
    ToolRuntime,
    ToolStability,
    ToolStatus,
    Determinism,
    ResourceProfile,
    ResumeSupport,
    ToolResult,
)
from tools.provider_jobs import request_json, download, poll, save_job

CONTRACTS = json.loads(
    (Path(__file__).parent / "provider_contracts/fal_models.json").read_text(
        encoding="utf-8"
    )
)


class FalMedia(BaseTool):
    provider = "fal.ai"
    runtime = ToolRuntime.API
    tier = ToolTier.GENERATE
    stability = ToolStability.BETA
    determinism = Determinism.STOCHASTIC
    dependencies = ["env:FAL_KEY"]
    install_instructions = "Configure FAL_KEY using https://fal.ai/dashboard/keys."
    resource_profile = ResourceProfile(network_required=True)
    resume_support = ResumeSupport.FROM_CHECKPOINT
    agent_skills = ["provider-model-refresh"]
    side_effects = [
        "submits a paid fal job",
        "writes media and optional job checkpoint",
    ]
    user_visible_verification = ["Inspect generated media and provider provenance"]
    idempotency_key_fields = [
        "model",
        "operation",
        "generation_mode",
        "prompt",
        "image_urls",
        "mask_url",
        "seed",
        "duration",
        "resolution",
        "provider_params",
    ]

    @property
    @abstractmethod
    def routes(self):
        """Map public model names to operation -> exact fal endpoint."""

    def __init__(self):
        models = list(self.routes)
        props = {}
        for routes in self.routes.values():
            for endpoint in routes.values():
                props.update(CONTRACTS[endpoint]["input_schema"]["properties"])
        # Full endpoint-specific validation happens before submitting a job.
        props = {
            key: {"description": value.get("description", key)}
            for key, value in props.items()
        }
        props.update(
            {
                "model": {"type": "string", "enum": models, "default": models[0]},
                "operation": {"type": "string"},
                "generation_mode": {"type": "string"},
                "image_url": {"type": "string"},
                "image_path": {"type": "string"},
                "mask_path": {"type": "string"},
                "image_paths": {"type": "array", "items": {"type": "string"}},
                "provider_params": {"type": "object"},
                "resume_job": {"type": "object"},
                "job_path": {"type": "string"},
                "output_path": {"type": "string"},
                "poll_timeout": {"type": "number", "exclusiveMinimum": 0},
                "poll_interval": {"type": "number", "exclusiveMinimum": 0},
            }
        )
        self.input_schema = {"type": "object", "properties": props}
        self.idempotency_key_fields = sorted(
            set(props)
            - {"resume_job", "job_path", "output_path", "poll_timeout", "poll_interval"}
        )

    def get_status(self):
        return (
            ToolStatus.AVAILABLE
            if os.getenv("FAL_KEY") or os.getenv("FAL_AI_API_KEY")
            else ToolStatus.UNAVAILABLE
        )

    def get_info(self):
        info = super().get_info()
        info["hosting_provider"] = "fal.ai"
        info["model_catalog"] = {
            m: {
                "routes": r,
                "verified_on": max(
                    CONTRACTS[e].get("verified_on", "2026-10-03") for e in r.values()
                ),
                "pricing_status": "quote_required",
            }
            for m, r in self.routes.items()
        }
        return info

    def estimate_cost(self, inputs):
        # No fabricated per-image/per-second rates. Callers must obtain a quote.
        raise PriceQuoteRequired(
            "A current fal price quote is required for this model/operation"
        )

    def build_request(self, inputs):
        model = inputs.get("model", next(iter(self.routes)))
        references = any(
            inputs.get(k)
            for k in ("image_path", "image_paths", "image_url", "image_urls")
        )
        operation = (
            inputs.get("generation_mode")
            or inputs.get("operation")
            or (
                "edit"
                if references and self.capability == "image_generation"
                else (
                    "image_to_video"
                    if references
                    else next(iter(self.routes.get(model, {})), "")
                )
            )
        )
        if operation == "generate":
            operation = (
                "generate"
                if "generate" in self.routes.get(model, {})
                else "text_to_video"
            )
        endpoint = self.routes.get(model, {}).get(operation)
        if not endpoint:
            raise ValueError(f"Unsupported model/operation: {model}/{operation}")
        schema = CONTRACTS[endpoint]["input_schema"]
        props = schema["properties"]
        payload = {k: v for k, v in inputs.items() if k in props}
        native = inputs.get("provider_params", {})
        if not isinstance(native, dict):
            raise ValueError("provider_params must be an object")
        payload.update(native)
        if "prompt_expansion_mode" in props:
            payload.setdefault("prompt_expansion_mode", "balanced")
        if inputs.get("image_url") and "start_image_url" in props:
            payload["start_image_url"] = inputs["image_url"]
        if inputs.get("image_url") and "image_urls" in props:
            payload["image_urls"] = [
                inputs["image_url"],
                *payload.get("image_urls", []),
            ]
        if inputs.get("mask_path"):
            if "mask_url" not in props:
                raise ValueError(f"{endpoint} does not accept a mask")
            from tools.schema_media import local_image

            payload["mask_url"] = local_image(inputs["mask_path"])
        paths = list(inputs.get("image_paths") or [])
        if inputs.get("image_path"):
            paths.insert(0, inputs["image_path"])
        if paths:
            import mimetypes, base64

            refs = [
                "data:"
                + (mimetypes.guess_type(p)[0] or "image/png")
                + ";base64,"
                + base64.b64encode(Path(p).read_bytes()).decode()
                for p in paths
            ]
            if "image_urls" in props:
                payload["image_urls"] = list(payload.get("image_urls") or []) + refs
            elif len(refs) == 1 and (
                "image_url" in props or "start_image_url" in props
            ):
                if payload.get("image_url") or payload.get("start_image_url"):
                    raise ValueError(
                        "This route accepts one source image; do not combine URL and local path"
                    )
                payload[
                    "start_image_url" if "start_image_url" in props else "image_url"
                ] = refs[0]
            else:
                raise ValueError("This route does not support the supplied image paths")
        if inputs.get("generate_audio") is not None and "audio" in props:
            payload["audio"] = inputs["generate_audio"]
        if inputs.get("n") is not None and "num_images" in props:
            payload["num_images"] = inputs["n"]
        if operation == "precise_edit":
            payload["edit_precision"] = "high"
        for key in (
            "image_url",
            "image_urls",
            "mask_url",
            "reference_image_urls",
            "reference_video_urls",
            "reference_audio_urls",
            "target_audio_url",
        ):
            if (
                inputs.get(key)
                and key not in props
                and not (
                    key == "image_url"
                    and ("start_image_url" in props or "image_urls" in props)
                )
            ):
                raise ValueError(f"{endpoint} does not accept {key}")
        Draft202012Validator(schema).validate(payload)
        if payload.get("mask_url") and len(payload.get("reference_image_urls", [])) > 3:
            raise ValueError(
                "Masked Ideogram edits allow at most three reference images"
            )
        if (payload.get("web_url") or payload.get("file_url")) and not payload.get(
            "enable_thinking"
        ):
            raise ValueError("web_url/file_url requires enable_thinking")
        return model, operation, endpoint, payload

    def execute(self, inputs):
        job = dict(inputs.get("resume_job") or {})
        try:
            key = os.getenv("FAL_KEY") or os.getenv("FAL_AI_API_KEY")
            if not key:
                raise ValueError("FAL_KEY is not configured")
            headers = {"Authorization": f"Key {key}"}
            if not job:
                model, operation, endpoint, payload = self.build_request(inputs)
                try:
                    submitted = request_json(
                        "POST",
                        f"https://queue.fal.run/{endpoint}",
                        headers=headers,
                        json=payload,
                    )
                    job = {
                        k: submitted[k]
                        for k in ("request_id", "status_url", "response_url")
                    }
                except Exception as exc:
                    # The provider may have accepted a paid job before a
                    # transport/response failure. Without its request_id no
                    # checkpoint can safely be resumed or resubmitted.
                    raise RuntimeError(
                        "fal submission outcome unknown; do not resubmit "
                        "before checking the fal dashboard: " + str(exc)
                    ) from exc
                job.update(
                    model=model, operation=operation, endpoint=endpoint, tool=self.name,
                    output_format=payload.get("output_format"),
                )
                save_job(inputs.get("job_path"), job)
            if job.get("tool") != self.name or self.routes.get(
                job.get("model"), {}
            ).get(job.get("operation")) != job.get("endpoint"):
                raise ValueError("Resume job belongs to a different tool or endpoint")
            for field in ("status_url", "response_url"):
                parsed = urlparse(job[field])
                if parsed.scheme != "https" or parsed.netloc != "queue.fal.run":
                    raise ValueError("Invalid fal job URL")
            poll(
                lambda: request_json("GET", job["status_url"], headers=headers),
                timeout=float(inputs.get("poll_timeout", 600)),
                interval=float(inputs.get("poll_interval", 2)),
            )
            result = request_json("GET", job["response_url"], headers=headers)
            values = result.get("images") or (
                [result["video"]]
                if result.get("video")
                else [result["audio"]] if result.get("audio") else []
            )
            if not values:
                raise ValueError("Completed job returned no media")
            ext = (
                ".mp4"
                if self.capability == "video_generation"
                else "." + (job.get("output_format") or inputs.get("output_format", "png"))
            )
            path = Path(inputs.get("output_path") or self.name + ext)
            outputs = [
                download(
                    v["url"],
                    (
                        path
                        if i == 0
                        else path.with_name(f"{path.stem}_{i + 1}{path.suffix}")
                    ),
                )
                for i, v in enumerate(values)
            ]
            return ToolResult(
                success=True,
                data={
                    "provider": self.provider,
                    "hosting_provider": "fal.ai",
                    "model": job["model"],
                    "operation": job["operation"],
                    "output": outputs[0],
                    "outputs": outputs,
                    "resume_job": job,
                    "cost_status": "unquoted",
                    "provider_result": result,
                },
                artifacts=outputs,
                cost_usd=None,
                model=job["model"],
            )
        except Exception as exc:
            return ToolResult(
                success=False, error=str(exc), data={"resume_job": job} if job else {}
            )

tools/minicut_cli.py:
"""Shared helpers for tools that drive the public ``minicut`` CLI.

The CLI prices every request for free and sends nothing until it is run
again with that exact price. These helpers keep that gate: ``quote`` turns
the CLI's needs_yes answer into an ``approval``, and ``send`` sends exactly
that approval and nothing else. The approval carries the CLI's idempotency
key, so sending it again after a timeout or an error never starts a second
paid job. ``collect`` waits for the job and returns the saved file path.

Sign-in and the key stay inside the CLI's own key store. Nothing here reads
or stores a key. Model-specific inputs stay in each tool.
"""

from __future__ import annotations

import hashlib
import json
import os
import platform
import shlex
import shutil
import subprocess
import time
from pathlib import Path
from typing import Any

from tools.base_tool import ToolResult

# MiniCut files a result as a library item; this is the item OpenMontage results go to.
LIBRARY_ITEM = "prop:openmontage"
NEEDS_YES = 3  # the CLI's exit code for "priced, nothing sent"
NOT_READY = 6  # the CLI's exit code for "job still running"
INSTALL_INSTRUCTIONS = (
    "Install the MiniCut CLI: curl -fsSL https://minicut.ai/install.sh | bash\n"
    "  Then sign in once: minicut login"
)


def find_cli() -> str | None:
    """Path of the ``minicut`` command, or None when it is not installed."""
    return shutil.which("minicut")


def minicut_home() -> Path:
    """The CLI's home folder: MINICUT_HOME, else ~/.minicut (Windows: %LOCALAPPDATA%\\minicut)."""
    env = os.environ.get("MINICUT_HOME") or os.environ.get("MH_HOME")
    if env:
        return Path(env)
    if platform.system() == "Windows":
        local = os.environ.get("LOCALAPPDATA", "")
        if not local or not local.isascii():
            raise RuntimeError("Set MINICUT_HOME to the MiniCut home folder (minicut doctor shows it)")
        return Path(local) / "minicut"
    return Path.home() / ".minicut"


def run(words: list[str], timeout: int = 900) -> tuple[int, dict[str, Any]]:
    """Run ``minicut <words>``; return its exit code and its last JSON line."""
    exe = find_cli()
    if not exe:
        raise RuntimeError("minicut not found. " + INSTALL_INSTRUCTIONS)
    proc = subprocess.run(
        [exe, *words], capture_output=True, text=True, encoding="utf-8",
        errors="replace", timeout=timeout, check=False,
    )
    lines = [ln for ln in (proc.stdout or "").splitlines() if ln.strip().startswith("{")]
    data = json.loads(lines[-1]) if lines else {}
    if not data and proc.returncode not in (0, NEEDS_YES, NOT_READY):
        data = {"error": {"message": (proc.stderr or proc.stdout or "").strip()[-500:]}}
    return proc.returncode, data


def stage(path: str) -> str:
    """Copy an input into the CLI's cache folder, the folders it reads inputs from."""
    src = Path(path).expanduser().resolve()
    if not src.is_file():
        raise ValueError(f"Input file not found: {src}")
    digest = hashlib.sha256(src.read_bytes()).hexdigest()[:16]
    dst = minicut_home() / "cache" / "openmontage" / f"{digest}{src.suffix.lower()}"
    if not dst.exists():
        dst.parent.mkdir(parents=True, exist_ok=True)
        shutil.copyfile(src, dst)
    return str(dst)


def gen_words(
    model: str,
    out_name: str,
    prompt: str | None = None,
    settings: dict[str, Any] | None = None,
    files: list[tuple[str, str | None]] | None = None,
) -> list[str]:
    """``gen`` words for any model: --set word=value pairs, then --in role=file (staged)."""
    words = ["gen", model, out_name]
    if prompt is not None:
        words += ["--prompt", prompt]
    for key, value in (settings or {}).items():
        if value is not None:
            words += ["--set", f"{key}={value}"]
    for role, path in files or []:
        if path:
            words += ["--in", f"{role}={stage(path)}"]
    return words + ["--target", LIBRARY_ITEM, "--json"]


def approval(data: dict[str, Any]) -> dict[str, Any]:
    """The CLI's needs_yes answer as an approval: credits, its key and its quote fingerprint."""
    argv = shlex.split(data["next_step"])
    return {
        "credits": data["max_credits"],
        "model": data.get("model"),
        "key": argv[argv.index("--key") + 1],
        "quote": argv[argv.index("--quote") + 1],
    }


def message(data: dict[str, Any], code: int) -> str:
    """The CLI's error as one line, with its Why and Change when given."""
    err = data.get("error") or {}
    parts = [err.get("message") or err.get("code") or f"minicut exit {code}"]
    if err.get("reason"):
        parts.append(f"Why: {err['reason']}")
    if err.get("change"):
        parts.append(f"Change: {err['change']}")
    return " ".join(parts)


def needs_yes(approved: dict[str, Any], reason: str = "") -> ToolResult:
    """A result that hands the price back for the user's yes. Nothing was sent."""
    return ToolResult(
        success=False,
        error=(
            f"{reason}MiniCut price is {approved['credits']} credits. Nothing was sent. "
            "Show the user this price, then run again with this approval after their yes."
        ),
        data={"approval_required": True, "approval": approved},
        cost_usd=0.0,
    )


def quote(words: list[str]) -> dict[str, Any]:
    """The free price for ``gen`` words, as an approval. Sends nothing."""
    code, data = run(words)
    if code != NEEDS_YES or data.get("state") != "needs_yes":
        raise RuntimeError(message(data, code))
    return approval(data)


def send(words: list[str], approved: dict[str, Any]) -> ToolResult | str:
    """Send exactly the approved line. Returns the job id, or a result to hand back."""
    resend = {"approval_required": False, "approval": approved}
    try:
        code, sent = run(words + [
            "--yes", "--max-credits", str(approved["credits"]),
            "--key", approved["key"], "--quote", approved["quote"],
        ])
    except subprocess.TimeoutExpired:
        return ToolResult(
            success=False, cost_usd=None, data=resend,
            error="minicut did not answer in time. Run again with the same approval; "
            "it is never charged twice.",
        )
    if code == NEEDS_YES and sent.get("state") == "needs_yes":
        # The request or the price changed since the yes: a new price, a new yes.
        return needs_yes(approval(sent), "The price or request changed. ")
    if code == 0 and sent.get("job_id"):
        return sent["job_id"]
    return ToolResult(
        success=False, cost_usd=None, data=resend,
        error=f"MiniCut did not take the job: {message(sent, code)}",
    )


def collect(job_id: str, poll_timeout: int = 900) -> ToolResult | str:
    """Wait for a job. Returns the saved file path, or a result to hand back."""
    deadline = time.monotonic() + int(poll_timeout)
    while True:
        code, got = run(["jobs", "--get", job_id, "--json"])
        row = next((j for j in got.get("jobs", []) if j.get("job_id") == job_id), {})
        if row.get("state") == "done" and row.get("paths"):
            return row["paths"][0]
        if row.get("state") in ("failed", "stopped"):
            return ToolResult(
                success=False,
                cost_usd=None,
                error=f"MiniCut job {row['state']}: {message(row, code)}",
                data={"job_id": job_id, "credits_charged": row.get("credits_charged")},
            )
        if row.get("state") == "done" and not row.get("saving_elsewhere"):
            raise RuntimeError(f"job done but not saved here: {message(row, code)}")
        if code not in (0, NOT_READY):
            raise RuntimeError(message(got, code))
        if time.monotonic() >= deadline:
            return ToolResult(
                success=False,
                cost_usd=None,
                error="Job is still running; run again with resume_job, do not resubmit",
                data={"resume_job": {"job_id": job_id}},
            )
        time.sleep(10)

tools/minicut_tool.py:
"""Shared base for the MiniCut image, voice and music tools.

Each tool names one MiniCut model and turns its inputs into ``gen`` words.
This base keeps the same price-then-yes flow as ``minicut_video``:
``dry_run`` returns the CLI's free quote as an ``approval``, ``execute``
sends exactly that approval, and sending it again never pays twice.
"""

from __future__ import annotations

import shutil
import time
from abc import abstractmethod
from pathlib import Path
from typing import Any

from tools import minicut_cli
from tools.base_tool import (
    BaseTool,
    Determinism,
    ExecutionMode,
    ResourceProfile,
    RetryPolicy,
    ToolResult,
    ToolRuntime,
    ToolStability,
    ToolStatus,
    ToolTier,
)
from tools.provider_pricing import PriceQuoteRequired

APPROVAL_SCHEMA = {
    "type": "object",
    "description": (
        "dry_run()['approval'], after the user said yes to its credits. "
        "Without it nothing is sent. Sending the same approval again never pays twice."
    ),
}
RESUME_SCHEMA = {
    "type": "object",
    "description": "{'job_id': ...} from a run that timed out. Collects it, no new charge.",
}


class MiniCutTool(BaseTool):
    """One MiniCut model behind the CLI's price-then-yes gate."""

    version = "0.1.0"
    tier = ToolTier.GENERATE
    provider = "minicut"
    stability = ToolStability.EXPERIMENTAL
    execution_mode = ExecutionMode.SYNC
    determinism = Determinism.STOCHASTIC
    runtime = ToolRuntime.API
    dependencies = ["cmd:minicut"]
    install_instructions = minicut_cli.INSTALL_INSTRUCTIONS
    not_good_for = ["offline generation", "runs with no user present to approve the price"]
    resource_profile = ResourceProfile(
        cpu_cores=1, ram_mb=256, vram_mb=0, disk_mb=100, network_required=True
    )
    # Paid submission: never retried automatically. A timeout is collected with resume_job.
    retry_policy = RetryPolicy(max_retries=0)

    model = ""  # the MiniCut model id
    default_output = "minicut_output"

    @abstractmethod
    def _request(self, inputs: dict[str, Any]) -> tuple[str, dict[str, Any], list[tuple[str, str | None]]]:
        """The prompt, the ``--set`` settings and the ``--in`` files for this model."""

    def _gen_words(self, inputs: dict[str, Any]) -> list[str]:
        prompt, settings, files = self._request(inputs)
        # The library file name; the result is copied to output_path once saved.
        out_name = Path(inputs.get("output_path") or self.default_output).name
        return minicut_cli.gen_words(self.model, out_name, prompt, settings, files)

    def get_status(self) -> ToolStatus:
        return ToolStatus.AVAILABLE if minicut_cli.find_cli() else ToolStatus.UNAVAILABLE

    def estimate_cost(self, inputs: dict[str, Any]) -> float:
        raise PriceQuoteRequired(
            "MiniCut prices each request in credits; dry_run returns the exact quote for free"
        )

    def estimate_runtime(self, inputs: dict[str, Any]) -> float:
        return 60.0

    def dry_run(self, inputs: dict[str, Any]) -> dict[str, Any]:
        result = super().dry_run(inputs)
        try:
            approval = minicut_cli.quote(self._gen_words(inputs))
        except Exception as exc:
            return {**result, "would_execute": False, "quote_reason": str(exc)}
        return {
            **result,
            "estimated_credits": approval["credits"],
            "approval": approval,
            "would_execute": False,
        }

    def execute(self, inputs: dict[str, Any]) -> ToolResult:
        start = time.time()
        output_path = Path(inputs.get("output_path") or self.default_output)
        job_id = (inputs.get("resume_job") or {}).get("job_id")
        try:
            if not job_id:
                if not inputs.get("approval"):
                    return minicut_cli.needs_yes(minicut_cli.quote(self._gen_words(inputs)))
                sent = minicut_cli.send(self._gen_words(inputs), inputs["approval"])
                if isinstance(sent, ToolResult):
                    return sent
                job_id = sent

            saved = minicut_cli.collect(job_id, inputs.get("poll_timeout", 900))
            if isinstance(saved, ToolResult):
                return saved
            # Keep the file type the model returned (a .wav stays .wav).
            suffix = Path(saved).suffix
            if suffix and suffix.lower() != output_path.suffix.lower():
                output_path = output_path.with_suffix(suffix)
            output_path.parent.mkdir(parents=True, exist_ok=True)
            shutil.copyfile(saved, output_path)
        except Exception as exc:
            data = {"resume_job": {"job_id": job_id}} if job_id else {}
            return ToolResult(
                success=False,
                error=f"MiniCut {self.model} failed: {exc}",
                data=data,
                cost_usd=None if job_id else 0.0,
            )

        return ToolResult(
            success=True,
            data={
                "provider": "minicut",
                "model": self.model,
                "job_id": job_id,
                "output": str(output_path),
                "output_path": str(output_path),
                "format": output_path.suffix.lstrip("."),
                # MiniCut bills in credits; the USD value depends on the user's plan.
                "cost_status": "unquoted",
            },
            artifacts=[str(output_path)],
            cost_usd=None,
            duration_seconds=round(time.time() - start, 2),
            model=self.model,
        )

tools/provider_jobs.py:
"""HTTP primitives for media adapters. Never retry a paid submission automatically."""

from __future__ import annotations

import base64
import json
import time
from pathlib import Path
from urllib.parse import urlparse

import requests


def request_json(method, url, *, headers=None, **kwargs):
    response = requests.request(method, url, headers=headers, timeout=60, **kwargs)
    response.raise_for_status()
    return response.json()


def download(url: str, path: Path) -> str:
    path.parent.mkdir(parents=True, exist_ok=True)
    if url.startswith("data:"):
        head, body = url.split(",", 1)
        if ";base64" not in head:
            raise ValueError("Only base64 media data URIs are supported")
        content = base64.b64decode(body, validate=True)
    else:
        if urlparse(url).scheme != "https":
            raise ValueError("Media output must be an HTTPS URL or base64 data URI")
        response = requests.get(url, timeout=120)
        response.raise_for_status()
        content = response.content
    if not content:
        raise ValueError("Provider returned empty media")
    temp = path.with_name(path.name + ".part")
    temp.write_bytes(content)
    temp.replace(path)
    return str(path)


def save_job(path, data):
    if path:
        target = Path(path)
        target.parent.mkdir(parents=True, exist_ok=True)
        temporary = target.with_name(target.name + ".part")
        temporary.write_text(json.dumps(data, indent=2), encoding="utf-8")
        temporary.replace(target)


def poll(fetch, *, timeout=600, interval=2):
    if timeout <= 0 or interval <= 0:
        raise ValueError("poll_timeout and poll_interval must be positive")
    deadline = time.monotonic() + timeout
    while True:
        result = fetch()
        state = str(result.get("status", "")).lower()
        if state in {"completed", "succeeded", "success"}:
            return result
        if state in {"failed", "cancelled", "canceled", "error"}:
            raise RuntimeError(
                f"Provider job {state}: {result.get('error', 'no detail')}"
            )
        if time.monotonic() >= deadline:
            raise TimeoutError(
                "Job is still pending; resume with the returned job metadata, do not resubmit"
            )
        time.sleep(min(interval, max(0, deadline - time.monotonic())))

