tools/provider_routing.py:
"""Explicit tool/host/model constraints shared by capability selectors."""

from __future__ import annotations


def filter_explicit_route(inputs, candidates):
    tool_name = inputs.get("preferred_tool")
    host = inputs.get("hosting_provider")
    model_field = next(
        (f for f in ("model", "model_id", "model_name") if inputs.get(f)), None
    )
    model = inputs.get(model_field) if model_field else None
    selected = []
    unvouched = []  # targeted open-field tools that cannot vouch for `model`
    for tool in candidates:
        if tool_name and tool.name != tool_name:
            continue
        if host and getattr(tool, "hosting_provider", tool.provider) != host:
            continue
        if model:
            props = tool.input_schema.get("properties", {})
            models = set()
            for field in ("model", "model_id", "model_name"):
                models.update(props.get(field, {}).get("enum", []))
            models.update(getattr(tool, "_MODELS", {}))
            models.update(getattr(tool, "_MODEL_ALIASES", {}))
            models.update(tool.get_info().get("model_catalog", {}))
            # Free-form model fields can't be enumerated; such a tool may still
            # vouch for a specific value (e.g. piper: an installed voice or .onnx path).
            vouch = getattr(tool, "vouches_for_model", None)
            if model not in models and not (
                model_field in props and vouch and vouch(model)
            ):
                # An open field can accept a caller-pinned model without
                # claiming that unrelated free-form tools support it in auto mode.
                if not (
                    not models
                    and model_field in props
                    and (tool_name or tool.provider == inputs.get("preferred_provider"))
                ):
                    continue
                unvouched.append(tool)
        operation = inputs.get("generation_mode") or inputs.get("operation")
        routes = getattr(tool, "routes", None) or getattr(tool, "models", None)
        if isinstance(routes, dict) and operation and operation != "rank":
            model_routes = (
                routes.get(model, {}) if model else next(iter(routes.values()), {})
            )
            normalized = (
                "text_to_video"
                if operation == "generate" and tool.capability == "video_generation"
                else operation
            )
            if tool.capability == "image_generation":
                if normalized == "generate" and "text_to_image" in model_routes:
                    has_references = any(inputs.get(key) for key in (
                        "image_url", "image_urls", "image_path", "image_paths"
                    ))
                    normalized = "image_to_image" if has_references else "text_to_image"
                elif normalized == "edit" and "image_to_image" in model_routes:
                    normalized = "image_to_image"
            if normalized == "video_edit" and "video_to_video_edit" in model_routes:
                normalized = "video_to_video_edit"
            if normalized not in model_routes:
                continue
        if tool.capability == "image_generation":
            props = tool.input_schema.get("properties", {})
            if any(inputs.get(k) and k not in props for k in ("mask_path", "mask_url")):
                continue
            # Template tools (accepts_image_input) decide from the template the
            # request's ``workflow`` selects, not from the default's schema.
            accepts_image = getattr(tool, "accepts_image_input", None)
            if accepts_image is not None and accepts_image(inputs):
                props = {**props, "image_path": {}}
            if any(
                inputs.get(k) and k not in props and "images" not in props
                for k in ("image_path", "image_paths", "image_url", "image_urls")
            ):
                continue
            if operation == "precise_edit" and not (
                getattr(tool, "supports", {}).get("precise_edit")
                or isinstance(routes, dict)
                and any("precise_edit" in r for r in routes.values())
            ):
                continue
        selected.append(tool)
    # A tool that declares the model beats one that merely might accept it.
    vouched = [t for t in selected if t not in unvouched]
    return vouched or selected

tools/schema_media.py:
"""Schema-validated Atlas, Replicate and LTX jobs with durable resume metadata."""

from __future__ import annotations

import base64
import json
import mimetypes
import os
from abc import abstractmethod
from pathlib import Path
from urllib.parse import quote

from jsonschema import Draft202012Validator
from tools.provider_pricing import PriceQuoteRequired

from tools.base_tool import (
    BaseTool,
    ToolTier,
    ToolRuntime,
    ToolStability,
    ResourceProfile,
    ResumeSupport,
    ToolResult,
)
from tools.provider_jobs import request_json, download, poll, save_job


def local_image(path):
    return (
        "data:"
        + (mimetypes.guess_type(path)[0] or "image/png")
        + ";base64,"
        + base64.b64encode(Path(path).read_bytes()).decode()
    )


class SchemaMedia(BaseTool):
    tier = ToolTier.GENERATE
    runtime = ToolRuntime.API
    stability = ToolStability.BETA
    resource_profile = ResourceProfile(network_required=True)
    resume_support = ResumeSupport.FROM_CHECKPOINT
    agent_skills = ["provider-model-refresh"]
    side_effects = [
        "submits a paid generation job",
        "writes media and optional resume checkpoint",
    ]
    idempotency_key_fields = [
        "model",
        "operation",
        "generation_mode",
        "prompt",
        "provider_params",
        "image_url",
        "image_paths",
        "duration",
        "resolution",
        "seed",
    ]

    @property
    @abstractmethod
    def catalog_file(self):
        """Checked-in schema file name."""

    def __init__(self):
        self.contracts = json.loads(
            (
                Path(__file__).parent / "provider_contracts" / self.catalog_file
            ).read_text(encoding="utf8")
        )
        props = {}
        for endpoint in self.endpoints:
            for name, spec in self.contracts[endpoint]["input_schema"][
                "properties"
            ].items():
                # Public union is intentionally permissive; selected route is validated fully.
                props[name] = {"description": spec.get("description", name)}
        props.update(
            {
                "model": {
                    "type": "string",
                    "enum": list(self.models),
                    "default": next(iter(self.models)),
                },
                "operation": {"type": "string"},
                "generation_mode": {"type": "string"},
                "image_url": {"type": "string"},
                "image_path": {"type": "string"},
                "image_urls": {"type": "array", "items": {"type": "string"}},
                "image_paths": {"type": "array", "items": {"type": "string"}},
                "mask_url": {"type": "string"},
                "mask_path": {"type": "string"},
                "aspect_ratio": {"type": "string"},
                "generate_audio": {"type": "boolean"},
                "provider_params": {"type": "object"},
                "resume_job": {"type": "object"},
                "job_path": {"type": "string"},
                "output_path": {"type": "string"},
                "poll_timeout": {"type": "number", "exclusiveMinimum": 0},
                "poll_interval": {"type": "number", "exclusiveMinimum": 0},
            }
        )
        self.input_schema = {"type": "object", "properties": props}
        self.idempotency_key_fields = sorted(
            set(props)
            - {"resume_job", "job_path", "output_path", "poll_timeout", "poll_interval"}
        )

    @property
    def endpoints(self):
        return {
            endpoint for routes in self.models.values() for endpoint in routes.values()
        }

    def get_info(self):
        info = super().get_info()
        info["hosting_provider"] = self.provider
        info["model_catalog"] = {
            model: {
                "routes": routes,
                "verified_on": max(
                    self.contracts[e].get("verified_on", "2026-10-03")
                    for e in routes.values()
                ),
                "pricing_status": "quote_required",
            }
            for model, routes in self.models.items()
        }
        return info

    def estimate_cost(self, inputs):
        raise PriceQuoteRequired(
            "Obtain a current price quote for this model, operation and resolution"
        )

    def build_request(self, inputs):
        model = inputs.get("model", next(iter(self.models)))
        routes = self.models.get(model, {})
        native_reference_fields = ("images", "image_input", "image", "image_uri")
        references = any(
            inputs.get(field)
            for field in (
                "image_url",
                "image_path",
                "image_urls",
                "image_paths",
                *native_reference_fields,
            )
        )
        operation = (
            inputs.get("generation_mode")
            or inputs.get("operation")
            or (
                "edit"
                if references and self.capability == "image_generation"
                else "image_to_video" if references else next(iter(routes), "")
            )
        )
        if operation == "generate" and self.capability == "video_generation":
            operation = "text_to_video"
        endpoint = routes.get(operation)
        if not endpoint:
            raise ValueError(f"Unsupported model/operation: {model}/{operation}")
        schema = self.contracts[endpoint]["input_schema"]
        props = schema["properties"]
        for field in native_reference_fields:
            if inputs.get(field) and field not in props:
                raise ValueError(f"{endpoint} does not accept {field}")
        payload = {k: v for k, v in inputs.items() if k in props and k != "model"}
        payload.update(inputs.get("provider_params") or {})
        if self.provider == "atlascloud":
            payload["model"] = endpoint
        if self.provider == "ltx":
            payload["model"] = model
        aliases = (
            {"mask_url": "mask", "generate_audio": "audio", "aspect_ratio": "ratio"}
            if self.provider == "atlascloud"
            else {}
        )
        for public, native in aliases.items():
            if public in inputs:
                if public in props:
                    continue
                if native not in props:
                    raise ValueError(f"{endpoint} does not support {public}")
                payload[native] = inputs[public]
        if inputs.get("mask_path"):
            if "mask" not in props:
                raise ValueError(f"{endpoint} does not accept a mask")
            payload["mask"] = local_image(inputs["mask_path"])
        refs = list(inputs.get("image_urls") or [])
        if inputs.get("image_url"):
            refs.insert(0, inputs["image_url"])
        paths = list(inputs.get("image_paths") or [])
        if inputs.get("image_path"):
            paths.insert(0, inputs["image_path"])
        refs.extend(local_image(p) for p in paths)
        if refs:
            target = (
                "images"
                if "images" in props
                else (
                    "image_input"
                    if "image_input" in props
                    else (
                        "image"
                        if "image" in props
                        else "image_uri" if "image_uri" in props else None
                    )
                )
            )
            if not target:
                raise ValueError(f"{endpoint} does not accept source images")
            if target in {"images", "image_input"}:
                payload[target] = list(payload.get(target) or []) + refs
            elif len(refs) == 1:
                if payload.get(target):
                    raise ValueError("Specify the source image only once")
                payload[target] = refs[0]
            else:
                raise ValueError("This route takes exactly one source image")
        for field in (
            "reference_image_urls",
            "reference_video_urls",
            "reference_audio_urls",
            "mask_url",
            "last_image",
            "last_frame_uri",
        ):
            if inputs.get(field) and field not in props and field not in aliases:
                raise ValueError(
                    f"{endpoint} does not support {field}; use its documented provider_params"
                )
        if self.provider == "replicate" and "allow_fallback_model" in props:
            if payload.get("allow_fallback_model"):
                raise ValueError(
                    "Model fallback is disabled; select the alternate model explicitly"
                )
            payload["allow_fallback_model"] = False
            if len(payload.get("image_input", [])) > 14:
                raise ValueError("At most 14 reference images")
        if (
            self.provider == "replicate"
            and operation == "image_to_video"
            and not payload.get("image")
        ):
            raise ValueError("image_to_video requires an image")
        if (
            self.provider == "replicate"
            and operation == "text_to_video"
            and payload.get("image")
        ):
            raise ValueError("Use image_to_video with a source image")
        if self.provider == "ltx":
            self.validate_ltx(payload, operation)
        Draft202012Validator(schema).validate(payload)
        return model, operation, endpoint, payload

    @staticmethod
    def validate_ltx(payload, operation):
        resolutions = {
            "1280x720",
            "720x1280",
            "1920x1080",
            "1080x1920",
            "2560x1440",
            "1440x2560",
            "3840x2160",
            "2160x3840",
        }
        if payload.get("resolution") not in resolutions:
            raise ValueError("Unsupported LTX-2.5 resolution")
        fps = payload.get("fps", 24)
        if fps not in {24, 25, 48, 50}:
            raise ValueError("LTX-2.5 supports 24, 25, 48 or 50 FPS")
        if operation != "audio_to_video":
            duration = payload.get("duration")
            max_duration = (
                20
                if payload["model"] == "ltx-2-5-fast"
                and fps in {24, 25}
                and payload["resolution"]
                in {"1280x720", "720x1280", "1920x1080", "1080x1920"}
                else 10
            )
            if duration is not None and duration not in range(6, max_duration + 1, 2):
                raise ValueError("Unsupported LTX duration for model/resolution/FPS")
            if duration is None and payload.get("last_frame_uri"):
                raise ValueError("Automatic duration cannot use a last frame")

    def execute(self, inputs):
        job = dict(inputs.get("resume_job") or {})
        try:
            key = os.environ[self.credential]
            headers = {"Authorization": f"Bearer {key}"}
            if not job:
                model, operation, endpoint, payload = self.build_request(inputs)
                if self.provider == "atlascloud":
                    action = (
                        "generateVideo"
                        if self.capability == "video_generation"
                        else "generateImage"
                    )
                    submitted = request_json(
                        "POST",
                        "https://api.atlascloud.ai/api/v1/model/" + action,
                        headers=headers,
                        json=payload,
                    )["data"]
                elif self.provider == "replicate":
                    submitted = request_json(
                        "POST",
                        "https://api.replicate.com/v1/models/"
                        + endpoint
                        + "/predictions",
                        headers=headers,
                        json={"input": payload},
                    )
                else:
                    submitted = request_json(
                        "POST",
                        "https://api.ltx.io/v2/" + endpoint,
                        headers=headers,
                        json=payload,
                    )
                job = {
                    "id": submitted["id"],
                    "model": model,
                    "operation": operation,
                    "endpoint": endpoint,
                    "tool": self.name,
                    "output_format": payload.get("output_format"),
                }
                save_job(inputs.get("job_path"), job)
            if job.get("tool") != self.name or self.models.get(
                job.get("model"), {}
            ).get(job.get("operation")) != job.get("endpoint"):
                raise ValueError("Resume job does not match this tool and route")
            identifier = quote(str(job["id"]), safe="")
            if self.provider == "atlascloud":
                url = "https://api.atlascloud.ai/api/v1/model/prediction/" + identifier
            elif self.provider == "replicate":
                url = "https://api.replicate.com/v1/predictions/" + identifier
            else:
                url = "https://api.ltx.io/v2/" + job["endpoint"] + "/" + identifier

            def fetch():
                response = request_json("GET", url, headers=headers)
                return response["data"] if self.provider == "atlascloud" else response

            result = poll(
                fetch,
                timeout=float(inputs.get("poll_timeout", 900)),
                interval=float(inputs.get("poll_interval", 2)),
            )
            values = (
                result.get("outputs")
                if self.provider == "atlascloud"
                else (
                    result.get("output")
                    if self.provider == "replicate"
                    else result.get("result", {}).get("video_url")
                )
            )
            if isinstance(values, str):
                values = [values]
            if not values:
                raise ValueError("Completed job returned no media")
            ext = (
                "mp4"
                if self.capability == "video_generation"
                else job.get("output_format")
                or ("jpg" if self.provider == "replicate" else "png")
            )
            path = Path(inputs.get("output_path") or self.name + "." + ext)
            outputs = [
                download(
                    value,
                    (
                        path
                        if i == 0
                        else path.with_name(f"{path.stem}_{i + 1}{path.suffix}")
                    ),
                )
                for i, value in enumerate(values)
            ]
            return ToolResult(
                success=True,
                data={
                    "provider": self.provider,
                    "model": job["model"],
                    "operation": job["operation"],
                    "output": outputs[0],
                    "outputs": outputs,
                    "resume_job": job,
                    "cost_status": "unquoted",
                    "provider_result": result,
                },
                artifacts=outputs,
                cost_usd=None,
                model=job["model"],
            )
        except Exception as exc:
            return ToolResult(
                success=False, error=str(exc), data={"resume_job": job} if job else {}
            )

tools/tool_registry.py:
"""Tool registry with status, stability, and support-envelope reporting.

The registry discovers all registered tools, reports their availability,
and lets the orchestrator/agents query capabilities by tier, status, etc.
"""

from __future__ import annotations

import importlib
import inspect
import pkgutil
from collections.abc import Iterable
from types import ModuleType
from typing import Any, Optional

from tools.base_tool import BaseTool, ToolStatus, ToolTier, ToolStability


# Unicode punctuation that breaks on Windows cp1252 stdout. Map each to an
# ASCII equivalent. This only touches strings rendered by registry helpers
# that an agent is likely to print to the user at preflight — not docstrings,
# comments, or markdown.
_UNICODE_DASH_REPLACEMENTS = {
    "\u2014": "--",   # em dash
    "\u2013": "-",    # en dash
    "\u2212": "-",    # minus sign
    "\u2018": "'",    # left single quote
    "\u2019": "'",    # right single quote
    "\u201c": '"',    # left double quote
    "\u201d": '"',    # right double quote
    "\u2026": "...",  # ellipsis
}


def _scrub_unicode_dashes(value: Any) -> Any:
    """Recursively normalize unicode punctuation in str leaves to ASCII.

    Used to keep `provider_menu_summary()` output readable on Windows cp1252
    stdout. Does NOT modify dict/list structure or non-string values.
    """
    if isinstance(value, str):
        out = value
        for needle, repl in _UNICODE_DASH_REPLACEMENTS.items():
            if needle in out:
                out = out.replace(needle, repl)
        return out
    if isinstance(value, list):
        return [_scrub_unicode_dashes(item) for item in value]
    if isinstance(value, tuple):
        return tuple(_scrub_unicode_dashes(item) for item in value)
    if isinstance(value, dict):
        return {k: _scrub_unicode_dashes(v) for k, v in value.items()}
    return value


class ToolRegistry:
    """Central registry of all OpenMontage tools."""

    def __init__(self) -> None:
        self._tools: dict[str, BaseTool] = {}
        self._discovered_packages: set[str] = set()

    def register(self, tool: BaseTool) -> None:
        """Register a tool instance."""
        if not tool.name:
            raise ValueError("Tool must have a non-empty name")
        self._tools[tool.name] = tool

    def clear(self) -> None:
        """Clear registered tools and discovery state."""
        self._tools.clear()
        self._discovered_packages.clear()

    def register_module(self, module: ModuleType) -> list[str]:
        """Register all concrete BaseTool subclasses defined in a module."""
        registered: list[str] = []
        for _, cls in inspect.getmembers(module, inspect.isclass):
            if cls is BaseTool or not issubclass(cls, BaseTool):
                continue
            if cls.__module__ != module.__name__ or inspect.isabstract(cls):
                continue
            tool = cls()
            self.register(tool)
            registered.append(tool.name)
        return registered

    @staticmethod
    def _load_dotenv() -> None:
        """Load .env file into os.environ if present, so tools can find API keys."""
        from pathlib import Path
        import os
        env_path = Path(__file__).resolve().parent.parent / ".env"
        if not env_path.is_file():
            return
        import re
        with open(env_path, encoding="utf-8", errors="ignore") as f:
            for line in f:
                line = line.strip()
                if not line or line.startswith("#") or "=" not in line:
                    continue
                key, _, value = line.partition("=")
                key = key.strip()
                value = value.strip()
                # Quoted value: take the content inside the quotes verbatim.
                if value[:1] in ("'", '"'):
                    quote = value[0]
                    end = value.find(quote, 1)
                    value = value[1:end] if end != -1 else value[1:]
                else:
                    # Strip an inline comment ('#' at line start or after
                    # whitespace) so "KEY=   # note" yields "" not "# note".
                    match = re.search(r"(^|\s)#", value)
                    if match:
                        value = value[: match.start()]
                    value = value.strip()
                if key and (key not in os.environ or not os.environ[key].strip()):
                    os.environ[key] = value

    def discover(self, package_name: str = "tools") -> list[str]:
        """Import a package tree and register any concrete tools it defines."""
        self._load_dotenv()
        package = importlib.import_module(package_name)
        discovered: list[str] = []
        package_paths = getattr(package, "__path__", None)
        if package_paths is None:
            return self.register_module(package)

        for module_info in pkgutil.walk_packages(package_paths, f"{package.__name__}."):
            if module_info.name.endswith(".base_tool") or module_info.name.endswith(".tool_registry"):
                continue
            module = importlib.import_module(module_info.name)
            discovered.extend(self.register_module(module))

        self._discovered_packages.add(package_name)
        return discovered

    def ensure_discovered(self, package_name: str = "tools") -> None:
        """Load tool modules once before reporting capabilities."""
        if package_name not in self._discovered_packages:
            self.discover(package_name)

    def get(self, name: str) -> Optional[BaseTool]:
        """Get a tool by name."""
        return self._tools.get(name)

    def list_all(self) -> list[str]:
        """List all registered tool names."""
        return list(self._tools.keys())

    def get_by_tier(self, tier: ToolTier) -> list[BaseTool]:
        """Get all tools in a given tier."""
        return [t for t in self._tools.values() if t.tier == tier]

    def get_by_capability(self, capability: str) -> list[BaseTool]:
        """Get all tools registered for a top-level capability family."""
        return [t for t in self._tools.values() if t.capability == capability]

    def capability_coverage(self, tool_names: Iterable[str]) -> dict[str, dict[str, int]]:
        """Count available concrete providers for capabilities touched by tools.

        Selector tools identify a capability but are excluded from its provider
        totals. Unknown tool names are ignored so stale optional manifest entries
        do not hide coverage for tools that are still registered.
        """
        self.ensure_discovered()
        capabilities = {
            tool.capability
            for name in tool_names
            if (tool := self._tools.get(name)) is not None
        }
        coverage: dict[str, dict[str, int]] = {}
        for capability in sorted(capabilities):
            providers = [
                tool
                for tool in self._tools.values()
                if tool.capability == capability and tool.provider != "selector"
            ]
            coverage[capability] = {
                "available": sum(
                    tool.get_status() == ToolStatus.AVAILABLE for tool in providers
                ),
                "total": len(providers),
            }
        return coverage

    def uncovered_capabilities(self, tool_names: Iterable[str]) -> list[str]:
        """Return touched capability families with no available provider."""
        return [
            capability
            for capability, counts in self.capability_coverage(tool_names).items()
            if counts["available"] == 0
        ]

    def get_by_provider(self, provider: str) -> list[BaseTool]:
        """Get all tools backed by a specific provider."""
        return [t for t in self._tools.values() if t.provider == provider]

    def get_by_status(self, status: ToolStatus) -> list[BaseTool]:
        """Get all tools with a given status."""
        return [t for t in self._tools.values() if t.get_status() == status]

    def get_available(self) -> list[BaseTool]:
        """Get all tools that are currently available."""
        return self.get_by_status(ToolStatus.AVAILABLE)

    def get_unavailable(self) -> list[BaseTool]:
        """Get all tools that are currently unavailable."""
        return self.get_by_status(ToolStatus.UNAVAILABLE)

    def get_by_stability(self, stability: ToolStability) -> list[BaseTool]:
        """Get all tools at a given stability level."""
        return [t for t in self._tools.values() if t.stability == stability]

    def find_by_capability(self, capability: str) -> list[BaseTool]:
        """Find tools that declare a given capability."""
        return [
            t for t in self._tools.values()
            if capability in t.capabilities
        ]

    def find_fallback(self, tool_name: str) -> Optional[BaseTool]:
        """Find the fallback tool for a given tool, if declared and available."""
        tool = self.get(tool_name)
        if tool is None:
            return None
        candidates = list(tool.fallback_tools or [])
        if tool.fallback and tool.fallback not in candidates:
            candidates.append(tool.fallback)
        for name in candidates:
            fb = self.get(name)
            if fb and fb.get_status() == ToolStatus.AVAILABLE:
                return fb
        return None

    def support_envelope(self) -> dict[str, Any]:
        """Generate a full support-envelope report for all tools.

        Returns a dict mapping tool name to its contract info + live status.
        This is the primary report the orchestrator uses to understand
        what the system can and cannot do.
        """
        self.ensure_discovered()
        report: dict[str, Any] = {}
        for name, tool in self._tools.items():
            info = tool.get_info()
            report[name] = info
        return report

    def capability_catalog(self) -> dict[str, list[dict[str, Any]]]:
        """Group the support envelope by top-level capability."""
        self.ensure_discovered()
        grouped: dict[str, list[dict[str, Any]]] = {}
        for tool in self._tools.values():
            grouped.setdefault(tool.capability, []).append(tool.get_info())
        for items in grouped.values():
            items.sort(key=lambda item: (item["provider"], item["name"]))
        return dict(sorted(grouped.items()))

    def provider_catalog(self) -> dict[str, list[dict[str, Any]]]:
        """Group the support envelope by provider."""
        self.ensure_discovered()
        grouped: dict[str, list[dict[str, Any]]] = {}
        for tool in self._tools.values():
            grouped.setdefault(tool.provider, []).append(tool.get_info())
        for items in grouped.values():
            items.sort(key=lambda item: (item["capability"], item["name"]))
        return dict(sorted(grouped.items()))

    def tier_summary(self) -> dict[str, dict[str, int]]:
        """Summarize tool counts by tier and status.

        Returns:
            {"core": {"available": 5, "unavailable": 2, "degraded": 0}, ...}
        """
        summary: dict[str, dict[str, int]] = {}
        for tier in ToolTier:
            tier_tools = self.get_by_tier(tier)
            counts = {"available": 0, "unavailable": 0, "degraded": 0}
            for t in tier_tools:
                status = t.get_status().value
                counts[status] = counts.get(status, 0) + 1
            if tier_tools:
                summary[tier.value] = counts
        return summary

    def provider_menu(self) -> dict[str, dict[str, Any]]:
        """Generate a capability-grouped provider menu for user-facing display.

        Returns a dict like:
        {
            "video_generation": {
                "available": [{"name": ..., "provider": ..., "best_for": ...}],
                "unavailable": [{"name": ..., "provider": ..., "install_instructions": ...}],
                "total": 12,
                "configured": 2,
            },
            ...
        }

        This powers the agent's preflight provider menu — the agent reads this
        output and presents it to the user.  Adding a new tool to tools/ is
        enough; this method auto-discovers it.
        """
        self.ensure_discovered()
        menu: dict[str, dict[str, Any]] = {}

        # Skip selectors — they aggregate, they aren't providers themselves
        tools = [t for t in self._tools.values() if t.provider != "selector"]

        for tool in tools:
            cap = tool.capability
            if cap not in menu:
                menu[cap] = {"available": [], "unavailable": [], "total": 0, "configured": 0}

            info = tool.get_info()
            status = tool.get_status()
            entry = {
                "name": tool.name,
                "provider": tool.provider,
                "runtime": tool.runtime.value,
                "best_for": tool.best_for,
                "dependencies": info.get("dependencies", []),
                "install_instructions": tool.install_instructions,
                "status": status.value,
            }
            for extra_key in (
                "source_provider_menu",
                "source_provider_summary",
                "render_engines",
                "remotion_note",
                "provider_matrix",
                "setup_offer",
                "operation_statuses",
                "resource_profiles",
                "resource_profile_note",
            ):
                if extra_key in info:
                    entry[extra_key] = info[extra_key]

            if status == ToolStatus.AVAILABLE:
                menu[cap]["available"].append(entry)
                menu[cap]["configured"] += 1
            else:
                menu[cap]["unavailable"].append(entry)
            menu[cap]["total"] += 1

        for bucket in menu.values():
            bucket["available"].sort(key=lambda entry: (entry["provider"], entry["name"]))
            bucket["unavailable"].sort(key=lambda entry: (entry["provider"], entry["name"]))

        return dict(sorted(menu.items()))

    def provider_menu_summary(self) -> dict[str, Any]:
        """Compact, human-ready rollup of provider_menu() for onboarding/preflight.

        Returns a dict shaped for the "N of M configured" capability menu the
        agent is supposed to present to the user per AGENT_GUIDE.md → "Provider
        Menu (Mandatory at Preflight)". Collapses the firehose of
        support_envelope() into something the agent can paraphrase in plain
        language in a few lines.

        Example output (abbreviated):
        {
          "composition_runtimes": {
            "ffmpeg": True,
            "remotion": True,
            "hyperframes": True,
          },
          "capabilities": [
            {"capability": "video_generation", "configured": 10, "total": 16,
             "available_providers": ["fal", "heygen", ...],
             "unavailable_providers": ["openai", ...]},
            ...
          ],
          "setup_offers": [
             {"capability": "music_generation", "tool": "suno_music",
              "install_instructions": "Add SUNO_API_KEY to .env"},
             ...
          ],
          "runtime_warnings": [
             "hyperframes: npm package `hyperframes` not resolvable: ...",
             ...
          ],
        }

        Agents should use this as the source for the preflight capability
        menu rather than rendering `support_envelope()` or `provider_menu()`
        raw. See AGENT_GUIDE.md > "Provider Menu (Mandatory at Preflight)".
        """
        self.ensure_discovered()
        menu = self.provider_menu()

        # Composition runtimes — lift from video_compose.get_info() since
        # they're the signal the runtime-selection contract depends on.
        comp_runtimes: dict[str, bool] = {}
        runtime_warnings: list[str] = []
        vc = self._tools.get("video_compose")
        if vc is not None:
            info = vc.get_info()
            engines = info.get("render_engines") or {}
            comp_runtimes = {k: bool(v) for k, v in engines.items()}
        # If hyperframes_compose is registered, surface its npm-resolve reasons
        # explicitly — those are the "looks available but isn't" failures.
        hf = self._tools.get("hyperframes_compose")
        if hf is not None:
            hf_info = hf.get_info()
            rc = hf_info.get("hyperframes_runtime") or {}
            for reason in rc.get("reasons") or []:
                runtime_warnings.append(f"hyperframes: {reason}")

        diagram_gen = self._tools.get("diagram_gen")
        if diagram_gen is not None:
            operation_statuses = diagram_gen.get_info().get("operation_statuses") or {}
            if operation_statuses.get("mermaid") != "available":
                runtime_warnings.append(
                    "diagram_gen: Mermaid CLI (mmdc) is unavailable; install with "
                    "npm install -g @mermaid-js/mermaid-cli"
                )

        # Capabilities rollup (configured/total + provider lists).
        # When a provider has multiple tools (e.g. seedance-fal and
        # seedance-replicate both reporting provider="seedance"), a
        # naive set-split shows the provider in BOTH available and
        # unavailable — confusing for users. Dedupe: if the provider has
        # any available tool, do NOT list it as unavailable.
        capabilities: list[dict[str, Any]] = []
        for cap, bucket in menu.items():
            available_providers = {
                e.get("provider") for e in bucket.get("available", [])
            } - {None}
            unavailable_providers = (
                {e.get("provider") for e in bucket.get("unavailable", [])}
                - {None}
                - available_providers  # provider with any available tool wins
            )
            capabilities.append(
                {
                    "capability": cap,
                    "configured": bucket.get("configured", 0),
                    "total": bucket.get("total", 0),
                    "available_providers": sorted(available_providers),
                    "unavailable_providers": sorted(unavailable_providers),
                }
            )

        # Setup offers — unavailable tools that would be 1-minute env-var fixes.
        # Filter for short install instructions referencing an env var so the
        # agent can lead with the easy wins.
        setup_offers: list[dict[str, Any]] = []
        for cap, bucket in menu.items():
            for entry in bucket.get("unavailable", []):
                offer = entry.get("setup_offer")
                if offer:
                    setup_offers.append(
                        {
                            "capability": cap,
                            "tool": entry.get("name"),
                            "provider": entry.get("provider"),
                            "runtime": entry.get("runtime"),
                            "install_instructions": entry.get("install_instructions") or "",
                            **offer,
                        }
                    )
                    continue

                env_vars = [
                    dep[4:]
                    for dep in entry.get("dependencies", [])
                    if isinstance(dep, str) and dep.startswith("env:")
                ]
                if env_vars:
                    setup_offers.append(
                        {
                            "capability": cap,
                            "tool": entry.get("name"),
                            "provider": entry.get("provider"),
                            "runtime": entry.get("runtime"),
                            "kind": "env_var",
                            "fix_complexity": "1-minute env-var",
                            "env_vars": env_vars,
                            "install_instructions": entry.get("install_instructions") or "",
                        }
                    )
                    continue

                hint = entry.get("install_instructions") or ""
                # Heuristic: 1-minute fixes mention an env var or API key.
                if any(k in hint.lower() for k in ["api key", "env", "_key=", "_api"]):
                    setup_offers.append(
                        {
                            "capability": cap,
                            "tool": entry.get("name"),
                            "provider": entry.get("provider"),
                            "runtime": entry.get("runtime"),
                            "install_instructions": hint,
                        }
                    )

            for entry in bucket.get("available", []) + bucket.get("unavailable", []):
                if entry.get("resource_profile_note"):
                    runtime_warnings.append(
                        f"{entry.get('name')}: {entry.get('resource_profile_note')}"
                    )

        result = {
            "composition_runtimes": comp_runtimes,
            "capabilities": capabilities,
            "setup_offers": setup_offers,
            "runtime_warnings": runtime_warnings,
        }
        # Normalize em-dashes and en-dashes to ASCII so preflight output prints
        # cleanly on Windows cp1252 stdout (the default on Git Bash / PowerShell
        # without PYTHONIOENCODING=utf-8). Agents paste this dict into chat; a
        # mojibake `�` in an install_instructions string looks like a bug.
        # Markdown docs keep their typographic dashes; this only touches the
        # runtime-reported strings.
        return _scrub_unicode_dashes(result)

    # Post-hoc fix: narrow helper that keeps the registry output stdout-safe on
    # Windows cp1252 without imposing a new style rule on every tool author.

    def gpu_required_tools(self) -> list[str]:
        """List tools that require GPU (VRAM > 0)."""
        return [
            t.name for t in self._tools.values()
            if t.resource_profile.vram_mb > 0
        ]

    def network_required_tools(self) -> list[str]:
        """List tools that require network access."""
        return [
            t.name for t in self._tools.values()
            if t.resource_profile.network_required
        ]


# Singleton registry instance
registry = ToolRegistry()

