        "Play the rendered MP4 and verify scene pacing, typography, and audio",
        "Inspect workspace_path/index.html in a browser via `npx hyperframes preview`",
    ]

    # ------------------------------------------------------------------
    # Status / availability
    # ------------------------------------------------------------------

    _NODE_FLOOR_MAJOR = 22
    _NPM_PACKAGE = "hyperframes"  # published npm name (NOT @hyperframes/cli — that's 404)
    # Process-level cache for the npm resolve check. Shape:
    #   {"version": "0.4.5"}   → package resolves
    #   {"error": "<short>"}   → resolution failed (offline, unpublished, etc.)
    # We cache per-process so the first call pays ~2-5s and subsequent calls
    # (get_info spam from the registry) are free. Only definitive answers are
    # cached — a timeout or network error is retried on the next call so one
    # slow registry round-trip cannot poison the rest of the run.
    _npm_resolve_cache: Optional[dict[str, str]] = None
    _cli_probe_cache: Optional[dict[str, str]] = None

    @classmethod
    def _node_major_version(cls) -> Optional[int]:
        """Return Node.js major version, or None if node isn't installed."""
        node = shutil.which("node")
        if not node:
            return None
        try:
            out = subprocess.run(
                [node, "--version"], capture_output=True, text=True, timeout=5
            )
            if out.returncode != 0:
                return None
            match = re.match(r"v?(\d+)\.", out.stdout.strip())
            if not match:
                return None
            return int(match.group(1))
        except (OSError, subprocess.SubprocessError):
            return None

    @classmethod
    def _resolve_npm_package(cls) -> dict[str, str]:
        """Verify the `hyperframes` npm package actually resolves.

        `_runtime_check` previously only verified that node/ffmpeg/npx existed
        on PATH, which meant `runtime_available: True` on any machine with
        Node + FFmpeg — even offline, even if npm was down, even if the
        package was unpublished. This method performs a cheap
        `npm view hyperframes version` (5s timeout) and caches the answer
        for the rest of the process.

        `npx` runs the CLI from its local cache, so a machine that has already
        installed the package can render with a slow or unreachable registry.
        The cache is therefore checked first (`npx --offline`); the registry is
        only consulted when nothing is cached, i.e. when an install is needed.

        Returns {"version": "X.Y.Z"} on success, {"error": "<short>"} on any
        failure (404, timeout, network error, npm missing). Never raises.
        """
        if cls._npm_resolve_cache is not None:
            return cls._npm_resolve_cache

        cached = cls._cached_cli_version()
        if cached:
            cls._npm_resolve_cache = {"version": cached}
            return cls._npm_resolve_cache

        npm = shutil.which("npm")
        if not npm:
            cls._npm_resolve_cache = {"error": "npm not on PATH"}
            return cls._npm_resolve_cache

        try:
            proc = subprocess.run(
                [npm, "view", cls._NPM_PACKAGE, "version"],
                capture_output=True,
                text=True,
                timeout=5,
            )
        except subprocess.TimeoutExpired:
            return {"error": "timeout (5s) — offline or slow registry"}
        except (OSError, subprocess.SubprocessError) as e:
            return {"error": f"npm view failed: {type(e).__name__}"}

        if proc.returncode != 0:
            stderr = (proc.stderr or "").strip()
            # Most common failure is 404 (package unpublished or name wrong).
            if "404" in stderr or "E404" in stderr:
                cls._npm_resolve_cache = {
                    "error": f"npm package `{cls._NPM_PACKAGE}` not found (404)"
                }
                return cls._npm_resolve_cache
            # Anything else (ETIMEDOUT, ENOTFOUND, ...) is treated as transient.
            tail = stderr.splitlines()[-1][:200] if stderr else f"exit {proc.returncode}"
            return {"error": f"npm view failed: {tail}"}

        version = (proc.stdout or "").strip()
        if not version:
            cls._npm_resolve_cache = {"error": "npm view returned empty version"}
        else:
            cls._npm_resolve_cache = {"version": version}
        return cls._npm_resolve_cache

    @classmethod
    def _cached_cli_version(cls) -> Optional[str]:
        """Return the CLI version from the local npx cache, or None.

        `--offline` makes npm fail fast with ENOTCACHED instead of touching
        the network, so this costs well under a second on a cold cache.
        """
        npx = shutil.which("npx")
        if not npx:
            return None
        try:
            proc = subprocess.run(
                [npx, "--offline", cls._NPM_PACKAGE, "--version"],
                capture_output=True,
                text=True,
                timeout=15,
            )
        except (OSError, subprocess.SubprocessError):
            return None
        if proc.returncode != 0:
            return None
        lines = (proc.stdout or "").strip().splitlines()
        return lines[-1].strip() if lines else None

    @classmethod
    def _probe_cli(cls) -> dict[str, str]:
        """Run the published CLI's doctor command once per process.

        Package resolution alone does not prove that the executable can start:
        an upstream packaging regression can publish successfully while every
        CLI command crashes during bootstrap. Provider preflight must not call
        that state available.
        """
        if cls._cli_probe_cache is not None:
            return cls._cli_probe_cache

        npx = shutil.which("npx")
        if not npx:
            cls._cli_probe_cache = {"error": "npx not on PATH"}
            return cls._cli_probe_cache

        try:
            proc = subprocess.run(
                [npx, "--yes", cls._NPM_PACKAGE, "doctor", "--json"],
                capture_output=True,
                text=True,
                timeout=20,
            )
        except subprocess.TimeoutExpired:
            # Not cached: a slow run says nothing about whether the CLI works.
            return {"error": "doctor timed out after 20s"}
        except (OSError, subprocess.SubprocessError) as exc:
            return {"error": f"doctor failed: {type(exc).__name__}"}

        if proc.returncode != 0:
            output = "\n".join(filter(None, [proc.stderr, proc.stdout])).strip()
            tail = output.splitlines()[-1][:200] if output else f"exit {proc.returncode}"
            cls._cli_probe_cache = {"error": f"doctor failed: {tail}"}
        else:
            cls._cli_probe_cache = {"status": "ok"}
        return cls._cli_probe_cache

    def _runtime_check(self) -> dict[str, Any]:
        """Return availability state for the HyperFrames runtime.

        Checks BOTH local binaries (node >= 22, ffmpeg, npx) AND that the
        `hyperframes` npm package actually resolves. A missing/404 package
        counts as unavailable — `runtime_available: True` means the runtime
        can genuinely run end-to-end, not just that the local tooling exists.
        """
        node_major = self._node_major_version()
        ffmpeg_ok = shutil.which("ffmpeg") is not None
        npx_ok = shutil.which("npx") is not None

        reasons: list[str] = []
        if node_major is None:
            reasons.append("node not found on PATH")
        elif node_major < self._NODE_FLOOR_MAJOR:
            reasons.append(
                f"node major version {node_major} < required {self._NODE_FLOOR_MAJOR}"
            )
        if not npx_ok:
            reasons.append("npx not found on PATH")
        if not ffmpeg_ok:
            reasons.append("ffmpeg not found on PATH")

        # Only probe npm if the local tooling is actually usable — otherwise
        # a missing-node run would also show a confusing npm error.
        npm_resolve: dict[str, str] = {}
        if not reasons:
            npm_resolve = self._resolve_npm_package()
            if "error" in npm_resolve:
                reasons.append(
                    f"npm package `{self._NPM_PACKAGE}` not resolvable: "
                    f"{npm_resolve['error']}"
                )

        cli_probe: dict[str, str] = {}
        if not reasons:
            cli_probe = self._probe_cli()
            if "error" in cli_probe:
                reasons.append(f"published CLI is not executable: {cli_probe['error']}")

        return {
            "runtime_available": not reasons,
            "node_major": node_major,
            "ffmpeg_available": ffmpeg_ok,
            "npx_available": npx_ok,
            "npm_package": self._NPM_PACKAGE,
            "npm_package_version": npm_resolve.get("version"),
            "npm_resolve_error": npm_resolve.get("error"),
            "cli_probe_status": cli_probe.get("status"),
            "cli_probe_error": cli_probe.get("error"),
            "reasons": reasons,
        }

    def get_status(self) -> ToolStatus:
        check = self._runtime_check()
        return ToolStatus.AVAILABLE if check["runtime_available"] else ToolStatus.UNAVAILABLE

    def get_info(self) -> dict[str, Any]:
        info = super().get_info()
        check = self._runtime_check()
        info["hyperframes_runtime"] = check
        if not check["runtime_available"]:
            info["setup_offer"] = {
                "effort": (
                    "1-minute fix"
                    if check["npx_available"] and check["ffmpeg_available"]
                    else "5-minute fix (install Node 22+ and/or FFmpeg)"
                ),
                "install_instructions": self.install_instructions,
                "unlocks": (
                    "HTML/CSS/GSAP composition runtime — kinetic typography, "
                    "product promos, registry blocks, website-to-video."
                ),
            }
        return info

    def estimate_cost(self, inputs: dict[str, Any]) -> float:
        return 0.0

    def estimate_runtime(self, inputs: dict[str, Any]) -> float:
        ed = inputs.get("edit_decisions") or {}
        cuts = ed.get("cuts", [])
        total = 0.0
        for c in cuts:
            out_s = float(c.get("out_seconds", 0) or 0)
            in_s = float(c.get("in_seconds", 0) or 0)
            total += max(0.0, out_s - in_s)
        return 30.0 + total * 0.5

    # ------------------------------------------------------------------
    # Execute
    # ------------------------------------------------------------------

    def execute(self, inputs: dict[str, Any]) -> ToolResult:
        operation = inputs["operation"]
        start = time.time()
        try:
            if operation == "doctor":
                result = self._doctor(inputs)
            elif operation == "scaffold_workspace":
                result = self._scaffold(inputs)
            elif operation == "lint":
                result = self._lint(inputs)
            elif operation == "validate":
                result = self._validate(inputs)
            elif operation == "inspect":
                result = self._inspect(inputs)
            elif operation == "check":
                result = self._check(inputs)
            elif operation == "render":
                result = self._render(inputs)
            elif operation == "render_existing":
                result = self._render_existing(inputs)
            elif operation == "add_block":
                result = self._add_block(inputs)
            else:
                return ToolResult(success=False, error=f"Unknown operation: {operation}")
        except Exception as e:
            log.exception("hyperframes_compose failed")
            return ToolResult(success=False, error=f"{type(e).__name__}: {e}")

        result.duration_seconds = round(time.time() - start, 2)
        return result

    # ------------------------------------------------------------------
    # Operations
    # ------------------------------------------------------------------

    def _doctor(self, inputs: dict[str, Any]) -> ToolResult:
        """Probe the environment. Reports node/ffmpeg/npx plus CLI doctor output."""
        check = self._runtime_check()
        out: dict[str, Any] = {"runtime_check": check}

        if not check["runtime_available"]:
            return ToolResult(
                success=False,
                error=(
                    "HyperFrames runtime floor not met: "
                    + "; ".join(check["reasons"])
                ),
                data=out,
            )

        # Ask the CLI itself for a deeper check. This also warms the npm
        # cache so the first real render doesn't pay the download cost.
        try:
            proc = self._run_hf(["doctor"], cwd=None, timeout=180, check=False)
            out["cli_doctor"] = {
                "exit_code": proc.returncode,
                "stdout_tail": (proc.stdout or "")[-4000:],
                "stderr_tail": (proc.stderr or "")[-4000:],
            }
            ok = proc.returncode == 0
            return ToolResult(
                success=ok,
                data=out,
                error=None if ok else f"hyperframes doctor exit {proc.returncode}",
            )
        except Exception as e:
            out["cli_doctor_error"] = str(e)
            return ToolResult(
                success=False,
                error=f"hyperframes doctor failed: {e}",
                data=out,
            )

    def _scaffold(self, inputs: dict[str, Any]) -> ToolResult:
        """Materialize the HyperFrames workspace from OpenMontage artifacts.

        This does NOT call `hyperframes init` — we want full control over the
        generated files so they map cleanly to edit_decisions. `init` is
        meant for humans bootstrapping a project by hand.
        """
        workspace = self._require_workspace(inputs)
        edit_decisions = inputs.get("edit_decisions") or {}
        asset_manifest = inputs.get("asset_manifest") or {}
        playbook = inputs.get("playbook") or {}
        profile_name = inputs.get("profile")

        if not edit_decisions.get("cuts"):
            return ToolResult(
                success=False,
                error="edit_decisions with non-empty cuts[] is required for scaffold_workspace",
            )

        width, height, fps = self._resolve_dimensions(profile_name, inputs.get("fps", 30))

        workspace.mkdir(parents=True, exist_ok=True)
        (workspace / "compositions").mkdir(exist_ok=True)
        assets_dir = workspace / "assets"
        assets_dir.mkdir(exist_ok=True)

        # Resolve asset IDs → file paths + copy into workspace.
        resolved_cuts, asset_copies = self._resolve_and_stage_assets(
            edit_decisions.get("cuts", []),
            asset_manifest.get("assets", []),
            workspace,
        )

        audio_refs = self._resolve_audio_refs(
            edit_decisions.get("audio", {}),
            asset_manifest.get("assets", []),
            workspace,
        )

        # Style bridge: playbook → CSS custom properties + DESIGN.md.
        css_vars, design_md = self._style_bridge(playbook, edit_decisions)

        # Write hyperframes.json (registry config).
        (workspace / "hyperframes.json").write_text(
            json.dumps(
                {
                    "registry": "https://raw.githubusercontent.com/heygen-com/hyperframes/main/registry",
                    "paths": {
                        "blocks": "compositions",
                        "components": "compositions/components",
                        "assets": "assets",
                    },
                },
                indent=2,
            ),
            encoding="utf-8",
        )

        # Write DESIGN.md (convenience file for human review + workspace context).
        if design_md:
            (workspace / "DESIGN.md").write_text(design_md, encoding="utf-8")

        # Write index.html — the main composition.
        total_duration = self._compute_total_duration(resolved_cuts)
        html = self._generate_index_html(
            cuts=resolved_cuts,
            audio_refs=audio_refs,
            width=width,
            height=height,
            total_duration=total_duration,
            css_vars=css_vars,
            title=edit_decisions.get("metadata", {}).get("title")
            or f"OpenMontage {edit_decisions.get('renderer_family', 'composition')}",
        )
        (workspace / "index.html").write_text(html, encoding="utf-8")

        return ToolResult(
            success=True,
            data={
                "operation": "scaffold_workspace",
                "workspace": str(workspace),
                "width": width,
                "height": height,
                "fps": fps,
                "total_duration_seconds": total_duration,
                "cut_count": len(resolved_cuts),
                "asset_copies": asset_copies,
            },
            artifacts=[str(workspace / "index.html")],
        )

    def _lint(self, inputs: dict[str, Any]) -> ToolResult:
        workspace = self._require_workspace(inputs)
        if not (workspace / "index.html").exists():
            return ToolResult(
                success=False,
                error=f"No index.html in {workspace}. Run scaffold_workspace first.",
            )
        proc = self._run_hf(["lint", "--json"], cwd=workspace, timeout=120, check=False)
        data: dict[str, Any] = {"exit_code": proc.returncode}
        payload = self._parse_json_output(proc.stdout)
        if payload is not None:
            data["report"] = payload
        else:
            data["stdout_tail"] = (proc.stdout or "")[-4000:]
        data["stderr_tail"] = (proc.stderr or "")[-2000:]
        ok = proc.returncode == 0
        return ToolResult(
            success=ok,
            data=data,
            error=None if ok else f"hyperframes lint exit {proc.returncode}",
        )

    def _validate(self, inputs: dict[str, Any]) -> ToolResult:
        workspace = self._require_workspace(inputs)
        if not (workspace / "index.html").exists():
            return ToolResult(
                success=False,
                error=f"No index.html in {workspace}. Run scaffold_workspace first.",
            )
        args = ["validate", "--json"]
        if inputs.get("skip_contrast"):
            args.append("--no-contrast")
        proc = self._run_hf(args, cwd=workspace, timeout=300, check=False)
        data: dict[str, Any] = {"exit_code": proc.returncode}
        payload = self._parse_json_output(proc.stdout)
        if payload is not None:
            data["report"] = payload
        else:
            data["stdout_tail"] = (proc.stdout or "")[-4000:]
        data["stderr_tail"] = (proc.stderr or "")[-2000:]
        ok = proc.returncode == 0
        return ToolResult(
            success=ok,
            data=data,
            error=None if ok else f"hyperframes validate exit {proc.returncode}",
        )

    def _inspect(self, inputs: dict[str, Any]) -> ToolResult:
        """Seek through an authored workspace and audit runtime/layout issues."""
        workspace = self._require_workspace(inputs)
        if not (workspace / "index.html").exists():
            return ToolResult(
                success=False,
                error=f"No index.html in {workspace}.",
            )
        proc = self._run_hf(["inspect", "--json"], cwd=workspace, timeout=300, check=False)
        data: dict[str, Any] = {"exit_code": proc.returncode}
        payload = self._parse_json_output(proc.stdout)
        if payload is not None:
            data["report"] = payload
        else:
            data["stdout_tail"] = (proc.stdout or "")[-4000:]
        data["stderr_tail"] = (proc.stderr or "")[-2000:]
        ok = proc.returncode == 0
        return ToolResult(
            success=ok,
            data=data,
            error=None if ok else f"hyperframes inspect exit {proc.returncode}",
        )

    def _check(self, inputs: dict[str, Any]) -> ToolResult:
        """Run the unified HyperFrames quality gate for authored workspaces."""
        workspace = self._require_workspace(inputs)
        if not (workspace / "index.html").exists():
            return ToolResult(success=False, error=f"No index.html in {workspace}.")
        args = ["check", "--json"]
        if inputs.get("skip_contrast", False):
            args.append("--no-contrast")
        if inputs.get("strict_check", False):
            args.append("--strict")
        if inputs.get("snapshots", False):
            args.append("--snapshots")
        proc = self._run_hf(args, cwd=workspace, timeout=300, check=False)
        data: dict[str, Any] = {"exit_code": proc.returncode}
        payload = self._parse_json_output(proc.stdout)
        if payload is not None:
            data["report"] = payload
        else:
            data["stdout_tail"] = (proc.stdout or "")[-4000:]
        data["stderr_tail"] = (proc.stderr or "")[-2000:]
        ok = proc.returncode == 0
        return ToolResult(
            success=ok,
            data=data,
            error=None if ok else f"hyperframes check exit {proc.returncode}",
        )

    def _add_block(self, inputs: dict[str, Any]) -> ToolResult:
        """Install a registry block or component via `hyperframes add`.

        Blocks are standalone sub-compositions (own dimensions, duration, timeline)
        that land at `compositions/<name>.html`. Components are effect snippets
        that land at `compositions/components/<name>.html`. After install, the
        caller is responsible for wiring the block into `index.html` via
        `data-composition-src` or pasting the component's snippet — see
        `.agents/skills/hyperframes-registry/SKILL.md`.
        """
        workspace = self._require_workspace(inputs)
        block = (inputs.get("block_name") or "").strip()
        if not block:
            return ToolResult(
                success=False,
                error="block_name is required for operation='add_block'",
            )
        if not workspace.exists():
            return ToolResult(
                success=False,
                error=(
                    f"Workspace {workspace} does not exist. Run "
                    "operation='scaffold_workspace' first."
                ),
            )
        args = ["add", block, "--json", "--no-clipboard"]
        proc = self._run_hf(args, cwd=workspace, timeout=300, check=False)
        data: dict[str, Any] = {
            "operation": "add_block",
            "block_name": block,
            "workspace": str(workspace),
            "exit_code": proc.returncode,
        }
        payload = self._parse_json_output(proc.stdout)
        if payload is not None:
            data["report"] = payload
        else:
            data["stdout_tail"] = (proc.stdout or "")[-4000:]
        data["stderr_tail"] = (proc.stderr or "")[-2000:]
        ok = proc.returncode == 0
        return ToolResult(
            success=ok,
            data=data,
            error=None if ok else f"hyperframes add {block} exit {proc.returncode}",
        )

    def _render(self, inputs: dict[str, Any]) -> ToolResult:
        """Full pipeline: scaffold → lint → validate → render."""
        runtime_ok = self._runtime_check()
        if not runtime_ok["runtime_available"]:
            return ToolResult(
                success=False,
                error=(
                    "HyperFrames runtime not available: "
                    + "; ".join(runtime_ok["reasons"])
                    + ". Per governance, this is a blocker — do NOT silently "
                    "fall back to another runtime without user approval."
                ),
                data={"runtime_check": runtime_ok},
            )

        workspace = self._require_workspace(inputs)
        output_path = Path(
            inputs.get("output_path") or (workspace / "renders" / "final.mp4")
        ).expanduser().resolve()
        output_path.parent.mkdir(parents=True, exist_ok=True)

        steps: dict[str, Any] = {}

        # 1. Scaffold — generate HTML/CSS/assets.
        scaffold = self._scaffold(inputs)
        steps["scaffold"] = scaffold.data
        if not scaffold.success:
            return ToolResult(
                success=False,
                error=f"Scaffold failed: {scaffold.error}",
                data={"steps": steps},
            )

        # 2. Lint — static contract checks.
        lint = self._lint({"workspace_path": str(workspace)})
        steps["lint"] = lint.data
        if not lint.success:
            if inputs.get("strict", False):
                return ToolResult(
                    success=False,
                    error=f"Lint failed (strict mode): {lint.error}",
                    data={"steps": steps},
                )
            log.warning("hyperframes lint reported issues (non-strict mode, continuing)")

        # 3. Validate — browser-based contract + contrast.
        validate = self._validate(
            {
                "workspace_path": str(workspace),
                "skip_contrast": inputs.get("skip_contrast", False),
            }
        )
        steps["validate"] = validate.data
        if not validate.success:
            return ToolResult(
                success=False,
                error=(
                    f"Validate failed: {validate.error}. HyperFrames render "
                    f"is blocked — fix the composition and re-run."
                ),
                data={"steps": steps},
            )

        # 4. Render.
        width, height, fps = self._resolve_dimensions(
            inputs.get("profile"), inputs.get("fps", 30)
        )
        quality = inputs.get("quality", "standard")
        args = [
            "render",
            "--output", str(output_path),
            "--fps", str(fps),
            "--quality", quality,
        ]
        proc = self._run_hf(args, cwd=workspace, timeout=1800, check=False)
        steps["render"] = {
            "exit_code": proc.returncode,
            "stdout_tail": (proc.stdout or "")[-4000:],
            "stderr_tail": (proc.stderr or "")[-4000:],
        }
        if proc.returncode != 0:
            return ToolResult(
                success=False,
                error=f"hyperframes render exit {proc.returncode}",
                data={"steps": steps},
            )

        if not output_path.exists():
            return ToolResult(
                success=False,
                error=(
                    f"hyperframes render exited 0 but output file missing: "
                    f"{output_path}. Check stdout_tail for the real path."
                ),
                data={"steps": steps},
            )

        return ToolResult(
            success=True,
            data={
                "operation": "render",
                "output": str(output_path),
                "workspace": str(workspace),
                "width": width,
                "height": height,
                "fps": fps,
                "quality": quality,
                "steps": steps,
            },
            artifacts=[str(output_path)],
        )

    def _render_existing(self, inputs: dict[str, Any]) -> ToolResult:
        """Validate and render a hand-authored workspace without scaffolding it.

        Atelier compositions own their HTML, CSS, JavaScript, and local assets.
        Re-running `_scaffold` would destroy that authored work, so this path
        performs the mandatory gates against the files already on disk.
        """
        runtime_ok = self._runtime_check()
        if not runtime_ok["runtime_available"]:
            return ToolResult(
                success=False,
                error=(
                    "HyperFrames runtime not available: "
                    + "; ".join(runtime_ok["reasons"])
                    + ". Per governance, do not swap runtimes silently."
                ),
                data={"runtime_check": runtime_ok},
            )

        workspace = self._require_workspace(inputs)
        entry = workspace / "index.html"
        if not entry.is_file():
            return ToolResult(
                success=False,
                error=f"No authored index.html in {workspace}.",
            )
        original_digest = self._file_digest(entry)
        output_path = Path(
            inputs.get("output_path") or (workspace / "renders" / "final.mp4")
        ).expanduser().resolve()
        output_path.parent.mkdir(parents=True, exist_ok=True)
        steps: dict[str, Any] = {}

        quality_check = self._check(
            {
                "workspace_path": str(workspace),
                "skip_contrast": inputs.get("skip_contrast", False),
                "strict_check": inputs.get("strict_check", False),
                "snapshots": inputs.get("snapshots", False),
            }
        )
        steps["check"] = quality_check.data
        if not quality_check.success:
            return ToolResult(
                success=False,
                error=f"Quality check failed for authored workspace: {quality_check.error}",
                data={"steps": steps},
            )

        _, _, fps = self._resolve_dimensions(
            inputs.get("profile"), inputs.get("fps", 30)
        )
        quality = inputs.get("quality", "standard")
        args = [
            "render",
            "--output", str(output_path),
            "--fps", str(fps),
            "--quality", quality,
            "--strict",
        ]
        proc = self._run_hf(args, cwd=workspace, timeout=1800, check=False)
        steps["render"] = {
            "exit_code": proc.returncode,
            "stdout_tail": (proc.stdout or "")[-4000:],
            "stderr_tail": (proc.stderr or "")[-4000:],
        }
        if proc.returncode != 0:
            return ToolResult(
                success=False,
                error=f"hyperframes render exit {proc.returncode}",
                data={"steps": steps},
            )
        if not output_path.is_file():
            return ToolResult(
                success=False,
                error=f"HyperFrames exited 0 but output is missing: {output_path}",
                data={"steps": steps},
            )
        if self._file_digest(entry) != original_digest:
            return ToolResult(
                success=False,
                error="Authored index.html changed during render_existing.",
                data={"steps": steps},
            )

        return ToolResult(
            success=True,
            data={
                "operation": "render_existing",
                "output": str(output_path),
                "workspace": str(workspace),
                "fps": fps,
                "quality": quality,
                "authored_entry_preserved": True,
                "steps": steps,
            },
            artifacts=[str(output_path)],
        )

    @staticmethod
    def _file_digest(path: Path) -> str:
        import hashlib

        return hashlib.sha256(path.read_bytes()).hexdigest()

    # ------------------------------------------------------------------
    # Workspace generation helpers
    # ------------------------------------------------------------------

    @staticmethod
    def _require_workspace(inputs: dict[str, Any]) -> Path:
        raw = inputs.get("workspace_path")
        if not raw:
            raise ValueError("workspace_path is required for this operation")
        return Path(raw).resolve()

    @staticmethod
    def _resolve_dimensions(
        profile_name: Optional[str], fps_in: int
    ) -> tuple[int, int, int]:
        """Resolve output dimensions from the media profile, with a safe default."""
        if profile_name:
            try:
                from lib.media_profiles import get_profile  # type: ignore
                p = get_profile(profile_name)
                return int(p.width), int(p.height), int(p.fps)
            except Exception:
                pass
        return 1920, 1080, int(fps_in)

    @staticmethod
    def _compute_total_duration(cuts: list[dict]) -> float:
        if not cuts:
            return 0.0
        return max(float(c.get("out_seconds", 0) or 0) for c in cuts)

    def _resolve_and_stage_assets(
        self,
        cuts: list[dict],
        assets: list[dict],
        workspace: Path,
    ) -> tuple[list[dict], list[dict[str, str]]]:
        """Resolve asset IDs in cuts[].source, copy files into workspace/assets/.

        HyperFrames resolves `src=` relative to the composition HTML file, so
        every asset must live inside the workspace tree. Copying is simpler
        (and portable) than symlinking, at the cost of disk space — these
        are regenerable under `projects/`.
        """
        asset_lookup = {a["id"]: a for a in assets if "id" in a}
        assets_dir = workspace / "assets"
        copies: list[dict[str, str]] = []
        resolved: list[dict] = []
        for cut in cuts:
            source = cut.get("source", "")
            resolved_cut = dict(cut)
            if source in asset_lookup:
                resolved_cut["source"] = asset_lookup[source].get("path", source)
            src_path = Path(resolved_cut["source"]) if resolved_cut.get("source") else None
            if src_path and src_path.exists() and not self._is_inside(src_path, workspace):
                dest = assets_dir / src_path.name
                if not dest.exists() or dest.stat().st_size != src_path.stat().st_size:
                    shutil.copy2(src_path, dest)
                resolved_cut["source"] = str(dest)
                copies.append({"from": str(src_path), "to": str(dest)})
            resolved.append(resolved_cut)
        return resolved, copies

    def _resolve_audio_refs(
        self,
        audio: dict[str, Any],
        assets: list[dict],
        workspace: Path,
    ) -> dict[str, Any]:
        """Resolve narration / music asset IDs and stage them."""
        asset_lookup = {a["id"]: a for a in assets if "id" in a}
        assets_dir = workspace / "assets"
        out: dict[str, Any] = {"narration": [], "music": None}

        for seg in audio.get("narration", {}).get("segments", []) or []:
            aid = seg.get("asset_id")
            if not aid or aid not in asset_lookup:
                continue
            src = Path(asset_lookup[aid].get("path", ""))
            if not src.exists():
                continue
            if not self._is_inside(src, workspace):
                dest = assets_dir / src.name
                if not dest.exists() or dest.stat().st_size != src.stat().st_size:
                    shutil.copy2(src, dest)
            else:
                dest = src
            out["narration"].append(
                {
                    "src": str(dest),
                    "start_seconds": float(seg.get("start_seconds", 0) or 0),
                    "end_seconds": float(seg.get("end_seconds", 0) or 0) or None,
                }
            )

        music = audio.get("music", {})
        m_id = music.get("asset_id")
        if m_id and m_id in asset_lookup:
            src = Path(asset_lookup[m_id].get("path", ""))
            if src.exists():
                if not self._is_inside(src, workspace):
                    dest = assets_dir / src.name
                    if not dest.exists() or dest.stat().st_size != src.stat().st_size:
                        shutil.copy2(src, dest)
                else:
                    dest = src
                out["music"] = {
                    "src": str(dest),
                    "volume": float(music.get("volume", 0.15) or 0.15),
                    "fade_in_seconds": float(music.get("fade_in_seconds", 0) or 0),
                    "fade_out_seconds": float(music.get("fade_out_seconds", 0) or 0),
                }

        return out

    @staticmethod
    def _is_inside(path: Path, root: Path) -> bool:
        try:
            path.resolve().relative_to(root.resolve())
            return True
        except ValueError:
            return False

    def _style_bridge(
        self,
        playbook: dict[str, Any],
        edit_decisions: dict[str, Any],
    ) -> tuple[dict[str, str], str]:
        """Bridge OpenMontage playbook → HyperFrames CSS vars + DESIGN.md.

        Delegates to `lib/hyperframes_style_bridge.py` so the logic is
        shareable and testable. Falls back to a safe built-in default when
        the bridge module isn't available.
        """
        try:
            from lib.hyperframes_style_bridge import style_bridge  # type: ignore
            return style_bridge(playbook, edit_decisions)
        except Exception as e:
            log.debug("style_bridge fallback: %s", e)

        vl = (playbook or {}).get("visual_language", {})
        palette = vl.get("color_palette", {})
        typo = (playbook or {}).get("typography", {})

        def _first(raw: Any, default: str) -> str:
            if isinstance(raw, list) and raw:
                return str(raw[0])
            if isinstance(raw, str) and raw:
                return raw
            return default

        bg = _first(palette.get("background"), "#0B0F1A")
        fg = _first(palette.get("text"), "#F5F5F5")
        accent = _first(palette.get("accent"), "#F59E0B")
        primary = _first(palette.get("primary"), "#2563EB")
        heading = typo.get("heading", {}).get("font") or typo.get("heading", {}).get("family") or "Inter"
        body = typo.get("body", {}).get("font") or typo.get("body", {}).get("family") or "Inter"

        css_vars = {
            "--color-bg": bg,
            "--color-fg": fg,
            "--color-accent": accent,
            "--color-primary": primary,
            "--font-heading": heading,
            "--font-body": body,
            "--ease-primary": "cubic-bezier(0.65, 0, 0.35, 1)",
            "--duration-entrance": "0.6s",
        }
        design_md = (
            "# DESIGN\n\n"
            "Generated by OpenMontage HyperFrames style bridge (fallback).\n\n"
            f"- Background: `{bg}`\n"
            f"- Foreground: `{fg}`\n"
            f"- Accent: `{accent}`\n"
            f"- Primary: `{primary}`\n"
            f"- Heading font: `{heading}`\n"
            f"- Body font: `{body}`\n"
        )
        return css_vars, design_md

    # ------------------------------------------------------------------
    # HTML generation (minimal, Phase 1)
    # ------------------------------------------------------------------

    def _generate_index_html(
        self,
        cuts: list[dict],
        audio_refs: dict[str, Any],
        width: int,
        height: int,
        total_duration: float,
        css_vars: dict[str, str],
        title: str,
    ) -> str:
        """Emit a HyperFrames-contract-compliant index.html.

        Phase 1 covers the minimum required for smoke-testing the runtime:
        - still images (img.clip)
        - video clips (video.clip, muted playsinline + separate audio if needed)
        - text cards (div.clip with styled <h1>)
        - narration segments (audio)
        - music bed (audio, lower volume)

        Richer scene types (registry blocks, kinetic typography) are authored
        by the agent directly into compositions/ — this generator just
        provides a functional starting skeleton.
        """
        vars_css = "\n      ".join(f"{k}: {v};" for k, v in css_vars.items())

        clip_html: list[str] = []
        entrance_tweens: list[str] = []
        for i, cut in enumerate(cuts):
            html, tween = self._cut_to_html(i, cut, width, height)
            clip_html.append(html)
            if tween:
                entrance_tweens.append(tween)

        audio_html: list[str] = []
        for j, nar in enumerate(audio_refs.get("narration") or []):
            src = self._rel_from_workspace(nar["src"])
            start = nar.get("start_seconds", 0)
            end = nar.get("end_seconds")
            duration = (end - start) if end and end > start else (total_duration - start)
            audio_html.append(
                f'<audio id="nar-{j}" '
                f'data-start="{self._f(start)}" data-duration="{self._f(duration)}" '
                f'data-track-index="2" src="{self._escape_attr(src)}" '
                f'data-volume="1"></audio>'
            )

        music = audio_refs.get("music")
        if music:
            src = self._rel_from_workspace(music["src"])
            audio_html.append(
                f'<audio id="music" '
                f'data-start="0" data-duration="{self._f(total_duration)}" '
                f'data-track-index="3" src="{self._escape_attr(src)}" '
                f'data-volume="{self._f(music["volume"])}"></audio>'
            )

        tween_block = "\n        ".join(entrance_tweens) if entrance_tweens else "// no tweens"

        return f"""<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <title>{self._escape_text(title)}</title>
  <style>
    :root {{
      {vars_css}
    }}
    body {{ margin: 0; background: var(--color-bg); color: var(--color-fg); font-family: var(--font-body); }}
    [data-composition-id="root"] {{
      position: relative;
      width: {width}px;
      height: {height}px;
      overflow: hidden;
    }}
    .clip {{ position: absolute; inset: 0; }}
    .clip.video-clip, .clip.image-clip {{ object-fit: cover; width: 100%; height: 100%; }}
    .clip.text-card {{ display: flex; align-items: center; justify-content: center; padding: 120px 160px; box-sizing: border-box; text-align: center; }}
    .clip.text-card h1 {{ font-family: var(--font-heading); font-weight: 700; font-size: 96px; line-height: 1.1; margin: 0; color: var(--color-fg); }}
    .clip.text-card .subtitle {{ font-size: 36px; margin-top: 24px; color: var(--color-accent); }}
  </style>
  <script src="https://cdn.jsdelivr.net/npm/gsap@3.14.2/dist/gsap.min.js"></script>
</head>
<body>
  <div data-composition-id="root" data-start="0" data-duration="{self._f(total_duration)}" data-width="{width}" data-height="{height}">
    {"".join(clip_html)}
    {"".join(audio_html)}
    <script>
      window.__timelines = window.__timelines || {{}};
      const tl = gsap.timeline({{ paused: true }});
      {tween_block}
      window.__timelines["root"] = tl;
    </script>
  </div>
</body>
</html>
"""

    def _cut_to_html(
        self, index: int, cut: dict, width: int, height: int
    ) -> tuple[str, Optional[str]]:
        """Render one cut + its entrance tween. Returns (html, tween or None)."""
        cut_id = f"cut-{index}"
        in_s = float(cut.get("in_seconds", 0) or 0)
        out_s = float(cut.get("out_seconds", 0) or 0)
        duration = max(0.1, out_s - in_s)

        source = cut.get("source") or ""
        cut_type = (cut.get("type") or "").lower()
        text = cut.get("text") or cut.get("title") or ""

        src_path = Path(source) if source else None
        ext = src_path.suffix.lower() if src_path else ""

        # Decide scene shape
        if cut_type in {"text_card", "hero_title", "callout"} or (not source and text):
            inner = f'<h1>{self._escape_text(text or f"Scene {index + 1}")}</h1>'
            subtitle = cut.get("subtitle") or cut.get("caption")
            if subtitle:
                inner += f'<div class="subtitle">{self._escape_text(subtitle)}</div>'
            html = (
                f'<div id="{cut_id}" class="clip text-card" '
                f'data-start="{self._f(in_s)}" data-duration="{self._f(duration)}" '
                f'data-track-index="1">{inner}</div>'
            )
            # Mild entrance — fade + lift.
            tween = (
                f'tl.from("#{cut_id} h1", {{ y: 40, opacity: 0, duration: 0.6, '
                f'ease: "power3.out" }}, {self._f(in_s + 0.1)});'
            )
            return html, tween

        if ext in _IMAGE_EXTENSIONS and src_path:
            rel = self._rel_from_workspace(str(src_path))
            html = (
                f'<img id="{cut_id}" class="clip image-clip" '
                f'src="{self._escape_attr(rel)}" '
                f'data-start="{self._f(in_s)}" data-duration="{self._f(duration)}" '
                f'data-track-index="1" alt="">'
            )
            tween = (
                f'tl.from("#{cut_id}", {{ scale: 1.05, opacity: 0, duration: 0.5, '
                f'ease: "power2.out" }}, {self._f(in_s)});'
            )
            return html, tween

        if ext in _VIDEO_EXTENSIONS and src_path:
            rel = self._rel_from_workspace(str(src_path))
            html = (
                f'<video id="{cut_id}" class="clip video-clip" '
                f'src="{self._escape_attr(rel)}" '
                f'data-start="{self._f(in_s)}" data-duration="{self._f(duration)}" '
                f'data-track-index="1" muted playsinline></video>'
            )
            return html, None

        # Unknown cut shape — render a placeholder text card so the render
        # still succeeds; lint/validate will surface the issue.
        if ext in {".html", ".htm"} and src_path:
            rel = self._rel_from_workspace(str(src_path))
            composition_id = Path(rel).stem
            html = (
                f'<div id="{cut_id}" class="clip composition-clip" '
                f'data-composition-id="{self._escape_attr(composition_id)}" '
                f'data-composition-src="{self._escape_attr(rel)}" '
                f'data-start="{self._f(in_s)}" data-duration="{self._f(duration)}" '
                f'data-width="{width}" data-height="{height}" '
                f'data-track-index="1"></div>'
            )
            return html, None

        placeholder = self._escape_text(text or cut.get("reason") or f"Scene {index + 1}")
        html = (
            f'<div id="{cut_id}" class="clip text-card" '
            f'data-start="{self._f(in_s)}" data-duration="{self._f(duration)}" '
            f'data-track-index="1"><h1>{placeholder}</h1></div>'
        )
        return html, None

    # ------------------------------------------------------------------
    # Utilities
    # ------------------------------------------------------------------

    def _run_hf(
        self,
        args: list[str],
        *,
        cwd: Optional[Path],
        timeout: int,
        check: bool,
    ) -> subprocess.CompletedProcess:
        """Invoke `npx hyperframes <args>` with the right Windows quirks.

        We intentionally bypass `self.run_command` here because we do NOT
        want to raise CalledProcessError on non-zero exits — the caller
        parses lint/validate/render exit codes itself.
        """
        cmd = ["npx", "--yes", "hyperframes", *args]
        # On Windows, resolve the .cmd wrapper so subprocess can find it
        # without shell=True.
        if os.name == "nt":
            resolved = shutil.which(cmd[0])
            if resolved:
                cmd[0] = resolved
        try:
            return subprocess.run(
                cmd,
                capture_output=True,
                text=True,
                timeout=timeout,
                cwd=str(cwd) if cwd else None,
                check=False,
            )
        except subprocess.TimeoutExpired as e:
            # Surface timeouts as a failed CompletedProcess so callers get a
            # uniform shape. The stderr tail will say timeout.
            return subprocess.CompletedProcess(
                args=cmd,
                returncode=124,
                stdout=e.stdout or "",
                stderr=(e.stderr or "") + f"\n[timeout after {timeout}s]",
            )

    @staticmethod
    def _parse_json_output(stdout: str) -> Optional[Any]:
        """Parse a `--json` report, tolerating surrounding banner lines."""
        if not stdout:
            return None
        start = stdout.find("{")
        end = stdout.rfind("}")
        if start == -1 or end == -1 or end <= start:
            return None
        try:
            return json.loads(stdout[start : end + 1])
        except json.JSONDecodeError:
            return None

    @staticmethod
    def _f(v: float) -> str:
        return f"{float(v):.3f}".rstrip("0").rstrip(".")

    @staticmethod
    def _escape_text(s: str) -> str:
        return (
            s.replace("&", "&amp;")
            .replace("<", "&lt;")
            .replace(">", "&gt;")
        )

    @staticmethod
    def _escape_attr(s: str) -> str:
        return HyperFramesCompose._escape_text(s).replace('"', "&quot;")

    @staticmethod
    def _rel_from_workspace(path: str) -> str:
        """HyperFrames resolves src= relative to index.html. Our asset files
        live under workspace/assets/, so when we stage a copy we know the
        relative path is `assets/<name>`. For files already in the workspace
        tree, fall back to the file name.
        """
        p = Path(path)
        # If it's already a relative path starting with assets/, keep as-is.
        if not p.is_absolute():
            return str(p).replace("\\", "/")
        parts = p.parts
        for anchor in ("assets", "compositions"):
            if anchor in parts:
                index = len(parts) - 1 - list(reversed(parts)).index(anchor)
                return "/".join(parts[index:])
        # Otherwise emit just the basename under assets/.
        return f"assets/{p.name}"

tools/video/kling_o3_fal_video.py:
"""All published Kling O3 video routes through fal.ai.

Standard, Pro and 4K each expose text, image, image-reference, video edit
and video-reference modes. No automatic retries of paid submissions; FalMedia
persists a queue checkpoint and supports GET-only resume after acceptance.
"""
from tools.fal_media import CONTRACTS, FalMedia


class KlingO3FalVideo(FalMedia):
    name = "kling_o3_fal_video"
    capability = "video_generation"
    capabilities = [
        "text_to_video", "image_to_video", "reference_to_video",
        "video_to_video_edit", "video_to_video_reference",
    ]
    supports = {operation: True for operation in (
        "text_to_video", "image_to_video", "reference_to_video",
        "video_to_video_edit", "video_to_video_reference",
    )}
    best_for = ["Kling O3 video generation, reference continuity and editing via fal.ai"]
    routes = {
        f"kling-o3-{tier}": {
            "text_to_video": f"fal-ai/kling-video/o3/{tier}/text-to-video",
            "image_to_video": f"fal-ai/kling-video/o3/{tier}/image-to-video",
            "reference_to_video": f"fal-ai/kling-video/o3/{tier}/reference-to-video",
            "video_to_video_edit": f"fal-ai/kling-video/o3/{tier}/video-to-video/edit",
            "video_to_video_reference": f"fal-ai/kling-video/o3/{tier}/video-to-video/reference",
        }
        for tier in ("standard", "pro", "4k")
    }

    def build_request(self, inputs):
        model = inputs.get("model", next(iter(self.routes)))
        operation = inputs.get("generation_mode") or inputs.get("operation")
        if operation == "video_edit":  # video_selector's legacy edit spelling
            operation = "video_to_video_edit"
        if not operation:
            if inputs.get("video_url") or inputs.get("reference_video_url"):
                raise ValueError("Select video_to_video_edit or video_to_video_reference explicitly")
            if any(inputs.get(key) for key in ("image_url", "image_path")):
                operation = "image_to_video"
            elif any(inputs.get(key) for key in (
                "image_urls", "image_paths", "start_image_url", "elements",
                "reference_image_urls", "reference_image_paths",
            )):
                operation = "reference_to_video"
            else:
                operation = "text_to_video"
        endpoint = self.routes.get(model, {}).get(operation)
        if not endpoint:
            raise ValueError(f"Unsupported model/operation: {model}/{operation}")
        if operation in {"text_to_video", "image_to_video", "reference_to_video"}:
            if inputs.get("prompt") is not None and inputs.get("multi_prompt") is not None:
                raise ValueError("Provide prompt or multi_prompt, not both")
        native = dict(inputs)
        aliases = {
            "reference_image_path", "reference_image_paths", "reference_image_url",
            "reference_image_urls", "reference_video_url", "reference_video_path",
            "reference_video_urls", "reference_video_paths", "reference_audio_urls",
            "reference_audio_paths", "last_image_url", "last_image_path",
            "video_path", "image_list", "video_list", "element_list",
        }
        if operation == "image_to_video":
            if native.get("reference_image_path"):
                if native.get("image_path") or native.get("image_url"):
                    raise ValueError("Provide only one first-frame image")
                native["image_path"] = native.pop("reference_image_path")
            if native.get("reference_image_url"):
                if native.get("image_url") or native.get("image_path"):
                    raise ValueError("Provide only one first-frame image")
                native["image_url"] = native.pop("reference_image_url")
        if operation in {"reference_to_video", "video_to_video_edit", "video_to_video_reference"}:
            urls = list(native.get("image_urls") or [])
            paths = list(native.get("image_paths") or [])
            urls.extend(native.pop("reference_image_urls", []) or [])
            paths.extend(native.pop("reference_image_paths", []) or [])
            if native.get("reference_image_url"):
                urls.append(native.pop("reference_image_url"))
            if native.get("reference_image_path"):
                paths.append(native.pop("reference_image_path"))
            if urls:
                native["image_urls"] = urls
            if paths:
                native["image_paths"] = paths
        if operation in {"image_to_video", "reference_to_video"}:
            if native.get("last_image_url") or native.get("last_image_path"):
                if native.get("end_image_url") or (native.get("last_image_url") and native.get("last_image_path")):
                    raise ValueError("Provide only one last-frame image")
                if native.get("last_image_url"):
                    native["end_image_url"] = native.pop("last_image_url")
                else:
                    from tools.schema_media import local_image
                    native["end_image_url"] = local_image(native.pop("last_image_path"))
        if operation in {"video_to_video_edit", "video_to_video_reference"} and native.get("reference_video_url"):
            if native.get("video_url"):
                raise ValueError("Provide only one source video URL")
            native["video_url"] = native.pop("reference_video_url")
        unsupported = sorted(key for key in aliases if native.get(key))
        if unsupported:
            raise ValueError(f"{endpoint} does not accept {', '.join(unsupported)}")
        props = CONTRACTS[endpoint]["input_schema"]["properties"]
        native_fields = {
            field
            for operations in self.routes.values()
            for route in operations.values()
            for field in CONTRACTS[route]["input_schema"]["properties"]
        }
        unexpected = native_fields.intersection(native).difference(props)
        if native.get("image_url") and operation == "reference_to_video":
            raise ValueError("Use start_image_url for the first frame; image_urls are references")
        if unexpected and not (unexpected == {"image_url"} and "image_urls" in props):
            raise ValueError(f"{endpoint} does not accept {', '.join(sorted(unexpected))}")
        return super().build_request({**native, "operation": operation, "generation_mode": operation})

tools/video/minimax_fal_video.py:
"""MiniMax H3 (Hailuo 03) generation through fal.ai."""

from __future__ import annotations

import os
import time
from pathlib import Path
from typing import Any

from tools.base_tool import (
    BaseTool,
    Determinism,
    ExecutionMode,
    ResourceProfile,
    RetryPolicy,
    ToolResult,
    ToolRuntime,
    ToolStability,
    ToolStatus,
    ToolTier,
)


class MiniMaxFalVideo(BaseTool):
    name = "minimax_fal_video"
    version = "0.1.0"
    tier = ToolTier.GENERATE
    capability = "video_generation"
    provider = "minimax"
    stability = ToolStability.BETA
    execution_mode = ExecutionMode.SYNC
    determinism = Determinism.STOCHASTIC
    runtime = ToolRuntime.API
    dependencies = ["env:FAL_KEY"]
    install_instructions = (
        "Set FAL_KEY (or FAL_AI_API_KEY) from https://fal.ai/dashboard/keys."
    )
    agent_skills = ["minimax-h3", "ai-video-gen"]
    capabilities = ["text_to_video", "image_to_video", "reference_to_video"]
    supports = {
        "text_to_video": True,
        "image_to_video": True,
        "reference_to_video": True,
        "multiple_reference_images": True,
        "reference_video": True,
        "reference_audio": True,
        "native_audio": True,
    }
    best_for = [
        "MiniMax H3 through an existing fal.ai account",
        "2K multimodal reference video",
    ]
    not_good_for = ["offline generation"]
    fallback_tools = ["minimax_video", "runway_video", "comfyui_video"]
    quality_score = 0.95
    input_schema = {
        "type": "object",
        "required": ["prompt"],
        "properties": {
            "prompt": {"type": "string"},
            "operation": {
                "type": "string",
                "enum": ["text_to_video", "image_to_video", "reference_to_video"],
                "default": "text_to_video",
            },
            "duration": {"type": "integer", "minimum": 5, "maximum": 15, "default": 5},
            "aspect_ratio": {
                "type": "string",
                "enum": ["adaptive", "21:9", "16:9", "4:3", "1:1", "3:4", "9:16"],
                "default": "16:9",
            },
            "image_url": {"type": "string"},
            "end_image_url": {"type": "string"},
            "reference_image_urls": {"type": "array", "items": {"type": "string"}},
            "reference_video_urls": {"type": "array", "items": {"type": "string"}},
            "reference_audio_urls": {"type": "array", "items": {"type": "string"}},
            "output_path": {"type": "string"},
        },
    }
    resource_profile = ResourceProfile(
        cpu_cores=1, ram_mb=512, vram_mb=0, disk_mb=500, network_required=True
    )
    retry_policy = RetryPolicy(
        max_retries=2, retryable_errors=["rate_limit", "timeout"]
    )
    idempotency_key_fields = ["prompt", "operation", "duration", "aspect_ratio"]
    side_effects = ["writes video file to output_path", "calls fal.ai API"]
    user_visible_verification = ["Watch the result and verify native audio"]

    @staticmethod
    def _api_key() -> str | None:
        return os.environ.get("FAL_KEY") or os.environ.get("FAL_AI_API_KEY")

    def get_status(self) -> ToolStatus:
        return ToolStatus.AVAILABLE if self._api_key() else ToolStatus.UNAVAILABLE

    def estimate_cost(self, inputs: dict[str, Any]) -> float:
        return round(0.19 * int(inputs.get("duration", 5)), 2)

    def estimate_runtime(self, inputs: dict[str, Any]) -> float:
        return 120.0

    def execute(self, inputs: dict[str, Any]) -> ToolResult:
        api_key = self._api_key()
        if not api_key:
            return ToolResult(
                success=False, error="FAL_KEY not set. " + self.install_instructions
            )
        import requests
        from tools.video._shared import probe_output

        operation = inputs.get("operation", "text_to_video")
        payload: dict[str, Any] = {
            "prompt": inputs["prompt"],
            "duration": int(inputs.get("duration", 5)),
            "resolution": "2K",
        }
        if operation != "image_to_video":
            payload["aspect_ratio"] = inputs.get("aspect_ratio", "16:9")
        if operation == "image_to_video":
            if not inputs.get("image_url"):
                return ToolResult(
                    success=False, error="image_to_video requires image_url"
                )
            payload["image_url"] = inputs["image_url"]
            if inputs.get("end_image_url"):
                payload["end_image_url"] = inputs["end_image_url"]
        elif operation == "reference_to_video":
            for key in (
                "reference_image_urls",
                "reference_video_urls",
                "reference_audio_urls",
            ):
                if inputs.get(key):
                    payload[key] = inputs[key]
            if not any(
                payload.get(key)
                for key in ("reference_image_urls", "reference_video_urls")
            ):
                return ToolResult(
                    success=False,
                    error="reference_to_video requires a reference image or video",
                )
        endpoint = f"fal-ai/minimax/hailuo-03/{operation.replace('_', '-')}"
        headers = {
            "Authorization": f"Key {api_key}",
            "Content-Type": "application/json",
        }
        started = time.time()
        try:
            submit = requests.post(
                f"https://queue.fal.run/{endpoint}",
                headers=headers,
                json=payload,
                timeout=30,
            )
            submit.raise_for_status()
            queued = submit.json()
            while True:
                time.sleep(5)
                status_response = requests.get(
                    queued["status_url"], headers=headers, timeout=15
                )
                status_response.raise_for_status()
                status = status_response.json().get("status")
                if status == "COMPLETED":
                    break
                if status in {"FAILED", "CANCELLED"}:
                    return ToolResult(
                        success=False,
                        error=f"fal.ai MiniMax H3 generation {status.lower()}",
                    )
            result_response = requests.get(
                queued["response_url"], headers=headers, timeout=30
            )
            result_response.raise_for_status()
            video_url = result_response.json()["video"]["url"]
            download = requests.get(video_url, timeout=180)
            download.raise_for_status()
            output_path = Path(inputs.get("output_path", "minimax_h3_fal_output.mp4"))
            output_path.parent.mkdir(parents=True, exist_ok=True)
            output_path.write_bytes(download.content)
        except Exception as exc:
            return ToolResult(
                success=False, error=f"fal.ai MiniMax H3 generation failed: {exc}"
            )
        return ToolResult(
            success=True,
            data={
                "provider": "minimax",
                "gateway": "fal.ai",
                "model": endpoint,
                "operation": operation,
                "output": str(output_path),
                **probe_output(output_path),
            },
            artifacts=[str(output_path)],
            cost_usd=self.estimate_cost(inputs),
            duration_seconds=round(time.time() - started, 2),
            model=endpoint,
        )

tools/video/minimax_video.py:
"""MiniMax video generation via the official first-party API.

MiniMax-H3 uses the v2 content-based API. Hailuo 2.3 and earlier models keep
using the v1 generation, query, and file-retrieval flow. Both API versions
support the global and mainland China hosts through ``MINIMAX_REGION``.
"""

from __future__ import annotations

import os
import time
from pathlib import Path
from typing import Any

from tools.base_tool import (
    BaseTool,
    Determinism,
    ExecutionMode,
    ResourceProfile,
    RetryPolicy,
    ToolResult,
    ToolRuntime,
    ToolStability,
    ToolStatus,
    ToolTier,
)

REGION_BASE_URLS = {
    "global": "https://api.minimax.io",
    "global_en": "https://api.minimax.io",
    "cn": "https://api.minimaxi.com",
    "cn_zh": "https://api.minimaxi.com",
}
DEFAULT_REGION = "global"

V2_MODELS = ["MiniMax-H3"]
V1_MODELS = [
    "MiniMax-Hailuo-2.3",
    "MiniMax-Hailuo-2.3-Fast",
    "MiniMax-Hailuo-02",
    "T2V-01-Director",
    "T2V-01",
    "I2V-01-Director",
    "I2V-01-live",
    "I2V-01",
]
MODELS = V2_MODELS + V1_MODELS
DEFAULT_MODEL = "MiniMax-H3"

V2_RATIO_VALUES = ["adaptive", "21:9", "16:9", "4:3", "1:1", "3:4", "9:16"]
_V2_IN_PROGRESS = {"queued", "running"}
_V2_SUCCESS = "succeeded"
_V2_FAILURES = {"failed", "cancelled"}
_V1_SUCCESS = "Success"
_V1_FAILURE = "Fail"


class MiniMaxVideo(BaseTool):
    name = "minimax_video"
    version = "0.3.0"
    tier = ToolTier.GENERATE
    capability = "video_generation"
    provider = "minimax"
    stability = ToolStability.EXPERIMENTAL
    execution_mode = ExecutionMode.SYNC
    determinism = Determinism.STOCHASTIC
    runtime = ToolRuntime.API

    dependencies = ["env:MINIMAX_API_KEY"]
    install_instructions = (
        "Set MINIMAX_API_KEY to your MiniMax API key.\n"
        "  Get one at https://platform.minimax.io/ (global) or "
        "https://platform.minimaxi.com/ (CN).\n"
        "  Optionally set MINIMAX_REGION=cn to route to the mainland China host, "
        "or MINIMAX_BASE_URL to override the endpoint entirely."
    )
    agent_skills = ["minimax-h3", "ai-video-gen"]

    capabilities = [
        "text_to_video",
        "image_to_video",
        "first_last_frame_to_video",
        "reference_to_video",
    ]
    supports = {
        "text_to_video": True,
        "image_to_video": True,
        "first_last_frame_to_video": True,
        "reference_to_video": True,
        "reference_image": True,
        "reference_video": True,
        "reference_audio": True,
        "native_audio": True,
        "camera_direction": True,
    }
    best_for = [
        (
            "2K text, image, first/last-frame, and reference video generation "
            "with MiniMax-H3"
        ),
        "prompt-following with camera directions and high-texture footage",
        "direct first-party API access with global and mainland China routing",
    ]
    not_good_for = ["offline generation", "clips longer than 15 seconds"]
    fallback_tools = ["kling_video", "veo_video", "wan_video"]

    input_schema = {
        "type": "object",
        "required": [],
        "properties": {
            "prompt": {"type": "string", "maxLength": 7000},
            "operation": {
                "type": "string",
                "enum": [
                    "text_to_video",
                    "image_to_video",
                    "first_last_frame_to_video",
                    "reference_to_video",
                ],
                "default": "text_to_video",
            },
            "model": {
                "type": "string",
                "enum": MODELS,
                "default": DEFAULT_MODEL,
            },
            "first_frame_image": {
                "type": "string",
                "description": "Public URL or data URI used as the first frame.",
            },
            "last_frame_image": {
                "type": "string",
                "description": (
                    "Public URL or data URI used as the last frame by MiniMax-H3."
                ),
            },
            "end_image_url": {
                "type": "string",
                "description": "Alias for last_frame_image.",
            },
            "image_url": {
                "type": "string",
                "description": "Selector-compatible alias for first_frame_image.",
            },
            "reference_image_url": {
                "type": "string",
                "description": (
                    "First-frame alias or a reference image for reference_to_video."
                ),
            },
            "reference_image_urls": {
                "type": "array",
                "items": {"type": "string"},
            },
            "reference_video_url": {
                "type": "string",
                "description": "Reference video URL for MiniMax-H3.",
            },
            "reference_video_urls": {
                "type": "array",
                "items": {"type": "string"},
            },
            "reference_audio_urls": {
                "type": "array",
                "items": {"type": "string"},
            },
            "prompt_optimizer": {"type": "boolean", "default": True},
            "fast_pretreatment": {"type": "boolean"},
            "duration": {
                "type": "integer",
                "minimum": 4,
                "maximum": 15,
                "description": (
                    "Clip length in seconds; MiniMax-H3 accepts integers from 4 to 15."
                ),
            },
            "resolution": {
                "type": "string",
                "description": (
                    "MiniMax-H3 requires 2K; v1 models accept their documented "
                    "resolutions."
                ),
            },
            "ratio": {"type": "string", "enum": V2_RATIO_VALUES},
            "aspect_ratio": {
                "type": "string",
                "enum": V2_RATIO_VALUES,
                "description": "Selector-compatible alias for ratio.",
            },
            "callback_url": {"type": "string"},
            "aigc_watermark": {
                "type": "boolean",
                "description": "Mainland China MiniMax-H3 watermark option.",
            },
            "poll_interval_seconds": {
                "type": "number",
                "minimum": 0.1,
                "maximum": 60,
                "default": 5,
                "description": "Seconds between task-status requests.",
            },
            "timeout_seconds": {
                "type": "number",
                "minimum": 1,
                "maximum": 3600,
                "default": 900,
                "description": (
                    "Maximum time to wait for remote generation. Timeout errors "
                    "include task_id so the job can be recovered manually."
                ),
            },
            "output_path": {"type": "string"},
        },
    }

    resource_profile = ResourceProfile(
        cpu_cores=1, ram_mb=512, vram_mb=0, disk_mb=500, network_required=True
    )
    retry_policy = RetryPolicy(
        max_retries=2, retryable_errors=["rate_limit", "timeout"]
    )
    idempotency_key_fields = [
        "prompt",
        "model",
        "operation",
        "first_frame_image",
        "last_frame_image",
        "end_image_url",
        "image_url",
        "reference_image_url",
        "reference_image_urls",
        "reference_video_url",
        "reference_video_urls",
        "reference_audio_urls",
        "prompt_optimizer",
        "fast_pretreatment",
        "duration",
        "resolution",
        "ratio",
        "aspect_ratio",
        "callback_url",
        "aigc_watermark",
    ]
    side_effects = ["writes video file to output_path", "calls MiniMax video API"]
    user_visible_verification = [
        "Watch generated clip for motion coherence and prompt adherence"
    ]

    def _get_api_key(self) -> str | None:
        return os.environ.get("MINIMAX_API_KEY")

    def _region(self) -> str:
        region = os.environ.get("MINIMAX_REGION", DEFAULT_REGION).strip().lower()
        return "cn" if region in {"cn", "cn_zh"} else "global"

    def _base_url(self) -> str:
        override = os.environ.get("MINIMAX_BASE_URL")
        if override:
            return override.rstrip("/")
        region = os.environ.get("MINIMAX_REGION", DEFAULT_REGION).strip().lower()
        return REGION_BASE_URLS.get(region, REGION_BASE_URLS[DEFAULT_REGION])

    def _uses_cn_api(self, base_url: str) -> bool:
        return self._region() == "cn" or "api.minimaxi.com" in base_url

    def get_status(self) -> ToolStatus:
        if self._get_api_key():
            return ToolStatus.AVAILABLE
        return ToolStatus.UNAVAILABLE

    def estimate_cost(self, inputs: dict[str, Any]) -> float:
        model = inputs.get("model", DEFAULT_MODEL)
        if model == "MiniMax-H3":
            duration = inputs.get("duration", 5)
            if isinstance(duration, str) and duration.isdigit():
                duration = int(duration)
            seconds = (
                duration
                if isinstance(duration, int) and not isinstance(duration, bool)
                else 5
            )
            reference_images = len(inputs.get("reference_image_urls") or [])
            additional_images = max(0, reference_images - 5)
            return round((seconds * 0.13) + (additional_images * 0.03), 2)
        if "Fast" in model:
            return 0.08
        return 0.15

    def estimate_runtime(self, inputs: dict[str, Any]) -> float:
        model = inputs.get("model", DEFAULT_MODEL)
        if model == "MiniMax-H3":
            return 90.0
        if "Fast" in model:
            return 30.0
        return 60.0

    @staticmethod
    def _base_resp_error(payload: dict[str, Any]) -> str | None:
        """Return an error string when a v1 base_resp signals failure."""
        base_resp = payload.get("base_resp") or {}
        status_code = base_resp.get("status_code")
        if status_code in (None, 0):
            return None
        status_msg = base_resp.get("status_msg", "")
        return f"MiniMax API error {status_code}: {status_msg}".strip()

    @staticmethod
    def _media_content(content_type: str, url: str, role: str) -> dict[str, Any]:
        return {
            "type": content_type,
            content_type: {"url": url},
            "role": role,
        }

    @staticmethod
    def _url_values(inputs: dict[str, Any], singular: str, plural: str) -> list[str]:
        values: list[str] = []
        if inputs.get(singular):
            values.append(str(inputs[singular]))
        values.extend(str(value) for value in (inputs.get(plural) or []) if value)
        return values

    def _build_v2_payload(
        self,
        inputs: dict[str, Any],
        base_url: str,
    ) -> tuple[dict[str, Any] | None, str | None]:
        operation = inputs.get("operation", "text_to_video")
        prompt = str(inputs.get("prompt") or "")
        if not prompt:
            return None, "MiniMax-H3 requires 'prompt'."
        if len(prompt) > 7000:
            return None, "MiniMax-H3 prompt must not exceed 7000 characters."

        content: list[dict[str, Any]] = [{"type": "text", "text": prompt}]
        first_frame = (
            inputs.get("first_frame_image")
            or inputs.get("image_url")
            or inputs.get("reference_image_url")
        )
        last_frame = inputs.get("last_frame_image") or inputs.get("end_image_url")

        if operation in {"image_to_video", "first_last_frame_to_video"}:
            if not first_frame:
                return None, f"{operation} requires 'first_frame_image'."
            content.append(
                self._media_content("image_url", str(first_frame), "first_frame")
            )
            if operation == "first_last_frame_to_video" and not last_frame:
                return None, "first_last_frame_to_video requires 'last_frame_image'."
            if last_frame:
                content.append(
                    self._media_content("image_url", str(last_frame), "last_frame")
                )
        elif operation == "reference_to_video":
            reference_images = self._url_values(
                inputs, "reference_image_url", "reference_image_urls"
            )
            reference_videos = self._url_values(
                inputs, "reference_video_url", "reference_video_urls"
            )
            reference_audio = [
                str(value)
                for value in (inputs.get("reference_audio_urls") or [])
                if value
            ]
            if not reference_images and not reference_videos and not reference_audio:
                return None, "reference_to_video requires at least one reference URL."
            if reference_audio and not (reference_images or reference_videos):
                return (
                    None,
                    "Reference audio requires at least one reference image or video.",
                )
            content.extend(
                self._media_content("image_url", url, "reference_image")
                for url in reference_images
            )
            content.extend(
                self._media_content("video_url", url, "reference_video")
                for url in reference_videos
            )
            content.extend(
                self._media_content("audio_url", url, "reference_audio")
                for url in reference_audio
            )
        elif operation != "text_to_video":
            return None, f"MiniMax-H3 does not support operation '{operation}'."

        duration = inputs.get("duration", 5)
        if isinstance(duration, str) and duration.isdigit():
            duration = int(duration)
        if (
            isinstance(duration, bool)
            or not isinstance(duration, int)
            or not 4 <= duration <= 15
        ):
            return None, "MiniMax-H3 duration must be an integer from 4 to 15 seconds."

        resolution = inputs.get("resolution", "2K")
        if resolution != "2K":
            return None, "MiniMax-H3 resolution must be '2K'."

        ratio = inputs.get("ratio") or inputs.get("aspect_ratio")
        if not ratio:
            ratio = "16:9" if operation == "text_to_video" else "adaptive"
        if ratio not in V2_RATIO_VALUES:
            return None, f"Unsupported MiniMax-H3 ratio '{ratio}'."
        if operation == "text_to_video" and ratio == "adaptive":
            return None, "MiniMax-H3 text_to_video does not support the adaptive ratio."

        payload: dict[str, Any] = {
            "model": "MiniMax-H3",
            "content": content,
            "resolution": resolution,
            "duration": duration,
            "ratio": ratio,
        }
        if inputs.get("callback_url"):
            payload["callback_url"] = inputs["callback_url"]
        if self._uses_cn_api(base_url) and "aigc_watermark" in inputs:
            payload["aigc_watermark"] = inputs["aigc_watermark"]
        return payload, None

    @staticmethod
    def _build_v1_payload(
        inputs: dict[str, Any], model: str
    ) -> tuple[dict[str, Any] | None, str | None]:
        operation = inputs.get("operation", "text_to_video")
        if operation not in {"text_to_video", "image_to_video"}:
            return None, f"{model} does not support operation '{operation}'."

        payload: dict[str, Any] = {"model": model}
        if operation == "image_to_video":
            first_frame = (
                inputs.get("first_frame_image")
                or inputs.get("reference_image_url")
                or inputs.get("image_url")
            )
            if not first_frame:
                return None, "image_to_video requires 'first_frame_image'."
            payload["first_frame_image"] = first_frame
            if inputs.get("prompt"):
                payload["prompt"] = inputs["prompt"]
        else:
            if not inputs.get("prompt"):
                return None, "text_to_video requires 'prompt'."
            payload["prompt"] = inputs["prompt"]

        if "prompt_optimizer" in inputs:
            payload["prompt_optimizer"] = inputs["prompt_optimizer"]
        for field in ("fast_pretreatment", "duration", "resolution", "callback_url"):
            if inputs.get(field) is not None:
                payload[field] = inputs[field]
        return payload, None

    def execute(self, inputs: dict[str, Any]) -> ToolResult:
        api_key = self._get_api_key()
        if not api_key:
            return ToolResult(
                success=False,
                error="MINIMAX_API_KEY not set. " + self.install_instructions,
            )

        import requests

        start = time.time()
        base_url = self._base_url()
        model = inputs.get("model", DEFAULT_MODEL)
        if model not in MODELS:
            return ToolResult(
                success=False, error=f"Unsupported MiniMax model '{model}'."
            )

        if model in V2_MODELS:
            payload, validation_error = self._build_v2_payload(inputs, base_url)
            api_version = "v2"
        else:
            payload, validation_error = self._build_v1_payload(inputs, model)
            api_version = "v1"
        if validation_error:
            return ToolResult(success=False, error=validation_error)
        assert payload is not None

        headers = {
            "Authorization": f"Bearer {api_key}",
            "Content-Type": "application/json",
        }

        def _redact(text: str) -> str:
            return text.replace(api_key, "***") if api_key else text

        task_id: str | None = None
        file_id: str | None = None
        task_data: dict[str, Any] = {}
        poll_interval = max(float(inputs.get("poll_interval_seconds", 5)), 0.1)
        timeout_seconds = max(float(inputs.get("timeout_seconds", 900)), 1.0)
        poll_deadline = time.monotonic() + timeout_seconds

        def _timeout_result() -> ToolResult:
            return ToolResult(
                success=False,
                error=(
                    f"MiniMax video generation timed out after {timeout_seconds:g}s; "
                    f"the remote task may still complete. Resume or inspect task_id "
                    f"'{task_id}'."
                ),
                data={
                    "provider": "minimax",
                    "model": model,
                    "api_version": api_version,
                    "task_id": task_id,
                    "status": "timed_out",
                },
                model=model,
            )

        try:
            submit_resp = requests.post(
                f"{base_url}/{api_version}/video_generation",
                headers=headers,
                json=payload,
                timeout=30,
            )
            submit_resp.raise_for_status()
            submit_data = submit_resp.json()
            if api_version == "v1":
                base_err = self._base_resp_error(submit_data)
                if base_err:
                    return ToolResult(success=False, error=base_err)
            task_id = submit_data.get("task_id")
            if not task_id:
                return ToolResult(
                    success=False, error="MiniMax API did not return a task_id."
                )

            download_url: str | None = None
            if api_version == "v2":
                while True:
                    if time.monotonic() >= poll_deadline:
                        return _timeout_result()
                    time.sleep(
                        min(poll_interval, max(poll_deadline - time.monotonic(), 0))
                    )
                    if time.monotonic() >= poll_deadline:
                        return _timeout_result()
                    status_resp = requests.get(
                        f"{base_url}/v2/query/video_generation/{task_id}",
                        headers=headers,
                        timeout=15,
                    )
                    status_resp.raise_for_status()
                    task_data = status_resp.json().get("task") or {}
                    status = task_data.get("status")
                    if status == _V2_SUCCESS:
                        download_url = (task_data.get("content") or {}).get("url")
                        break
                    if status in _V2_FAILURES:
                        error = task_data.get("error") or "unknown error"
                        return ToolResult(
                            success=False,
                            error=f"MiniMax-H3 video generation {status}: {error}",
                        )
                    if status not in _V2_IN_PROGRESS:
                        return ToolResult(
                            success=False,
                            error=(
                                f"MiniMax-H3 returned unknown task status '{status}'."
                            ),
                        )
            else:
                while True:
                    if time.monotonic() >= poll_deadline:
                        return _timeout_result()
                    time.sleep(
                        min(poll_interval, max(poll_deadline - time.monotonic(), 0))
                    )
                    if time.monotonic() >= poll_deadline:
                        return _timeout_result()
                    status_resp = requests.get(
                        f"{base_url}/v1/query/video_generation",
                        headers=headers,
                        params={"task_id": task_id},
                        timeout=15,
                    )
                    status_resp.raise_for_status()
                    status_data = status_resp.json()
                    base_err = self._base_resp_error(status_data)
                    if base_err:
                        return ToolResult(success=False, error=base_err)
                    status = status_data.get("status", "")
                    if status == _V1_SUCCESS:
                        file_id = status_data.get("file_id")
                        break
                    if status == _V1_FAILURE:
                        return ToolResult(
                            success=False, error="MiniMax video generation failed."
                        )

                if not file_id:
                    return ToolResult(
                        success=False,
                        error="MiniMax API did not return a file_id on success.",
                    )
                file_resp = requests.get(
                    f"{base_url}/v1/files/retrieve",
                    headers=headers,
                    params={"file_id": file_id},
                    timeout=30,
                )
                file_resp.raise_for_status()
                file_data = file_resp.json()
                base_err = self._base_resp_error(file_data)
                if base_err:
                    return ToolResult(success=False, error=base_err)
                download_url = (file_data.get("file") or {}).get("download_url")

            if not download_url:
                return ToolResult(
                    success=False, error="MiniMax API did not return a download URL."
                )

            video_response = requests.get(download_url, timeout=120)
            video_response.raise_for_status()
            output_path = Path(inputs.get("output_path", "minimax_output.mp4"))
            output_path.parent.mkdir(parents=True, exist_ok=True)
            output_path.write_bytes(video_response.content)
        except Exception as e:  # noqa: BLE001 - surface a redacted error to the caller
            return ToolResult(
                success=False,
                error=f"MiniMax video generation failed: {_redact(str(e))}",
                data={
                    "provider": "minimax",
                    "model": model,
                    "api_version": api_version,
                    "task_id": task_id,
                }
                if task_id
                else {},
                model=model,
            )

        data: dict[str, Any] = {
            "provider": "minimax",
            "model": model,
            "api_version": api_version,
            "region": base_url,
            "task_id": task_id,
            "prompt": inputs.get("prompt", ""),
            "output": str(output_path),
        }
        if file_id:
            data["file_id"] = file_id
        if task_data:
            data["task"] = task_data

        return ToolResult(
            success=True,
            data=data,
            artifacts=[str(output_path)],
            cost_usd=self.estimate_cost(inputs),
            duration_seconds=round(time.time() - start, 2),
            model=model,
        )

