    )
    idempotency_key_fields = [
        "prompt",
        "model_version",
        "model_variant",
        "operation",
        "duration",
        "seed",
    ]
    side_effects = ["writes video file to output_path", "calls fal.ai API"]
    user_visible_verification = [
        "Watch generated clip for motion coherence, audio sync, and visual quality"
    ]

    def _get_api_key(self) -> str | None:
        return os.environ.get("FAL_KEY") or os.environ.get("FAL_AI_API_KEY")

    def get_status(self) -> ToolStatus:
        if self._get_api_key():
            return ToolStatus.AVAILABLE
        return ToolStatus.UNAVAILABLE

    def estimate_cost(self, inputs: dict[str, Any]) -> float:
        if inputs.get("model_version", "2.0") == "2.5":
            return round(
                0.30
                * (
                    5
                    if inputs.get("duration", "5") == "auto"
                    else int(inputs.get("duration", "5"))
                ),
                2,
            )
        variant = inputs.get("model_variant", "standard")
        duration = inputs.get("duration", "5")
        secs = 5 if duration == "auto" else int(duration)
        rate = 0.2419 if variant == "fast" else 0.3034
        return round(rate * secs, 2)

    def estimate_runtime(self, inputs: dict[str, Any]) -> float:
        if inputs.get("model_version", "2.0") == "2.5":
            return 150.0
        variant = inputs.get("model_variant", "standard")
        return 60.0 if variant == "fast" else 120.0

    def execute(self, inputs: dict[str, Any]) -> ToolResult:
        api_key = self._get_api_key()
        if not api_key:
            return ToolResult(
                success=False,
                error="FAL_KEY not set. " + self.install_instructions,
            )

        import requests

        start = time.time()
        operation = inputs.get("operation", "text_to_video")
        model_version = inputs.get("model_version", "2.0")
        variant = inputs.get("model_variant", "standard")
        operation_path = operation.replace("_", "-")

        if model_version == "2.5":
            if variant == "fast":
                return ToolResult(
                    success=False,
                    error="Seedance 2.5 on fal.ai has no fast endpoint; use model_variant='standard'.",
                )
            model_path = f"bytedance/seedance-2.5/{operation_path}"
        elif variant == "fast":
            model_path = f"bytedance/seedance-2.0/fast/{operation_path}"
        else:
            model_path = f"bytedance/seedance-2.0/{operation_path}"

        payload: dict[str, Any] = {"prompt": inputs["prompt"]}

        if inputs.get("duration"):
            payload["duration"] = inputs["duration"]
        if inputs.get("aspect_ratio"):
            payload["aspect_ratio"] = inputs["aspect_ratio"]
        if inputs.get("resolution"):
            payload["resolution"] = inputs["resolution"]
        if "generate_audio" in inputs:
            payload["generate_audio"] = inputs["generate_audio"]
        if inputs.get("seed") is not None:
            payload["seed"] = inputs["seed"]

        if operation == "image_to_video":
            if inputs.get("image_url"):
                payload["image_url"] = inputs["image_url"]
            elif inputs.get("image_path"):
                from tools.video._shared import upload_image_fal

                payload["image_url"] = upload_image_fal(inputs["image_path"])
            if inputs.get("end_image_url"):
                payload["end_image_url"] = inputs["end_image_url"]
            if model_version == "2.5":
                payload["aspect_ratio"] = "auto"

        if operation == "reference_to_video":
            ref_image_urls = list(inputs.get("reference_image_urls") or [])
            for local_path in inputs.get("reference_image_paths") or []:
                from tools.video._shared import upload_image_fal

                ref_image_urls.append(upload_image_fal(local_path))
            max_images = 30 if model_version == "2.5" else 9
            max_videos = 10 if model_version == "2.5" else 3
            max_audios = 10 if model_version == "2.5" else 3
            if len(ref_image_urls) > max_images:
                return ToolResult(
                    success=False,
                    error=f"Seedance {model_version} reference_to_video accepts at most {max_images} reference images; got {len(ref_image_urls)}",
                )
            ref_video_urls = list(inputs.get("reference_video_urls") or [])
            if len(ref_video_urls) > max_videos:
                return ToolResult(
                    success=False,
                    error=f"Seedance {model_version} reference_to_video accepts at most {max_videos} reference videos; got {len(ref_video_urls)}",
                )
            ref_audio_urls = list(inputs.get("reference_audio_urls") or [])
            if len(ref_audio_urls) > max_audios:
                return ToolResult(
                    success=False,
                    error=f"Seedance {model_version} reference_to_video accepts at most {max_audios} reference audio clips; got {len(ref_audio_urls)}",
                )
            # fal's 2.0 and 2.5 reference-to-video endpoints both read image_urls /
            # video_urls / audio_urls; reference_*_urls is silently dropped and the
            # request fails with "At least one reference image or video is required."
            if ref_image_urls:
                payload["image_urls"] = ref_image_urls
            if ref_video_urls:
                payload["video_urls"] = ref_video_urls
            if ref_audio_urls:
                payload["audio_urls"] = ref_audio_urls

        headers = {
            "Authorization": f"Key {api_key}",
            "Content-Type": "application/json",
        }

        try:
            submit_resp = requests.post(
                f"https://queue.fal.run/{model_path}",
                headers=headers,
                json=payload,
                timeout=30,
            )
            submit_resp.raise_for_status()
            queue_data = submit_resp.json()
            status_url = queue_data["status_url"]
            response_url = queue_data["response_url"]

            while True:
                time.sleep(5)
                status_resp = requests.get(status_url, headers=headers, timeout=15)
                status_resp.raise_for_status()
                status = status_resp.json().get("status", "UNKNOWN")
                if status == "COMPLETED":
                    break
                if status in ("FAILED", "CANCELLED"):
                    return ToolResult(
                        success=False,
                        error=f"Seedance {model_version} video generation {status.lower()}",
                    )

            result_resp = requests.get(response_url, headers=headers, timeout=30)
            result_resp.raise_for_status()
            data = result_resp.json()

            video_url = data["video"]["url"]
            video_response = requests.get(video_url, timeout=120)
            video_response.raise_for_status()

            output_path = Path(inputs.get("output_path", "seedance_output.mp4"))
            output_path.parent.mkdir(parents=True, exist_ok=True)
            output_path.write_bytes(video_response.content)

        except Exception as e:
            return ToolResult(
                success=False,
                error=f"Seedance {model_version} video generation failed: {e}",
            )

        from tools.video._shared import probe_output

        probed = probe_output(output_path)
        return ToolResult(
            success=True,
            data={
                "provider": "seedance",
                "model": model_path,
                "prompt": inputs["prompt"],
                "operation": operation,
                "variant": variant,
                "model_version": model_version,
                "aspect_ratio": inputs.get("aspect_ratio", "16:9"),
                "resolution": inputs.get("resolution", "720p"),
                "generate_audio": inputs.get("generate_audio", True),
                "seed": data.get("seed"),
                "output": str(output_path),
                "output_path": str(output_path),
                "format": "mp4",
                **probed,
            },
            artifacts=[str(output_path)],
            cost_usd=self.estimate_cost(inputs),
            duration_seconds=round(time.time() - start, 2),
            model=model_path,
        )

tools/video/sora_video.py:
"""OpenAI Sora video generation via the OpenAI Video API."""

from __future__ import annotations

import base64
import mimetypes
import os
import time
from pathlib import Path
from typing import Any

from tools.base_tool import (
    BaseTool,
    Determinism,
    ExecutionMode,
    ResourceProfile,
    RetryPolicy,
    ToolResult,
    ToolRuntime,
    ToolStability,
    ToolStatus,
    ToolTier,
)


_DEFAULT_MODEL = "sora-2"
_DEFAULT_SIZE = "720x1280"
_DEFAULT_SECONDS = "4"
_ALLOWED_MODELS = ["sora-2", "sora-2-pro"]
_ALLOWED_SIZES = ["1280x720", "720x1280", "1024x1792", "1792x1024"]
_ALLOWED_SECONDS = ["4", "8", "12"]
_MIN_OPENAI_VERSION = (2, 44, 0)


class SoraVideo(BaseTool):
    name = "sora_video"
    version = "0.1.0"
    tier = ToolTier.GENERATE
    capability = "video_generation"
    provider = "openai"
    stability = ToolStability.BETA
    execution_mode = ExecutionMode.SYNC
    determinism = Determinism.STOCHASTIC
    runtime = ToolRuntime.API

    dependencies = []
    install_instructions = (
        "Set OPENAI_API_KEY to your OpenAI API key with Sora API access.\n"
        "  pip install 'openai>=2.44.0'"
    )
    agent_skills = ["ai-video-gen"]

    capabilities = ["text_to_video", "image_to_video"]
    supports = {
        "text_to_video": True,
        "image_to_video": True,
        "native_audio": True,
        "camera_direction": True,
        "social_ads": True,
        "short_clips": True,
    }
    best_for = [
        "OpenAI Sora 2 / Sora 2 Pro clips from the project .env credentials",
        "short cinematic product-ad inserts with native ambience or dialogue",
        "4, 8, or 12 second social-video clips that OpenMontage can stitch and compose",
    ]
    not_good_for = ["offline generation", "long continuous scenes", "projects without Sora API access"]
    fallback_tools = ["veo_video", "gemini_omni_video", "seedance_video", "kling_video", "minimax_video"]

    input_schema = {
        "type": "object",
        "required": ["prompt"],
        "properties": {
            "prompt": {"type": "string"},
            "operation": {
                "type": "string",
                "enum": ["text_to_video", "image_to_video"],
                "default": "text_to_video",
            },
            "model": {
                "type": "string",
                "enum": _ALLOWED_MODELS,
                "default": _DEFAULT_MODEL,
            },
            "size": {
                "type": "string",
                "enum": _ALLOWED_SIZES,
                "default": _DEFAULT_SIZE,
            },
            "aspect_ratio": {
                "type": "string",
                "enum": ["16:9", "9:16"],
                "default": "9:16",
                "description": "Selector-friendly alias used to choose 1280x720 or 720x1280 when size is omitted.",
            },
            "seconds": {
                "type": "string",
                "enum": _ALLOWED_SECONDS,
                "default": _DEFAULT_SECONDS,
            },
            "duration": {
                "type": "string",
                "description": "Alias for seconds. Must be one of 4, 8, or 12.",
            },
            "input_reference_path": {
                "type": "string",
                "description": "Optional jpg/png/webp reference image for image-to-video.",
            },
            "reference_image_path": {
                "type": "string",
                "description": "Alias for input_reference_path.",
            },
            "output_path": {"type": "string"},
        },
    }

    resource_profile = ResourceProfile(
        cpu_cores=1, ram_mb=512, vram_mb=0, disk_mb=1000, network_required=True
    )
    retry_policy = RetryPolicy(max_retries=1, retryable_errors=["rate_limit", "timeout"])
    idempotency_key_fields = ["prompt", "model", "size", "seconds"]
    side_effects = ["writes video file to output_path", "calls OpenAI Video API"]
    user_visible_verification = ["Watch generated clip for motion coherence, artifacts, and audio quality"]

    def get_status(self) -> ToolStatus:
        if not os.environ.get("OPENAI_API_KEY"):
            return ToolStatus.UNAVAILABLE
        if not self._openai_sdk_supports_videos():
            return ToolStatus.UNAVAILABLE
        return ToolStatus.AVAILABLE

    def estimate_cost(self, inputs: dict[str, Any]) -> float:
        seconds = int(self._normalize_seconds(inputs))
        # Placeholder estimate until the registry has live OpenAI video pricing.
        return 0.50 * (seconds / 4)

    def estimate_runtime(self, inputs: dict[str, Any]) -> float:
        seconds = int(self._normalize_seconds(inputs))
        return 120.0 * (seconds / 4)

    def execute(self, inputs: dict[str, Any]) -> ToolResult:
        if not os.environ.get("OPENAI_API_KEY"):
            return ToolResult(
                success=False,
                error="OPENAI_API_KEY not set. " + self.install_instructions,
            )
        if not self._openai_sdk_supports_videos():
            return ToolResult(
                success=False,
                error="OpenAI SDK with Videos API support is required. " + self.install_instructions,
            )

        from openai import OpenAI

        start = time.time()
        model = self._normalize_model(inputs)
        size = self._normalize_size(inputs, model)
        seconds = self._normalize_seconds(inputs)
        prompt = str(inputs["prompt"]).strip()
        output_path = Path(inputs.get("output_path", "sora_output.mp4"))
        output_path.parent.mkdir(parents=True, exist_ok=True)

        payload: dict[str, Any] = {
            "model": model,
            "prompt": prompt,
            "size": size,
            "seconds": seconds,
        }

        reference_path = inputs.get("input_reference_path") or inputs.get("reference_image_path")
        if inputs.get("operation") == "image_to_video" or reference_path:
            if not reference_path:
                return ToolResult(success=False, error="image_to_video requires input_reference_path")
            reference = Path(str(reference_path))
            if not reference.exists():
                return ToolResult(success=False, error=f"Input reference not found: {reference}")
            payload["input_reference"] = {"image_url": self._file_to_data_uri(reference)}

        client = OpenAI()
        try:
            video = client.videos.create_and_poll(**payload)
            video_id = self._get_video_id(video)
            if not video_id:
                return ToolResult(success=False, error=f"OpenAI Sora response did not include a video id: {video}")

            status = self._get_status_value(video)
            if status != "completed":
                return ToolResult(success=False, error=f"OpenAI Sora generation ended with status: {status}")

            content = client.videos.download_content(video_id, variant="video")
            self._write_download(content, output_path)
        except Exception as exc:
            return ToolResult(success=False, error=f"OpenAI Sora video generation failed: {exc}")

        return ToolResult(
            success=True,
            data={
                "provider": "openai",
                "model": model,
                "video_id": video_id,
                "prompt": prompt,
                "output": str(output_path),
                "size": size,
                "seconds": seconds,
                "format": "mp4",
            },
            artifacts=[str(output_path)],
            cost_usd=self.estimate_cost(inputs),
            duration_seconds=round(time.time() - start, 2),
            model=model,
        )

    @classmethod
    def _openai_sdk_supports_videos(cls) -> bool:
        try:
            import openai
            from openai import OpenAI
        except Exception:
            return False

        if cls._version_tuple(getattr(openai, "__version__", "")) < _MIN_OPENAI_VERSION:
            return False
        return hasattr(OpenAI(), "videos")

    @staticmethod
    def _version_tuple(version: str) -> tuple[int, int, int]:
        parts = []
        for part in version.split(".")[:3]:
            digits = "".join(ch for ch in part if ch.isdigit())
            parts.append(int(digits or "0"))
        while len(parts) < 3:
            parts.append(0)
        return tuple(parts)

    @staticmethod
    def _normalize_model(inputs: dict[str, Any]) -> str:
        model = str(inputs.get("model", _DEFAULT_MODEL)).strip().lower()
        if model not in _ALLOWED_MODELS:
            raise ValueError("model must be one of: sora-2, sora-2-pro")
        return model

    @staticmethod
    def _normalize_size(inputs: dict[str, Any], model: str) -> str:
        default_size = "1280x720" if inputs.get("aspect_ratio") == "16:9" else _DEFAULT_SIZE
        size = str(inputs.get("size", default_size)).strip().lower()
        allowed = {"1280x720", "720x1280"} if model == "sora-2" else set(_ALLOWED_SIZES)
        if size not in allowed:
            raise ValueError(f"size must be one of: {', '.join(sorted(allowed))} for model {model}")
        return size

    @staticmethod
    def _normalize_seconds(inputs: dict[str, Any]) -> str:
        seconds = str(inputs.get("seconds") or inputs.get("duration") or _DEFAULT_SECONDS).strip().lower()
        seconds = seconds[:-1] if seconds.endswith("s") else seconds
        if seconds not in _ALLOWED_SECONDS:
            raise ValueError("seconds must be one of: 4, 8, 12")
        return seconds

    @staticmethod
    def _get_status_value(video: Any) -> str:
        if isinstance(video, dict):
            return str(video.get("status") or video.get("state") or "unknown")
        return str(getattr(video, "status", None) or getattr(video, "state", None) or "unknown")

    @staticmethod
    def _get_video_id(video: Any) -> str | None:
        if isinstance(video, dict):
            value = video.get("id")
            return value if isinstance(value, str) else None
        value = getattr(video, "id", None)
        return value if isinstance(value, str) else None

    @staticmethod
    def _file_to_data_uri(path: Path) -> str:
        mime_type, _ = mimetypes.guess_type(path.name)
        if not mime_type:
            mime_type = "application/octet-stream"
        encoded = base64.b64encode(path.read_bytes()).decode("ascii")
        return f"data:{mime_type};base64,{encoded}"

    @staticmethod
    def _write_download(content: Any, output_path: Path) -> None:
        if hasattr(content, "write_to_file"):
            content.write_to_file(output_path)
            return
        if hasattr(content, "read"):
            output_path.write_bytes(content.read())
            return
        if hasattr(content, "content"):
            output_path.write_bytes(content.content)
            return
        output_path.write_bytes(bytes(content))

