    idempotency_key_fields = ["prompt", "width", "height", "steps", "seed"]
    side_effects = ["writes image file to output_path"]
    user_visible_verification = ["Inspect generated image for quality and prompt adherence"]

    def __init__(self) -> None:
        self._client = ComfyUIClient(capability="image")

    def get_status(self) -> ToolStatus:
        if not self._client.is_available():
            return ToolStatus.UNAVAILABLE
        _, missing = self._client.check_models(_REQUIRED_MODELS)
        if missing:
            return ToolStatus.DEGRADED
        return ToolStatus.AVAILABLE

    def estimate_cost(self, inputs: dict[str, Any]) -> float:
        return 0.0

    def estimate_runtime(self, inputs: dict[str, Any]) -> float:
        return float(inputs.get("steps", 20)) * 1.5

    def get_info(self) -> dict[str, Any]:
        info = super().get_info()
        info["setup_offer"] = self.setup_offer
        info["bundled_model_stack"] = BUNDLED_MODEL_STACKS["flux2-txt2img"]
        return info

    def execute(self, inputs: dict[str, Any]) -> ToolResult:
        custom_workflow = bool(inputs.get("workflow_json") or inputs.get("workflow_path"))
        if custom_workflow and not inputs.get("output_node"):
            return ToolResult(
                success=False,
                error=(
                    "Custom ComfyUI workflows require output_node so OpenMontage "
                    "knows which ComfyUI node to download artifacts from."
                ),
            )

        if not self._client.is_available():
            return ToolResult(
                success=False,
                error=self._client.unavailable_reason(),
            )

        if not custom_workflow:
            _, missing = self._client.check_models(_REQUIRED_MODELS)
            if missing:
                return ToolResult(
                    success=False,
                    data=missing_models_payload(
                        missing,
                        workflow_key="flux2-txt2img",
                        workflow_name="flux2-txt2img.json",
                    ),
                    error=(
                        f"ComfyUI server is running but missing required models: "
                        f"{', '.join(missing)}.\n"
                        f"See data.missing_models for destination hints and download URLs."
                    ),
                )

        start = time.time()
        seed = inputs.get("seed") or ComfyUIClient.random_seed()
        width = inputs.get("width", 1024)
        height = inputs.get("height", 1024)
        steps = inputs.get("steps", 20)
        guidance = inputs.get("guidance", 3.5)
        output_path = Path(inputs.get("output_path", f"comfyui_image_{seed}.png"))

        try:
            if custom_workflow:
                workflow = self._load_custom_workflow(inputs)
                output_node = str(inputs["output_node"])
            else:
                workflow = ComfyUIClient.load_workflow(_WORKFLOWS / "flux2-txt2img.json")
                workflow = ComfyUIClient.patch_workflow(workflow, {
                    "4": {"text": inputs["prompt"]},
                    "5": {"guidance": guidance},
                    "6": {"width": width, "height": height, "batch_size": 1},
                    "7": {"noise_seed": seed},
                    "10": {"steps": steps, "width": width, "height": height},
                    "13": {"filename_prefix": output_path.stem},
                })
                output_node = "13"

            provenance = self._workflow_provenance(
                inputs, custom_workflow, output_node, workflow
            )
            paths = self._client.generate(
                workflow, output_node=output_node, dest=output_path, timeout=600,
            )

        except ComfyUIError as exc:
            return ToolResult(success=False, error=str(exc))
        except Exception as exc:
            return ToolResult(success=False, error=f"ComfyUI image generation failed: {exc}")

        model_name = self._model_name(inputs, custom_workflow)
        return ToolResult(
            success=True,
            data={
                "provider": "comfyui",
                "model": model_name,
                "prompt": inputs["prompt"],
                "width": width,
                "height": height,
                "steps": steps,
                "guidance": guidance,
                "output": str(paths[0]),
                "format": "png",
                "workflow_provenance": provenance,
            },
            artifacts=[str(p) for p in paths],
            cost_usd=0.0,
            duration_seconds=round(time.time() - start, 2),
            seed=seed,
            model=model_name,
        )

    @staticmethod
    def _load_custom_workflow(inputs: dict[str, Any]) -> dict:
        if inputs.get("workflow_json"):
            return json.loads(inputs["workflow_json"])
        return ComfyUIClient.load_workflow(Path(inputs["workflow_path"]))

    @staticmethod
    def _model_name(inputs: dict[str, Any], custom_workflow: bool) -> str:
        if not custom_workflow:
            return "flux2-dev-nvfp4"
        return (
            inputs.get("workflow_model")
            or inputs.get("model")
            or inputs.get("workflow_name")
            or "custom-comfyui-workflow"
        )

    @staticmethod
    def _workflow_provenance(
        inputs: dict[str, Any],
        custom_workflow: bool,
        output_node: str,
        workflow: dict[str, Any],
    ) -> dict[str, Any]:
        if not custom_workflow:
            return {
                "source": "bundled",
                "workflow": "flux2-txt2img.json",
                "workflow_hash_sha256": workflow_hash(workflow),
                "model_stack": model_stack("flux2-txt2img", inputs),
                "output_node": output_node,
            }
        return {
            "source": "user_supplied",
            "workflow_name": inputs.get("workflow_name"),
            "workflow_path": inputs.get("workflow_path"),
            "model": inputs.get("workflow_model") or inputs.get("model"),
            "workflow_hash_sha256": workflow_hash(workflow),
            "model_stack": model_stack(None, inputs),
            "model_stack_source": (
                "caller_supplied"
                if inputs.get("workflow_model_stack")
                else "unknown_custom_workflow"
            ),
            "output_node": output_node,
        }

tools/graphics/dashscope_image.py:
"""DashScope (Alibaba Cloud Bailian) image generation via Qwen-Image models.

Uses the DashScope-native multimodal-generation endpoint (NOT OpenAI-compatible
mode, which only supports /chat/completions and /embeddings). The response
contains a temporary image URL (valid ~24h) that must be downloaded separately.
"""

from __future__ import annotations

import os
import time
from pathlib import Path
from typing import Any

from tools.base_tool import (
    BaseTool,
    Determinism,
    ExecutionMode,
    ResourceProfile,
    RetryPolicy,
    ToolResult,
    ToolRuntime,
    ToolStability,
    ToolStatus,
    ToolTier,
)


class DashscopeImage(BaseTool):
    name = "dashscope_image"
    version = "0.1.0"
    tier = ToolTier.GENERATE
    capability = "image_generation"
    provider = "dashscope"
    stability = ToolStability.EXPERIMENTAL
    execution_mode = ExecutionMode.SYNC
    determinism = Determinism.STOCHASTIC
    runtime = ToolRuntime.API

    dependencies = []
    install_instructions = (
        "Set DASHSCOPE_API_KEY to your Alibaba Cloud DashScope API key.\n"
        "  Get one at https://dashscope.aliyun.com/"
    )
    fallback = "grok_image"
    fallback_tools = ["grok_image", "openai_image", "flux_image", "recraft_image"]
    agent_skills = ["dashscope"]

    capabilities = ["generate_image", "text_to_image"]
    supports = {
        "multiple_outputs": True,
        "aspect_ratio": True,
        "resolution": True,
        "negative_prompt": True,
        "seed": True,
    }
    best_for = [
        "high-quality image generation with Qwen-Image models",
        "Chinese-language prompt understanding",
        "cost-effective image generation via Alibaba Cloud",
    ]
    not_good_for = ["offline generation", "image editing (use grok_image edit mode)"]

    input_schema = {
        "type": "object",
        "required": ["prompt"],
        "properties": {
            "prompt": {"type": "string"},
            "model": {
                "type": "string",
                "enum": [
                    "qwen-image-2.0-pro",
                    "qwen-image-max",
                    "wan2.7-image",
                    "z-image-turbo",
                ],
                "default": "qwen-image-2.0-pro",
            },
            "size": {
                "type": "string",
                "default": "1024*1024",
                "description": (
                    'Image size as "W*H" (asterisk separator, NOT "x"). '
                    'Examples: "1024*1024", "2048*2048", "2688*1536".'
                ),
            },
            "n": {"type": "integer", "default": 1, "minimum": 1, "maximum": 6},
            "negative_prompt": {
                "type": "string",
                "description": "Negative prompt (max 500 chars). Things to avoid in the image.",
            },
            "prompt_extend": {
                "type": "boolean",
                "default": True,
                "description": "Enable DashScope prompt auto-rewrite for better results.",
            },
            "watermark": {"type": "boolean", "default": False},
            "seed": {"type": "integer", "minimum": 0, "maximum": 2147483647},
            "output_path": {"type": "string"},
        },
    }

    resource_profile = ResourceProfile(
        cpu_cores=1, ram_mb=512, vram_mb=0, disk_mb=100, network_required=True
    )
    retry_policy = RetryPolicy(
        max_retries=2, retryable_errors=["rate_limit", "timeout"]
    )
    idempotency_key_fields = [
        "prompt",
        "model",
        "size",
        "n",
        "negative_prompt",
        "seed",
        "prompt_extend",
        "watermark",
    ]
    side_effects = [
        "writes image file to output_path",
        "calls DashScope (Alibaba Cloud) image generation API",
    ]
    user_visible_verification = [
        "Inspect generated image for relevance and quality"
    ]

    ENDPOINT = (
        "https://dashscope.aliyuncs.com/api/v1/services/aigc/"
        "multimodal-generation/generation"
    )

    def get_status(self) -> ToolStatus:
        if os.environ.get("DASHSCOPE_API_KEY"):
            return ToolStatus.AVAILABLE
        return ToolStatus.UNAVAILABLE

    def estimate_cost(self, inputs: dict[str, Any]) -> float:
        # Conservative per-image estimate; DashScope bills per image.
        # Check the DashScope console for actual pricing.
        n = int(inputs.get("n", 1))
        return n * 0.02

    def execute(self, inputs: dict[str, Any]) -> ToolResult:
        api_key = os.environ.get("DASHSCOPE_API_KEY")
        if not api_key:
            return ToolResult(
                success=False,
                error="DASHSCOPE_API_KEY not set. " + self.install_instructions,
            )

        import requests

        start = time.time()
        try:
            payload = self._build_payload(inputs)
            response = requests.post(
                self.ENDPOINT,
                headers={
                    "Authorization": f"Bearer {api_key}",
                    "Content-Type": "application/json",
                },
                json=payload,
                timeout=180,
            )
            response.raise_for_status()
            data = response.json()

            image_urls = self._extract_image_urls(data)
            if not image_urls:
                return ToolResult(
                    success=False,
                    error="DashScope returned no image URLs",
                )

            # DashScope bills per image and URLs expire ~24h; save every one.
            output_paths = self._resolve_output_paths(
                inputs.get("output_path", "dashscope_image.png"),
                count=len(image_urls),
            )
            for path, url in zip(output_paths, image_urls):
                download = requests.get(url, timeout=120)
                download.raise_for_status()
                path.parent.mkdir(parents=True, exist_ok=True)
                path.write_bytes(download.content)

            usage = data.get("usage", {})
            n_generated = len(image_urls)

        except Exception as e:
            return ToolResult(
                success=False,
                error=f"DashScope image generation failed: {self._safe_error(e)}",
            )

        return ToolResult(
            success=True,
            data={
                "provider": "dashscope",
                "model": payload["model"],
                "prompt": inputs["prompt"],
                "size": payload["parameters"]["size"],
                "output": str(output_paths[0]),
                "outputs": [str(p) for p in output_paths],
                "images_generated": n_generated,
                "usage": usage,
            },
            artifacts=[str(p) for p in output_paths],
            cost_usd=self.estimate_cost(inputs),
            duration_seconds=round(time.time() - start, 2),
            model=payload["model"],
        )

    @staticmethod
    def _extract_image_urls(data: dict[str, Any]) -> list[str]:
        """Collect image URLs from every choice whose finish_reason is "stop".

        Per Qwen Cloud docs, a multi-output task is SUCCEEDED if at least one
        image is generated; failed choices carry finish_reason != "stop" and
        must be skipped to avoid downloading partial/empty results.
        """
        urls: list[str] = []
        for choice in data.get("output", {}).get("choices", []):
            if choice.get("finish_reason") != "stop":
                continue
            for item in choice.get("message", {}).get("content", []):
                url = item.get("image")
                if url:
                    urls.append(url)
        return urls

    @staticmethod
    def _resolve_output_paths(base: str, count: int) -> list[Path]:
        """Derive distinct paths for `count` images. Single image keeps the
        base path unchanged; multiple images insert an index before the
        extension (foo.png -> foo_1.png, foo_2.png, ...)."""
        base_path = Path(base)
        if count <= 1:
            return [base_path]
        stem = base_path.stem
        suffix = base_path.suffix
        parent = base_path.parent
        return [parent / f"{stem}_{i}{suffix}" for i in range(1, count + 1)]

    def _build_payload(self, inputs: dict[str, Any]) -> dict[str, Any]:
        parameters: dict[str, Any] = {
            "size": inputs.get("size", "1024*1024"),
            "n": int(inputs.get("n", 1)),
            "prompt_extend": bool(inputs.get("prompt_extend", True)),
            "watermark": bool(inputs.get("watermark", False)),
        }
        if inputs.get("negative_prompt"):
            parameters["negative_prompt"] = inputs["negative_prompt"]
        if inputs.get("seed") is not None:
            parameters["seed"] = int(inputs["seed"])

        return {
            "model": inputs.get("model", "qwen-image-2.0-pro"),
            "input": {
                "messages": [
                    {
                        "role": "user",
                        "content": [{"text": inputs["prompt"]}],
                    }
                ]
            },
            "parameters": parameters,
        }

    @staticmethod
    def _safe_error(exc: Exception) -> str:
        return str(exc).replace(
            os.environ.get("DASHSCOPE_API_KEY", ""), "[redacted]"
        )

tools/graphics/diagram_gen.py:
"""Diagram generation tool using Mermaid CLI, Cairo/Pillow, or Graphviz.

Generates technical diagrams from text descriptions. Supports Mermaid
syntax (flowcharts, sequence diagrams, etc.) and simple box/arrow
diagrams via Pillow as fallback.
"""

from __future__ import annotations

import functools
import json
import re
import shutil
import subprocess
import time
from pathlib import Path
from typing import Any, Optional

from tools.base_tool import (
    BaseTool,
    Determinism,
    ExecutionMode,
    ResourceProfile,
    ToolResult,
    ToolStability,
    ToolStatus,
    ToolTier,
)


@functools.lru_cache(maxsize=None)
def _mmdc_major_version(mmdc_path: str) -> Optional[int]:
    """Return the installed mermaid-cli major version, or None if unknown."""
    try:
        proc = subprocess.run(
            [mmdc_path, "--version"], capture_output=True, text=True, timeout=30
        )
    except (OSError, subprocess.TimeoutExpired):
        return None
    match = re.search(r"(\d+)\.\d+", proc.stdout or "")
    return int(match.group(1)) if match else None


def _mmdc_width_args(width: int) -> list[str]:
    """mermaid-cli 12 replaced ``-w/--width`` with ``--size``."""
    mmdc_path = shutil.which("mmdc")
    major = _mmdc_major_version(mmdc_path) if mmdc_path else None
    if major is not None and major >= 12:
        return ["--size", str(width)]
    return ["-w", str(width)]


class DiagramGen(BaseTool):
    name = "diagram_gen"
    version = "0.1.0"
    tier = ToolTier.CORE
    capability = "graphics"
    provider = "mermaid"
    stability = ToolStability.EXPERIMENTAL
    execution_mode = ExecutionMode.SYNC
    determinism = Determinism.DETERMINISTIC

    dependencies = []  # checked dynamically
    install_instructions = (
        "For Mermaid diagrams:\n"
        "  npm install -g @mermaid-js/mermaid-cli\n"
        "For Pillow-based diagrams (fallback):\n"
        "  pip install Pillow"
    )
    agent_skills = ["beautiful-mermaid", "d3-viz"]

    capabilities = [
        "generate_mermaid",
        "generate_flowchart",
        "generate_box_diagram",
    ]

    input_schema = {
        "type": "object",
        "required": ["diagram_type"],
        "properties": {
            "diagram_type": {
                "type": "string",
                "enum": ["mermaid", "flowchart", "boxes"],
            },
            "definition": {
                "type": "string",
                "description": "Mermaid syntax or diagram description",
            },
            "boxes": {
                "type": "array",
                "items": {
                    "type": "object",
                    "properties": {
                        "label": {"type": "string"},
                        "color": {"type": "string"},
                    },
                },
                "description": "Box definitions for box diagram type",
            },
            "connections": {
                "type": "array",
                "items": {
                    "type": "object",
                    "properties": {
                        "from": {"type": "integer"},
                        "to": {"type": "integer"},
                        "label": {"type": "string"},
                    },
                },
            },
            "title": {"type": "string"},
            "theme": {
                "type": "string",
                "enum": ["dark", "light", "neutral"],
                "default": "dark",
            },
            "width": {"type": "integer", "default": 1200},
            "height": {"type": "integer", "default": 800},
            "output_path": {"type": "string"},
            "allow_text_fallback": {
                "type": "boolean",
                "default": False,
                "description": "Render Mermaid source as a text card when Mermaid CLI is unavailable",
            },
        },
    }

    resource_profile = ResourceProfile(cpu_cores=1, ram_mb=256, vram_mb=0, disk_mb=50)
    idempotency_key_fields = [
        "diagram_type", "definition", "boxes", "connections",
        "title", "theme", "width", "height", "allow_text_fallback",
    ]
    side_effects = ["writes diagram image to output_path"]
    user_visible_verification = [
        "Verify diagram accurately represents the described structure",
    ]

    def get_status(self) -> ToolStatus:
        statuses = self.operation_statuses()
        if all(status == "available" for status in statuses.values()):
            return ToolStatus.AVAILABLE
        if any(status == "available" for status in statuses.values()):
            return ToolStatus.DEGRADED
        return ToolStatus.UNAVAILABLE

    def operation_statuses(self) -> dict[str, str]:
        """Return backend availability for each supported diagram type."""
        return {
            "mermaid": "available" if self._has_mermaid() else "unavailable",
            "flowchart": "available" if self._has_pillow() else "unavailable",
            "boxes": "available" if self._has_pillow() else "unavailable",
        }

    def get_info(self) -> dict[str, Any]:
        info = super().get_info()
        info["operation_statuses"] = self.operation_statuses()
        return info

    def idempotency_key(self, inputs: dict[str, Any]) -> str:
        return super().idempotency_key(
            {**inputs, "allow_text_fallback": inputs.get("allow_text_fallback", False)}
        )

    def cache_key(self, inputs: dict[str, Any]) -> str:
        return super().cache_key(
            {**inputs, "allow_text_fallback": inputs.get("allow_text_fallback", False)}
        )

    def _has_mermaid(self) -> bool:
        return shutil.which("mmdc") is not None

    def _has_pillow(self) -> bool:
        try:
            from PIL import Image  # noqa: F401
            return True
        except ImportError:
            return False

    def execute(self, inputs: dict[str, Any]) -> ToolResult:
        diagram_type = inputs["diagram_type"]
        start = time.time()

        try:
            if diagram_type == "mermaid":
                result = self._render_mermaid(inputs)
            elif diagram_type in ("flowchart", "boxes"):
                result = self._render_boxes(inputs)
            else:
                return ToolResult(success=False, error=f"Unknown diagram type: {diagram_type}")
        except Exception as e:
            return ToolResult(success=False, error=f"Diagram generation failed: {e}")

        result.duration_seconds = round(time.time() - start, 2)
        return result

    def _render_mermaid(self, inputs: dict[str, Any]) -> ToolResult:
        definition = inputs.get("definition", "")
        if not definition:
            return ToolResult(success=False, error="Mermaid definition required")

        output_path = Path(inputs.get("output_path", "diagram.png"))
        output_path.parent.mkdir(parents=True, exist_ok=True)
        theme = inputs.get("theme", "dark")

        if self._has_mermaid():
            # Write temp mermaid file
            temp_mmd = output_path.with_suffix(".mmd")
            temp_mmd.write_text(definition, encoding="utf-8")

            mermaid_config = {"theme": theme}
            config_path = output_path.with_suffix(".mermaid.json")
            config_path.write_text(json.dumps(mermaid_config), encoding="utf-8")

            cmd = [
                "mmdc",
                "-i", str(temp_mmd),
                "-o", str(output_path),
                "-c", str(config_path),
                "-b", "transparent",
                *_mmdc_width_args(inputs.get("width", 1200)),
            ]

            try:
                self.run_command(cmd, timeout=30)
            finally:
                temp_mmd.unlink(missing_ok=True)
                config_path.unlink(missing_ok=True)

            return ToolResult(
                success=True,
                data={
                    "method": "mermaid-cli",
                    "output": str(output_path),
                },
                artifacts=[str(output_path)],
            )
        if inputs.get("allow_text_fallback", False):
            return self._render_text_card(definition, inputs)

        return ToolResult(
            success=False,
            error=(
                "Mermaid CLI (mmdc) is not available. "
                "Install it with: npm install -g @mermaid-js/mermaid-cli"
            ),
        )

    def _render_boxes(self, inputs: dict[str, Any]) -> ToolResult:
        """Render a box-and-arrow diagram using Pillow."""
        if not self._has_pillow():
            return ToolResult(
                success=False,
                error="Pillow required for box diagrams. Run: pip install Pillow",
            )

        from PIL import Image, ImageDraw, ImageFont

        boxes = inputs.get("boxes", [])
        connections = inputs.get("connections", [])
        title = inputs.get("title", "")
        theme = inputs.get("theme", "dark")
        width = inputs.get("width", 1200)
        height = inputs.get("height", 800)
        output_path = Path(inputs.get("output_path", "diagram.png"))
        output_path.parent.mkdir(parents=True, exist_ok=True)

        # Theme colors
        if theme == "dark":
            bg, text_color, box_default, line_color = "#1e1e2e", "#cdd6f4", "#45475a", "#89b4fa"
        elif theme == "light":
            bg, text_color, box_default, line_color = "#ffffff", "#333333", "#e1e4e8", "#0366d6"
        else:
            bg, text_color, box_default, line_color = "#2d2d2d", "#d4d4d4", "#404040", "#569cd6"

        img = Image.new("RGB", (width, height), bg)
        draw = ImageDraw.Draw(img)

        try:
            font = ImageFont.truetype("arial.ttf", 18)
            title_font = ImageFont.truetype("arial.ttf", 24)
        except (IOError, OSError):
            font = ImageFont.load_default()
            title_font = font

        # Draw title
        y_offset = 20
        if title:
            bbox = draw.textbbox((0, 0), title, font=title_font)
            tw = bbox[2] - bbox[0]
            draw.text(((width - tw) // 2, y_offset), title, fill=text_color, font=title_font)
            y_offset += 50

        # Layout boxes in a grid
        if not boxes:
            boxes = [{"label": "Empty"}]

        cols = min(len(boxes), 4)
        rows = (len(boxes) + cols - 1) // cols
        box_w = min(200, (width - 80) // cols - 20)
        box_h = 60
        x_gap = (width - cols * box_w) // (cols + 1)
        y_gap = max(40, (height - y_offset - rows * box_h) // (rows + 1))

        box_positions = []
        for i, box in enumerate(boxes):
            col = i % cols
            row = i // cols
            x = x_gap + col * (box_w + x_gap)
            y = y_offset + y_gap + row * (box_h + y_gap)

            fill = box.get("color", box_default)
            draw.rounded_rectangle(
                [(x, y), (x + box_w, y + box_h)],
                radius=8,
                fill=fill,
                outline=line_color,
                width=2,
            )

            label = box.get("label", f"Box {i}")
            bbox = draw.textbbox((0, 0), label, font=font)
            lw = bbox[2] - bbox[0]
            lh = bbox[3] - bbox[1]
            draw.text(
                (x + (box_w - lw) // 2, y + (box_h - lh) // 2),
                label, fill=text_color, font=font,
            )

            box_positions.append((x, y, x + box_w, y + box_h))

        # Draw connections
        for conn in connections:
            fi = conn.get("from", 0)
            ti = conn.get("to", 0)
            if fi >= len(box_positions) or ti >= len(box_positions):
                continue

            fx1, fy1, fx2, fy2 = box_positions[fi]
            tx1, ty1, tx2, ty2 = box_positions[ti]

            start_x = (fx1 + fx2) // 2
            start_y = fy2
            end_x = (tx1 + tx2) // 2
            end_y = ty1

            draw.line([(start_x, start_y), (end_x, end_y)], fill=line_color, width=2)

            # Arrow head
            arrow_size = 8
            draw.polygon(
                [(end_x, end_y), (end_x - arrow_size, end_y - arrow_size * 2), (end_x + arrow_size, end_y - arrow_size * 2)],
                fill=line_color,
            )

            # Connection label
            conn_label = conn.get("label")
            if conn_label:
                mid_x = (start_x + end_x) // 2
                mid_y = (start_y + end_y) // 2
                draw.text((mid_x + 5, mid_y - 10), conn_label, fill=text_color, font=font)

        img.save(output_path)

        return ToolResult(
            success=True,
            data={
                "method": "pillow",
                "output": str(output_path),
                "box_count": len(boxes),
                "connection_count": len(connections),
            },
            artifacts=[str(output_path)],
        )

    def _render_text_card(self, text: str, inputs: dict[str, Any]) -> ToolResult:
        """Fallback: render text as a styled card image."""
        if not self._has_pillow():
            return ToolResult(
                success=False,
                error="Pillow required. Run: pip install Pillow",
            )

        from PIL import Image, ImageDraw, ImageFont

        output_path = Path(inputs.get("output_path", "diagram.png"))
        output_path.parent.mkdir(parents=True, exist_ok=True)
        width = inputs.get("width", 800)

        try:
            font = ImageFont.truetype("consola.ttf", 16)
        except (IOError, OSError):
            font = ImageFont.load_default()

        # Calculate needed height
        lines = text.split("\n")
        line_height = 22
        height = max(200, len(lines) * line_height + 80)

        img = Image.new("RGB", (width, height), "#1e1e2e")
        draw = ImageDraw.Draw(img)

        y = 40
        for line in lines:
            draw.text((40, y), line, fill="#cdd6f4", font=font)
            y += line_height

        img.save(output_path)

        return ToolResult(
            success=True,
            data={
                "method": "text_card",
                "output": str(output_path),
            },
            artifacts=[str(output_path)],
        )

tools/graphics/fal_3d.py:
"""Text/image-to-3D and object reconstruction through fal.ai."""

from __future__ import annotations

import json
import os
import time
from pathlib import Path
from typing import Any
from urllib.parse import urlparse

import requests

from tools.base_tool import (
    BaseTool,
    Determinism,
    ExecutionMode,
    ResourceProfile,
    RetryPolicy,
    ToolResult,
    ToolRuntime,
    ToolStability,
    ToolStatus,
    ToolTier,
)


_MODELS = {
    "text_to_3d": "fal-ai/hunyuan-3d/v3.1/rapid/text-to-3d",
    "image_to_3d": "fal-ai/hunyuan-3d/v3.1/rapid/image-to-3d",
    "reconstruct_objects": "fal-ai/sam-3/3d-objects",
}


def _api_key() -> str | None:
    return os.environ.get("FAL_KEY") or os.environ.get("FAL_AI_API_KEY")


def _download_file(file_info: dict[str, Any], destination: Path) -> Path:
    url = str(file_info["url"])
    suffix = Path(urlparse(url).path).suffix.lower()
    if suffix not in {".glb", ".gltf", ".obj", ".fbx", ".ply", ".zip"}:
        suffix = ".glb" if file_info.get("content_type") == "model/gltf-binary" else destination.suffix
    target = destination.with_suffix(suffix or ".glb")
    response = requests.get(url, timeout=180)
    response.raise_for_status()
    target.parent.mkdir(parents=True, exist_ok=True)
    target.write_bytes(response.content)
    return target


class Fal3D(BaseTool):
    name = "fal_3d"
    version = "0.1.0"
    tier = ToolTier.GENERATE
    capability = "3d_asset_generation"
    provider = "fal"
    stability = ToolStability.BETA
    execution_mode = ExecutionMode.ASYNC
    determinism = Determinism.SEEDED
    runtime = ToolRuntime.API
    dependencies = ["env:FAL_KEY"]
    install_instructions = "Set FAL_KEY (or FAL_AI_API_KEY). Create a key at https://fal.ai/dashboard/keys."
    agent_skills = ["3d-asset-generation", "threejs-loaders", "threejs-materials"]
    capabilities = ["text_to_3d", "image_to_3d", "multi_object_reconstruction", "textured_glb", "pbr_mesh"]
    supports = {
        "text_to_3d": True,
        "image_to_3d": True,
        "multi_object": True,
        "pbr": True,
        "glb": True,
        "seed": True,
    }
    best_for = [
        "Image-conditioned hero props whose silhouette must match concept art",
        "Extracting multiple textured GLBs and placements from a regional concept image",
        "Rapid textured environment assets",
    ]
    not_good_for = ["Rendering a complete cinematic world", "Large repeated scatter libraries"]
    input_schema = {
        "type": "object",
        "required": ["operation", "output_path"],
        "properties": {
            "operation": {"type": "string", "enum": list(_MODELS)},
            "prompt": {"type": "string"},
            "image_url": {"type": "string"},
            "image_path": {"type": "string"},
            "output_path": {"type": "string"},
            "enable_pbr": {"type": "boolean", "default": True},
            "seed": {"type": "integer"},
            "export_textured_glb": {"type": "boolean", "default": True},
            "detection_threshold": {"type": "number", "minimum": 0.1, "maximum": 1.0},
            "poll_timeout_seconds": {"type": "integer", "minimum": 30, "maximum": 1800, "default": 900},
        },
    }
    output_schema = {"type": "object"}
    artifact_schema = {"artifact": "3d_asset"}
    resource_profile = ResourceProfile(cpu_cores=1, ram_mb=512, disk_mb=2000, network_required=True)
    retry_policy = RetryPolicy(max_retries=1, retryable_errors=["rate_limit", "timeout"])
    idempotency_key_fields = ["operation", "prompt", "image_url", "image_path", "enable_pbr", "seed"]
    side_effects = ["calls fal.ai", "may upload a local input image", "writes generated 3D assets and provenance"]
    user_visible_verification = ["Inspect silhouette, back-side completion, topology, texture seams, and material response"]
    quality_score = 0.88

    def get_status(self) -> ToolStatus:
        return ToolStatus.AVAILABLE if _api_key() else ToolStatus.UNAVAILABLE

    def estimate_cost(self, inputs: dict[str, Any]) -> float:
        if inputs.get("operation") == "reconstruct_objects":
            return 0.02
        return 0.225 + (0.15 if inputs.get("enable_pbr", True) else 0.0)

    def execute(self, inputs: dict[str, Any]) -> ToolResult:
        key = _api_key()
        if not key:
            return ToolResult(success=False, error="fal.ai API key not set. " + self.install_instructions)
        operation = str(inputs.get("operation") or "")
        if operation not in _MODELS:
            return ToolResult(success=False, error=f"Unknown operation {operation!r}")
        if operation == "text_to_3d" and not inputs.get("prompt"):
            return ToolResult(success=False, error="prompt is required for text_to_3d")
        if operation != "text_to_3d" and not (inputs.get("image_url") or inputs.get("image_path")):
            return ToolResult(success=False, error=f"image_url or image_path is required for {operation}")

        payload: dict[str, Any] = {}
        if operation == "text_to_3d":
            payload["prompt"] = inputs["prompt"]
            payload["enable_pbr"] = bool(inputs.get("enable_pbr", True))
        else:
            image_url = inputs.get("image_url")
            if not image_url:
                from tools.video._shared import upload_image_fal
                image_url = upload_image_fal(str(inputs["image_path"]))
            payload["image_url" if operation == "reconstruct_objects" else "input_image_url"] = image_url
            if operation == "image_to_3d":
                payload["enable_pbr"] = bool(inputs.get("enable_pbr", True))
            else:
                payload["export_textured_glb"] = bool(inputs.get("export_textured_glb", True))
                if inputs.get("prompt"):
                    payload["prompt"] = inputs["prompt"]
                if inputs.get("detection_threshold") is not None:
                    payload["detection_threshold"] = inputs["detection_threshold"]
        if inputs.get("seed") is not None:
            payload["seed"] = inputs["seed"]

        headers = {"Authorization": f"Key {key}", "Content-Type": "application/json"}
        model = _MODELS[operation]
        started = time.time()
        try:
            submit = requests.post(f"https://queue.fal.run/{model}", headers=headers, json=payload, timeout=45)
            submit.raise_for_status()
            queued = submit.json()
            status_url = queued["status_url"]
            response_url = queued["response_url"]
            deadline = time.monotonic() + int(inputs.get("poll_timeout_seconds", 900))
            while time.monotonic() < deadline:
                status_response = requests.get(status_url, headers=headers, timeout=30)
                status_response.raise_for_status()
                status = str(status_response.json().get("status", "")).upper()
                if status == "COMPLETED":
                    break
                if status in {"FAILED", "CANCELLED"}:
                    raise RuntimeError(f"request {status.lower()}")
                time.sleep(3)
            else:
                raise TimeoutError("fal.ai request exceeded the poll timeout")
            result_response = requests.get(response_url, headers=headers, timeout=45)
            result_response.raise_for_status()
            data = result_response.json()

            destination = Path(str(inputs["output_path"])).expanduser().resolve()
            file_infos: list[dict[str, Any]] = []
            if operation == "reconstruct_objects":
                if data.get("model_glb"):
                    file_infos.append(data["model_glb"])
                file_infos.extend(data.get("individual_glbs") or [])
            else:
                urls = data.get("model_urls") or {}
                candidate = urls.get("glb") or data.get("model_glb") or urls.get("obj")
                if candidate:
                    file_infos.append(candidate)
            if not file_infos:
                raise RuntimeError("fal.ai completed without a downloadable mesh")

            artifacts: list[str] = []
            for index, file_info in enumerate(file_infos):
                target = destination if index == 0 else destination.with_name(f"{destination.stem}-{index:02d}{destination.suffix}")
                artifacts.append(str(_download_file(file_info, target)))
            provenance = destination.with_suffix(".provenance.json")
            provenance.write_text(json.dumps({
                "version": "1.0",
                "provider": "fal",
                "model": model,
                "request_id": queued.get("request_id"),
                "operation": operation,
                "prompt": inputs.get("prompt"),
                "metadata": data.get("metadata"),
                "source_url": f"https://fal.ai/models/{model}",
                "outputs": artifacts,
            }, indent=2), encoding="utf-8")
            artifacts.append(str(provenance))
        except Exception as exc:
            return ToolResult(success=False, error=f"fal.ai 3D generation failed: {exc}")

        return ToolResult(
            success=True,
            data={"provider": "fal", "model": model, "operation": operation, "outputs": artifacts[:-1]},
            artifacts=artifacts,
            cost_usd=self.estimate_cost(inputs),
            duration_seconds=round(time.time() - started, 2),
            seed=inputs.get("seed"),
            model=model,
        )

