  background: transparent;
  color: #f5f8ff;
}

.world-stage { position: absolute; inset: 0; width: 100%; height: 100%; overflow: hidden; background: #05080d; }
#world-canvas { position: absolute; inset: 0; width: 100%; height: 100%; display: block; }

#world-vignette {
