    determinism = Determinism.DETERMINISTIC

    dependencies = ["cmd:ffmpeg"]
    install_instructions = "Install FFmpeg: https://ffmpeg.org/download.html"
    agent_skills = ["ffmpeg"]

    capabilities = [
        "skin_smoothing",
        "sharpening",
        "lighting_correction",
        "color_balance",
        "denoise",
        "preset_chain",
    ]

    input_schema = {
        "type": "object",
        "required": ["input_path"],
        "properties": {
            "input_path": {"type": "string"},
            "output_path": {"type": "string"},
            "preset": {
                "type": "string",
                "enum": list(PRESETS.keys()),
                "default": "talking_head_standard",
            },
            "presets": {
                "type": "array",
                "items": {"type": "string"},
                "description": "Apply multiple presets in sequence",
            },
            "custom_vf": {
                "type": "string",
                "description": "Custom FFmpeg video filter string (advanced)",
            },
            "codec": {"type": "string", "default": "libx264"},
            "crf": {"type": "integer", "default": 20},
        },
    }

    resource_profile = ResourceProfile(cpu_cores=2, ram_mb=1024, vram_mb=0, disk_mb=2000)
    idempotency_key_fields = [
        "input_path", "preset", "presets", "custom_vf",
        "codec", "crf",
    ]
    side_effects = ["writes enhanced video to output_path"]
    user_visible_verification = [
        "Compare enhanced output with original side-by-side",
        "Verify skin texture is natural, not plastic",
    ]

    def execute(self, inputs: dict[str, Any]) -> ToolResult:
        input_path = Path(inputs["input_path"])
        if not input_path.exists():
            return ToolResult(success=False, error=f"Input not found: {input_path}")

        output_path = Path(
            inputs.get("output_path", str(input_path.with_stem(f"{input_path.stem}_enhanced")))
        )
        codec = inputs.get("codec", "libx264")
        crf = inputs.get("crf", 20)

        # Build filter chain
        vf = self._build_filter(inputs)
        if not vf:
            return ToolResult(success=False, error="No preset, presets, or custom_vf specified")

        start = time.time()

        cmd = [
            "ffmpeg", "-y",
            "-i", str(input_path),
            "-vf", vf,
            "-c:v", codec, "-crf", str(crf),
            "-c:a", "copy",
            str(output_path),
        ]

        try:
            self.run_command(cmd)
        except Exception as e:
            return ToolResult(success=False, error=f"FFmpeg failed: {e}")

        elapsed = time.time() - start

        return ToolResult(
            success=True,
            data={
                "input": str(input_path),
                "output": str(output_path),
                "filter": vf,
                "preset": inputs.get("preset"),
            },
            artifacts=[str(output_path)],
            duration_seconds=round(elapsed, 2),
        )

    def _build_filter(self, inputs: dict[str, Any]) -> str:
        if "custom_vf" in inputs:
            return inputs["custom_vf"]

        if "presets" in inputs:
            chains = []
            for name in inputs["presets"]:
                if name not in PRESETS:
                    continue
                chains.append(PRESETS[name]["vf"])
            return ",".join(chains)

        preset_name = inputs.get("preset", "talking_head_standard")
        preset = PRESETS.get(preset_name)
        if preset:
            return preset["vf"]
        return ""

    @staticmethod
    def list_presets() -> dict[str, str]:
        """Return available presets and their descriptions."""
        return {name: p["description"] for name, p in PRESETS.items()}

tools/enhancement/face_restore.py:
"""Face restoration tool wrapping CodeFormer / GFPGAN.

Restores degraded or low-quality faces in images and video frames.
Fixes blur, compression artifacts, and low resolution specifically on
face regions while preserving the rest of the image.
"""

from __future__ import annotations

import time
from pathlib import Path
from typing import Any

from tools.base_tool import (
    BaseTool,
    Determinism,
    ExecutionMode,
    ResourceProfile,
    ToolResult,
    ToolRuntime,
    ToolStability,
    ToolStatus,
    ToolTier,
)
from tools.enhancement._basicsr_compat import ensure_basicsr_compat


class FaceRestore(BaseTool):
    name = "face_restore"
    version = "0.1.0"
    tier = ToolTier.ENHANCE
    capability = "enhancement"
    provider = "codeformer"
    stability = ToolStability.EXPERIMENTAL
    execution_mode = ExecutionMode.SYNC
    determinism = Determinism.DETERMINISTIC
    runtime = ToolRuntime.LOCAL_GPU

    dependencies = ["python:gfpgan", "python:torch"]
    install_instructions = (
        "uv pip install gfpgan torch\n"
        "Works on: CUDA (NVIDIA), MPS (Apple Silicon M-series, macOS >= 12.3), CPU fallback.\n"
        "No CUDA build needed on macOS — uv pip install torch includes MPS support."
    )
    agent_skills = ["ffmpeg"]
    fallback = None

    capabilities = [
        "face_restoration",
        "face_detection",
        "quality_enhancement",
    ]

    input_schema = {
        "type": "object",
        "required": ["input_path"],
        "properties": {
            "input_path": {
                "type": "string",
                "description": "Path to image or video frame",
            },
            "output_path": {
                "type": "string",
                "description": "Output path (defaults to {stem}_restored.{ext})",
            },
            "model": {
                "type": "string",
                "enum": ["GFPGAN", "CodeFormer"],
                "default": "GFPGAN",
                "description": (
                    "Restoration model to use. CodeFormer is not available yet: "
                    "the gfpgan package has no CodeFormer architecture."
                ),
            },
            "fidelity": {
                "type": "number",
                "default": 0.5,
                "description": (
                    "0 = max quality, 1 = max fidelity to input (CodeFormer only)"
                ),
            },
            "upscale": {
                "type": "integer",
                "default": 2,
                "description": "Face upscale factor",
            },
            "bg_upsampler": {
                "type": "boolean",
                "default": False,
                "description": "Also upscale background with Real-ESRGAN",
            },
        },
    }

    resource_profile = ResourceProfile(
        cpu_cores=2, ram_mb=2048, vram_mb=2048, disk_mb=1000
    )
    idempotency_key_fields = ["input_path", "model", "fidelity", "upscale"]
    side_effects = ["writes restored image to output_path"]
    user_visible_verification = [
        "Compare restored face with original for natural appearance",
        "Verify face identity is preserved after restoration",
    ]

    def get_status(self) -> ToolStatus:
        try:
            ensure_basicsr_compat()
            import gfpgan  # noqa: F401
            return ToolStatus.AVAILABLE
        except ImportError:
            return ToolStatus.UNAVAILABLE

    def execute(self, inputs: dict[str, Any]) -> ToolResult:
        input_path = Path(inputs["input_path"])
        if not input_path.exists():
            return ToolResult(success=False, error=f"Input not found: {input_path}")

        output_path = Path(
            inputs.get(
                "output_path",
                str(input_path.with_stem(f"{input_path.stem}_restored")),
            )
        )
        model_name = inputs.get("model", "GFPGAN")
        if model_name == "CodeFormer":
            # GFPGANer only builds GFPGAN/RestoreFormer archs; asking it for
            # CodeFormer used to download the weights and then fail to load.
            return ToolResult(
                success=False,
                error="CodeFormer is not supported by the gfpgan backend; use model='GFPGAN'.",
            )
        fidelity = inputs.get("fidelity", 0.5)
        upscale = inputs.get("upscale", 2)
        bg_upsampler_flag = inputs.get("bg_upsampler", False)

        try:
            import cv2
            import inspect
            ensure_basicsr_compat()
            from gfpgan import GFPGANer
            import torch
            from tools.video._shared import get_torch_device as _get_device
        except ImportError as e:
            return ToolResult(
                success=False,
                error=f"Missing dependency: {e}. Run: uv pip install gfpgan",
            )

        _device = _get_device()

        start = time.time()

        # Optional background upsampler
        bg_upsampler = None
        if bg_upsampler_flag:
            try:
                from basicsr.archs.rrdbnet_arch import RRDBNet
                from realesrgan import RealESRGANer

                realesrgan_model = RRDBNet(
                    num_in_ch=3, num_out_ch=3, num_feat=64,
                    num_block=23, num_grow_ch=32, scale=2,
                )
                bg_kwargs: dict = {
                    "scale": 2,
                    "model_path": (
                        "https://github.com/xinntao/Real-ESRGAN/releases/download/"
                        "v0.2.1/RealESRGAN_x2plus.pth"
                    ),
                    "model": realesrgan_model,
                    "tile": 400,
                    "tile_pad": 10,
                    "pre_pad": 0,
                    "half": (_device == "cuda"),
                }
                # Guard: only pass device= if the installed version accepts it
                if "device" in inspect.signature(RealESRGANer.__init__).parameters:
                    bg_kwargs["device"] = torch.device(_device)
                bg_upsampler = RealESRGANer(**bg_kwargs)
            except ImportError:
                bg_upsampler = None

        model_path = (
            "https://github.com/TencentARC/GFPGAN/releases/download/"
            "v1.3.0/GFPGANv1.3.pth"
        )
        arch = "clean"

        # Instantiate restorer
        try:
            restorer_kwargs: dict = {
                "model_path": model_path,
                "upscale": upscale,
                "arch": arch,
                "bg_upsampler": bg_upsampler,
            }
            # Guard: only pass device= if the installed version accepts it
            if "device" in inspect.signature(GFPGANer.__init__).parameters:
                restorer_kwargs["device"] = torch.device(_device)
            restorer = GFPGANer(**restorer_kwargs)
        except Exception as e:
            return ToolResult(
                success=False, error=f"Failed to load {model_name} model: {e}"
            )

        # Read input image
        input_img = cv2.imread(str(input_path), cv2.IMREAD_COLOR)
        if input_img is None:
            return ToolResult(
                success=False, error=f"Failed to read image: {input_path}"
            )

        # Run restoration
        try:
            _, restored_faces, restored_img = restorer.enhance(
                input_img,
                has_aligned=False,
                only_center_face=False,
                paste_back=True,
                weight=fidelity if model_name == "CodeFormer" else None,
            )
        except Exception as e:
            return ToolResult(success=False, error=f"Restoration failed: {e}")

        if restored_img is None:
            return ToolResult(
                success=False, error="Restoration produced no output"
            )

        # Save restored output
        output_path.parent.mkdir(parents=True, exist_ok=True)
        cv2.imwrite(str(output_path), restored_img)

        elapsed = time.time() - start
        faces_detected = len(restored_faces) if restored_faces else 0

        return ToolResult(
            success=True,
            data={
                "input": str(input_path),
                "output": str(output_path),
                "model": model_name,
                "faces_detected": faces_detected,
                "upscale": upscale,
                "fidelity": fidelity if model_name == "CodeFormer" else None,
                "bg_upsampler": bg_upsampler_flag,
            },
            artifacts=[str(output_path)],
            duration_seconds=round(elapsed, 2),
        )

tools/enhancement/minicut_upscale.py:
"""Cloud video upscale (Topaz) through the MiniCut CLI.

Needs no local GPU: the clip is sent to MiniCut model ``topaz-standard``
and the upscaled clip is written to ``output_path``. Video only (mp4, mov or
webm); still images are not covered, use ``upscale`` for those.

``dry_run`` returns the CLI's free price quote as an ``approval``, and
``execute`` sends exactly that approval and nothing else; sending it again
never starts a second paid job. The CLI calls live in ``tools/minicut_cli.py``.
"""

from __future__ import annotations

import shutil
import time
from pathlib import Path
from typing import Any

from tools import minicut_cli
from tools.base_tool import (
    BaseTool,
    Determinism,
    ExecutionMode,
    ResourceProfile,
    RetryPolicy,
    ToolResult,
    ToolRuntime,
    ToolStability,
    ToolStatus,
    ToolTier,
)
from tools.provider_pricing import PriceQuoteRequired

MODEL = "topaz-standard"
VIDEO_EXTENSIONS = {".mp4", ".mov", ".webm"}


class MiniCutUpscale(BaseTool):
    name = "minicut_upscale"
    version = "0.1.0"
    tier = ToolTier.ENHANCE
    capability = "enhancement"
    provider = "minicut"
    stability = ToolStability.EXPERIMENTAL
    execution_mode = ExecutionMode.SYNC
    determinism = Determinism.DETERMINISTIC
    runtime = ToolRuntime.API

    dependencies = ["cmd:minicut"]
    install_instructions = minicut_cli.INSTALL_INSTRUCTIONS
    agent_skills = ["ffmpeg"]

    capabilities = ["video_upscale"]
    supports = {
        "video_upscale": True,
        "image_upscale": False,
        "price_quote_before_run": True,
    }
    best_for = [
        "upscaling a finished clip without a local GPU",
        "paid runs that must show the price and wait for a yes",
    ]
    not_good_for = ["still images", "offline runs", "runs with no user present to approve the price"]
    fallback_tools = ["upscale"]

    input_schema = {
        "type": "object",
        "required": ["input_path"],
        "properties": {
            "input_path": {"type": "string", "description": "The clip to upscale (mp4, mov or webm)"},
            "output_path": {"type": "string"},
            "scale": {"type": "integer", "minimum": 1, "maximum": 4, "default": 2},
            "approval": {
                "type": "object",
                "description": (
                    "dry_run()['approval'], after the user said yes to its credits. "
                    "Without it nothing is sent. Sending the same approval again never pays twice."
                ),
            },
            "resume_job": {
                "type": "object",
                "description": "{'job_id': ...} from a run that timed out. Collects it, no new charge.",
            },
            "poll_timeout": {"type": "integer", "default": 900},
        },
    }

    resource_profile = ResourceProfile(
        cpu_cores=1, ram_mb=512, vram_mb=0, disk_mb=2000, network_required=True
    )
    # Paid submission: never retried automatically. A timeout is collected with resume_job.
    retry_policy = RetryPolicy(max_retries=0)
    idempotency_key_fields = ["input_path", "scale"]
    side_effects = [
        "writes upscaled video to output_path",
        "spends MiniCut credits after approval",
        "keeps a copy of the result in the MiniCut library",
    ]
    user_visible_verification = ["Compare upscaled clip with the original for detail and artifacts"]

    # ---- CLI ----

    @staticmethod
    def _output_path(inputs: dict[str, Any]) -> Path:
        src = Path(inputs["input_path"])
        return Path(inputs.get("output_path") or src.with_name(f"{src.stem}_upscaled.mp4"))

    def _gen_words(self, inputs: dict[str, Any]) -> list[str]:
        src = Path(inputs["input_path"])
        if src.suffix.lower() not in VIDEO_EXTENSIONS:
            raise ValueError(
                f"minicut_upscale takes a video (mp4, mov or webm), got {src.name}. "
                "Use upscale for still images."
            )
        settings = {"upscale-factor": int(inputs.get("scale", 2))}
        # The library file name; the result is copied to output_path once saved.
        out_name = self._output_path(inputs).name
        return minicut_cli.gen_words(MODEL, out_name, None, settings, [("source", str(src))])

    # ---- Contract ----

    def get_status(self) -> ToolStatus:
        return ToolStatus.AVAILABLE if minicut_cli.find_cli() else ToolStatus.UNAVAILABLE

    def estimate_cost(self, inputs: dict[str, Any]) -> float:
        raise PriceQuoteRequired(
            "MiniCut prices each request in credits; dry_run returns the exact quote for free"
        )

    def estimate_runtime(self, inputs: dict[str, Any]) -> float:
        return 300.0

    def dry_run(self, inputs: dict[str, Any]) -> dict[str, Any]:
        result = super().dry_run(inputs)
        try:
            approval = minicut_cli.quote(self._gen_words(inputs))
        except Exception as exc:
            return {**result, "would_execute": False, "quote_reason": str(exc)}
        return {
            **result,
            "estimated_credits": approval["credits"],
            "approval": approval,
            "would_execute": False,
        }

    def execute(self, inputs: dict[str, Any]) -> ToolResult:
        start = time.time()
        output_path = self._output_path(inputs)
        job_id = (inputs.get("resume_job") or {}).get("job_id")
        try:
            if not job_id:
                if not inputs.get("approval"):
                    return minicut_cli.needs_yes(minicut_cli.quote(self._gen_words(inputs)))
                sent = minicut_cli.send(self._gen_words(inputs), inputs["approval"])
                if isinstance(sent, ToolResult):
                    return sent
                job_id = sent

            saved = minicut_cli.collect(job_id, inputs.get("poll_timeout", 900))
            if isinstance(saved, ToolResult):
                return saved
            output_path.parent.mkdir(parents=True, exist_ok=True)
            shutil.copyfile(saved, output_path)
        except Exception as exc:
            data = {"resume_job": {"job_id": job_id}} if job_id else {}
            return ToolResult(
                success=False,
                error=f"MiniCut upscale failed: {exc}",
                data=data,
                cost_usd=None if job_id else 0.0,
            )

        from tools.video._shared import probe_output

        return ToolResult(
            success=True,
            data={
                "provider": "minicut",
                "model": MODEL,
                "job_id": job_id,
                "input": str(inputs["input_path"]),
                "output": str(output_path),
                "output_path": str(output_path),
                "scale": int(inputs.get("scale", 2)),
                "type": "video",
                # MiniCut bills in credits; the USD value depends on the user's plan.
                "cost_status": "unquoted",
                **probe_output(output_path),
            },
            artifacts=[str(output_path)],
            cost_usd=None,
            duration_seconds=round(time.time() - start, 2),
            model=MODEL,
        )

tools/capture/cap_recorder.py:
"""Cap integration tool — local Loom alternative.

Detects whether Cap (https://cap.so) is installed, checks if it's running,
and picks up recordings from its output directory. If Cap isn't installed,
provides setup guidance the agent can present to the user.

Cap provides:
  - Polished recording UI with webcam overlay
  - Cursor highlight and click effects
  - Hardware-accelerated capture (GPU)
  - Built-in editor with captions
  - Clean system audio capture

This tool does NOT control Cap directly — it acts as a bridge:
  1. Detect Cap installation and status
  2. Guide user through setup if needed
  3. Pick up completed recordings for the screen-demo pipeline
"""

from __future__ import annotations

import glob
import json
import os
import platform
import shutil
import subprocess
import time
from pathlib import Path
from typing import Any

from tools.base_tool import (
    BaseTool,
    Determinism,
    ExecutionMode,
    ResourceProfile,
    ToolResult,
    ToolRuntime,
    ToolStability,
    ToolTier,
)


def _find_cap_binary() -> str | None:
    """Find the Cap executable on the system."""
    sys_platform = platform.system()

    if sys_platform == "Windows":
        # Cap installs to AppData/Local on Windows
        candidates = [
            Path(os.environ.get("LOCALAPPDATA", "")) / "Cap" / "Cap.exe",
            Path(os.environ.get("PROGRAMFILES", "")) / "Cap" / "Cap.exe",
            # Tauri apps sometimes install here
            Path(os.environ.get("LOCALAPPDATA", "")) / "Programs" / "cap" / "Cap.exe",
        ]
        for c in candidates:
            if c.exists():
                return str(c)
        # Try PATH
        if shutil.which("Cap") or shutil.which("cap"):
            return shutil.which("Cap") or shutil.which("cap")

    elif sys_platform == "Darwin":
        candidates = [
            Path("/Applications/Cap.app/Contents/MacOS/Cap"),
            Path.home() / "Applications" / "Cap.app" / "Contents" / "MacOS" / "Cap",
        ]
        for c in candidates:
            if c.exists():
                return str(c)

    elif sys_platform == "Linux":
        candidates = ["cap", "Cap"]
        for c in candidates:
            found = shutil.which(c)
            if found:
                return found
        # AppImage or Flatpak
        appimage = Path.home() / "Applications" / "Cap.AppImage"
        if appimage.exists():
            return str(appimage)

    return None


def _find_cap_recordings_dir() -> Path | None:
    """Find Cap's recording output directory."""
    sys_platform = platform.system()

    if sys_platform == "Windows":
        # Cap stores recordings in AppData
        base = Path(os.environ.get("APPDATA", "")) / "so.cap.desktop"
        if base.exists():
            return base
        # Alternative path
        base2 = Path(os.environ.get("LOCALAPPDATA", "")) / "so.cap.desktop"
        if base2.exists():
            return base2

    elif sys_platform == "Darwin":
        base = Path.home() / "Library" / "Application Support" / "so.cap.desktop"
        if base.exists():
            return base

    elif sys_platform == "Linux":
        base = Path.home() / ".local" / "share" / "so.cap.desktop"
        if base.exists():
            return base

    return None


def _is_cap_running() -> bool:
    """Check if Cap is currently running."""
    sys_platform = platform.system()
    try:
        if sys_platform == "Windows":
            result = subprocess.run(
                ["tasklist", "/FI", "IMAGENAME eq Cap.exe", "/NH"],
                capture_output=True, text=True, timeout=5,
            )
            return "Cap.exe" in result.stdout
        elif sys_platform == "Darwin":
            result = subprocess.run(
                ["pgrep", "-x", "Cap"],
                capture_output=True, text=True, timeout=5,
            )
            return result.returncode == 0
        elif sys_platform == "Linux":
            result = subprocess.run(
                ["pgrep", "-x", "cap"],
                capture_output=True, text=True, timeout=5,
            )
            return result.returncode == 0
    except Exception:
        pass
    return False


def _get_recent_recordings(recordings_dir: Path, since_seconds: int = 300) -> list[dict]:
    """Find Cap recordings created within the last N seconds."""
    recordings = []
    cutoff = time.time() - since_seconds

    # Cap stores recordings as directories with output/ subdirs
    for item in sorted(recordings_dir.iterdir(), key=lambda p: p.stat().st_mtime, reverse=True):
        if not item.is_dir():
            continue
        # Look for video files in the recording directory
        for pattern in ["*.mp4", "output/*.mp4", "output/result.mp4"]:
            for video in item.glob(pattern):
                if video.stat().st_mtime > cutoff:
                    recordings.append({
                        "path": str(video),
                        "name": item.name,
                        "size_mb": round(video.stat().st_size / (1024 * 1024), 1),
                        "modified": video.stat().st_mtime,
                    })

    return recordings[:10]  # Return most recent 10


class CapRecorder(BaseTool):
    name = "cap_recorder"
    version = "0.1.0"
    tier = ToolTier.SOURCE
    capability = "screen_capture"
    provider = "cap"
    stability = ToolStability.BETA
    execution_mode = ExecutionMode.SYNC
    determinism = Determinism.DETERMINISTIC
    runtime = ToolRuntime.LOCAL

    dependencies = []  # No hard dependencies — detection is graceful
    install_instructions = (
        "Cap is a free, open-source Loom alternative.\n\n"
        "Install from: https://cap.so/download\n"
        "  - Windows: Download and run the installer\n"
        "  - macOS: Download the .dmg or use: brew install --cask cap\n"
        "  - Linux: Download the AppImage from GitHub releases\n\n"
        "Source code: https://github.com/CapSoftware/cap\n\n"
        "Cap provides webcam overlay, cursor highlighting, and a polished\n"
        "recording UI that FFmpeg-based recording cannot match."
    )

    capabilities = [
        "detect_cap",
        "check_status",
        "find_recordings",
        "setup_guidance",
    ]

    best_for = [
        "Professional screen recordings with webcam overlay",
        "Cursor highlight and click effect recordings",
        "Recording with a visual UI (not CLI-driven)",
        "Recordings that need polished audio capture",
    ]

    not_good_for = [
        "Automated/headless screen recording",
        "Recording without user interaction",
        "Quick recordings where setup time matters",
    ]

    input_schema = {
        "type": "object",
        "required": ["operation"],
        "properties": {
            "operation": {
                "type": "string",
                "enum": ["detect", "status", "find_recordings", "setup_guide", "pick_latest"],
                "description": (
                    "'detect' — check if Cap is installed, "
                    "'status' — check if Cap is running, "
                    "'find_recordings' — list recent recordings, "
                    "'setup_guide' — get install instructions, "
                    "'pick_latest' — get the most recent recording file"
                ),
            },
            "output_dir": {
                "type": "string",
                "description": "For pick_latest: copy the recording here",
            },
            "since_minutes": {
                "type": "integer",
                "default": 5,
                "description": "For find_recordings: look back this many minutes",
            },
        },
    }

    output_schema = {
        "type": "object",
        "properties": {
            "installed": {"type": "boolean"},
            "running": {"type": "boolean"},
            "binary_path": {"type": ["string", "null"]},
            "recordings_dir": {"type": ["string", "null"]},
            "recordings": {"type": "array"},
            "setup_instructions": {"type": "string"},
        },
    }

    resource_profile = ResourceProfile(
        cpu_cores=1, ram_mb=64, vram_mb=0, disk_mb=0, network_required=False,
    )

    side_effects = []
    fallback_tools = ["screen_recorder"]

    def get_status(self):
        """Cap tool is always 'available' — it gracefully handles missing Cap."""
        from tools.base_tool import ToolStatus
        return ToolStatus.AVAILABLE

    def execute(self, inputs: dict[str, Any]) -> ToolResult:
        operation = inputs["operation"]

        if operation == "detect":
            return self._detect()
        elif operation == "status":
            return self._status()
        elif operation == "find_recordings":
            since = inputs.get("since_minutes", 5)
            return self._find_recordings(since)
        elif operation == "setup_guide":
            return self._setup_guide()
        elif operation == "pick_latest":
            output_dir = inputs.get("output_dir")
            return self._pick_latest(output_dir)
        else:
            return ToolResult(
                success=False,
                error=f"Unknown operation: {operation}. "
                      f"Valid: detect, status, find_recordings, setup_guide, pick_latest",
            )

    def _detect(self) -> ToolResult:
        binary = _find_cap_binary()
        recordings_dir = _find_cap_recordings_dir()
        running = _is_cap_running() if binary else False

        return ToolResult(
            success=True,
            data={
                "installed": binary is not None,
                "running": running,
                "binary_path": binary,
                "recordings_dir": str(recordings_dir) if recordings_dir else None,
                "platform": platform.system(),
            },
        )

    def _status(self) -> ToolResult:
        binary = _find_cap_binary()
        if not binary:
            return ToolResult(
                success=True,
                data={
                    "installed": False,
                    "running": False,
                    "message": "Cap is not installed. Use operation='setup_guide' for install instructions.",
                },
            )

        running = _is_cap_running()
        recordings_dir = _find_cap_recordings_dir()

        return ToolResult(
            success=True,
            data={
                "installed": True,
                "running": running,
                "binary_path": binary,
                "recordings_dir": str(recordings_dir) if recordings_dir else None,
                "message": "Cap is running and ready to record." if running
                          else "Cap is installed but not running. The user should open Cap to start recording.",
            },
        )

    def _find_recordings(self, since_minutes: int) -> ToolResult:
        recordings_dir = _find_cap_recordings_dir()
        if not recordings_dir:
            return ToolResult(
                success=True,
                data={
                    "recordings": [],
                    "message": "Cap recordings directory not found. Cap may not be installed or hasn't made any recordings yet.",
                },
            )

        recordings = _get_recent_recordings(recordings_dir, since_seconds=since_minutes * 60)

        return ToolResult(
            success=True,
            data={
                "recordings": recordings,
                "recordings_dir": str(recordings_dir),
                "count": len(recordings),
                "message": f"Found {len(recordings)} recording(s) from the last {since_minutes} minutes."
                          if recordings else f"No recordings found in the last {since_minutes} minutes.",
            },
        )

    def _setup_guide(self) -> ToolResult:
        sys_platform = platform.system()
        binary = _find_cap_binary()

        if binary:
            return ToolResult(
                success=True,
                data={
                    "installed": True,
                    "binary_path": binary,
                    "message": "Cap is already installed!",
                    "next_step": "Open Cap and start recording. When done, use operation='pick_latest' to grab the recording.",
                },
            )

        instructions = {
            "Windows": {
                "recommended": "Download from https://cap.so/download",
                "alternative": "winget install CapSoftware.Cap",
                "time_estimate": "2 minutes",
            },
            "Darwin": {
                "recommended": "brew install --cask cap",
                "alternative": "Download .dmg from https://cap.so/download",
                "time_estimate": "2 minutes",
            },
            "Linux": {
                "recommended": "Download AppImage from https://github.com/CapSoftware/cap/releases",
                "alternative": "Build from source: https://github.com/CapSoftware/cap",
                "time_estimate": "3-5 minutes",
            },
        }

        platform_guide = instructions.get(sys_platform, instructions["Linux"])

        return ToolResult(
            success=True,
            data={
                "installed": False,
                "platform": sys_platform,
                "setup": platform_guide,
                "what_you_get": [
                    "Webcam overlay (picture-in-picture)",
                    "Cursor highlight and click effects",
                    "Clean system + microphone audio capture",
                    "Built-in editor with auto-captions",
                    "Polished recording UI",
                ],
                "source_code": "https://github.com/CapSoftware/cap",
                "message": f"Cap is not installed. Setup takes about {platform_guide['time_estimate']}.",
            },
        )

    def _pick_latest(self, output_dir: str | None) -> ToolResult:
        recordings_dir = _find_cap_recordings_dir()
        if not recordings_dir:
            return ToolResult(
                success=False,
                error="Cap recordings directory not found.",
            )

        recordings = _get_recent_recordings(recordings_dir, since_seconds=3600)
        if not recordings:
            return ToolResult(
                success=False,
                error="No recent Cap recordings found. Record something in Cap first.",
            )

        latest = recordings[0]
        source = Path(latest["path"])

        if output_dir:
            dest = Path(output_dir) / source.name
            dest.parent.mkdir(parents=True, exist_ok=True)
            shutil.copy2(source, dest)
            return ToolResult(
                success=True,
                data={
                    "output_path": str(dest),
                    "original_path": str(source),
                    "size_mb": latest["size_mb"],
                    "capture_method": "cap",
                },
                artifacts=[str(dest)],
            )

        return ToolResult(
            success=True,
            data={
                "output_path": str(source),
                "size_mb": latest["size_mb"],
                "capture_method": "cap",
            },
            artifacts=[str(source)],
        )

tools/capture/screen_capture_selector.py:
"""Capability-level screen capture selector — routes between FFmpeg and Cap.

Presents two options to the agent/user:
  1. FFmpeg (screen_recorder) — ready immediately, CLI-driven, no webcam
  2. Cap (cap_recorder) — needs install, polished UI, webcam overlay, cursor effects

Provider discovery is automatic via the registry (capability="screen_capture").
"""

from __future__ import annotations

from typing import Any

from tools.base_tool import (
    BaseTool,
    Determinism,
    ExecutionMode,
    ResourceProfile,
    ToolResult,
    ToolRuntime,
    ToolStability,
    ToolStatus,
    ToolTier,
)


class ScreenCaptureSelector(BaseTool):
    name = "screen_capture_selector"
    version = "0.1.0"
    tier = ToolTier.SOURCE
    capability = "screen_capture"
    provider = "selector"
    stability = ToolStability.BETA
    execution_mode = ExecutionMode.SYNC
    determinism = Determinism.DETERMINISTIC
    runtime = ToolRuntime.HYBRID

    # `screen-demo` named the Layer 2 pipeline directory, not a Layer 3 skill,
    # so it never resolved. No Layer 3 skill covers OS screen capture — the
    # capture guidance this selector needs lives in the pipeline manifest's
    # per-stage `skill:` entries (skills/pipelines/screen-demo/), which the
    # agent already reads.

    capabilities = [
        "screen_recording",
        "provider_selection",
        "cap_setup_guidance",
    ]

    best_for = [
        "Choosing between quick FFmpeg recording and polished Cap recording",
        "Guiding users through screen capture setup",
        "Routing screen-demo pipeline to the right capture tool",
    ]

    not_good_for = [
        "Direct screen recording (use the selected provider instead)",
    ]

    input_schema = {
        "type": "object",
        "required": ["operation"],
        "properties": {
            "operation": {
                "type": "string",
                "enum": ["recommend", "record", "pick_latest"],
                "description": (
                    "'recommend' — assess available options and recommend one, "
                    "'record' — record screen using specified or best provider, "
                    "'pick_latest' — grab the most recent recording from any provider"
                ),
            },
            "preferred_provider": {
                "type": "string",
                "enum": ["auto", "ffmpeg", "cap"],
                "default": "auto",
                "description": "Provider preference. 'auto' picks the best available.",
            },
            "output_path": {
                "type": "string",
                "description": "Path for the output MP4 file (required for 'record' operation)",
            },
            "duration_seconds": {
                "type": "integer",
                "default": 60,
                "description": "Recording duration in seconds (FFmpeg only)",
            },
            "fps": {
                "type": "integer",
                "default": 30,
                "description": "Frames per second (FFmpeg only)",
            },
            "capture_audio": {
                "type": "boolean",
                "default": True,
                "description": "Whether to capture audio (FFmpeg only)",
            },
            "region": {
                "type": "object",
                "description": "Screen region to capture (FFmpeg only)",
                "properties": {
                    "x": {"type": "integer"},
                    "y": {"type": "integer"},
                    "width": {"type": "integer"},
                    "height": {"type": "integer"},
                },
            },
            "since_minutes": {
                "type": "integer",
                "default": 5,
                "description": "For pick_latest: look back this many minutes",
            },
        },
    }

    output_schema = {
        "type": "object",
        "properties": {
            "recommended_provider": {"type": "string"},
            "options": {"type": "array"},
            "output_path": {"type": "string"},
            "capture_method": {"type": "string"},
        },
    }

    resource_profile = ResourceProfile(
        cpu_cores=1, ram_mb=64, vram_mb=0, disk_mb=0, network_required=False,
    )

    side_effects = []

    def _providers(self) -> dict[str, BaseTool]:
        """Auto-discover screen_capture providers from the registry."""
        from tools.tool_registry import registry
        registry.ensure_discovered()
        tools = registry.get_by_capability("screen_capture")
        return {t.provider: t for t in tools if t.name != self.name}

    @property
    def fallback_tools(self) -> list[str]:
        return list(self._providers().keys())

    def get_status(self) -> ToolStatus:
        providers = self._providers()
        if any(t.get_status() == ToolStatus.AVAILABLE for t in providers.values()):
            return ToolStatus.AVAILABLE
        return ToolStatus.UNAVAILABLE

    def execute(self, inputs: dict[str, Any]) -> ToolResult:
        operation = inputs["operation"]

        if operation == "recommend":
            return self._recommend(inputs)
        elif operation == "record":
            return self._record(inputs)
        elif operation == "pick_latest":
            return self._pick_latest(inputs)
        else:
            return ToolResult(
                success=False,
                error=f"Unknown operation: {operation}. Valid: recommend, record, pick_latest",
            )

    def _recommend(self, inputs: dict[str, Any]) -> ToolResult:
        """Assess both providers and return a recommendation with tradeoffs."""
        providers = self._providers()

        ffmpeg_tool = providers.get("ffmpeg")
        cap_tool = providers.get("cap")

        options = []

        # FFmpeg option — always available if ffmpeg is installed
        if ffmpeg_tool:
            ffmpeg_status = ffmpeg_tool.get_status()
            options.append({
                "provider": "ffmpeg",
                "tool": "screen_recorder",
                "label": "Quick Recording (FFmpeg)",
                "available": ffmpeg_status == ToolStatus.AVAILABLE,
                "setup_required": ffmpeg_status != ToolStatus.AVAILABLE,
                "strengths": [
                    "Ready immediately — no additional install",
                    "CLI-driven — works in automated pipelines",
                    "Full screen or region capture",
                    "System + microphone audio",
                ],
                "limitations": [
                    "No webcam overlay (picture-in-picture)",
                    "No cursor highlight or click effects",
                    "No built-in editor or captions",
                    "Raw capture — no polish",
                ],
                "best_when": "You need a quick recording or automated capture",
            })

        # Cap option — may need install
        if cap_tool:
            cap_detect = cap_tool.execute({"operation": "detect"})
            cap_installed = cap_detect.data.get("installed", False) if cap_detect.success else False
            cap_running = cap_detect.data.get("running", False) if cap_detect.success else False

            status_label = "Running" if cap_running else ("Installed" if cap_installed else "Not installed")
            options.append({
                "provider": "cap",
                "tool": "cap_recorder",
                "label": "Pro Recording (Cap)",
                "available": cap_installed,
                "running": cap_running,
                "status": status_label,
                "setup_required": not cap_installed,
                "strengths": [
                    "Webcam overlay (picture-in-picture)",
                    "Cursor highlight and click effects",
                    "GPU-accelerated capture",
                    "Built-in editor with auto-captions",
                    "Clean system audio capture",
                    "Polished, professional output",
                ],
                "limitations": [
                    "Requires separate install (~2 min)",
                    "User must interact with Cap's UI to record",
                    "Cannot be fully automated from CLI",
                ],
                "best_when": "You want professional, polished screen recordings",
                "setup_time": "~2 minutes" if not cap_installed else None,
            })

        # Determine recommendation
        preferred = inputs.get("preferred_provider", "auto")
        if preferred == "cap" and any(o["provider"] == "cap" for o in options):
            recommended = "cap"
        elif preferred == "ffmpeg" and any(o["provider"] == "ffmpeg" for o in options):
            recommended = "ffmpeg"
        else:
            # Auto: recommend Cap if installed+running, otherwise FFmpeg
            cap_option = next((o for o in options if o["provider"] == "cap"), None)
            if cap_option and cap_option.get("running"):
                recommended = "cap"
            elif any(o["provider"] == "ffmpeg" and o["available"] for o in options):
                recommended = "ffmpeg"
            elif cap_option and cap_option.get("available"):
                recommended = "cap"
            else:
                recommended = "ffmpeg"

        return ToolResult(
            success=True,
            data={
                "recommended_provider": recommended,
                "options": options,
                "message": self._build_recommendation_message(recommended, options),
            },
        )

    def _build_recommendation_message(self, recommended: str, options: list[dict]) -> str:
        """Build a human-readable recommendation message for the agent to present."""
        cap_option = next((o for o in options if o["provider"] == "cap"), None)
        ffmpeg_option = next((o for o in options if o["provider"] == "ffmpeg"), None)

        lines = ["**Screen Recording Options:**\n"]

        if ffmpeg_option:
            status = "Ready" if ffmpeg_option["available"] else "Needs FFmpeg install"
            lines.append(f"**Option 1 — Quick Recording (FFmpeg)** [{status}]")
            lines.append("  Basic screen capture, works immediately. No webcam or effects.\n")

        if cap_option:
            status = cap_option.get("status", "Unknown")
            lines.append(f"**Option 2 — Pro Recording (Cap)** [{status}]")
            lines.append("  Webcam overlay, cursor effects, built-in editor. Professional output.")
            if not cap_option.get("available"):
                lines.append("  Setup takes ~2 minutes. I can guide you through it.\n")
            else:
                lines.append("")

        lines.append(f"**Recommended:** {recommended}")
        return "\n".join(lines)

    def _record(self, inputs: dict[str, Any]) -> ToolResult:
        """Route a record request to the appropriate provider."""
        preferred = inputs.get("preferred_provider", "auto")
        providers = self._providers()

        # Determine which provider to use
        if preferred == "cap":
            tool = providers.get("cap")
            if tool:
                # Cap doesn't do the actual recording — it picks up what Cap recorded
                return tool.execute({"operation": "pick_latest", "output_dir": inputs.get("output_path")})
            return ToolResult(success=False, error="Cap provider not found in registry.")

        if preferred == "ffmpeg" or preferred == "auto":
            tool = providers.get("ffmpeg")
            if tool and tool.get_status() == ToolStatus.AVAILABLE:
                return tool.execute({
                    "output_path": inputs.get("output_path", "recording.mp4"),
                    "duration_seconds": inputs.get("duration_seconds", 60),
                    "fps": inputs.get("fps", 30),
                    "capture_audio": inputs.get("capture_audio", True),
                    "region": inputs.get("region"),
                })

            # FFmpeg not available — try Cap
            cap_tool = providers.get("cap")
            if cap_tool:
                cap_detect = cap_tool.execute({"operation": "detect"})
                if cap_detect.success and cap_detect.data.get("running"):
                    return cap_tool.execute({
                        "operation": "pick_latest",
                        "output_dir": inputs.get("output_path"),
                    })

            return ToolResult(
                success=False,
                error="No screen capture provider available. Install FFmpeg or Cap.",
            )

        return ToolResult(success=False, error=f"Unknown provider: {preferred}")

    def _pick_latest(self, inputs: dict[str, Any]) -> ToolResult:
        """Try to pick the latest recording from any available provider."""
        providers = self._providers()
        since = inputs.get("since_minutes", 5)

        # Try Cap first (more likely to have user-initiated recordings)
        cap_tool = providers.get("cap")
        if cap_tool:
            result = cap_tool.execute({
                "operation": "find_recordings",
                "since_minutes": since,
            })
            if result.success and result.data.get("recordings"):
                latest = result.data["recordings"][0]
                return ToolResult(
                    success=True,
                    data={
                        "output_path": latest["path"],
                        "size_mb": latest["size_mb"],
                        "capture_method": "cap",
                        "source": "cap_recordings_dir",
                    },
                    artifacts=[latest["path"]],
                )

        return ToolResult(
            success=False,
            error="No recent recordings found. Record something first using Cap or FFmpeg.",
        )

tools/capture/screen_recorder.py:
"""FFmpeg-based screen recorder.

Cross-platform screen capture using FFmpeg's native capture devices.
Records screen + optional audio to MP4. Designed as the "quick start"
option — no install beyond FFmpeg, works everywhere, CLI-driven.

Platform capture devices:
  Windows: gdigrab (screen) + dshow (audio)
  macOS:   avfoundation (screen + audio)
  Linux:   x11grab (screen) + pulse (audio)
"""

from __future__ import annotations

import os
import platform
import signal
import subprocess
import time
from pathlib import Path
from typing import Any

from tools.base_tool import (
    BaseTool,
    Determinism,
    ExecutionMode,
    ResourceProfile,
    ToolResult,
    ToolRuntime,
    ToolStability,
    ToolTier,
)


def _detect_audio_device_windows() -> str | None:
    """Find a working audio input device on Windows via dshow."""
    try:
        result = subprocess.run(
            ["ffmpeg", "-list_devices", "true", "-f", "dshow", "-i", "dummy"],
            capture_output=True, text=True, timeout=10,
        )
        # dshow lists devices in stderr
        output = result.stderr
        lines = output.splitlines()
        for i, line in enumerate(lines):
            if "audio" in line.lower() and "DirectShow audio" in line:
                # Next line(s) contain actual device names
                for j in range(i + 1, min(i + 10, len(lines))):
                    if '"' in lines[j] and "Alternative name" not in lines[j]:
                        name = lines[j].split('"')[1]
                        return name
    except Exception:
        pass
    return None


def _detect_audio_device_mac() -> str | None:
    """Find the default audio input index on macOS via avfoundation."""
    try:
        result = subprocess.run(
            ["ffmpeg", "-f", "avfoundation", "-list_devices", "true", "-i", ""],
            capture_output=True, text=True, timeout=10,
        )
        output = result.stderr
        in_audio = False
        for line in output.splitlines():
            if "AVFoundation audio devices" in line:
                in_audio = True
                continue
            if in_audio and "[" in line and "]" in line:
                # Return first audio device index
                idx = line.split("[")[1].split("]")[0].strip()
                if idx.isdigit():
                    return idx
    except Exception:
        pass
    return None


class ScreenRecorder(BaseTool):
    name = "screen_recorder"
    version = "0.1.0"
    tier = ToolTier.SOURCE
    capability = "screen_capture"
    provider = "ffmpeg"
    stability = ToolStability.BETA
    execution_mode = ExecutionMode.SYNC
    determinism = Determinism.DETERMINISTIC
    runtime = ToolRuntime.LOCAL

    dependencies = ["binary:ffmpeg"]
    install_instructions = (
        "Install ffmpeg:\n"
        "  Windows: winget install ffmpeg\n"
        "  macOS: brew install ffmpeg\n"
        "  Linux: sudo apt install ffmpeg"
    )

    capabilities = [
        "record_screen",
        "record_screen_with_audio",
        "record_region",
    ]

    best_for = [
        "Quick screen recording without additional software",
        "Automated screen capture for demo pipelines",
        "Recording specific screen regions for tutorials",
    ]

    not_good_for = [
        "Webcam overlay (PiP) — use Cap for that",
        "Cursor highlight effects — use Cap for that",
        "Interactive recording with pause/resume UI",
    ]

    input_schema = {
        "type": "object",
        "required": ["output_path"],
        "properties": {
            "output_path": {
                "type": "string",
                "description": "Path for the output MP4 file",
            },
            "duration_seconds": {
                "type": "integer",
                "default": 60,
                "description": "Recording duration in seconds (default: 60, max: 600)",
            },
            "fps": {
                "type": "integer",
                "default": 30,
                "description": "Frames per second (15, 24, 30, or 60)",
            },
            "capture_audio": {
                "type": "boolean",
                "default": True,
                "description": "Whether to capture system/microphone audio",
            },
            "region": {
                "type": "object",
                "description": "Optional screen region to capture (full screen if omitted)",
                "properties": {
                    "x": {"type": "integer", "description": "Left offset in pixels"},
                    "y": {"type": "integer", "description": "Top offset in pixels"},
                    "width": {"type": "integer", "description": "Width in pixels"},
                    "height": {"type": "integer", "description": "Height in pixels"},
                },
            },
            "screen_index": {
                "type": "integer",
                "default": 0,
                "description": "Monitor index for multi-monitor setups (0 = primary)",
            },
        },
    }

    output_schema = {
        "type": "object",
        "properties": {
            "output_path": {"type": "string"},
            "duration_seconds": {"type": "number"},
            "resolution": {"type": "string"},
            "has_audio": {"type": "boolean"},
            "file_size_mb": {"type": "number"},
        },
    }

    resource_profile = ResourceProfile(
        cpu_cores=2, ram_mb=512, vram_mb=0, disk_mb=500, network_required=False,
    )

    side_effects = ["creates_file"]
    fallback_tools = ["cap_recorder"]

    def execute(self, inputs: dict[str, Any]) -> ToolResult:
        output_path = Path(inputs["output_path"])
        duration = min(inputs.get("duration_seconds", 60), 600)
        fps = inputs.get("fps", 30)
        capture_audio = inputs.get("capture_audio", True)
        region = inputs.get("region")
        screen_index = inputs.get("screen_index", 0)

        output_path.parent.mkdir(parents=True, exist_ok=True)

        sys_platform = platform.system()
        cmd = self._build_command(
            sys_platform, str(output_path), duration, fps,
            capture_audio, region, screen_index,
        )

        if cmd is None:
            return ToolResult(
                success=False,
                error=f"Screen recording not supported on {sys_platform}. "
                      f"Supported: Windows, macOS, Linux.",
            )

        start_time = time.time()
        try:
            proc = subprocess.run(
                cmd, capture_output=True, text=True,
                timeout=duration + 30,  # grace period
            )
            elapsed = time.time() - start_time

            if not output_path.exists():
                return ToolResult(
                    success=False,
                    error=f"Recording failed — no output file. FFmpeg stderr: {proc.stderr[-500:]}",
                )

            file_size_mb = output_path.stat().st_size / (1024 * 1024)

            # Probe the output to get actual resolution
            resolution = self._probe_resolution(str(output_path))

            return ToolResult(
                success=True,
                data={
                    "output_path": str(output_path),
                    "duration_seconds": round(elapsed, 1),
                    "resolution": resolution,
                    "has_audio": capture_audio,
                    "file_size_mb": round(file_size_mb, 1),
                    "platform": sys_platform,
                    "capture_method": "ffmpeg",
                },
                artifacts=[str(output_path)],
                duration_seconds=elapsed,
            )

        except subprocess.TimeoutExpired:
            # Recording completed by timeout — this is expected behavior
            if output_path.exists():
                file_size_mb = output_path.stat().st_size / (1024 * 1024)
                return ToolResult(
                    success=True,
                    data={
                        "output_path": str(output_path),
                        "duration_seconds": duration,
                        "has_audio": capture_audio,
                        "file_size_mb": round(file_size_mb, 1),
                        "platform": sys_platform,
                        "capture_method": "ffmpeg",
                    },
                    artifacts=[str(output_path)],
                    duration_seconds=duration,
                )
            return ToolResult(success=False, error="Recording timed out with no output")

        except Exception as exc:
            return ToolResult(success=False, error=str(exc))

    def _build_command(
        self,
        sys_platform: str,
        output_path: str,
        duration: int,
        fps: int,
        capture_audio: bool,
        region: dict | None,
        screen_index: int,
    ) -> list[str] | None:
        """Build platform-specific FFmpeg capture command."""

        if sys_platform == "Windows":
            return self._build_windows_cmd(
                output_path, duration, fps, capture_audio, region,
            )
        elif sys_platform == "Darwin":
            return self._build_mac_cmd(
                output_path, duration, fps, capture_audio, region, screen_index,
            )
        elif sys_platform == "Linux":
            return self._build_linux_cmd(
                output_path, duration, fps, capture_audio, region,
            )
        return None

    def _build_windows_cmd(
        self, output_path: str, duration: int, fps: int,
        capture_audio: bool, region: dict | None,
    ) -> list[str]:
        cmd = ["ffmpeg", "-y"]

        # Video input: gdigrab
        cmd += ["-f", "gdigrab"]
        cmd += ["-framerate", str(fps)]
        cmd += ["-t", str(duration)]

        if region:
            cmd += ["-offset_x", str(region.get("x", 0))]
            cmd += ["-offset_y", str(region.get("y", 0))]
            cmd += ["-video_size", f"{region['width']}x{region['height']}"]

        cmd += ["-i", "desktop"]

        # Audio input: dshow
        if capture_audio:
            audio_device = _detect_audio_device_windows()
            if audio_device:
                cmd += ["-f", "dshow", "-i", f"audio={audio_device}"]

        # Output encoding
        cmd += ["-c:v", "libx264", "-preset", "ultrafast", "-crf", "23"]
        if capture_audio:
            cmd += ["-c:a", "aac", "-b:a", "128k"]
        cmd += ["-pix_fmt", "yuv420p"]
        cmd += [output_path]

        return cmd

    def _build_mac_cmd(
        self, output_path: str, duration: int, fps: int,
        capture_audio: bool, region: dict | None, screen_index: int,
    ) -> list[str]:
        cmd = ["ffmpeg", "-y"]

        # avfoundation: "screen_index:audio_index" or "screen_index:none"
        audio_idx = "none"
        if capture_audio:
            detected = _detect_audio_device_mac()
            if detected:
                audio_idx = detected

        cmd += ["-f", "avfoundation"]
        cmd += ["-framerate", str(fps)]
        cmd += ["-t", str(duration)]

        if region:
            # avfoundation doesn't support region directly — we crop in post
            cmd += ["-i", f"{screen_index}:{audio_idx}"]
            cmd += ["-vf", f"crop={region['width']}:{region['height']}:{region.get('x', 0)}:{region.get('y', 0)}"]
        else:
            cmd += ["-i", f"{screen_index}:{audio_idx}"]

        cmd += ["-c:v", "libx264", "-preset", "ultrafast", "-crf", "23"]
        if capture_audio and audio_idx != "none":
            cmd += ["-c:a", "aac", "-b:a", "128k"]
        cmd += ["-pix_fmt", "yuv420p"]
        cmd += [output_path]

        return cmd

    def _build_linux_cmd(
        self, output_path: str, duration: int, fps: int,
        capture_audio: bool, region: dict | None,
    ) -> list[str]:
        cmd = ["ffmpeg", "-y"]

        # x11grab
        display = os.environ.get("DISPLAY", ":0.0")
        cmd += ["-f", "x11grab"]
        cmd += ["-framerate", str(fps)]
        cmd += ["-t", str(duration)]

        if region:
            cmd += ["-video_size", f"{region['width']}x{region['height']}"]
            cmd += ["-i", f"{display}+{region.get('x', 0)},{region.get('y', 0)}"]
        else:
            # Full screen — need to detect resolution
            cmd += ["-i", display]

        if capture_audio:
            cmd += ["-f", "pulse", "-i", "default"]

        cmd += ["-c:v", "libx264", "-preset", "ultrafast", "-crf", "23"]
        if capture_audio:
            cmd += ["-c:a", "aac", "-b:a", "128k"]
        cmd += ["-pix_fmt", "yuv420p"]
        cmd += [output_path]

        return cmd

    def _probe_resolution(self, path: str) -> str:
        """Get video resolution via ffprobe."""
        try:
            result = subprocess.run(
                [
                    "ffprobe", "-v", "error",
                    "-select_streams", "v:0",
                    "-show_entries", "stream=width,height",
                    "-of", "csv=p=0",
                    path,
                ],
                capture_output=True, text=True, timeout=10,
            )
            parts = result.stdout.strip().split(",")
            if len(parts) == 2:
                return f"{parts[0]}x{parts[1]}"
        except Exception:
            pass
        return "unknown"

tools/avatar/heygen_avatar.py:
"""HeyGen v3 Avatar V digital twins with eligibility checks and resumable jobs."""

from __future__ import annotations

import os
from pathlib import Path
from urllib.parse import quote

from tools.provider_pricing import PriceQuoteRequired

from tools.base_tool import (
    BaseTool,
    ToolTier,
    ToolRuntime,
    ToolStability,
    Determinism,
    ResourceProfile,
    ResumeSupport,
    ToolResult,
)
from tools.provider_jobs import request_json, download, poll, save_job

BASE = "https://api.heygen.com/v3"


class HeyGenAvatar(BaseTool):
    name = "heygen_avatar"
    capability = "avatar"
    provider = "heygen"
    tier = ToolTier.GENERATE
    runtime = ToolRuntime.API
    stability = ToolStability.BETA
    determinism = Determinism.STOCHASTIC
    dependencies = ["env:HEYGEN_API_KEY"]
    install_instructions = "Configure HEYGEN_API_KEY from your HeyGen API account."
    agent_skills = ["provider-model-refresh"]
    capabilities = [
        "avatar_video",
        "audio_to_video",
        "list_looks",
        "inspect_look",
        "resume",
    ]
    supports = {
        "avatar_v": True,
        "script": True,
        "audio_url": True,
        "motion_prompt": True,
        "eligibility_preflight": True,
    }
    best_for = ["Avatar V digital-twin presenters with explicit engine selection"]
    resource_profile = ResourceProfile(network_required=True)
    resume_support = ResumeSupport.FROM_CHECKPOINT
    side_effects = [
        "submits paid HeyGen video generation",
        "writes video and optional job checkpoint",
    ]
    user_visible_verification = [
        "Review presenter identity, lip sync, motion and voice"
    ]
    idempotency_key_fields = [
        "avatar_id",
        "script",
        "voice_id",
        "audio_url",
        "audio_asset_id",
        "engine",
        "motion_prompt",
        "reference_look_id",
        "resolution",
        "aspect_ratio",
    ]
    input_schema = {
        "type": "object",
        "properties": {
            "operation": {
                "type": "string",
                "enum": ["generate", "list_looks", "inspect_look", "resume"],
                "default": "generate",
            },
            "avatar_id": {"type": "string"},
            "script": {"type": "string"},
            "voice_id": {"type": "string"},
            "audio_url": {"type": "string"},
            "audio_asset_id": {"type": "string"},
            "engine": {
                "type": "string",
                "enum": ["avatar_v", "avatar_iv"],
                "default": "avatar_v",
            },
            "motion_prompt": {"type": "string"},
            "reference_look_id": {"type": "string"},
            "resolution": {
                "type": "string",
                "enum": ["720p", "1080p", "4k"],
                "default": "1080p",
            },
            "aspect_ratio": {
                "type": "string",
                "enum": ["auto", "16:9", "9:16", "4:5", "5:4", "1:1"],
                "default": "auto",
            },
            "output_format": {
                "type": "string",
                "enum": ["mp4", "webm"],
                "default": "mp4",
            },
            "remove_background": {"type": "boolean"},
            "title": {"type": "string"},
            "resume_job": {"type": "object"},
            "job_path": {"type": "string"},
            "output_path": {"type": "string"},
            "poll_timeout": {"type": "number", "exclusiveMinimum": 0},
            "poll_interval": {"type": "number", "exclusiveMinimum": 0},
            "token": {"type": "string"},
        },
    }

    def estimate_cost(self, inputs):
        if inputs.get("operation") in {"list_looks", "inspect_look"}:
            return 0.0
        raise PriceQuoteRequired(
            "Quote HeyGen account pricing and expected duration before generation"
        )

    @staticmethod
    def build_payload(inputs):
        from jsonschema import validate

        validate(inputs, HeyGenAvatar.input_schema)
        if not inputs.get("avatar_id"):
            raise ValueError("avatar_id must identify an existing look")
        sources = [
            k for k in ("script", "audio_url", "audio_asset_id") if inputs.get(k)
        ]
        if len(sources) != 1:
            raise ValueError("Provide exactly one of script, audio_url, audio_asset_id")
        if sources == ["script"] and not inputs.get("voice_id"):
            raise ValueError("Script generation requires voice_id")
        if sources != ["script"] and inputs.get("voice_id"):
            raise ValueError("voice_id is only used with script")
        engine = inputs.get("engine", "avatar_v")
        if inputs.get("reference_look_id") and engine != "avatar_v":
            raise ValueError("reference_look_id requires Avatar V")
        payload = {
            "type": "avatar",
            "avatar_id": inputs["avatar_id"],
            "engine": {"type": engine},
            "resolution": inputs.get("resolution", "1080p"),
            "aspect_ratio": inputs.get("aspect_ratio", "auto"),
        }
        for k in (
            "script",
            "voice_id",
            "audio_url",
            "audio_asset_id",
            "motion_prompt",
            "reference_look_id",
            "title",
            "output_format",
            "remove_background",
        ):
            if k in inputs:
                payload[k] = inputs[k]
        return payload

    def execute(self, inputs):
        job = dict(inputs.get("resume_job") or {})
        try:
            key = os.getenv("HEYGEN_API_KEY")
            if not key:
                raise ValueError("HEYGEN_API_KEY is not configured")
            headers = {"x-api-key": key}

            def get(path, **kwargs):
                return request_json("GET", BASE + path, headers=headers, **kwargs).get(
                    "data", {}
                )

            operation = inputs.get("operation", "generate")
            if operation == "list_looks":
                params = {"token": inputs["token"]} if inputs.get("token") else {}
                return ToolResult(
                    success=True, data=get("/avatars/looks", params=params)
                )
            if operation == "inspect_look":
                return ToolResult(
                    success=True,
                    data=get("/avatars/looks/" + quote(inputs["avatar_id"], safe="")),
                )
            if operation not in {"generate", "resume"}:
                raise ValueError("Unknown avatar operation")
            if operation == "resume" and not job:
                raise ValueError(
                    "resume requires resume_job from the original submission"
                )
            if not job:
                payload = self.build_payload(inputs)
                look = get("/avatars/looks/" + quote(inputs["avatar_id"], safe=""))
                engine = payload["engine"]["type"]
                if engine not in look.get("supported_api_engines", []):
                    raise ValueError(
                        f"Look does not support {engine}; no engine fallback was performed"
                    )
                if engine == "avatar_v" and look.get("avatar_type") != "digital_twin":
                    raise ValueError("Avatar V requires an eligible digital_twin look")
                if inputs.get("reference_look_id"):
                    reference = get(
                        "/avatars/looks/" + quote(inputs["reference_look_id"], safe="")
                    )
                    group = look.get("group_id") or look.get("avatar_group_id")
                    reference_group = reference.get("group_id") or reference.get(
                        "avatar_group_id"
                    )
                    if (
                        not group
                        or group != reference_group
                        or reference.get("avatar_type") != "digital_twin"
                    ):
                        raise ValueError(
                            "Reference look must be a digital twin in the same verified avatar group"
                        )
                result = request_json(
                    "POST", BASE + "/videos", headers=headers, json=payload
                )["data"]
                job = {
                    "video_id": result["video_id"],
                    "tool": self.name,
                    "model": engine,
                    "output_format": inputs.get("output_format", "mp4"),
                }
                save_job(inputs.get("job_path"), job)
            if job.get("tool") != self.name or job.get("model") not in {
                "avatar_v",
                "avatar_iv",
            }:
                raise ValueError("Invalid HeyGen resume job")
            result = poll(
                lambda: get("/videos/" + quote(job["video_id"], safe="")),
                timeout=float(inputs.get("poll_timeout", 900)),
                interval=float(inputs.get("poll_interval", 3)),
            )
            path = Path(
                inputs.get("output_path")
                or f"heygen_avatar.{job.get('output_format', 'mp4')}"
            )
            output = download(result["video_url"], path)
            return ToolResult(
                success=True,
                data={
                    "provider": self.provider,
                    "model": job["model"],
                    "output": output,
                    "output_path": output,
                    "resume_job": job,
                    "cost_status": "unquoted",
                    "duration_seconds": result.get("duration"),
                    "subtitle_url": result.get("subtitle_url"),
                },
                artifacts=[output],
                cost_usd=None,
                model=job["model"],
            )
        except Exception as exc:
            return ToolResult(
                success=False, error=str(exc), data={"resume_job": job} if job else {}
            )

tools/avatar/kling_avatar.py:
"""Kling official API avatar image-to-video provider."""

from __future__ import annotations

import time
from pathlib import Path
from typing import Any

from tools._kling.account import account_usage_hint_for_error, get_account_costs
from tools._kling.callbacks import validate_callback_url
from tools._kling.client import KlingClient
from tools._kling.errors import KlingAPIError
from tools._kling.media import (
    extension_from_url,
    normalize_image_input,
    normalize_media_input,
    numbered_output_path,
    output_path_with_suffix,
)
from tools._kling.schemas import AVATAR_MODES
from tools.base_tool import (
    BaseTool,
    DependencyError,
    Determinism,
    ExecutionMode,
    ResourceProfile,
    RetryPolicy,
    ToolResult,
    ToolRuntime,
    ToolStability,
    ToolTier,
)
from tools.video._shared import probe_output


class KlingAvatar(BaseTool):
    name = "kling_avatar"
    version = "0.1.0"
    tier = ToolTier.GENERATE
    capability = "avatar"
    provider = "kling_official"
    stability = ToolStability.EXPERIMENTAL
    execution_mode = ExecutionMode.SYNC
    determinism = Determinism.STOCHASTIC
    runtime = ToolRuntime.API

    dependencies = ["env:KLING_API_KEY"]
    install_instructions = (
        "Set KLING_API_KEY in .env for the official Kling API. "
        "Provide an avatar image plus either audio_id or sound_file/audio_path."
    )
    agent_skills = ["kling-official", "avatar-video"]

    capabilities = ["photo_to_video", "avatar_video", "audio_driven_avatar"]
    supports = {
        "photo_to_video": True,
        "audio_driven_animation": True,
        "offline": False,
        "cloud_render": True,
    }
    best_for = [
        "official Kling cloud avatar presenter clips",
        "high-quality image-to-video avatar generation from a supplied portrait",
        "projects already using a Kling official account and resource pack",
    ]
    not_good_for = [
        "fully offline avatar generation",
        "free local drafts",
        "silently replacing the local talking_head provider",
    ]
    fallback_tools = ["talking_head", "lip_sync"]

    input_schema = {
        "type": "object",
        "anyOf": [
            {"required": ["image_url"]},
            {"required": ["image_path"]},
        ],
        "allOf": [
            {
                "anyOf": [
                    {"required": ["audio_id"]},
                    {"required": ["sound_file"]},
                    {"required": ["sound_file_url"]},
                    {"required": ["sound_file_path"]},
                    {"required": ["audio_path"]},
                ]
            }
        ],
        "properties": {
            "image_url": {"type": "string"},
            "image_path": {"type": "string"},
            "audio_id": {"type": "string"},
            "sound_file": {
                "type": "string",
                "description": "Official Kling sound_file value or raw base64 audio.",
            },
            "sound_file_url": {"type": "string"},
            "sound_file_path": {"type": "string"},
            "audio_path": {
                "type": "string",
                "description": "Alias for sound_file_path for compatibility with local avatar tools.",
            },
            "prompt": {"type": "string"},
            "mode": {"type": "string", "enum": AVATAR_MODES, "default": "std"},
            "callback_url": {"type": "string"},
            "external_task_id": {"type": "string"},
            "include_account_usage": {
                "type": "boolean",
                "default": False,
                "description": "Optional low-frequency account usage diagnostic; not used by default.",
            },
            "timeout_seconds": {"type": "integer", "default": 900},
            "poll_interval": {"type": "number", "default": 5.0},
            "output_path": {"type": "string"},
        },
    }

    resource_profile = ResourceProfile(
        cpu_cores=1, ram_mb=512, vram_mb=0, disk_mb=500, network_required=True
    )
    retry_policy = RetryPolicy(
        max_retries=2,
        backoff_seconds=2.0,
        retryable_errors=["1302", "1303", "5000", "5001", "5002"],
    )
    idempotency_key_fields = [
        "image_url",
        "image_path",
        "audio_id",
        "sound_file",
        "sound_file_url",
        "sound_file_path",
        "audio_path",
        "prompt",
        "mode",
    ]
    side_effects = ["paid remote generation via official Kling API", "writes avatar video to output_path"]
    user_visible_verification = ["Watch generated avatar video for identity preservation and mouth motion"]
    quality_score = 0.82
    latency_p50_seconds = 240.0

    def estimate_cost(self, inputs: dict[str, Any]) -> float:
        base = 0.35
        if inputs.get("mode") == "pro":
            base *= 1.7
        if inputs.get("sound_file_path") or inputs.get("audio_path"):
            base += 0.04
        return round(base, 4)

    def estimate_runtime(self, inputs: dict[str, Any]) -> float:
        return 240.0

    def dry_run(self, inputs: dict[str, Any]) -> dict[str, Any]:
        result = super().dry_run(inputs)
        result.update(
            {
                "paid_api": True,
                "cost_estimate_confidence": "low",
                "cost_estimate_basis": "Conservative OpenMontage avatar estimate pending official account-usage reconciliation.",
            }
        )
        return result

    def execute(self, inputs: dict[str, Any]) -> ToolResult:
        try:
            self.check_dependencies()
        except DependencyError as exc:
            return ToolResult(success=False, error=str(exc))

        start = time.time()
        try:
            request = self._build_request(inputs)
            client = KlingClient()
            task_id = client.create_classic_task(request["path"], request["payload"])
            outputs = client.poll_classic(
                request["path"],
                task_id,
                "videos",
                timeout_seconds=int(inputs.get("timeout_seconds", 900)),
                poll_interval=float(inputs.get("poll_interval", 5.0)),
            )
            paths = self._download_videos(client, outputs, inputs)
            probed = probe_output(paths[0])
        except (KlingAPIError, TimeoutError, ValueError, KeyError, FileNotFoundError) as exc:
            data: dict[str, Any] = {"provider": self.provider}
            if isinstance(exc, KlingAPIError):
                data.update(
                    {
                        "error_code": exc.code,
                        "request_id": exc.request_id,
                        "http_status": exc.http_status,
                        "account_usage_diagnostic": account_usage_hint_for_error(exc),
                    }
                )
            return ToolResult(success=False, data=data, error=f"Kling official avatar generation failed: {exc}")
        except Exception as exc:
            return ToolResult(success=False, data={"provider": self.provider}, error=f"Kling official avatar generation failed: {exc}")

        return ToolResult(
            success=True,
            data={
                "provider": self.provider,
                "model": "kling-official-avatar",
                "task_id": task_id,
                "operation": "image_to_avatar_video",
                "mode": request["payload"].get("mode"),
                "prompt": request["payload"].get("prompt"),
                "avatar_source": request["avatar_source"],
                "audio_source": request["audio_source"],
                "remote_outputs": outputs,
                "output": str(paths[0]),
                "output_path": str(paths[0]),
                "video_paths": [str(path) for path in paths],
                "format": "mp4",
                "cost_estimate_confidence": "low",
                "cost_estimate_basis": "Conservative estimate pending official account-usage reconciliation.",
                **self._account_usage_result(inputs, client),
                **self._callback_result_data(inputs, task_id),
                **probed,
            },
            artifacts=[str(path) for path in paths],
            cost_usd=self.estimate_cost(inputs),
            duration_seconds=round(time.time() - start, 2),
            model="kling-official-avatar",
        )

    def _build_request(self, inputs: dict[str, Any]) -> dict[str, Any]:
        image = normalize_image_input(inputs.get("image_url"), inputs.get("image_path"))
        if not image:
            raise ValueError("Kling avatar requires image_url or image_path")

        mode = str(inputs.get("mode") or "std")
        if mode not in AVATAR_MODES:
            raise ValueError(f"mode must be one of: {', '.join(AVATAR_MODES)}")

        payload: dict[str, Any] = {
            "image": image,
            "mode": mode,
        }
        if inputs.get("prompt"):
            payload["prompt"] = str(inputs["prompt"])

        audio_source = self._copy_audio_input(inputs, payload)
        self._copy_common_task_fields(inputs, payload)
        return {
            "protocol": "classic",
            "path": "/v1/videos/avatar/image2video",
            "payload": payload,
            "operation": "image_to_avatar_video",
            "model": "kling-official-avatar",
            "avatar_source": inputs.get("image_url") or inputs.get("image_path"),
            "audio_source": audio_source,
        }

    @staticmethod
    def _copy_audio_input(inputs: dict[str, Any], payload: dict[str, Any]) -> dict[str, Any]:
        audio_id = str(inputs.get("audio_id") or "").strip()
        if audio_id:
            payload["audio_id"] = audio_id
            return {"type": "audio_id", "value": audio_id}

        sound_path = inputs.get("sound_file_path") or inputs.get("audio_path")
        sound_file = normalize_media_input(
            url=inputs.get("sound_file_url"),
            path=sound_path,
            value=inputs.get("sound_file"),
            label="Avatar audio file",
        )
        if not sound_file:
            raise ValueError("Kling avatar requires audio_id, sound_file, sound_file_url, sound_file_path, or audio_path")
        payload["sound_file"] = sound_file
        return {
            "type": "sound_file",
            "source": inputs.get("sound_file_url") or sound_path or "inline",
        }

    def _download_videos(
        self,
        client: KlingClient,
        outputs: list[dict[str, Any]],
        inputs: dict[str, Any],
    ) -> list[Path]:
        if not outputs:
            raise ValueError("Kling avatar response contained no videos")
        base_path = Path(inputs.get("output_path", "kling_avatar.mp4"))
        paths: list[Path] = []
        for index, item in enumerate(outputs):
            url = self._output_url(item)
            suffix = extension_from_url(url, ".mp4")
            output_path = numbered_output_path(output_path_with_suffix(base_path, suffix), index, suffix)
            client.download(url, output_path)
            paths.append(output_path)
        return paths

    @staticmethod
    def _output_url(item: dict[str, Any]) -> str:
        url = item.get("url") or item.get("video_url") or item.get("resource_url")
        if url:
            return str(url)
        resource = item.get("resource") or {}
        if isinstance(resource, dict) and resource.get("url"):
            return str(resource["url"])
        raise ValueError(f"Kling avatar response item contained no downloadable URL: {item}")

    @staticmethod
    def _copy_common_task_fields(inputs: dict[str, Any], payload: dict[str, Any]) -> None:
        callback_url = validate_callback_url(inputs.get("callback_url"))
        if callback_url:
            payload["callback_url"] = callback_url
        if inputs.get("external_task_id"):
            payload["external_task_id"] = inputs["external_task_id"]

    @staticmethod
    def _callback_result_data(inputs: dict[str, Any], task_id: str) -> dict[str, Any]:
        callback_url = inputs.get("callback_url")
        if not callback_url:
            return {}
        return {
            "callback_url": str(callback_url),
            "callback_requested": True,
            "polling_used": True,
            "task_id": task_id,
        }

    @staticmethod
    def _account_usage_result(inputs: dict[str, Any], client: KlingClient) -> dict[str, Any]:
        if not inputs.get("include_account_usage"):
            return {}
        try:
            usage = get_account_costs(client=client)
            return {
                "account_usage": usage,
                "cost_source": "estimate_with_account_usage_context",
                "reconciled_cost_usd": None,
            }
        except Exception as exc:
            return {
                "account_usage_error": str(exc),
                "cost_source": "estimate",
                "reconciled_cost_usd": None,
            }

