"""Lip-sync tool for dubbing and localization.

Syncs lip movements in a video to match a different audio track using
Wav2Lip or MuseTalk models. Primary use case: replace original speech
with translated audio and make the speaker's lips match.
"""

from __future__ import annotations

import os
import subprocess
import time
from pathlib import Path
from typing import Any

from tools.base_tool import (
    BaseTool,
    Determinism,
    ExecutionMode,
    ResourceProfile,
    ToolResult,
    ToolRuntime,
    ToolStability,
    ToolStatus,
    ToolTier,
)


# Model checkpoint filenames by variant
MODEL_CHECKPOINTS = {
    "wav2lip": "wav2lip.pth",
    "wav2lip_gan": "wav2lip_gan.pth",
}


class LipSync(BaseTool):
    name = "lip_sync"
    version = "0.1.0"
    tier = ToolTier.GENERATE
    capability = "avatar"
    provider = "wav2lip"
    stability = ToolStability.EXPERIMENTAL
    execution_mode = ExecutionMode.SYNC
    determinism = Determinism.STOCHASTIC
    runtime = ToolRuntime.LOCAL_GPU

    dependencies = ["python:torch", "cmd:ffmpeg"]
    install_instructions = (
        "Option 1: pip install wav2lip (if available)\n"
        "Option 2: Clone https://github.com/Rudrabha/Wav2Lip and set WAV2LIP_PATH env var\n"
        "Requires: PyTorch with CUDA, ffmpeg"
    )

    agent_skills = ["ffmpeg"]

    capabilities = [
        "lip_sync",
        "audio_video_alignment",
        "dubbing_support",
    ]

    input_schema = {
        "type": "object",
        "required": ["video_path", "audio_path"],
        "properties": {
            "video_path": {
                "type": "string",
                "description": "Path to source video with face",
            },
            "audio_path": {
                "type": "string",
                "description": "Path to audio track to sync lips to",
            },
            "output_path": {
                "type": "string",
                "description": "Output video path (defaults to {stem}_lipsync.mp4)",
            },
            "model": {
                "type": "string",
                "enum": ["wav2lip", "wav2lip_gan"],
                "default": "wav2lip",
                "description": "Model variant (gan = higher quality but slower)",
            },
            "face_padding": {
                "type": "array",
                "items": {"type": "integer"},
                "minItems": 4,
                "maxItems": 4,
                "default": [0, 10, 0, 0],
                "description": "Padding around face crop: [top, bottom, left, right]",
            },
            "resize_factor": {
                "type": "integer",
                "default": 1,
                "description": "Downscale factor for faster processing",
            },
        },
    }

    resource_profile = ResourceProfile(
        cpu_cores=2, ram_mb=4096, vram_mb=4096, disk_mb=2000
    )
    idempotency_key_fields = ["video_path", "audio_path", "model", "face_padding", "resize_factor"]
    side_effects = ["writes lip-synced video to output_path"]
    user_visible_verification = [
        "Watch output video to verify lip movements match the new audio",
        "Check face region for visual artifacts or jitter",
    ]

    def get_status(self) -> ToolStatus:
        """Check Wav2Lip availability via env var or Python import."""
        # Check WAV2LIP_PATH environment variable
        wav2lip_path = os.environ.get("WAV2LIP_PATH")
        if wav2lip_path and Path(wav2lip_path).is_dir():
            return ToolStatus.AVAILABLE

        # Fallback: try importing wav2lip as a Python package
        try:
            import wav2lip  # noqa: F401
            return ToolStatus.AVAILABLE
        except ImportError:
            pass

        return ToolStatus.UNAVAILABLE

    def estimate_cost(self, inputs: dict[str, Any]) -> float:
        return 0.0  # local GPU, free

    def _resolve_wav2lip_dir(self) -> Path | None:
        """Locate the Wav2Lip installation directory."""
        wav2lip_path = os.environ.get("WAV2LIP_PATH")
        if wav2lip_path:
            p = Path(wav2lip_path)
            if p.is_dir():
                return p

        # Fallback: check if wav2lip is importable and find its location
        try:
            import wav2lip
            return Path(wav2lip.__file__).parent
        except (ImportError, AttributeError):
            pass

        return None

    def execute(self, inputs: dict[str, Any]) -> ToolResult:
        if self.get_status() != ToolStatus.AVAILABLE:
            return ToolResult(
                success=False,
                error="Wav2Lip not available. " + self.install_instructions,
            )

        video_path = Path(inputs["video_path"]).resolve()
        audio_path = Path(inputs["audio_path"]).resolve()

        if not video_path.exists():
            return ToolResult(success=False, error=f"Video not found: {video_path}")
        if not audio_path.exists():
            return ToolResult(success=False, error=f"Audio not found: {audio_path}")

        output_path = Path(
            inputs.get("output_path", str(video_path.with_stem(f"{video_path.stem}_lipsync")))
        ).resolve()
        output_path.parent.mkdir(parents=True, exist_ok=True)

        model_variant = inputs.get("model", "wav2lip")
        face_padding = inputs.get("face_padding", [0, 10, 0, 0])
        resize_factor = inputs.get("resize_factor", 1)

        wav2lip_dir = self._resolve_wav2lip_dir()
        if wav2lip_dir is None:
            return ToolResult(
                success=False,
                error="Could not locate Wav2Lip directory. " + self.install_instructions,
            )

        checkpoint = wav2lip_dir / "checkpoints" / MODEL_CHECKPOINTS[model_variant]
        if not checkpoint.exists():
            return ToolResult(
                success=False,
                error=f"Model checkpoint not found: {checkpoint}",
            )

        inference_script = wav2lip_dir / "inference.py"
        if not inference_script.exists():
            return ToolResult(
                success=False,
                error=f"Inference script not found: {inference_script}",
            )

        start = time.time()

        cmd = [
            "python", str(inference_script),
            "--checkpoint_path", str(checkpoint),
            "--face", str(video_path),
            "--audio", str(audio_path),
            "--outfile", str(output_path),
            "--pads", *[str(p) for p in face_padding],
            "--resize_factor", str(resize_factor),
        ]

        try:
            self.run_command(cmd, timeout=600, cwd=wav2lip_dir)
        except subprocess.TimeoutExpired:
            return ToolResult(success=False, error="Lip-sync timed out after 600 seconds")
        except Exception as e:
            return ToolResult(success=False, error=f"Wav2Lip inference failed: {e}")

        if not output_path.exists():
            return ToolResult(
                success=False,
                error=f"Inference completed but output file missing: {output_path}",
            )

        elapsed = time.time() - start

        return ToolResult(
            success=True,
            data={
                "video_input": str(video_path),
                "audio_input": str(audio_path),
                "output": str(output_path),
                "model": model_variant,
                "resize_factor": resize_factor,
                "face_padding": face_padding,
            },
            artifacts=[str(output_path)],
            duration_seconds=round(elapsed, 2),
            model=model_variant,
        )

tools/audio/_realtime_session.py:
"""Bounded realtime audio transport. Callers own turns and tool execution."""

from __future__ import annotations
import base64
import json
import os
import time
from urllib.parse import urlparse, urlencode
import requests
from websockets.sync.client import connect


class RealtimeAudioSession:
    """Context-managed bidirectional client; never executes received tool calls.

    send/receive expose provider events for live callers. cancel interrupts a
    response; submit_tool_result returns a caller-approved function result.
    Secrets stay in memory and are never returned or persisted.
    """

    def __init__(
        self,
        provider,
        model,
        *,
        voice=None,
        instructions="",
        tools=None,
        turn_detection=None,
        timeout=180,
        sample_rate=24000,
        pacing="realtime",
    ):
        if not 0 < timeout <= 3600:
            raise ValueError("timeout must be 1-3600 seconds")
        if sample_rate not in {16000, 24000}:
            raise ValueError("PCM sample rate must be 16000 or 24000")
        self.provider = provider
        self.model = model
        self.timeout = timeout
        self.sample_rate = sample_rate
        self.socket = None
        self.deadline = None
        pcm = {"type": "audio/pcm", "rate": sample_rate}
        if provider == "grok":
            if model not in {"grok-voice-3.0", "grok-voice-latest"}:
                raise ValueError("Unsupported Grok voice model")
            self.url = "wss://api.x.ai/v1/realtime?" + urlencode({"model": model})
            self.headers = {"Authorization": "Bearer " + os.environ["XAI_API_KEY"]}
            self.session = {
                "voice": voice or "eve",
                "instructions": instructions,
                "turn_detection": turn_detection,
                "audio": {"input": {"format": pcm}, "output": {"format": pcm}},
                "tools": tools or [],
            }
        elif provider == "elevenlabs":
            if model not in {"eleven_realtime_v1_mini", "eleven_realtime_v1_max"}:
                raise ValueError("Unsupported Eleven realtime model")
            if sample_rate != 24000:
                raise ValueError("Eleven Realtime uses PCM at 24000 Hz")
            self.url = "wss://api.elevenlabs.io/v1/convai/realtime"
            self.headers = {}
            self.session = {
                "type": "realtime",
                "model": model,
                "instructions": instructions,
                "output_modalities": ["audio"],
                "audio": {
                    "input": {
                        "format": pcm,
                        "turn_detection": turn_detection,
                        "pacing": pacing,
                    },
                    "output": {
                        "format": {"type": "audio/pcm"},
                        "voice": voice or "brian",
                    },
                },
                "tools": tools or [],
            }
        elif provider == "microsoft_mai":
            if model != "MAI-Transcribe-2-Streaming":
                raise ValueError("Unsupported MAI transcription model")
            if turn_detection is not None or tools:
                raise ValueError("MAI transcription does not support VAD or tools")
            endpoint = urlparse(os.environ["MAI_ENDPOINT"])
            if (
                endpoint.scheme != "https"
                or not (endpoint.hostname or "").endswith(".services.ai.azure.com")
                or endpoint.path not in ("", "/")
            ):
                raise ValueError(
                    "MAI_ENDPOINT must be the HTTPS Foundry resource origin"
                )
            self.url = f"wss://{endpoint.netloc}/mai/v1/realtime?intent=transcription"
            self.headers = {"api-key": os.environ["MAI_API_KEY"]}
            self.session = {
                "type": "transcription",
                "audio": {
                    "input": {
                        "format": pcm,
                        "transcription": {
                            "model": os.environ["MAI_TRANSCRIBE_DEPLOYMENT"],
                            "language": None,
                        },
                        "turn_detection": None,
                        "noise_reduction": None,
                    }
                },
            }
        else:
            raise ValueError("Unsupported realtime provider")

    def __enter__(self):
        if self.provider == "elevenlabs":
            r = requests.post(
                "https://api.elevenlabs.io/v1/convai/realtime/client_secrets",
                headers={"xi-api-key": os.environ["ELEVENLABS_API_KEY"]},
                json={"session": self.session, "expires_after": {"seconds": 600}},
                timeout=30,
            )
            r.raise_for_status()
            self.headers = {"Authorization": "Bearer " + r.json()["value"]}
        self.deadline = time.monotonic() + self.timeout
        self.socket = connect(
            self.url,
            additional_headers=self.headers,
            open_timeout=20,
            max_size=16 * 1024 * 1024,
        )
        try:
            if self.provider != "elevenlabs":
                self.send({"type": "session.update", "session": self.session})
                self.wait_for("session.updated")
            else:
                self.wait_for("session.created")
            return self
        except Exception:
            self.socket.close()
            raise

    def __exit__(self, *args):
        if self.socket:
            self.socket.close()
        self.headers.clear()

    def send(self, event):
        if not self.socket:
            raise RuntimeError("Session is not connected")
        if time.monotonic() >= self.deadline:
            raise TimeoutError("Realtime session deadline exceeded")
        self.socket.send(json.dumps(event))

    def receive(self):
        remaining = self.deadline - time.monotonic()
        if remaining <= 0:
            raise TimeoutError("Realtime session deadline exceeded")
        event = json.loads(self.socket.recv(timeout=remaining))
        if event.get("type") == "error":
            raise RuntimeError(
                "Provider rejected a realtime event: "
                + str(event.get("error", {}).get("code", "unknown"))
            )
        return event

    def wait_for(self, event_type):
        while True:
            event = self.receive()
            if event.get("type") == event_type:
                return event

    def append_audio(self, pcm):
        if not pcm or len(pcm) % 2:
            raise ValueError("Audio must be nonempty mono PCM16LE")
        self.send(
            {
                "type": "input_audio_buffer.append",
                "audio": base64.b64encode(pcm).decode(),
            }
        )

    def commit(self):
        self.send({"type": "input_audio_buffer.commit"})

    def cancel(self):
        self.send({"type": "response.cancel"})

    def submit_tool_result(self, call_id, result):
        self.send(
            {
                "type": "conversation.item.create",
                "item": {
                    "type": "function_call_output",
                    "call_id": call_id,
                    "output": json.dumps(result),
                },
            }
        )

    def request_response(self):
        self.send({"type": "response.create"})

