"""Piper local text-to-speech provider tool."""

from __future__ import annotations

import os
import shutil
import subprocess
import time
from pathlib import Path
from typing import Any

from tools.base_tool import (
    BaseTool,
    Determinism,
    ExecutionMode,
    ResourceProfile,
    RetryPolicy,
    ToolResult,
    ToolRuntime,
    ToolStability,
    ToolStatus,
    ToolTier,
)


class PiperTTS(BaseTool):
    name = "piper_tts"
    version = "0.1.0"
    tier = ToolTier.VOICE
    capability = "tts"
    provider = "piper"
    stability = ToolStability.EXPERIMENTAL
    execution_mode = ExecutionMode.SYNC
    determinism = Determinism.DETERMINISTIC
    runtime = ToolRuntime.LOCAL

    dependencies = ["cmd:piper"]
    install_instructions = (
        "Install Piper TTS:\n"
        "  pip install piper-tts\n"
        "Or download from https://github.com/rhasspy/piper/releases\n"
        "Then download a voice model:\n"
        "  python -m piper.download_voices --download-dir ~/.piper/models en_US-lessac-medium"
    )
    agent_skills = ["text-to-speech"]

    capabilities = [
        "text_to_speech",
        "offline_generation",
    ]
    supports = {
        "voice_cloning": False,
        "multilingual": False,
        "offline": True,
        "native_audio": True,
    }
    best_for = [
        "offline narration fallback",
        "privacy-sensitive local-only workflows",
    ]
    not_good_for = [
        "best-in-class expressive voice quality",
        "voice clone matching",
    ]

    input_schema = {
        "type": "object",
        "required": ["text"],
        "properties": {
            "text": {"type": "string"},
            "model": {
                "type": "string",
                "default": "en_US-lessac-medium",
            },
            "speaker_id": {
                "type": "integer",
                "default": 0,
            },
            "length_scale": {
                "type": "number",
                "default": 1.0,
            },
            "sentence_silence": {
                "type": "number",
                "default": 0.3,
            },
            "output_path": {"type": "string"},
        },
    }

    resource_profile = ResourceProfile(
        cpu_cores=2, ram_mb=512, vram_mb=0, disk_mb=200, network_required=False
    )
    retry_policy = RetryPolicy(max_retries=1, retryable_errors=[])
    idempotency_key_fields = ["text", "model", "speaker_id", "length_scale"]
    side_effects = ["writes audio file to output_path"]
    user_visible_verification = ["Listen to generated audio for intelligibility"]

    def vouches_for_model(self, model: str) -> bool:
        """True when `piper --model <model>` (as _generate invokes it) finds a voice.

        Mirrors piper's own lookup: an existing file path (absolute or relative),
        else `<name>.onnx` in the cwd or the configured home voice directory.
        False means "can't confirm", not "unsupported":
        provider_routing then applies its generic free-form-model policy.
        """
        return Path(model).is_file() or any(
            (directory / f"{model}.onnx").is_file()
            for directory in (Path.cwd(), self._voice_data_dir())
        )

    @staticmethod
    def _voice_data_dir() -> Path:
        return Path.home() / ".piper" / "models"

    def get_status(self) -> ToolStatus:
        if shutil.which("piper"):
            return ToolStatus.AVAILABLE
        return ToolStatus.UNAVAILABLE

    def estimate_cost(self, inputs: dict[str, Any]) -> float:
        return 0.0

    def execute(self, inputs: dict[str, Any]) -> ToolResult:
        if self.get_status() != ToolStatus.AVAILABLE:
            return ToolResult(success=False, error="Piper TTS not available. " + self.install_instructions)

        start = time.time()
        try:
            result = self._generate(inputs)
        except Exception as exc:
            return ToolResult(success=False, error=f"Local TTS generation failed: {exc}")

        result.duration_seconds = round(time.time() - start, 2)
        return result

    def _generate(self, inputs: dict[str, Any]) -> ToolResult:
        output_path = Path(inputs.get("output_path", "tts_output.wav"))
        output_path.parent.mkdir(parents=True, exist_ok=True)

        proc = subprocess.run(
            [
                "piper",
                "--model", inputs.get("model", "en_US-lessac-medium"),
                "--data-dir", str(self._voice_data_dir()),
                "--speaker", str(inputs.get("speaker_id", 0)),
                "--length-scale", str(inputs.get("length_scale", 1.0)),
                "--sentence-silence", str(inputs.get("sentence_silence", 0.3)),
                "--output_file", str(output_path),
            ],
            input=inputs["text"],
            capture_output=True,
            text=True,
            # Both sides UTF-8: the Windows default (cp1252) turns accented text
            # into input piper can't decode, which yields an empty WAV.
            encoding="utf-8",
            env={**os.environ, "PYTHONIOENCODING": "utf-8"},
            timeout=300,
        )

        if proc.returncode != 0:
            return ToolResult(success=False, error=f"Piper failed (exit {proc.returncode}): {proc.stderr}")
        if not output_path.exists():
            return ToolResult(success=False, error=f"Piper output file missing: {output_path}")

        return ToolResult(
            success=True,
            data={
                "provider": self.provider,
                "model": inputs.get("model", "en_US-lessac-medium"),
                "speaker_id": inputs.get("speaker_id", 0),
                "text_length": len(inputs["text"]),
                "output": str(output_path),
                "format": "wav",
            },
            artifacts=[str(output_path)],
            model=inputs.get("model", "en_US-lessac-medium"),
        )

tools/audio/realtime_audio.py:
"""Realtime speech sessions, isolated from the narration selector."""

import base64
import io
import json
import os
import wave
from pathlib import Path
from tools.audio._speech_api import SpeechAPI
from tools.audio._realtime_session import RealtimeAudioSession
from tools.base_tool import ToolResult, ToolStatus


class RealtimeAudio(SpeechAPI):
    name = "realtime_audio"
    provider = "realtime_audio"
    capability = "realtime_audio"
    capabilities = [
        "speech_to_speech",
        "streaming_transcription",
        "tool_events",
        "cancellation",
    ]
    credential = "XAI_API_KEY"
    dependencies = ["python:websockets"]
    install_instructions = "Configure XAI_API_KEY, ELEVENLABS_API_KEY, or MAI_API_KEY + MAI_ENDPOINT + MAI_TRANSCRIBE_DEPLOYMENT for the selected provider."
    input_schema = {
        "type": "object",
        "required": ["provider", "model"],
        "properties": {
            "provider": {"enum": ["grok", "elevenlabs", "microsoft_mai"]},
            "model": {
                "enum": [
                    "grok-voice-3.0",
                    "grok-voice-latest",
                    "eleven_realtime_v1_mini",
                    "eleven_realtime_v1_max",
                    "MAI-Transcribe-2-Streaming",
                ]
            },
            "text": {"type": "string"},
            "audio_path": {"type": "string"},
            "voice_id": {"type": "string"},
            "instructions": {"type": "string"},
            "tools": {"type": "array", "items": {"type": "object"}},
            "timeout": {"type": "number", "exclusiveMinimum": 0, "maximum": 3600},
            "output_path": {"type": "string"},
        },
    }

    def get_status(self):
        return (
            ToolStatus.AVAILABLE
            if os.getenv("XAI_API_KEY")
            or os.getenv("ELEVENLABS_API_KEY")
            or all(
                os.getenv(k)
                for k in ("MAI_API_KEY", "MAI_ENDPOINT", "MAI_TRANSCRIBE_DEPLOYMENT")
            )
            else ToolStatus.UNAVAILABLE
        )

    def execute(self, inputs):
        from jsonschema import validate

        try:
            validate(inputs, self.input_schema)
            return self.generate(inputs, None)
        except Exception as exc:
            return ToolResult(success=False, error=f"Realtime session failed: {exc}")

    def generate(self, inputs, key):
        provider = inputs["provider"]
        transcribe = provider == "microsoft_mai"
        if inputs.get("tools"):
            raise ValueError(
                "Use RealtimeAudioSession for tool calls; the file runner closes after one response"
            )
        if bool(inputs.get("text")) == bool(inputs.get("audio_path")):
            raise ValueError("Supply exactly one text or audio_path")
        if transcribe and not inputs.get("audio_path"):
            raise ValueError("MAI requires audio input")
        suffix = ".json" if transcribe else ".wav"
        out = Path(inputs.get("output_path") or "realtime_output" + suffix)
        if out.suffix.lower() != suffix:
            raise ValueError("output_path must end in " + suffix)
        pcm = None
        rate = 24000
        if inputs.get("audio_path"):
            with wave.open(inputs["audio_path"], "rb") as audio:
                rate = audio.getframerate()
                if (
                    audio.getnchannels() != 1
                    or audio.getsampwidth() != 2
                    or rate not in {16000, 24000}
                ):
                    raise ValueError("Input must be mono PCM16 WAV at 16 or 24 kHz")
                if audio.getnframes() / rate > 600:
                    raise ValueError(
                        "File runner accepts at most 10 minutes; use RealtimeAudioSession for live streams"
                    )
                pcm = audio.readframes(audio.getnframes())
        events = []
        chunks = []
        completed = False
        with RealtimeAudioSession(
            provider,
            inputs["model"],
            voice=inputs.get("voice_id"),
            instructions=inputs.get("instructions", ""),
            tools=None,
            timeout=inputs.get("timeout", 180),
            sample_rate=rate,
            pacing="bursty",
        ) as session:
            import threading

            sender_errors = []

            def send_input():
                try:
                    if pcm is not None:
                        for offset in range(0, len(pcm), rate * 2):
                            session.append_audio(pcm[offset : offset + rate * 2])
                        session.commit()
                    else:
                        session.send(
                            {
                                "type": "conversation.item.create",
                                "item": {
                                    "type": "message",
                                    "role": "user",
                                    "content": [
                                        {"type": "input_text", "text": inputs["text"]}
                                    ],
                                },
                            }
                        )
                    if not transcribe:
                        session.request_response()
                except Exception as exc:
                    sender_errors.append(exc)
                    session.socket.close()

            sender = threading.Thread(target=send_input, daemon=True)
            sender.start()
            while True:
                event = session.receive()
                kind = event.get("type") or ""
                if kind in {"response.output_audio.delta", "response.audio.delta"}:
                    chunks.append(base64.b64decode(event["delta"], validate=True))
                    events.append({"type": kind, "bytes": len(chunks[-1])})
                elif kind.startswith("session."):
                    # Do not persist session configuration, credentials or connection metadata.
                    continue
                else:
                    events.append(event)
                if (
                    transcribe
                    and kind == "conversation.item.input_audio_transcription.completed"
                ):
                    completed = True
                    break
                if kind == "response.done":
                    status = event.get("response", {}).get("status", "completed")
                    if status != "completed":
                        raise ValueError("Realtime response ended with " + status)
                    completed = True
                    break
            sender.join(timeout=5)
            if sender_errors:
                raise sender_errors[0]
            if sender.is_alive():
                raise TimeoutError("Realtime input sender did not finish")
        if not completed:
            raise ValueError("Realtime response incomplete")
        out.parent.mkdir(parents=True, exist_ok=True)
        if transcribe:
            out.write_text(
                json.dumps(events, ensure_ascii=False, indent=2), encoding="utf8"
            )
            artifacts = [str(out)]
        else:
            if not chunks:
                raise ValueError("Realtime response returned no audio")
            with wave.open(str(out), "wb") as writer:
                writer.setnchannels(1)
                writer.setsampwidth(2)
                writer.setframerate(rate)
                writer.writeframes(b"".join(chunks))
            sidecar = out.with_name(out.name + ".events.json")
            sidecar.write_text(
                json.dumps(events, ensure_ascii=False, indent=2), encoding="utf8"
            )
            artifacts = [str(out), str(sidecar)]
        return ToolResult(
            success=True,
            data={
                "output": str(out),
                "provider": provider,
                "model": inputs["model"],
                "events": events,
                "cost_status": "unquoted",
            },
            artifacts=artifacts,
            model=inputs["model"],
            cost_usd=None,
        )

