                "enum": ["auto", "on", "off"],
                "description": "Text normalization mode for providers that support it.",
            },
            "seed": {
                "type": "integer",
                "description": "Optional generation seed for providers that support reproducible speech.",
            },
            "voice_performance": {
                "type": "object",
                "description": "Structured voice-performance plan or section delivery cues from the script artifact.",
            },
            "sample_mode": {
                "type": "boolean",
                "default": False,
                "description": "True when generating an approval sample before batch narration.",
            },
            "output_format": {
                "type": ["string", "object"],
                "description": "Audio output format (e.g. mp3_44100_128). Passed through to provider.",
            },
            "preferred_provider": {
                "type": "string",
                "description": "Provider name or 'auto'. Valid values are discovered at runtime from the registry.",
                "default": "auto",
            },
            "allowed_providers": {
                "type": "array",
                "items": {"type": "string"},
            },
            "operation": {
                "type": "string",
                "enum": ["generate", "rank"],
                "default": "generate",
                "description": "Operation mode. 'rank' returns scored provider rankings without generating.",
            },
            "output_path": {"type": "string"},
        },
    }

    def _providers(self) -> list[BaseTool]:
        """Auto-discover TTS providers from the registry."""
        from tools.tool_registry import registry

        registry.ensure_discovered()
        return [t for t in registry.get_by_capability("tts") if t.name != self.name]

    @property
    def fallback_tools(self) -> list[str]:
        """Dynamically built from discovered providers."""
        return [t.name for t in self._providers()]

    @property
    def provider_matrix(self) -> dict[str, dict[str, str]]:
        """Built at runtime from each provider's best_for field."""
        matrix = {}
        for tool in self._providers():
            strength = ", ".join(tool.best_for) if tool.best_for else tool.name
            matrix[tool.provider] = {"tool": tool.name, "strength": strength}
        return matrix

    def get_status(self) -> ToolStatus:
        if any(tool.get_status() == ToolStatus.AVAILABLE for tool in self._providers()):
            return ToolStatus.AVAILABLE
        return ToolStatus.UNAVAILABLE

    def estimate_cost(self, inputs: dict[str, Any]) -> float:
        candidates = self._providers()
        if not candidates:
            return 0.0
        tool, _ = self._select_best_tool(
            inputs, candidates, self._prepare_task_context(inputs)
        )
        return tool.estimate_cost(inputs) if tool else 0.0

    def execute(self, inputs: dict[str, Any]) -> ToolResult:
        from lib.scoring import rank_providers

        task_context = self._prepare_task_context(inputs)
        from tools.provider_routing import filter_explicit_route

        candidates = filter_explicit_route(inputs, self._providers())

        # Rank mode — return scored provider rankings without generating
        if inputs.get("operation") == "rank":
            rankings = rank_providers(candidates, task_context)
            return ToolResult(
                success=True,
                data={
                    "rankings": self._serialize_rankings(candidates, rankings),
                    "explanation": "\n".join(r.explain() for r in rankings[:5]),
                    "normalized_task_context": task_context,
                },
            )

        # Normal generation — use scored selection
        tool, score = self._select_best_tool(inputs, candidates, task_context)
        if tool is None:
            return ToolResult(success=False, error="No TTS provider available.")

        try:
            adapted = self._adapt_inputs(tool, inputs)
        except (ValueError, TypeError) as exc:
            return ToolResult(success=False, error=str(exc))
        result = tool.execute(adapted)
        if result.success:
            result.data.setdefault("selected_tool", tool.name)
            result.data["selected_provider"] = tool.provider
            result.data["selection_reason"] = (
                score.explain() if score else f"Selected {tool.provider} ({tool.name})"
            )
            if score:
                result.data["provider_score"] = score.to_dict()
            result.data.update(self._tool_context_payload(tool))
            result.data["alternatives_considered"] = [
                t.name
                for t in candidates
                if t.name != tool.name and t.get_status().value == "available"
            ]
        return result

    @staticmethod
    def _adapt_inputs(tool: BaseTool, inputs: dict[str, Any]) -> dict[str, Any]:
        """Translate capability-level controls to provider-native inputs."""
        adapted = dict(inputs)
        props = tool.input_schema.get("properties", {})
        if inputs.get("model") and "model_id" in props and "model" not in props:
            if inputs.get("model_id") and inputs["model_id"] != inputs["model"]:
                raise ValueError("model and model_id disagree")
            adapted["model_id"] = inputs["model"]
            adapted.pop("model", None)
        if tool.name not in {"azure_tts", "mai_tts"}:
            return adapted

        if inputs.get("voice_id") and not inputs.get("voice"):
            adapted["voice"] = inputs["voice_id"]

        speed = inputs.get("speaking_rate", inputs.get("speed"))
        if speed is not None and "rate" not in inputs:
            percent = round((float(speed) - 1.0) * 100)
            adapted["rate"] = f"{percent:+d}%" if percent else "0%"

        pitch = inputs.get("pitch")
        if isinstance(pitch, (int, float)):
            adapted["pitch"] = f"{pitch:+g}st" if pitch else "0%"

        # The selector's numeric style is ElevenLabs-specific. Azure's style
        # is a named express-as value such as "calm" or "newscast".
        if not isinstance(inputs.get("style"), str):
            adapted.pop("style", None)

        output_format = str(inputs.get("output_format", ""))
        if output_format.startswith("mp3"):
            adapted["output_format"] = "mp3"
        elif output_format.startswith(("wav", "riff", "pcm")):
            adapted["output_format"] = "wav"
        return adapted

    def _select_best_tool(
        self,
        inputs: dict[str, Any],
        candidates: list[BaseTool],
        task_context: dict[str, Any],
    ) -> tuple[BaseTool | None, object]:
        """Select the best TTS provider using scored ranking."""
        from lib.scoring import rank_providers

        from tools.provider_routing import filter_explicit_route

        candidates = filter_explicit_route(inputs, candidates)
        preferred = inputs.get("preferred_provider", "auto")
        allowed = set(inputs.get("allowed_providers") or [])
        if allowed:
            candidates = [tool for tool in candidates if tool.provider in allowed]

        rankings = rank_providers(candidates, task_context)

        tool_by_name: dict[str, BaseTool] = {}
        for tool in candidates:
            if (
                tool.name not in tool_by_name
                and tool.get_status() == ToolStatus.AVAILABLE
            ):
                tool_by_name[tool.name] = tool

        if preferred != "auto":
            for score_item in rankings:
                if (
                    score_item.provider == preferred
                    and score_item.tool_name in tool_by_name
                ):
                    return tool_by_name[score_item.tool_name], score_item

        for score_item in rankings:
            if score_item.tool_name in tool_by_name:
                return tool_by_name[score_item.tool_name], score_item

        return None, None

    def _prepare_task_context(self, inputs: dict[str, Any]) -> dict[str, Any]:
        from lib.scoring import normalize_task_context

        return normalize_task_context(
            inputs.get("task_context", {}),
            prompt=inputs.get("text", ""),
            capability=self.capability,
            operation=inputs.get("operation", "generate"),
        )

    @staticmethod
    def _tool_context_payload(tool: BaseTool) -> dict[str, Any]:
        info = tool.get_info()
        return {
            "selected_tool_agent_skills": info.get("agent_skills", []),
            "required_agent_skills": info.get("agent_skills", []),
            "selected_tool_usage_location": info.get("usage_location"),
            "selected_tool_best_for": info.get("best_for", []),
        }

    def _serialize_rankings(
        self, candidates: list[BaseTool], rankings: list[object]
    ) -> list[dict[str, Any]]:
        tool_by_name = {tool.name: tool for tool in candidates}
        serialized: list[dict[str, Any]] = []
        for score in rankings:
            item = score.to_dict()
            tool = tool_by_name.get(score.tool_name)
            if tool:
                info = tool.get_info()
                item["agent_skills"] = info.get("agent_skills", [])
                item["usage_location"] = info.get("usage_location")
                item["best_for"] = info.get("best_for", [])
                item["status"] = str(tool.get_status())
            serialized.append(item)
        return serialized

tools/analysis/composition_validator.py:
"""Pre-render composition validator.

Checks an ExplainerProps JSON for common issues before rendering:
- Missing asset files (images, audio)
- Narration duration exceeding video duration
- Music duration shorter than video (warning)
- Overlapping or out-of-order cuts
- Required fields present

Run this before every render to catch problems that would otherwise
produce broken or truncated output.
"""

from __future__ import annotations

import json
import time
from pathlib import Path
from typing import Any

from tools.analysis.audio_probe import probe_duration
from tools.base_tool import (
    BaseTool,
    Determinism,
    ExecutionMode,
    ResourceProfile,
    ToolResult,
    ToolRuntime,
    ToolStability,
    ToolStatus,
    ToolTier,
)


class CompositionValidator(BaseTool):
    name = "composition_validator"
    version = "0.1.0"
    tier = ToolTier.CORE
    capability = "analysis"
    provider = "local"
    stability = ToolStability.PRODUCTION
    execution_mode = ExecutionMode.SYNC
    determinism = Determinism.DETERMINISTIC
    runtime = ToolRuntime.LOCAL

    dependencies = ["binary:ffprobe"]
    install_instructions = "Requires ffprobe on PATH (part of ffmpeg)."

    capabilities = ["validate_composition", "pre_render_check"]
    best_for = [
        "catching audio-video duration mismatches before render",
        "verifying all referenced assets exist",
        "pre-flight check before expensive render operations",
    ]

    input_schema = {
        "type": "object",
        "required": ["composition_path"],
        "properties": {
            "composition_path": {
                "type": "string",
                "description": "Path to the composition JSON file",
            },
            "assets_root": {
                "type": "string",
                "description": (
                    "Root directory for resolving relative asset paths. "
                    "If omitted, resolved from render_runtime (see below)."
                ),
            },
            "render_runtime": {
                "type": "string",
                "enum": ["remotion", "hyperframes", "ffmpeg"],
                "description": (
                    "Which runtime will consume this composition. Drives the "
                    "default asset root: remotion→remotion-composer/public, "
                    "hyperframes→<workspace>/assets or composition's parent, "
                    "ffmpeg→composition's parent. Explicit assets_root wins."
                ),
            },
        },
    }

    resource_profile = ResourceProfile(
        cpu_cores=1, ram_mb=64, vram_mb=0, disk_mb=0, network_required=False
    )
    side_effects = []

    def get_status(self) -> ToolStatus:
        return ToolStatus.AVAILABLE

    def estimate_cost(self, inputs: dict[str, Any]) -> float:
        return 0.0

    def execute(self, inputs: dict[str, Any]) -> ToolResult:
        comp_path = Path(inputs["composition_path"])
        if not comp_path.exists():
            return ToolResult(success=False, error=f"Composition not found: {comp_path}")

        start = time.time()

        try:
            comp = json.loads(comp_path.read_text(encoding="utf-8"))
        except (json.JSONDecodeError, UnicodeDecodeError) as e:
            return ToolResult(success=False, error=f"Invalid JSON: {e}")

        # Determine assets root. Explicit wins; otherwise dispatch by runtime.
        # `render_runtime` may be passed in inputs, or extracted from the
        # composition JSON itself (edit_decisions.render_runtime).
        explicit_root = inputs.get("assets_root") or ""
        assets_root = Path(explicit_root) if explicit_root else None
        runtime = (
            inputs.get("render_runtime")
            or comp.get("render_runtime")
            or ""
        ).strip().lower()

        if assets_root is None or not assets_root.is_dir():
            if runtime == "hyperframes":
                # HyperFrames workspaces keep assets/ alongside index.html.
                # Composition JSON typically lives in projects/<p>/artifacts/,
                # so the workspace is at projects/<p>/hyperframes/.
                candidate = comp_path
                resolved = None
                for _ in range(5):
                    candidate = candidate.parent
                    hf_assets = candidate / "hyperframes" / "assets"
                    if hf_assets.is_dir():
                        resolved = hf_assets
                        break
                    local_assets = candidate / "assets"
                    if local_assets.is_dir() and (candidate / "index.html").is_file():
                        resolved = local_assets
                        break
                assets_root = resolved or comp_path.parent
            elif runtime == "ffmpeg":
                # FFmpeg jobs reference files by absolute path; fall back to
                # the composition's parent for any bare-name references.
                assets_root = comp_path.parent
            else:
                # Remotion (default): remotion-composer/public
                candidate = comp_path
                resolved = None
                for _ in range(5):
                    candidate = candidate.parent
                    public = candidate / "remotion-composer" / "public"
                    if public.is_dir():
                        resolved = public
                        break
                assets_root = resolved or comp_path.parent

        errors: list[str] = []
        warnings: list[str] = []
        info: list[str] = []

        cuts = comp.get("cuts", [])
        audio = comp.get("audio", {})

        # --- Check 1: Cuts exist ---
        if not cuts:
            errors.append("No cuts defined in composition")
            return self._result(errors, warnings, info, start)

        # --- Check 2: Video duration ---
        video_duration = 0.0
        for cut in cuts:
            out_s = cut.get("out_seconds", 0)
            if out_s > video_duration:
                video_duration = out_s
        info.append(f"Video duration: {video_duration}s ({len(cuts)} cuts)")
        info.append(f"Render runtime: {runtime or 'default (remotion)'}; assets root: {assets_root}")

        # --- Check 3: Cut ordering and gaps ---
        sorted_cuts = sorted(cuts, key=lambda c: c.get("in_seconds", 0))
        for i, cut in enumerate(sorted_cuts):
            in_s = cut.get("in_seconds", 0)
            out_s = cut.get("out_seconds", 0)
            if out_s <= in_s:
                errors.append(
                    f"Cut '{cut.get('id', i)}': out_seconds ({out_s}) <= in_seconds ({in_s})"
                )

        # --- Check 4: Asset files exist ---
        for cut in cuts:
            source = cut.get("source", "")
            if source:
                asset_path = assets_root / source
                if not asset_path.exists():
                    errors.append(f"Missing asset: {source} (looked in {assets_root})")

            bg_img = cut.get("backgroundImage", "")
            if bg_img:
                bg_path = assets_root / bg_img
                if not bg_path.exists():
                    errors.append(f"Missing background image: {bg_img}")

        # --- Check 5: Narration duration vs video duration ---
        narration = audio.get("narration", {})
        narration_src = narration.get("src", "")
        if narration_src:
            narration_path = assets_root / narration_src
            if not narration_path.exists():
                errors.append(f"Missing narration audio: {narration_src}")
            else:
                narration_dur = probe_duration(narration_path)
                if narration_dur is not None:
                    info.append(f"Narration duration: {narration_dur:.1f}s")
                    overshoot = narration_dur - video_duration
                    if overshoot > 1.0:
                        errors.append(
                            f"Narration ({narration_dur:.1f}s) exceeds video ({video_duration}s) "
                            f"by {overshoot:.1f}s — audio will be cut off"
                        )
                    elif overshoot > 0:
                        warnings.append(
                            f"Narration ({narration_dur:.1f}s) slightly exceeds video ({video_duration}s) "
                            f"by {overshoot:.1f}s"
                        )
                else:
                    warnings.append(f"Could not probe narration duration: {narration_src}")

        # --- Check 6: Music duration ---
        music = audio.get("music", {})
        music_src = music.get("src", "")
        if music_src:
            music_path = assets_root / music_src
            if not music_path.exists():
                errors.append(f"Missing music audio: {music_src}")
            else:
                music_dur = probe_duration(music_path)
                if music_dur is not None:
                    info.append(f"Music duration: {music_dur:.1f}s")
                    if music_dur < video_duration:
                        warnings.append(
                            f"Music ({music_dur:.1f}s) is shorter than video ({video_duration}s) "
                            f"— will end early"
                        )

        # --- Check 7: No audio at all ---
        if not narration_src and not music_src:
            warnings.append("No audio configured (no narration or music)")

        return self._result(errors, warnings, info, start)

    def _result(
        self,
        errors: list[str],
        warnings: list[str],
        info: list[str],
        start: float,
    ) -> ToolResult:
        passed = len(errors) == 0
        data = {
            "valid": passed,
            "errors": errors,
            "warnings": warnings,
            "info": info,
            "error_count": len(errors),
            "warning_count": len(warnings),
        }

        if not passed:
            summary = "; ".join(errors[:3])
            return ToolResult(
                success=False,
                error=f"Composition has {len(errors)} error(s): {summary}",
                data=data,
                duration_seconds=round(time.time() - start, 2),
            )

        return ToolResult(
            success=True,
            data=data,
            duration_seconds=round(time.time() - start, 2),
        )

tools/analysis/dashscope_asr.py:
"""DashScope (Alibaba Cloud Bailian) ASR with word-level timestamps.

Uses the DashScope-native async transcription endpoint with
X-DashScope-Async: enable header. The model qwen3-asr-flash-filetrans is the
ONLY DashScope path that returns word-level timestamps (the sync
qwen3-asr-flash via /chat/completions does not).

Pattern: submit (POST) -> poll (GET /tasks/{task_id}) -> download
transcription_url -> parse transcripts[].sentences[].words[].

This tool replaces the broken `whisperx` slot for subtitle-aligned
transcription. Word timestamps are normalized from milliseconds to seconds.
"""

from __future__ import annotations

import os
import time
from pathlib import Path
from typing import Any

from tools.base_tool import (
    BaseTool,
    Determinism,
    ExecutionMode,
    ResourceProfile,
    RetryPolicy,
    ToolResult,
    ToolRuntime,
    ToolStability,
    ToolStatus,
    ToolTier,
)


class DashscopeAsr(BaseTool):
    name = "dashscope_asr"
    version = "0.1.0"
    tier = ToolTier.ANALYZE
    capability = "analysis"
    provider = "dashscope"
    stability = ToolStability.EXPERIMENTAL
    execution_mode = ExecutionMode.ASYNC
    determinism = Determinism.DETERMINISTIC
    runtime = ToolRuntime.API

    dependencies = []
    install_instructions = (
        "Set DASHSCOPE_API_KEY to your Alibaba Cloud DashScope API key.\n"
        "  Get one at https://dashscope.aliyun.com/"
    )
    fallback = "transcriber"
    fallback_tools = ["transcriber"]
    agent_skills = ["dashscope"]

    capabilities = [
        "speech_to_text",
        "word_timestamps",
        "multilingual",
    ]
    supports = {
        "word_timestamps": True,
        "multilingual": True,
        "offline": False,
    }
    best_for = [
        "word-level timestamp transcription for subtitle alignment",
        "Mandarin and English speech recognition",
        "replacing whisperx when word-level granularity is needed",
    ]
    not_good_for = [
        "real-time transcription",
        "local/offline transcription",
    ]

    input_schema = {
        "type": "object",
        "required": ["audio_url"],
        "properties": {
            "audio_url": {
                "type": "string",
                "description": (
                    "Publicly accessible URL of the audio file to transcribe. "
                    "Must be reachable by DashScope servers — local paths "
                    "are not supported."
                ),
            },
            "model": {
                "type": "string",
                "enum": ["qwen3-asr-flash-filetrans"],
                "default": "qwen3-asr-flash-filetrans",
            },
            "language_hints": {
                "type": "array",
                "items": {"type": "string"},
                "default": ["zh", "en"],
                "description": (
                    "Language hints to improve accuracy. "
                    'Examples: ["zh", "en", "ja"].'
                ),
            },
            "enable_words": {
                "type": "boolean",
                "default": True,
                "description": (
                    "Enable word-level timestamps. Required for subtitle "
                    "alignment."
                ),
            },
            "output_path": {"type": "string"},
            "poll_interval_seconds": {
                "type": "number",
                "default": 5.0,
                "minimum": 1.0,
            },
            "timeout_seconds": {
                "type": "integer",
                "default": 300,
                "minimum": 30,
            },
        },
    }

    resource_profile = ResourceProfile(
        cpu_cores=1, ram_mb=256, vram_mb=0, disk_mb=20, network_required=True
    )
    retry_policy = RetryPolicy(
        max_retries=2,
        backoff_seconds=2.0,
        retryable_errors=["timeout", "rate_limit"],
    )
    idempotency_key_fields = ["audio_url", "model", "enable_words", "language_hints"]
    side_effects = [
        "writes transcription JSON to output_path",
        "calls DashScope (Alibaba Cloud) ASR API (async submit + poll)",
    ]
    user_visible_verification = [
        "Check transcription text for accuracy",
        "Verify word-level timestamps before building subtitles",
    ]

    SUBMIT_URL = (
        "https://dashscope.aliyuncs.com/api/v1/services/audio/asr/"
        "transcription"
    )
    POLL_URL_TEMPLATE = (
        "https://dashscope.aliyuncs.com/api/v1/tasks/{task_id}"
    )

    def get_status(self) -> ToolStatus:
        if os.environ.get("DASHSCOPE_API_KEY"):
            return ToolStatus.AVAILABLE
        return ToolStatus.UNAVAILABLE

    def estimate_cost(self, inputs: dict[str, Any]) -> float:
        # DashScope ASR pricing is per-minute; check console for actual cost.
        return 0.0

    def execute(self, inputs: dict[str, Any]) -> ToolResult:
        api_key = os.environ.get("DASHSCOPE_API_KEY")
        if not api_key:
            return ToolResult(
                success=False,
                error="DASHSCOPE_API_KEY not set. " + self.install_instructions,
            )

        audio_url = inputs.get("audio_url", "").strip()
        if not audio_url:
            return ToolResult(
                success=False, error="audio_url is required."
            )
        if not self._is_public_url(audio_url):
            return ToolResult(
                success=False,
                error=(
                    "audio_url must be a publicly accessible URL (http/https). "
                    "DashScope servers fetch the file; local paths are not "
                    "supported. Upload the audio to a public location first."
                ),
            )
        # DashScope ASR rejects http:// URLs with InvalidParameter.MalformedURL;
        # upgrade to https:// before submitting. Note: signed OSS URLs with
        # query params (Expires, Signature) may also be rejected — prefer clean
        # public file URLs when possible.
        if audio_url.startswith("http://"):
            audio_url = "https://" + audio_url[len("http://"):]
            inputs = {**inputs, "audio_url": audio_url}

        start = time.time()
        try:
            result = self._transcribe(inputs, api_key=api_key)
        except Exception as exc:
            return ToolResult(
                success=False,
                error=f"DashScope ASR failed: {self._safe_error(exc)}",
            )

        result.duration_seconds = round(time.time() - start, 2)
        return result

    def _transcribe(
        self, inputs: dict[str, Any], *, api_key: str
    ) -> ToolResult:
        import json
        import requests

        payload = self._build_payload(inputs)
        headers = {
            "Authorization": f"Bearer {api_key}",
            "Content-Type": "application/json",
            "X-DashScope-Async": "enable",
        }

        # Submit
        submit_resp = requests.post(
            self.SUBMIT_URL, headers=headers, json=payload, timeout=(10, 60)
        )
        submit_data = self._json_or_raise(submit_resp)
        self._raise_for_error(submit_resp.status_code, submit_data)

        task_id = submit_data.get("output", {}).get("task_id")
        if not task_id:
            raise RuntimeError(
                "DashScope ASR submit succeeded but did not return "
                "output.task_id"
            )

        # Poll
        poll_data = self._poll_task(
            requests_module=requests,
            api_key=api_key,
            task_id=task_id,
            poll_interval=float(inputs.get("poll_interval_seconds", 5.0)),
            timeout_seconds=int(inputs.get("timeout_seconds", 300)),
        )

        # qwen3-asr-flash-filetrans returns output.result.transcription_url
        # (singular "result", NOT "results" array like paraformer-v2)
        result = poll_data.get("output", {}).get("result", {})
        transcription_url = result.get("transcription_url")
        if not transcription_url:
            raise RuntimeError(
                "DashScope ASR task succeeded but "
                "result.transcription_url missing"
            )

        # Download transcription JSON
        trans_resp = requests.get(transcription_url, timeout=120)
        trans_resp.raise_for_status()
        transcription = trans_resp.json()

        # Save full transcription
        output_path = Path(
            inputs.get("output_path", "dashscope_asr.json")
        )
        output_path.parent.mkdir(parents=True, exist_ok=True)
        output_path.write_text(
            json.dumps(transcription, ensure_ascii=False, indent=2) + "\n",
            encoding="utf-8",
        )

        # Parse word-level timestamps (normalize ms -> seconds)
        words = self._extract_words(transcription)
        transcripts = transcription.get("transcripts", [])

        return ToolResult(
            success=True,
            data={
                "provider": "dashscope",
                "model": payload["model"],
                "audio_url": inputs["audio_url"],
                "task_id": task_id,
                "transcripts": transcripts,
                "words": words,
                "word_count": len(words),
                "output": str(output_path),
            },
            artifacts=[str(output_path)],
            cost_usd=self.estimate_cost(inputs),
            model=payload["model"],
        )

    def _build_payload(self, inputs: dict[str, Any]) -> dict[str, Any]:
        return {
            "model": inputs.get(
                "model", "qwen3-asr-flash-filetrans"
            ),
            "input": {
                "file_url": inputs["audio_url"],
            },
            "parameters": {
                "enable_words": bool(inputs.get("enable_words", True)),
                "language_hints": inputs.get(
                    "language_hints", ["zh", "en"]
                ),
            },
        }

    def _poll_task(
        self,
        *,
        requests_module: Any,
        api_key: str,
        task_id: str,
        poll_interval: float,
        timeout_seconds: int,
    ) -> dict[str, Any]:
        deadline = time.time() + timeout_seconds
        headers = {"Authorization": f"Bearer {api_key}"}
        while time.time() < deadline:
            time.sleep(poll_interval)
            resp = requests_module.get(
                self.POLL_URL_TEMPLATE.format(task_id=task_id),
                headers=headers,
                timeout=(10, 60),
            )
            data = self._json_or_raise(resp)
            self._raise_for_error(resp.status_code, data)
            status = data.get("output", {}).get("task_status")
            if status == "SUCCEEDED":
                return data
            if status == "FAILED":
                msg = data.get("output", {}).get(
                    "message", "unknown error"
                )
                raise RuntimeError(
                    f"DashScope ASR task failed: {msg}"
                )
        raise TimeoutError(
            f"DashScope ASR task {task_id} did not finish within "
            f"{timeout_seconds}s"
        )

    @staticmethod
    def _is_public_url(url: str) -> bool:
        return url.startswith("http://") or url.startswith("https://")

    @staticmethod
    def _extract_words(
        transcription: dict[str, Any]
    ) -> list[dict[str, Any]]:
        """Extract flat word list with timestamps normalized to seconds."""
        words: list[dict[str, Any]] = []
        for transcript in transcription.get("transcripts", []):
            for sentence in transcript.get("sentences", []):
                for word in sentence.get("words", []):
                    words.append(
                        {
                            "text": word.get("text", ""),
                            "begin_time_seconds": round(
                                word.get("begin_time", 0) / 1000.0, 3
                            ),
                            "end_time_seconds": round(
                                word.get("end_time", 0) / 1000.0, 3
                            ),
                        }
                    )
        return words

    @staticmethod
    def _json_or_raise(response: Any) -> dict[str, Any]:
        try:
            return response.json()
        except ValueError as exc:
            raise RuntimeError(
                f"Non-JSON response from DashScope API: "
                f"HTTP {response.status_code}"
            ) from exc

    def _raise_for_error(
        self, http_status: int, payload: dict[str, Any]
    ) -> None:
        if http_status < 400:
            return
        code = payload.get("code")
        message = payload.get("message", "unknown error")
        raise RuntimeError(
            f"DashScope API error: HTTP {http_status}, "
            f"code {code}: {message}"
        )

    @staticmethod
    def _safe_error(exc: Exception) -> str:
        return str(exc).replace(
            os.environ.get("DASHSCOPE_API_KEY", ""), "[redacted]"
        )

tools/analysis/transcript_fetcher.py:
"""YouTube transcript fetcher tool wrapping youtube-transcript-api.

Extracts transcripts/captions from YouTube videos without downloading the video.
Instant, free, no API key needed. Falls back to yt-dlp subtitle download.
"""

from __future__ import annotations

import re
import time
from typing import Any

from tools.base_tool import (
    BaseTool,
    Determinism,
    ExecutionMode,
    ResourceProfile,
    ToolResult,
    ToolStability,
    ToolStatus,
    ToolTier,
    ToolRuntime,
)


class TranscriptFetcher(BaseTool):
    name = "transcript_fetcher"
    version = "0.1.0"
    tier = ToolTier.ANALYZE
    capability = "analysis"
    provider = "youtube-transcript-api"
    stability = ToolStability.PRODUCTION
    execution_mode = ExecutionMode.SYNC
    determinism = Determinism.DETERMINISTIC
    runtime = ToolRuntime.LOCAL

    dependencies = ["python:youtube_transcript_api"]
    install_instructions = (
        "Install youtube-transcript-api: pip install youtube-transcript-api"
    )
    agent_skills = []

    capabilities = [
        "fetch_transcript",
        "list_transcripts",
    ]

    best_for = [
        "fast YouTube transcript extraction",
        "caption-based analysis without video download",
        "getting timestamped text from YouTube videos",
    ]

    not_good_for = [
        "non-YouTube platforms (Instagram, TikTok)",
        "videos without any captions",
        "speaker diarization (use transcriber tool instead)",
    ]

    input_schema = {
        "type": "object",
        "required": ["url_or_video_id"],
        "properties": {
            "url_or_video_id": {
                "type": "string",
                "description": "YouTube URL or video ID",
            },
            "languages": {
                "type": "array",
                "items": {"type": "string"},
                "default": ["en"],
                "description": "Preferred languages in priority order",
            },
            "include_auto_generated": {
                "type": "boolean",
                "default": True,
                "description": "Whether to include auto-generated captions",
            },
        },
    }

    output_schema = {
        "type": "object",
        "properties": {
            "transcript": {
                "type": "array",
                "items": {
                    "type": "object",
                    "properties": {
                        "text": {"type": "string"},
                        "start": {"type": "number"},
                        "duration": {"type": "number"},
                    },
                },
            },
            "full_text": {"type": "string"},
            "language": {"type": "string"},
            "is_auto_generated": {"type": "boolean"},
            "word_count": {"type": "integer"},
            "source": {"type": "string"},
        },
    }

    resource_profile = ResourceProfile(
        cpu_cores=1, ram_mb=256, vram_mb=0, disk_mb=10,
        network_required=True,
    )
    idempotency_key_fields = ["url_or_video_id", "languages"]
    side_effects = []
    fallback = "transcriber"
    user_visible_verification = [
        "Spot-check transcript accuracy against video audio",
    ]

    def _extract_video_id(self, url_or_id: str) -> str:
        """Extract YouTube video ID from URL or return as-is if already an ID."""
        # Already a bare ID (11 chars, alphanumeric + - _)
        if re.match(r"^[A-Za-z0-9_-]{11}$", url_or_id):
            return url_or_id

        # Standard YouTube URLs
        patterns = [
            r"(?:youtube\.com/watch\?.*v=|youtu\.be/|youtube\.com/embed/|youtube\.com/shorts/)([A-Za-z0-9_-]{11})",
        ]
        for pattern in patterns:
            match = re.search(pattern, url_or_id)
            if match:
                return match.group(1)

        # If nothing matched, try using the whole string as ID
        return url_or_id.strip()

    def execute(self, inputs: dict[str, Any]) -> ToolResult:
        video_id = self._extract_video_id(inputs["url_or_video_id"])
        languages = inputs.get("languages", ["en"])
        include_auto = inputs.get("include_auto_generated", True)

        start = time.time()

        try:
            from youtube_transcript_api import YouTubeTranscriptApi

            ytt = YouTubeTranscriptApi()

            # Fetch transcript using the instance-based API (v1.0+)
            transcript_result = ytt.fetch(video_id, languages=languages)

            # Build segments and full text from snippets
            segments = []
            full_text_parts = []
            for snippet in transcript_result.snippets:
                segments.append({
                    "text": snippet.text,
                    "start": round(snippet.start, 3),
                    "duration": round(snippet.duration, 3),
                })
                full_text_parts.append(snippet.text)

            full_text = " ".join(full_text_parts)
            word_count = len(full_text.split())

            # Get auto-generated status and language from the result
            is_auto = getattr(transcript_result, "is_generated", False)
            detected_lang = getattr(transcript_result, "language", languages[0])
            # If language is an object, get the code
            if hasattr(detected_lang, "code"):
                detected_lang = detected_lang.code
            elif not isinstance(detected_lang, str):
                detected_lang = languages[0]

            elapsed = time.time() - start

            return ToolResult(
                success=True,
                data={
                    "transcript": segments,
                    "full_text": full_text,
                    "language": detected_lang,
                    "is_auto_generated": is_auto,
                    "word_count": word_count,
                    "source": "youtube_captions",
                    "video_id": video_id,
                    "segment_count": len(segments),
                },
                duration_seconds=round(elapsed, 2),
            )

        except ImportError:
            return ToolResult(
                success=False,
                error="youtube-transcript-api not installed. Run: pip install youtube-transcript-api",
            )
        except Exception as e:
            elapsed = time.time() - start
            error_str = str(e)

            # Provide helpful error messages
            if "Could not retrieve" in error_str or "TranscriptsDisabled" in error_str:
                return ToolResult(
                    success=False,
                    error=(
                        f"No captions available for video {video_id}. "
                        "This video may not have captions enabled. "
                        "Fallback: download the video and use the transcriber tool "
                        "with Whisper for local transcription."
                    ),
                    data={"video_id": video_id, "fallback_suggested": "transcriber"},
                    duration_seconds=round(elapsed, 2),
                )

            return ToolResult(
                success=False,
                error=f"Transcript fetch failed: {error_str}",
                data={"video_id": video_id},
                duration_seconds=round(elapsed, 2),
            )

tools/analysis/video_analyzer.py:
"""Video analyzer tool — comprehensive reference video analysis.

Orchestrates multiple analysis tools to produce a VideoAnalysisBrief from a
video URL or local file. Runs entirely locally with zero API keys: yt-dlp for
download, youtube-transcript-api for captions, PySceneDetect/FFmpeg for scene
detection, FFmpeg for frame extraction, and faster-whisper for transcription.

The agent's own vision model analyzes extracted keyframes — this tool provides
the structured data; the agent provides the visual interpretation.
"""

from __future__ import annotations

import json
import time
from pathlib import Path
from typing import Any

from lib.paths import PROJECTS_DIR
from tools.base_tool import (
    BaseTool,
    Determinism,
    ExecutionMode,
    ResourceProfile,
    ToolResult,
    ToolStability,
    ToolStatus,
    ToolTier,
    ToolRuntime,
)


class VideoAnalyzer(BaseTool):
    name = "video_analyzer"
    version = "0.1.0"
    tier = ToolTier.ANALYZE
    capability = "analysis"
    provider = "multi"
    stability = ToolStability.BETA
    execution_mode = ExecutionMode.SYNC
    determinism = Determinism.DETERMINISTIC
    runtime = ToolRuntime.LOCAL

    dependencies = ["cmd:ffmpeg"]
    install_instructions = (
        "Core: FFmpeg is required (https://ffmpeg.org/download.html)\n"
        "For URL downloads: pip install yt-dlp\n"
        "For YouTube transcripts: pip install youtube-transcript-api\n"
        "For local transcription: pip install faster-whisper\n"
        "For scene detection: pip install scenedetect[opencv]\n"
        "All dependencies are free and local — no API keys needed."
    )
    agent_skills = ["video-understand", "ffmpeg"]

    capabilities = [
        "analyze_reference_video",
        "extract_structure",
        "extract_style",
        "extract_transcript",
    ]

    best_for = [
        "comprehensive video analysis",
        "reference video understanding",
        "style extraction from example video",
        "understanding video structure and pacing",
    ]

    not_good_for = [
        "editing or modifying video",
        "generating new video content",
    ]

    input_schema = {
        "type": "object",
        "required": ["source"],
        "properties": {
            "source": {
                "type": "string",
                "description": "Video file path or URL (YouTube, Shorts, Instagram, TikTok)",
            },
            "analysis_depth": {
                "type": "string",
                "enum": ["transcript_only", "standard", "deep"],
                "default": "standard",
                "description": (
                    "transcript_only: transcript + metadata only. "
                    "standard: + scene detection + keyframes + audio energy. "
                    "deep: + intra-scene sampling + detailed style extraction."
                ),
            },
            "max_keyframes": {
                "type": "integer",
                "default": 20,
                "minimum": 1,
                "maximum": 50,
                "description": "Maximum keyframes to extract",
            },
            "output_dir": {
                "type": "string",
                "description": "Directory for analysis outputs (default: auto-generated)",
            },
        },
    }

    output_schema = {
        "type": "object",
        "description": "VideoAnalysisBrief artifact — see schemas/artifacts/video_analysis_brief.schema.json",
    }

    resource_profile = ResourceProfile(
        cpu_cores=2, ram_mb=2048, vram_mb=0, disk_mb=3000,
        network_required=False,  # Only needed for URL sources
    )
    idempotency_key_fields = ["source", "analysis_depth"]
    side_effects = [
        "downloads video to output_dir (if URL)",
        "writes keyframe images to output_dir/keyframes/",
        "writes analysis JSON to output_dir/video_analysis_brief.json",
    ]
    fallback_tools = []
    user_visible_verification = [
        "Review keyframe images for representative coverage",
        "Check transcript accuracy against video",
        "Verify scene boundaries look correct",
    ]

    def _is_url(self, source: str) -> bool:
        """Check if source is a URL vs local file."""
        return source.startswith(("http://", "https://", "www."))

    def _detect_platform(self, source: str) -> str:
        """Detect platform from URL."""
        if not self._is_url(source):
            return "local_file"
        s = source.lower()
        if "youtube.com/shorts" in s:
            return "shorts"
        if "youtube.com" in s or "youtu.be" in s:
            return "youtube"
        if "instagram.com" in s:
            return "instagram"
        if "tiktok.com" in s:
            return "tiktok"
        return "other_url"

    def _is_youtube(self, platform: str) -> bool:
        return platform in ("youtube", "shorts")

    def execute(self, inputs: dict[str, Any]) -> ToolResult:
        source = inputs["source"]
        depth = inputs.get("analysis_depth", "standard")
        max_keyframes = inputs.get("max_keyframes", 20)

        # Setup output directory
        if inputs.get("output_dir"):
            output_dir = Path(inputs["output_dir"])
        else:
            output_dir = PROJECTS_DIR / "_analysis" / f"analysis_{int(time.time())}"
        output_dir.mkdir(parents=True, exist_ok=True)

        platform = self._detect_platform(source)
        is_url = self._is_url(source)
        start = time.time()

        # Initialize brief structure
        brief = {
            "version": "1.0",
            "source": {
                "type": platform,
                "duration_seconds": 0,
            },
            "content_analysis": {
                "summary": "",
                "topics": [],
                "target_audience": "general",
            },
            "structure_analysis": {
                "total_scenes": 0,
                "scenes": [],
                "pacing_profile": {},
            },
        }

        if is_url:
            brief["source"]["url"] = source
        else:
            brief["source"]["local_path"] = source

        # Track what succeeded and what failed
        steps_completed = []
        steps_failed = []

        # ─── STEP 1: Get metadata + download (if URL) ───
        video_path = None
        audio_path = None
        metadata = {}

        if is_url:
            try:
                from tools.analysis.video_downloader import VideoDownloader
                downloader = VideoDownloader()

                if depth == "transcript_only" and self._is_youtube(platform):
                    # Only get metadata, skip video download
                    dl_result = downloader.execute({
                        "url": source,
                        "output_dir": str(output_dir),
                        "format": "metadata_only",
                    })
                else:
                    dl_result = downloader.execute({
                        "url": source,
                        "output_dir": str(output_dir),
                        "format": "video",
                        "max_resolution": "720p",
                    })

                if dl_result.success:
                    metadata = dl_result.data.get("metadata", {})
                    video_path = dl_result.data.get("video_path")
                    audio_path = dl_result.data.get("audio_path")
                    brief["source"]["title"] = metadata.get("title", "")
                    brief["source"]["duration_seconds"] = metadata.get("duration", 0)
                    brief["source"]["resolution"] = metadata.get("resolution", "")
                    brief["source"]["platform_metadata"] = {
                        "uploader": metadata.get("uploader", ""),
                        "upload_date": metadata.get("upload_date", ""),
                        "view_count": metadata.get("view_count", 0),
                        "like_count": metadata.get("like_count", 0),
                        "description": metadata.get("description", ""),
                    }
                    steps_completed.append("metadata")
                    if video_path:
                        steps_completed.append("download")
                else:
                    steps_failed.append(f"download: {dl_result.error}")
            except Exception as e:
                steps_failed.append(f"download: {e}")
        else:
            # Local file
            local_path = Path(source)
            if not local_path.exists():
                return ToolResult(
                    success=False,
                    error=f"Local file not found: {source}",
                )
            video_path = str(local_path)
            # Get duration via ffprobe
            try:
                duration = self._get_duration(local_path)
                brief["source"]["duration_seconds"] = duration
                brief["source"]["title"] = local_path.stem
                steps_completed.append("metadata")
            except Exception as e:
                steps_failed.append(f"metadata: {e}")

        # ─── STEP 2: Get transcript ───
        transcript_data = None

        # Try youtube-transcript-api first (instant, for YouTube)
        if self._is_youtube(platform):
            try:
                from youtube_transcript_api import YouTubeTranscriptApi

                from tools.analysis.transcript_fetcher import TranscriptFetcher
                fetcher = TranscriptFetcher()

                # Auto-detect available languages instead of hardcoding "en"
                languages_to_try = ["en"]
                try:
                    ytt = YouTubeTranscriptApi()
                    available = ytt.list(fetcher._extract_video_id(source))
                    # Build priority list: manual first, then auto-generated
                    lang_codes = []
                    for t in available:
                        code = t.language_code if hasattr(t, "language_code") else str(t)
                        if code not in lang_codes:
                            lang_codes.append(code)
                    if lang_codes:
                        languages_to_try = lang_codes
                except Exception:
                    pass  # Fall through to default ["en"]

                tf_result = fetcher.execute({
                    "url_or_video_id": source,
                    "languages": languages_to_try,
                    "include_auto_generated": True,
                })
                if tf_result.success:
                    transcript_data = tf_result.data
                    brief["narration_transcript"] = {
                        "full_text": transcript_data.get("full_text", ""),
                        "segments": transcript_data.get("transcript", []),
                        "language": transcript_data.get("language", "en"),
                        "word_count": transcript_data.get("word_count", 0),
                    }
                    steps_completed.append("transcript_youtube")
            except Exception as e:
                steps_failed.append(f"transcript_youtube: {e}")

        # Fallback: If transcript failed and we don't have audio yet,
        # download the video to get audio for Whisper transcription
        if transcript_data is None and audio_path is None and video_path is None and is_url:
            try:
                from tools.analysis.video_downloader import VideoDownloader
                downloader = VideoDownloader()
                dl_result = downloader.execute({
                    "url": source,
                    "output_dir": str(output_dir),
                    "format": "video",
                    "max_resolution": "720p",
                })
                if dl_result.success:
                    video_path = dl_result.data.get("video_path")
                    audio_path = dl_result.data.get("audio_path")
                    if video_path:
                        steps_completed.append("download_for_whisper")
                    # Also update metadata if we didn't have it
                    if not metadata:
                        metadata = dl_result.data.get("metadata", {})
                        brief["source"]["title"] = metadata.get("title", "")
                        brief["source"]["duration_seconds"] = metadata.get("duration", 0)
            except Exception as e:
                steps_failed.append(f"download_for_whisper: {e}")

        # Fallback: Whisper transcription on audio
        if transcript_data is None and audio_path:
            try:
                from tools.analysis.transcriber import Transcriber
                transcriber = Transcriber()
                # Let Whisper auto-detect language instead of assuming English
                tr_inputs = {
                    "input_path": audio_path,
                    "model_size": "base",
                    "output_dir": str(output_dir),
                }
                # Only set language if we know it from transcript attempt
                detected_lang = brief.get("narration_transcript", {}).get("language")
                if detected_lang and detected_lang != "en":
                    tr_inputs["language"] = detected_lang
                # else: let Whisper auto-detect

                tr_result = transcriber.execute(tr_inputs)
                if tr_result.success:
                    segments = tr_result.data.get("segments", [])
                    full_text = " ".join(s.get("text", "") for s in segments)
                    brief["narration_transcript"] = {
                        "full_text": full_text,
                        "segments": [
                            {
                                "start": s.get("start", 0),
                                "end": s.get("end", 0),
                                "text": s.get("text", ""),
                            }
                            for s in segments
                        ],
                        "language": tr_result.data.get("language", "en"),
                        "word_count": len(full_text.split()),
                    }
                    transcript_data = brief["narration_transcript"]
                    steps_completed.append("transcript_whisper")
            except Exception as e:
                steps_failed.append(f"transcript_whisper: {e}")

        # For transcript_only depth, we're done
        if depth == "transcript_only":
            brief["_analysis_meta"] = {
                "depth": depth,
                "steps_completed": steps_completed,
                "steps_failed": steps_failed,
                "duration_seconds": round(time.time() - start, 2),
            }
            self._save_brief(brief, output_dir)
            return ToolResult(
                success=True,
                data=brief,
                artifacts=[str(output_dir / "video_analysis_brief.json")],
                duration_seconds=round(time.time() - start, 2),
            )

        # ─── STEP 3: Scene detection (standard + deep) ───
        scenes = []
        if video_path:
            try:
                from tools.analysis.scene_detect import SceneDetect
                detector = SceneDetect()
                sd_result = detector.execute({
                    "input_path": video_path,
                    "method": "content",
                    "min_scene_length_seconds": 0.5,
                    "output_path": str(output_dir / "scenes.json"),
                })
                if sd_result.success:
                    scenes = sd_result.data.get("scenes", [])
                    steps_completed.append("scene_detect")
            except Exception as e:
                steps_failed.append(f"scene_detect: {e}")

        # Build scene list for the brief
        if scenes:
            brief["structure_analysis"]["total_scenes"] = len(scenes)
            brief_scenes = []
            for scene in scenes:
                brief_scenes.append({
                    "scene_index": scene.get("index", scene.get("scene_index", 0)),
                    "start_time": scene.get("start_seconds", 0),
                    "end_time": scene.get("end_seconds", 0),
                    "description": "",  # Agent fills this via vision
                    "visual_type": "other",  # Agent classifies via vision
                    "energy_level": "medium",
                })
            brief["structure_analysis"]["scenes"] = brief_scenes

            # Compute pacing profile
            durations = [
                s.get("end_seconds", 0) - s.get("start_seconds", 0)
                for s in scenes
            ]
            total_duration = brief["source"]["duration_seconds"] or sum(durations)
            if durations:
                brief["structure_analysis"]["pacing_profile"] = {
                    "avg_scene_duration_seconds": round(sum(durations) / len(durations), 2),
                    "shortest_scene_seconds": round(min(durations), 2),
                    "longest_scene_seconds": round(max(durations), 2),
                    "cuts_per_minute": round(len(durations) / (total_duration / 60), 2) if total_duration > 0 else 0,
                    "pacing_style": self._classify_pacing(durations),
                }

        # ─── STEP 3b: Motion classification per scene ───
        if video_path and scenes:
            try:
                motion_results = self._classify_scene_motion(video_path, scenes)
                for bs, mr in zip(brief["structure_analysis"]["scenes"], motion_results):
                    bs["motion_type"] = mr["motion_type"]
                    bs["flow_variance"] = mr["flow_variance"]
                steps_completed.append("motion_classification")
            except Exception as e:
                steps_failed.append(f"motion_classification: {e}")

        # ─── STEP 4: Keyframe extraction (scene-guided) ───
        keyframes = []
        keyframe_dir = output_dir / "keyframes"
        if video_path and scenes:
            try:
                # Extract keyframes at scene boundaries + midpoints
                timestamps = self._compute_keyframe_timestamps(scenes, max_keyframes, depth)

                from tools.analysis.frame_sampler import FrameSampler
                sampler = FrameSampler()
                fs_result = sampler.execute({
                    "input_path": video_path,
                    "strategy": "timestamps",
                    "timestamps": timestamps,
                    "output_dir": str(keyframe_dir),
                    "format": "jpg",
                    "quality": 2,
                })
                if fs_result.success:
                    for frame in fs_result.data.get("frames", []):
                        # Map each frame to its scene
                        scene_idx = self._timestamp_to_scene(
                            frame["timestamp_seconds"], scenes
                        )
                        keyframes.append({
                            "timestamp": frame["timestamp_seconds"],
                            "scene_index": scene_idx,
                            "path": frame["path"],
                            "description": "",  # Agent fills via vision
                        })
                    steps_completed.append("keyframes")
            except Exception as e:
                steps_failed.append(f"keyframes: {e}")
        elif video_path and not scenes:
            # No scene detection — fall back to count-based extraction
            try:
                from tools.analysis.frame_sampler import FrameSampler
                sampler = FrameSampler()
                fs_result = sampler.execute({
                    "input_path": video_path,
                    "strategy": "count",
                    "count": min(max_keyframes, 15),
                    "output_dir": str(keyframe_dir),
                    "format": "jpg",
                    "quality": 2,
                })
                if fs_result.success:
                    for frame in fs_result.data.get("frames", []):
                        keyframes.append({
                            "timestamp": frame["timestamp_seconds"],
                            "scene_index": 0,
                            "path": frame["path"],
                            "description": "",
                        })
                    steps_completed.append("keyframes_uniform")
            except Exception as e:
                steps_failed.append(f"keyframes_uniform: {e}")

        brief["keyframes"] = keyframes

        # ─── STEP 5: Audio energy analysis ───
        if audio_path or video_path:
            audio_source = audio_path or video_path
            try:
                from tools.analysis.audio_energy import AudioEnergy
                energy = AudioEnergy()
                ae_result = energy.execute({
                    "input_path": audio_source,
                    "video_duration_seconds": brief["source"]["duration_seconds"],
                })
                if ae_result.success:
                    # Store energy profile summary in style_profile
                    if "style_profile" not in brief:
                        brief["style_profile"] = {}
                    brief["style_profile"]["audio_energy_profile"] = {
                        "recommended_offset": ae_result.data.get("recommended_offset_seconds", 0),
                        "has_energy_data": True,
                    }
                    steps_completed.append("audio_energy")
            except Exception as e:
                steps_failed.append(f"audio_energy: {e}")

        # ─── STEP 6: Build replication guidance ───
        brief["replication_guidance"] = {
            "suggested_pipeline": self._suggest_pipeline(brief),
            "suggested_playbook": "flat-motion-graphics",
            "key_elements_to_replicate": [],  # Agent fills via analysis
            "elements_requiring_custom_work": [],
            "estimated_complexity": self._estimate_complexity(brief),
            "motion_required": self._needs_motion(brief),
            "creative_differentiation_seeds": [],  # Agent fills
        }

        # ─── STEP 7: Initialize style_profile ───
        if "style_profile" not in brief:
            brief["style_profile"] = {}

        # Narration style from transcript
        if transcript_data:
            duration = brief["source"]["duration_seconds"]
            wc = transcript_data.get("word_count", 0) if isinstance(transcript_data, dict) else brief.get("narration_transcript", {}).get("word_count", 0)
            wpm = round(wc / (duration / 60), 1) if duration > 0 else 0
            brief["style_profile"]["narration_style"] = {
                "has_narration": wc > 20,
                "speaker_count": 1,  # Agent refines via analysis
                "delivery_style": "",  # Agent fills
                "words_per_minute": wpm,
            }

        # Initialize remaining style fields for agent to fill
        brief["style_profile"].setdefault("color_palette", {
            "primary_colors": [],
            "accent_colors": [],
            "overall_mood": "",
        })
        brief["style_profile"].setdefault("typography_observed", "")
        brief["style_profile"].setdefault("transition_types", [])
        brief["style_profile"].setdefault("music_style", "")
        brief["style_profile"].setdefault("subtitle_style", "")
        brief["style_profile"].setdefault("production_quality", "prosumer")
        brief["style_profile"].setdefault("closest_playbook", "")
        brief["style_profile"].setdefault("playbook_delta", "")

        # ─── Finalize ───
        brief["_analysis_meta"] = {
            "depth": depth,
            "steps_completed": steps_completed,
            "steps_failed": steps_failed,
            "keyframe_count": len(keyframes),
            "scene_count": len(scenes),
            "has_transcript": transcript_data is not None,
            "duration_seconds": round(time.time() - start, 2),
        }

        self._save_brief(brief, output_dir)

        elapsed = time.time() - start
        artifacts = [str(output_dir / "video_analysis_brief.json")]
        if keyframe_dir.exists():
            artifacts.append(str(keyframe_dir))

        return ToolResult(
            success=True,
            data=brief,
            artifacts=artifacts,
            duration_seconds=round(elapsed, 2),
        )

    # ─── Helpers ───

    def _get_duration(self, video_path: Path) -> float:
        """Get video duration via ffprobe."""
        cmd = [
            "ffprobe", "-v", "quiet",
            "-show_entries", "format=duration",
            "-of", "json",
            str(video_path),
        ]
        result = self.run_command(cmd)
        data = json.loads(result.stdout)
        return float(data.get("format", {}).get("duration", 0))

    def _compute_keyframe_timestamps(
        self, scenes: list[dict], max_frames: int, depth: str
    ) -> list[float]:
        """Compute optimal keyframe timestamps from scene boundaries."""
        timestamps = []

        for scene in scenes:
            start = scene.get("start_seconds", 0)
            end = scene.get("end_seconds", 0)
            duration = end - start

            # First frame of each scene
            timestamps.append(start + 0.1)

            # Midpoint for scenes > 3 seconds
            if duration > 3.0:
                timestamps.append(start + duration / 2)

            # For deep analysis, add more intra-scene samples
            if depth == "deep" and duration > 6.0:
                timestamps.append(start + duration * 0.25)
                timestamps.append(start + duration * 0.75)

        # Deduplicate, sort, and limit
        timestamps = sorted(set(round(t, 3) for t in timestamps))
        if len(timestamps) > max_frames:
            # Uniform subsample to max_frames
            step = len(timestamps) / max_frames
            timestamps = [timestamps[int(i * step)] for i in range(max_frames)]

        return timestamps

    def _timestamp_to_scene(self, ts: float, scenes: list[dict]) -> int:
        """Map a timestamp to its scene index."""
        for scene in scenes:
            start = scene.get("start_seconds", 0)
            end = scene.get("end_seconds", 0)
            if start <= ts <= end:
                return scene.get("index", scene.get("scene_index", 0))
        return 0

    def _classify_pacing(self, durations: list[float]) -> str:
        """Classify pacing style from scene durations."""
        if not durations:
            return "variable"
        avg = sum(durations) / len(durations)
        if avg > 10:
            return "slow_contemplative"
        if avg > 5:
            return "steady_educational"
        if avg > 2:
            return "dynamic_social"
        return "rapid_fire"

    def _suggest_pipeline(self, brief: dict) -> str:
        """Suggest the best pipeline based on content analysis."""
        platform = brief["source"]["type"]
        pacing = brief["structure_analysis"].get("pacing_profile", {}).get("pacing_style", "")

        if platform in ("shorts", "tiktok", "instagram"):
            return "animation"  # Short-form → animation pipeline works well
        if pacing in ("slow_contemplative",):
            return "cinematic"
        return "animated-explainer"

    def _estimate_complexity(self, brief: dict) -> str:
        """Estimate how complex it would be to recreate this style."""
        scenes = brief["structure_analysis"]["total_scenes"]
        duration = brief["source"]["duration_seconds"]

        if duration > 300 or scenes > 30:
            return "complex"
        if duration > 120 or scenes > 15:
            return "moderate"
        return "simple"

    def _needs_motion(self, brief: dict) -> bool:
        """Determine if motion (video gen or Remotion) is required."""
        # If we have per-scene motion data, use it — majority motion_clip = motion required
        scenes = brief["structure_analysis"].get("scenes", [])
        motion_scenes = [s for s in scenes if s.get("motion_type") == "motion_clip"]
        if scenes and motion_scenes:
            return len(motion_scenes) / len(scenes) >= 0.3
        # Fallback to pacing heuristic
        pacing = brief["structure_analysis"].get("pacing_profile", {}).get("pacing_style", "")
        return pacing in ("dynamic_social", "rapid_fire")

    def _classify_scene_motion(
        self, video_path: str, scenes: list[dict]
    ) -> list[dict]:
        """Classify each scene as static_image, animated_still, or motion_clip.

        Samples 2-3 frame pairs per scene and computes dense optical flow
        variance using Farneback. Low uniform flow = pan/zoom on a still.
        High heterogeneous flow = real character/object motion.
        """
        import numpy as np

        try:
            import cv2
        except ImportError:
            return [{"motion_type": "unknown", "flow_variance": -1}] * len(scenes)

        cap = cv2.VideoCapture(video_path)
        if not cap.isOpened():
            return [{"motion_type": "unknown", "flow_variance": -1}] * len(scenes)

        fps = cap.get(cv2.CAP_PROP_FPS) or 30.0
        results = []

        for scene in scenes:
            start = scene.get("start_seconds", 0)
            end = scene.get("end_seconds", 0)
            duration = end - start

            if duration < 0.3:
                results.append({"motion_type": "static_image", "flow_variance": 0.0})
                continue

            # Sample 2-3 frame pairs spaced across the scene
            gap = min(0.4, duration / 3)
            sample_times = [start + duration * p for p in (0.25, 0.5, 0.75) if start + duration * p + gap <= end]
            if not sample_times:
                sample_times = [start + 0.1]

            flow_variances = []
            flow_mag_means = []

            for t in sample_times:
                frame_a = self._read_frame_at(cap, t, fps)
                frame_b = self._read_frame_at(cap, t + gap, fps)
                if frame_a is None or frame_b is None:
                    continue

                # Downscale to 360p height for speed
                h, w = frame_a.shape[:2]
                scale = 360 / h if h > 360 else 1.0
                if scale < 1.0:
                    dim = (int(w * scale), 360)
                    frame_a = cv2.resize(frame_a, dim)
                    frame_b = cv2.resize(frame_b, dim)

                gray_a = cv2.cvtColor(frame_a, cv2.COLOR_BGR2GRAY)
                gray_b = cv2.cvtColor(frame_b, cv2.COLOR_BGR2GRAY)

                flow = cv2.calcOpticalFlowFarneback(
                    gray_a, gray_b, None,
                    pyr_scale=0.5, levels=3, winsize=15,
                    iterations=3, poly_n=5, poly_sigma=1.2, flags=0,
                )

                mag = np.sqrt(flow[..., 0] ** 2 + flow[..., 1] ** 2)
                flow_mag_means.append(float(np.mean(mag)))
                # Variance of magnitude = heterogeneity of motion
                flow_variances.append(float(np.var(mag)))

            if not flow_variances:
                results.append({"motion_type": "unknown", "flow_variance": -1})
                continue

            avg_variance = sum(flow_variances) / len(flow_variances)
            avg_magnitude = sum(flow_mag_means) / len(flow_mag_means)

            # Classification thresholds (tuned for 360p, 0.4s gap):
            # - static_image: near-zero flow (no motion at all)
            # - animated_still: uniform flow (pan/zoom on a still image)
            # - motion_clip: heterogeneous flow (objects moving independently)
            if avg_magnitude < 0.5:
                motion_type = "static_image"
            elif avg_variance < 2.0:
                motion_type = "animated_still"
            else:
                motion_type = "motion_clip"

            results.append({
                "motion_type": motion_type,
                "flow_variance": round(avg_variance, 3),
            })

        cap.release()
        return results

    def _read_frame_at(self, cap, timestamp: float, fps: float):
        """Read a single frame at the given timestamp."""
        import cv2
        frame_num = int(timestamp * fps)
        cap.set(cv2.CAP_PROP_POS_FRAMES, frame_num)
        ret, frame = cap.read()
        return frame if ret else None

    def _save_brief(self, brief: dict, output_dir: Path) -> None:
        """Save the VideoAnalysisBrief to disk."""
        out_path = output_dir / "video_analysis_brief.json"
        # Remove non-serializable items
        clean_brief = {k: v for k, v in brief.items()}
        with open(out_path, "w", encoding="utf-8") as f:
            json.dump(clean_brief, f, indent=2, default=str)

tools/analysis/visual_qa.py:
"""Visual QA tool for automated video quality checks.

Extracts frames at specified timestamps and runs basic quality checks:
- File existence, resolution, duration, codec validation
- Frame extraction for visual inspection by the agent
- Caption occlusion check (compares brightness in face vs caption zones)
- Transition verification (frame similarity at transition points)

Returns frame paths so the agent can visually inspect them.
"""

from __future__ import annotations

import time
from pathlib import Path
from typing import Any

from tools.base_tool import (
    BaseTool,
    Determinism,
    ExecutionMode,
    ResourceProfile,
    ToolResult,
    ToolStability,
    ToolTier,
)


class VisualQA(BaseTool):
    name = "visual_qa"
    version = "0.1.0"
    tier = ToolTier.CORE
    capability = "analysis"
    provider = "ffmpeg"
    stability = ToolStability.EXPERIMENTAL
    execution_mode = ExecutionMode.SYNC
    determinism = Determinism.DETERMINISTIC

    dependencies = ["cmd:ffmpeg", "cmd:ffprobe"]
    install_instructions = "Install FFmpeg: https://ffmpeg.org/download.html"
    agent_skills = ["ffmpeg"]

    capabilities = [
        "extract_review_frames",
        "probe_video",
        "check_audio_levels",
    ]

    input_schema = {
        "type": "object",
        "required": ["operation", "input_path"],
        "properties": {
            "operation": {
                "type": "string",
                "enum": ["review", "probe", "audio_levels"],
                "description": (
                    "review: extract frames at timestamps for visual inspection. "
                    "probe: get video metadata (duration, resolution, codecs). "
                    "audio_levels: check audio volume at specified timestamps."
                ),
            },
            "input_path": {
                "type": "string",
                "description": "Path to the video file to inspect.",
            },
            "timestamps": {
                "type": "array",
                "items": {"type": "number"},
                "description": (
                    "Timestamps (in seconds) at which to extract frames or "
                    "check audio levels."
                ),
            },
            "output_dir": {
                "type": "string",
                "description": (
                    "Directory to save extracted frames. Defaults to a "
                    "'review_frames' subdirectory next to the input file."
                ),
            },
            "checks": {
                "type": "array",
                "items": {
                    "type": "string",
                    "enum": [
                        "resolution",
                        "duration",
                        "audio_present",
                        "pixel_format",
                        "file_size",
                    ],
                },
                "description": "Specific checks to run (probe operation).",
            },
            "expected": {
                "type": "object",
                "description": (
                    "Expected values for validation. "
                    "Keys: width, height, min_duration, max_duration, "
                    "pixel_format, has_audio."
                ),
                "properties": {
                    "width": {"type": "integer"},
                    "height": {"type": "integer"},
                    "min_duration": {"type": "number"},
                    "max_duration": {"type": "number"},
                    "pixel_format": {"type": "string"},
                    "has_audio": {"type": "boolean"},
                },
            },
        },
    }

    resource_profile = ResourceProfile(cpu_cores=1, ram_mb=512, vram_mb=0, disk_mb=200)
    idempotency_key_fields = ["operation", "input_path", "timestamps"]
    side_effects = ["writes frame images to output_dir"]
    user_visible_verification = [
        "Visually inspect extracted frames for quality issues",
    ]

    def execute(self, inputs: dict[str, Any]) -> ToolResult:
        operation = inputs["operation"]
        input_path = inputs["input_path"]

        if not Path(input_path).exists():
            return ToolResult(success=False, error=f"Input not found: {input_path}")

        start = time.time()

        try:
            if operation == "review":
                result = self._review(inputs)
            elif operation == "probe":
                result = self._probe(inputs)
            elif operation == "audio_levels":
                result = self._audio_levels(inputs)
            else:
                return ToolResult(success=False, error=f"Unknown operation: {operation}")
        except Exception as e:
            return ToolResult(success=False, error=str(e))

        result.duration_seconds = round(time.time() - start, 2)
        return result

    def _review(self, inputs: dict[str, Any]) -> ToolResult:
        """Extract frames at specified timestamps for visual review."""
        input_path = inputs["input_path"]
        timestamps = inputs.get("timestamps", [])

        if not timestamps:
            # Auto-generate timestamps: start, 25%, 50%, 75%, end-1s
            dur = self._get_duration(input_path)
            timestamps = [
                1.0,
                dur * 0.25,
                dur * 0.50,
                dur * 0.75,
                max(dur - 1.0, 0),
            ]

        output_dir = inputs.get("output_dir")
        if not output_dir:
            output_dir = str(Path(input_path).parent / "review_frames")
        Path(output_dir).mkdir(parents=True, exist_ok=True)

        frames = []
        for ts in timestamps:
            ts_label = f"{ts:.1f}".replace(".", "_")
            frame_path = str(Path(output_dir) / f"frame_{ts_label}s.jpg")
            cmd = [
                "ffmpeg", "-y",
                "-ss", str(ts),
                "-i", input_path,
                "-frames:v", "1",
                "-q:v", "2",
                frame_path,
            ]
            try:
                self.run_command(cmd)
                if Path(frame_path).exists():
                    frames.append({
                        "timestamp": ts,
                        "path": frame_path,
                    })
            except Exception:
                frames.append({
                    "timestamp": ts,
                    "path": None,
                    "error": f"Failed to extract frame at {ts}s",
                })

        return ToolResult(
            success=True,
            data={
                "operation": "review",
                "input": input_path,
                "frame_count": len([f for f in frames if f.get("path")]),
                "frames": frames,
            },
            artifacts=[f["path"] for f in frames if f.get("path")],
        )

    def _probe(self, inputs: dict[str, Any]) -> ToolResult:
        """Probe video metadata and optionally validate against expectations."""
        input_path = inputs["input_path"]
        expected = inputs.get("expected", {})

        # Get comprehensive probe data
        cmd = [
            "ffprobe", "-v", "error",
            "-show_entries",
            "format=duration,size:stream=width,height,codec_name,pix_fmt,"
            "r_frame_rate,sample_rate,channels,codec_type",
            "-of", "json",
            input_path,
        ]
        import json
        probe_result = self.run_command(cmd)
        probe_out = probe_result.stdout
        probe_data = json.loads(probe_out)

        # Extract key info
        video_stream = None
        audio_stream = None
        for s in probe_data.get("streams", []):
            if s.get("codec_type") == "video" and not video_stream:
                video_stream = s
            elif s.get("codec_type") == "audio" and not audio_stream:
                audio_stream = s

        info = {
            "duration": float(probe_data.get("format", {}).get("duration", 0)),
            "file_size_mb": round(
                int(probe_data.get("format", {}).get("size", 0)) / 1048576, 1
            ),
            "has_audio": audio_stream is not None,
        }
        if video_stream:
            info.update({
                "width": video_stream.get("width"),
                "height": video_stream.get("height"),
                "pixel_format": video_stream.get("pix_fmt"),
                "video_codec": video_stream.get("codec_name"),
                "frame_rate": video_stream.get("r_frame_rate"),
            })
        if audio_stream:
            info.update({
                "audio_codec": audio_stream.get("codec_name"),
                "sample_rate": audio_stream.get("sample_rate"),
                "channels": audio_stream.get("channels"),
            })

        # Validate against expectations
        issues = []
        if "width" in expected and info.get("width") != expected["width"]:
            issues.append(f"Width: expected {expected['width']}, got {info.get('width')}")
        if "height" in expected and info.get("height") != expected["height"]:
            issues.append(f"Height: expected {expected['height']}, got {info.get('height')}")
        if "min_duration" in expected and info["duration"] < expected["min_duration"]:
            issues.append(
                f"Duration too short: {info['duration']:.1f}s < {expected['min_duration']}s"
            )
        if "max_duration" in expected and info["duration"] > expected["max_duration"]:
            issues.append(
                f"Duration too long: {info['duration']:.1f}s > {expected['max_duration']}s"
            )
        if "pixel_format" in expected and info.get("pixel_format") != expected["pixel_format"]:
            issues.append(
                f"Pixel format: expected {expected['pixel_format']}, got {info.get('pixel_format')}"
            )
        if "has_audio" in expected and info["has_audio"] != expected["has_audio"]:
            issues.append(
                f"Audio: expected {'present' if expected['has_audio'] else 'absent'}, "
                f"got {'present' if info['has_audio'] else 'absent'}"
            )

        info["validation_issues"] = issues
        info["validation_passed"] = len(issues) == 0

        return ToolResult(
            success=True,
            data={
                "operation": "probe",
                "input": input_path,
                **info,
            },
        )

    def _audio_levels(self, inputs: dict[str, Any]) -> ToolResult:
        """Check audio levels at specified timestamps."""
        input_path = inputs["input_path"]
        timestamps = inputs.get("timestamps", [])

        if not timestamps:
            dur = self._get_duration(input_path)
            timestamps = [1.0, dur * 0.5, max(dur - 2.0, 0)]

        levels = []
        for ts in timestamps:
            cmd = [
                "ffmpeg", "-y",
                "-ss", str(ts),
                "-t", "3",
                "-i", input_path,
                "-vn", "-af", "volumedetect",
                "-f", "null", "NUL" if __import__("sys").platform == "win32" else "/dev/null",
            ]
            try:
                cmd_result = self.run_command(cmd)
                output = cmd_result.stderr  # volumedetect outputs to stderr
                mean_vol = None
                max_vol = None
                for line in output.split("\n"):
                    if "mean_volume" in line:
                        mean_vol = float(line.split("mean_volume:")[1].strip().split()[0])
                    elif "max_volume" in line:
                        max_vol = float(line.split("max_volume:")[1].strip().split()[0])
                levels.append({
                    "timestamp": ts,
                    "mean_volume_db": mean_vol,
                    "max_volume_db": max_vol,
                })
            except Exception as e:
                levels.append({
                    "timestamp": ts,
                    "error": str(e),
                })

        return ToolResult(
            success=True,
            data={
                "operation": "audio_levels",
                "input": input_path,
                "levels": levels,
            },
        )

    def _get_duration(self, path: str) -> float:
        cmd = [
            "ffprobe", "-v", "error",
            "-show_entries", "format=duration",
            "-of", "csv=p=0",
            path,
        ]
        dur_result = self.run_command(cmd)
        return float(dur_result.stdout.strip().split("\n")[0])

