    "@remotion/player": "^4.0.484",
    "@remotion/transitions": "^4.0.484",
    "d3-geo": "^3.1.1",
    "fast-uri": "^3.1.5",
    "react": "^18.2.0",
    "react-dom": "^18.2.0",
    "remotion": "^4.0.484",
    "topojson-client": "^3.1.0",
    "world-atlas": "^2.0.2"
  },
  "devDependencies": {
    "@types/react": "^18.2.0",
    "typescript": "^5.3.0"
  },
  "overrides": {
    "nanoid": "3.3.18"
