import React from "react";
import { loadSpaceGrotesk } from "./lib/localFonts";
import {
  AbsoluteFill,
  Audio,
  CalculateMetadataFunction,
  OffthreadVideo,
  Sequence,
  interpolate,
  spring,
  useCurrentFrame,
  useVideoConfig,
} from "remotion";

import { CinematicRendererProps, CinematicTone, CinematicVideoScene } from "./cinematic/types";
import { CaptionOverlay } from "./components/CaptionOverlay";
import { resolveAsset } from "./lib/resolveAsset";

const FPS = 30;

const { fontFamily } = loadSpaceGrotesk(["400", "500", "700"]);

const toneGradient = (tone: CinematicTone) => {
  switch (tone) {
    case "steel":
      return "linear-gradient(180deg, rgba(6,12,18,0.18) 0%, rgba(2,4,8,0.48) 100%)";
    case "void":
      return "linear-gradient(180deg, rgba(2,4,8,0.14) 0%, rgba(0,0,0,0.56) 100%)";
    case "neutral":
      return "linear-gradient(180deg, rgba(10,10,12,0.16) 0%, rgba(0,0,0,0.42) 100%)";
    case "cold":
    default:
      return "linear-gradient(180deg, rgba(8,16,24,0.18) 0%, rgba(2,4,8,0.42) 100%)";
  }
};

const SceneVideo: React.FC<{ scene: CinematicVideoScene }> = ({ scene }) => {
  const frame = useCurrentFrame();
  const { fps } = useVideoConfig();
  const durationInFrames = Math.max(1, Math.round(scene.durationSeconds * fps));
  const fadeInFrames = scene.fadeInFrames ?? 10;
  const fadeOutFrames = scene.fadeOutFrames ?? 10;
  const fadeOutStart = Math.max(0, durationInFrames - fadeOutFrames);
  const fadeInOpacity =
    fadeInFrames === 0
      ? 1
      : interpolate(frame, [0, fadeInFrames], [0, 1], {
          extrapolateLeft: "clamp",
          extrapolateRight: "clamp",
        });
  const fadeOutOpacity =
    fadeOutFrames === 0
      ? 1
      : interpolate(frame, [fadeOutStart, durationInFrames], [1, 0], {
          extrapolateLeft: "clamp",
          extrapolateRight: "clamp",
        });
  const opacity = Math.min(fadeInOpacity, fadeOutOpacity);

  const scale = interpolate(frame, [0, durationInFrames], [1.015, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  const trimBefore =
    scene.trimBeforeSeconds !== undefined
      ? Math.round(scene.trimBeforeSeconds * fps)
      : undefined;
  const trimAfter =
    scene.trimAfterSeconds !== undefined
      ? Math.round(scene.trimAfterSeconds * fps)
      : undefined;

  return (
    <AbsoluteFill style={{ backgroundColor: "#020407", opacity }}>
      <OffthreadVideo
        muted
        src={resolveAsset(scene.src)}
        trimBefore={trimBefore}
        trimAfter={trimAfter}
        playbackRate={scene.playbackRate}
        style={{
          width: "100%",
          height: "100%",
          objectFit: "cover",
          transform: `scale(${scale})`,
          filter:
            scene.filter ?? "contrast(1.06) saturate(0.88) brightness(0.92)",
        }}
      />
      <AbsoluteFill
        style={{
          background: toneGradient(scene.tone ?? "cold"),
          mixBlendMode: "multiply",
        }}
      />
      <AbsoluteFill
        style={{
          background:
            "radial-gradient(circle at center, transparent 52%, rgba(0,0,0,0.52) 100%)",
        }}
      />
      <AbsoluteFill
        style={{
          background:
            "linear-gradient(180deg, rgba(255,255,255,0.02) 0%, transparent 8%, transparent 92%, rgba(255,255,255,0.02) 100%)",
          opacity: 0.6,
        }}
      />
    </AbsoluteFill>
  );
};

const SignalTexture: React.FC<{
  accent: string;
  intensity: number;
  lineCount: number;
}> = ({ accent, intensity, lineCount }) => {
  const frame = useCurrentFrame();
  // The frame width, not a hardcoded 1920: odd lines sit on the right edge.
  const { width: frameWidth } = useVideoConfig();

  return (
    <AbsoluteFill style={{ pointerEvents: "none" }}>
      {new Array(lineCount).fill(true).map((_, index) => {
        const pulse = Math.max(0, Math.sin(frame * 0.06 + index * 0.85));
        const opacity = (0.025 + pulse * 0.07) * intensity;
        const width = 18 + ((index * 37) % 56);
        const top = 140 + index * 42;
        const left = index % 2 === 0 ? 0 : frameWidth - width;

        return (
          <div
            key={index}
            style={{
              position: "absolute",
              top,
              left,
              width,
              height: 1,
              background: accent,
              boxShadow: `0 0 16px ${accent}`,
              opacity,
            }}
          />
        );
      })}
      <div
        style={{
          position: "absolute",
          inset: 0,
          background:
            "repeating-linear-gradient(180deg, rgba(255,255,255,0.028) 0px, rgba(255,255,255,0.028) 1px, transparent 2px, transparent 6px)",
          opacity: 0.12 * intensity,
        }}
      />
    </AbsoluteFill>
  );
};

const TitleCard: React.FC<{
  text: string;
  accent: string;
  intensity: number;
  titleFontSize: number;
  titleWidth: number;
  signalLineCount: number;
  backgroundSrc?: string;
  backgroundTrimBeforeSeconds?: number;
  backgroundTrimAfterSeconds?: number;
  variant?: "plate" | "overlay";
}> = ({
  text,
  accent,
  intensity,
  titleFontSize,
  titleWidth,
  signalLineCount,
  backgroundSrc,
  backgroundTrimBeforeSeconds,
  backgroundTrimAfterSeconds,
  variant = "plate",
}) => {
  const frame = useCurrentFrame();
  const { fps, durationInFrames } = useVideoConfig();

  const container = spring({
    fps,
    frame,
    config: { damping: 22, stiffness: 80 },
  });

  const exit = interpolate(
    frame,
    [durationInFrames - 14, durationInFrames],
    [1, 0],
    { extrapolateLeft: "clamp", extrapolateRight: "clamp" },
  );

  // Split by newlines first (each line rendered in its own block),
  // then word-stagger inside each line. This preserves intentional
  // \n separators (e.g. "TITLE 1\nTITLE 2") that the old whitespace
  // regex was collapsing into a single space.
  const lines = text.split(/\r?\n/);
  const staggerFrames = 3;
  const wordFadeFrames = 14;

  const lineGrow = interpolate(frame, [0, 22], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });
  const lineExit = exit;
  const flareOpacity =
    0.22 + Math.max(0, Math.sin(frame * 0.09)) * 0.18 * intensity;

  const bgScale = interpolate(frame, [0, durationInFrames], [1.04, 1.1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  const bgTrimBefore =
    backgroundTrimBeforeSeconds !== undefined
      ? Math.round(backgroundTrimBeforeSeconds * fps)
      : undefined;
  const bgTrimAfter =
    backgroundTrimAfterSeconds !== undefined
      ? Math.round(backgroundTrimAfterSeconds * fps)
      : undefined;

  const plateBg =
    variant === "overlay"
      ? "transparent"
      : "radial-gradient(ellipse at 50% 50%, rgba(8,14,22,0.78) 0%, rgba(2,4,8,0.92) 58%, rgba(0,0,0,1) 100%)";

  return (
    <AbsoluteFill
      style={{
        background: "#000",
        justifyContent: "center",
        alignItems: "center",
      }}
    >
      {backgroundSrc ? (
        <>
          <AbsoluteFill style={{ transform: `scale(${bgScale})`, opacity: 0.62 }}>
            <OffthreadVideo
              muted
              src={resolveAsset(backgroundSrc)}
              trimBefore={bgTrimBefore}
              trimAfter={bgTrimAfter}
              style={{
                width: "100%",
                height: "100%",
                objectFit: "cover",
                filter: "contrast(1.08) saturate(0.55) brightness(0.55) blur(4px)",
              }}
            />
          </AbsoluteFill>
          <AbsoluteFill
            style={{
              background:
                "linear-gradient(180deg, rgba(0,0,0,0.65) 0%, rgba(0,0,0,0.35) 40%, rgba(0,0,0,0.35) 60%, rgba(0,0,0,0.78) 100%)",
            }}
          />
        </>
      ) : null}

      <AbsoluteFill
        style={{
          background: plateBg,
        }}
      />

      <SignalTexture
        accent={accent}
        intensity={intensity * 0.7}
        lineCount={signalLineCount}
      />

      {/* Top accent line — grows from center outwards */}
      <div
        style={{
          position: "absolute",
          width: 1100 * lineGrow,
          height: 1,
          background: accent,
          boxShadow: `0 0 24px ${accent}`,
          opacity: flareOpacity * lineExit,
          transform: "translateY(-118px)",
        }}
      />
      <div
        style={{
          position: "absolute",
          width: 1100 * lineGrow,
          height: 1,
          background: accent,
          boxShadow: `0 0 24px ${accent}`,
          opacity: flareOpacity * 0.75 * lineExit,
          transform: "translateY(118px)",
        }}
      />

      {/* Word-stagger text reveal */}
      <div
        style={{
          opacity: exit,
          width: titleWidth,
          textAlign: "center",
          fontFamily,
          fontWeight: 500,
          fontSize: titleFontSize,
          lineHeight: 1.12,
          letterSpacing: "0.16em",
          color: "#f6f4ee",
          textTransform: "uppercase",
          textShadow: "0 0 34px rgba(255,255,255,0.10), 0 0 2px rgba(0,0,0,0.8)",
        }}
      >
        {(() => {
          let wordCounter = 0;
          return lines.map((line, lineIdx) => {
            const tokens = line.split(/(\s+)/).filter((w) => w.length > 0);
            return (
              <div key={lineIdx} style={{ display: "block" }}>
                {tokens.map((w, ti) => {
                  if (/^\s+$/.test(w)) {
                    return <span key={ti}>&nbsp;</span>;
                  }
                  const startFrame = wordCounter * staggerFrames;
                  wordCounter += 1;
                  const wordOpacity = interpolate(
                    frame,
                    [startFrame, startFrame + wordFadeFrames],
                    [0, 1],
                    { extrapolateLeft: "clamp", extrapolateRight: "clamp" },
                  );
                  const blur = interpolate(
                    frame,
                    [startFrame, startFrame + wordFadeFrames],
                    [6, 0],
                    { extrapolateLeft: "clamp", extrapolateRight: "clamp" },
                  );
                  const ty = interpolate(
                    frame,
                    [startFrame, startFrame + wordFadeFrames],
                    [14, 0],
                    { extrapolateLeft: "clamp", extrapolateRight: "clamp" },
                  );
                  return (
                    <span
                      key={ti}
                      style={{
                        display: "inline-block",
                        opacity: wordOpacity,
                        filter: `blur(${blur}px)`,
                        transform: `translateY(${ty}px)`,
                      }}
                    >
                      {w}
                    </span>
                  );
                })}
              </div>
            );
          });
        })()}
      </div>

      {/* Subtle accent dot centered under text */}
      <div
        style={{
          position: "absolute",
          width: 6,
          height: 6,
          borderRadius: "50%",
          background: accent,
          boxShadow: `0 0 18px ${accent}`,
          opacity: 0.55 * container * lineExit,
          transform: "translateY(172px)",
        }}
      />
    </AbsoluteFill>
  );
};

export const Soundtrack: React.FC<{
  src: string;
  volume: number;
  trimBeforeSeconds?: number;
  trimAfterSeconds?: number;
  fadeInSeconds: number;
  fadeOutSeconds: number;
}> = ({
  src,
  volume,
  trimBeforeSeconds,
  trimAfterSeconds,
  fadeInSeconds,
  fadeOutSeconds,
}) => {
  const frame = useCurrentFrame();
  const { durationInFrames, fps } = useVideoConfig();

  const fadeInFrames = Math.max(1, Math.round(fadeInSeconds * fps));
  const fadeOutFrames = Math.max(1, Math.round(fadeOutSeconds * fps));
  const trimBefore =
    trimBeforeSeconds !== undefined
      ? Math.round(trimBeforeSeconds * fps)
      : undefined;
  const trimAfter =
    trimAfterSeconds !== undefined
      ? Math.round(trimAfterSeconds * fps)
      : undefined;

  const fadeIn = interpolate(frame, [0, fadeInFrames], [0, volume], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });
  const fadeOut = interpolate(
    frame,
    [durationInFrames - fadeOutFrames, durationInFrames],
    [volume, 0],
    {
      extrapolateLeft: "clamp",
      extrapolateRight: "clamp",
    },
  );

  return (
    <Audio
      src={resolveAsset(src)}
      trimBefore={trimBefore}
      trimAfter={trimAfter}
      volume={() => Math.min(fadeIn, fadeOut)}
    />
  );
};

export const calculateCinematicMetadata: CalculateMetadataFunction<CinematicRendererProps> =
  async ({ props }) => {
    const totalSeconds =
      props.scenes.length === 0
        ? 30
        : Math.max(
            ...props.scenes.map((scene) => scene.startSeconds + scene.durationSeconds),
          );

    return {
      durationInFrames: Math.max(1, Math.ceil(totalSeconds * FPS)),
      fps: FPS,
      width: 1920,
      height: 1080,
    };
  };

export const CinematicRenderer: React.FC<CinematicRendererProps> = ({
  scenes,
  titleFontSize = 78,
  titleWidth = 1320,
  signalLineCount = 18,
  soundtrack,
  music,
  captions,
  captionProps,
}) => {
  return (
    <AbsoluteFill style={{ backgroundColor: "#000000" }}>
      {/* Layer 1: Narration audio */}
      {soundtrack ? (
        <Soundtrack
          src={soundtrack.src}
          volume={soundtrack.volume ?? 1}
          trimBeforeSeconds={soundtrack.trimBeforeSeconds}
          trimAfterSeconds={soundtrack.trimAfterSeconds}
          fadeInSeconds={soundtrack.fadeInSeconds ?? 0.3}
          fadeOutSeconds={soundtrack.fadeOutSeconds ?? 0.5}
        />
      ) : null}
      {/* Layer 2: Music bed (separate track, ducked) */}
      {music ? (
        <Soundtrack
          src={music.src}
          volume={music.volume ?? 0.15}
          trimBeforeSeconds={music.trimBeforeSeconds}
          trimAfterSeconds={music.trimAfterSeconds}
          fadeInSeconds={music.fadeInSeconds ?? 2}
          fadeOutSeconds={music.fadeOutSeconds ?? 3}
        />
      ) : null}
      {/* Layer 3: Video scenes */}
      {scenes.map((scene) => (
        <Sequence
          key={scene.id}
          from={Math.round(scene.startSeconds * FPS)}
          durationInFrames={Math.round(scene.durationSeconds * FPS)}
        >
          {scene.kind === "video" ? (
            <SceneVideo scene={scene} />
          ) : (
            <TitleCard
              text={scene.text}
              accent={scene.accent ?? "#86d8ff"}
              intensity={scene.intensity ?? 1}
              titleFontSize={titleFontSize}
              titleWidth={titleWidth}
              signalLineCount={signalLineCount}
              backgroundSrc={scene.backgroundSrc}
              backgroundTrimBeforeSeconds={scene.backgroundTrimBeforeSeconds}
              backgroundTrimAfterSeconds={scene.backgroundTrimAfterSeconds}
              variant={scene.variant}
            />
          )}
        </Sequence>
      ))}
      {/* Layer 4: TikTok-style captions */}
      {captions?.words ? (
        <CaptionOverlay
          words={captions.words}
          wordsPerPage={captions.wordsPerPage ?? 5}
          fontSize={captions.fontSize ?? 48}
          color={captions.color ?? "#F8FAFC"}
          highlightColor={captions.highlightColor ?? "#FBBF24"}
          backgroundColor={captions.backgroundColor ?? "rgba(0, 0, 0, 0.6)"}
          {...captionProps}
        />
      ) : null}
    </AbsoluteFill>
  );
};

remotion-composer/src/CollageBurst.tsx:
import {
  AbsoluteFill,
  Img,
  OffthreadVideo,
  Sequence,
  interpolate,
  random,
  spring,
  useCurrentFrame,
  useVideoConfig,
} from "remotion";
import React from "react";
import { loadPlayfair } from "./lib/localFonts";
import { resolveAsset } from "./lib/resolveAsset";

const { fontFamily: playfairFamily } = loadPlayfair("normal", ["400", "700"]);
const { fontFamily: playfairItalic } = loadPlayfair("italic", ["400", "700"]);

export type CollageTransition =
  | "pop"
  | "slide-zoom"
  | "spin"
  | "shutter"
  | "glitch"
  | "swoop";

export interface CollageClip {
  src: string;
  kind: "image" | "video";
  inSeconds: number;
  outSeconds: number;
  x: number; // 0..1 center
  y: number; // 0..1 center
  widthPct: number; // 0..1 of frame width
  aspect?: number; // width/height, default 3/4 (portrait card)
  rotation: number; // degrees
  sourceInSeconds?: number;
  transition?: CollageTransition;
  hero?: boolean; // adds extra polish + flash boost
  seed?: number;
}

export type CollageBurstProps = {
  backgroundSrc: string;
  backgroundInSeconds?: number;
  curtainStartSeconds: number;
  curtainEndSeconds: number;
  clips: CollageClip[];
};

// ----------------------------------------------------------------------------
// Opening text — elegant serif card that lives in the pre-reveal black, then
// fades out as the curtain opens.
// ----------------------------------------------------------------------------
const OpeningText: React.FC<{
  lineOne: string;
  lineTwo: string;
  fadeInStart: number;
  fadeInEnd: number;
  fadeOutStart: number;
  fadeOutEnd: number;
}> = ({ lineOne, lineTwo, fadeInStart, fadeInEnd, fadeOutStart, fadeOutEnd }) => {
  const frame = useCurrentFrame();
  if (frame < fadeInStart || frame > fadeOutEnd) return null;

  const fadeIn = interpolate(frame, [fadeInStart, fadeInEnd], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });
  const fadeOut = interpolate(frame, [fadeOutStart, fadeOutEnd], [1, 0], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });
  const opacity = fadeIn * fadeOut;

  // Slight rise on entry, slight drift on exit
  const yIn = interpolate(fadeIn, [0, 1], [18, 0]);
  const yOut = interpolate(fadeOut, [0, 1], [-10, 0]);
  const y = yIn + yOut;

  // Line draws in from center outward
  const lineProgress = interpolate(frame, [fadeInStart, fadeInEnd + 8], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  const cream = "#F5E7C5";
  const gold = "rgba(255, 214, 150, 0.9)";

  return (
    <AbsoluteFill
      style={{
        pointerEvents: "none",
        display: "flex",
        flexDirection: "column",
        alignItems: "center",
        justifyContent: "center",
        paddingTop: "8%",
        opacity,
      }}
    >
      <div
        style={{
          transform: `translateY(${y}px)`,
          textAlign: "center",
          filter: `drop-shadow(0 0 22px rgba(255, 200, 120, 0.3))`,
        }}
      >
        {/* Decorative rule */}
        <div
          style={{
            width: 160 * lineProgress,
            height: 1.5,
            background: `linear-gradient(90deg, rgba(245,231,197,0) 0%, ${gold} 50%, rgba(245,231,197,0) 100%)`,
            margin: "0 auto 28px",
          }}
        />
        <div
          style={{
            fontFamily: playfairFamily,
            fontWeight: 400,
            fontSize: 46,
            color: cream,
            letterSpacing: "0.01em",
            lineHeight: 1.35,
            textShadow: "0 2px 18px rgba(0,0,0,0.7)",
          }}
        >
          {lineOne}
        </div>
        <div
          style={{
            fontFamily: playfairItalic,
            fontStyle: "italic",
            fontWeight: 400,
            fontSize: 78,
            color: cream,
            letterSpacing: "0.005em",
            lineHeight: 1.15,
            marginTop: 14,
            textShadow: "0 2px 22px rgba(0,0,0,0.75)",
          }}
        >
          {lineTwo}
        </div>
        {/* Small jewel divider */}
        <div
          style={{
            marginTop: 30,
            display: "flex",
            justifyContent: "center",
            alignItems: "center",
            gap: 14,
            opacity: lineProgress,
          }}
        >
          <div
            style={{
              width: 60,
              height: 1,
              background: `linear-gradient(90deg, rgba(245,231,197,0) 0%, ${gold} 100%)`,
            }}
          />
          <div
            style={{
              width: 6,
              height: 6,
              borderRadius: 999,
              background: gold,
              boxShadow: `0 0 14px ${gold}`,
            }}
          />
          <div
            style={{
              width: 60,
              height: 1,
              background: `linear-gradient(90deg, ${gold} 0%, rgba(245,231,197,0) 100%)`,
            }}
          />
        </div>
      </div>
    </AbsoluteFill>
  );
};

// ----------------------------------------------------------------------------
// White flash — brief burst when a card lands. Rendered at composition level.
// ----------------------------------------------------------------------------
const CardFlash: React.FC<{ atFrame: number; strength?: number }> = ({
  atFrame,
  strength = 0.4,
}) => {
  const frame = useCurrentFrame();
  if (frame < atFrame - 1 || frame > atFrame + 6) return null;
  const t = (frame - atFrame) / 6;
  const opacity = Math.max(0, (1 - t) * strength);
  return (
    <AbsoluteFill
      style={{
        backgroundColor: "white",
        opacity,
        pointerEvents: "none",
        mixBlendMode: "screen",
      }}
    />
  );
};

// ----------------------------------------------------------------------------
// CollageCard — picks an entry transition by `clip.transition` and plays video
// starting at its in-time via <Sequence>.
// ----------------------------------------------------------------------------
const CollageCard: React.FC<{ clip: CollageClip; frameW: number; frameH: number }> = ({
  clip,
  frameW,
  frameH,
}) => {
  const frame = useCurrentFrame();
  const { fps } = useVideoConfig();
  const inFrame = clip.inSeconds * fps;
  const outFrame = clip.outSeconds * fps;
  if (frame < inFrame - 2 || frame > outFrame + 8) return null;

  const rel = frame - inFrame;
  const relOut = frame - outFrame;
  const seed = clip.seed ?? 0;
  const transition = clip.transition ?? "pop";

  // Common spring value 0→1 over ~18f for entrance
  const entry = spring({
    frame: rel,
    fps,
    config: { damping: 10, stiffness: 130, mass: 0.85 },
    durationInFrames: 20,
  });

  const exit = spring({
    frame: relOut,
    fps,
    config: { damping: 14, stiffness: 200, mass: 0.8 },
    durationInFrames: 12,
  });

  const isExiting = frame >= outFrame;

  // Base transform values derived from transition
  let scale = 1;
  let rot = clip.rotation;
  let offX = 0;
  let offY = 0;
  let opacity = 1;
  let clipPathCss: string | undefined;
  let blur = 0;

  if (!isExiting) {
    const e = entry;
    const inv = 1 - e;
    switch (transition) {
      case "pop":
        scale = e;
        opacity = e;
        break;
      case "slide-zoom": {
        const dir = (seed % 4); // 0=left, 1=right, 2=top, 3=bottom
        const slide = frameW * 0.6 * inv;
        if (dir === 0) offX = -slide;
        else if (dir === 1) offX = slide;
        else if (dir === 2) offY = -slide;
        else offY = slide;
        scale = 0.7 + 0.3 * e;
        opacity = e;
        blur = inv * 8;
        break;
      }
      case "spin": {
        scale = e;
        rot = clip.rotation + (1 - e) * (seed % 2 === 0 ? 540 : -540);
        opacity = e;
        break;
      }
      case "shutter": {
        scale = 0.92 + 0.08 * e;
        opacity = e > 0.1 ? 1 : 0;
        const pct = Math.round(inv * 50);
        clipPathCss = `inset(${pct}% 0 ${pct}% 0 round 14px)`;
        break;
      }
      case "glitch": {
        scale = 0.85 + 0.15 * e;
        opacity = e;
        // High-frequency jitter first ~8f then settles
        const jitterAmt = Math.max(0, 1 - rel / 8);
        offX = (random(`gx${seed}-${Math.floor(rel / 1)}`) - 0.5) * 40 * jitterAmt;
        offY = (random(`gy${seed}-${Math.floor(rel / 1)}`) - 0.5) * 40 * jitterAmt;
        rot = clip.rotation + (random(`gr${seed}-${Math.floor(rel / 2)}`) - 0.5) * 16 * jitterAmt;
        break;
      }
      case "swoop": {
        // arc in from a corner
        const fromX = (seed % 2 === 0 ? -1 : 1) * frameW * 0.55;
        const fromY = -frameH * 0.3;
        offX = fromX * inv;
        offY = fromY * inv;
        scale = 0.6 + 0.4 * e;
        rot = clip.rotation + inv * (seed % 2 === 0 ? -35 : 35);
        opacity = e;
        break;
      }
    }
  } else {
    // Exit: quick shrink + fade
    const o = exit;
    scale = 1 - 0.7 * o;
    opacity = 1 - o;
    rot = clip.rotation + o * (seed % 2 === 0 ? -8 : 8);
  }

  // Gentle idle breathing while held
  const idle = Math.sin((rel - 20) / 14 + seed) * 0.012;
  const held = !isExiting && rel > 20;
  const idleScale = held ? 1 + idle : 1;

  const aspect = clip.aspect ?? 3 / 4; // default portrait
  const w = frameW * clip.widthPct;
  const h = w / aspect;
  const cx = clip.x * frameW;
  const cy = clip.y * frameH;

  // Source offset for videos — Sequence starts at inFrame so OffthreadVideo
  // naturally begins playback on card entry.
  const startFromFrames = Math.round((clip.sourceInSeconds ?? 0) * fps);

  const borderWidth = clip.hero ? 10 : 8;
  const glowColor = clip.hero ? "rgba(255, 210, 140, 0.5)" : "rgba(255,255,255,0.05)";

  const cardContent =
    clip.kind === "image" ? (
      <Img
        src={resolveAsset(clip.src)}
        style={{
          width: "100%",
          height: "100%",
          objectFit: "cover",
          display: "block",
        }}
      />
    ) : (
      <Sequence from={inFrame} layout="none">
        <OffthreadVideo
          src={resolveAsset(clip.src)}
          startFrom={startFromFrames}
          muted
          playbackRate={1}
          style={{
            width: "100%",
            height: "100%",
            objectFit: "cover",
            display: "block",
          }}
        />
      </Sequence>
    );

  return (
    <div
      style={{
        position: "absolute",
        left: cx - w / 2,
        top: cy - h / 2,
        width: w,
        height: h,
        transform: `translate(${offX}px, ${offY}px) rotate(${rot}deg) scale(${scale * idleScale})`,
        transformOrigin: "center center",
        opacity,
        filter: blur > 0 ? `blur(${blur}px)` : undefined,
        willChange: "transform",
      }}
    >
      <div
        style={{
          position: "absolute",
          inset: 0,
          borderRadius: 16,
          overflow: "hidden",
          boxShadow: clip.hero
            ? "0 40px 100px rgba(0,0,0,0.7), 0 0 90px rgba(255,200,120,0.55), 0 8px 18px rgba(0,0,0,0.55)"
            : "0 24px 60px rgba(0,0,0,0.6), 0 8px 18px rgba(0,0,0,0.4)",
          border: `${borderWidth}px solid #FAFAF5`,
          backgroundColor: "#FAFAF5",
          clipPath: clipPathCss,
        }}
      >
        {cardContent}
        {/* Subtle inner vignette on hero cards for depth */}
        {clip.hero && (
          <AbsoluteFill
            style={{
              pointerEvents: "none",
              background:
                "radial-gradient(ellipse at center, rgba(0,0,0,0) 55%, rgba(0,0,0,0.4) 100%)",
            }}
          />
        )}
        {/* Warm film edge glow for hero */}
        {clip.hero && (
          <AbsoluteFill
            style={{
              pointerEvents: "none",
              boxShadow: `inset 0 0 60px ${glowColor}`,
            }}
          />
        )}
      </div>
    </div>
  );
};

export const CollageBurst: React.FC<CollageBurstProps> = ({
  backgroundSrc,
  backgroundInSeconds = 0,
  curtainStartSeconds,
  curtainEndSeconds,
  clips,
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  const curtainStart = curtainStartSeconds * fps;
  const curtainEnd = curtainEndSeconds * fps;

  const t = interpolate(frame, [curtainStart, curtainEnd], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });
  const ease = t < 0.5 ? 4 * t * t * t : 1 - Math.pow(-2 * t + 2, 3) / 2;
  const panelShift = ease * (width / 2 + 40);

  const seamOpacity = frame < curtainStart ? 0.65 + 0.35 * Math.sin(frame / 3) : 0;
  const seamGlow = frame < curtainStart ? 0.6 + 0.4 * Math.sin(frame / 4) : 0;

  const bgStartFrame = Math.max(0, curtainStart - 6);
  const bgVisible = frame >= bgStartFrame;

  // Slow cinematic zoom
  const bgZoom = interpolate(frame, [curtainStart, curtainStart + 900], [1.05, 1.18], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  // Screen shake intensity — spikes briefly around each clip entry
  let shakeX = 0;
  let shakeY = 0;
  for (const c of clips) {
    const entryFrame = c.inSeconds * fps;
    const dist = frame - entryFrame;
    if (dist >= 0 && dist < 6) {
      const falloff = 1 - dist / 6;
      const amp = (c.hero ? 12 : 5) * falloff;
      shakeX += (random(`sx-${entryFrame}-${dist}`) - 0.5) * amp;
      shakeY += (random(`sy-${entryFrame}-${dist}`) - 0.5) * amp;
    }
  }

  return (
    <AbsoluteFill style={{ backgroundColor: "#0a0a0a" }}>
      {/* ---------- Hazy muted background ---------- */}
      {bgVisible && (
        <AbsoluteFill
          style={{
            transform: `scale(${bgZoom})`,
            filter: "saturate(0.35) brightness(0.55) contrast(0.95) blur(6px)",
            opacity: 0.55,
          }}
        >
          <OffthreadVideo
            src={resolveAsset(backgroundSrc)}
            startFrom={Math.round(backgroundInSeconds * fps)}
            muted
            style={{
              width: "100%",
              height: "100%",
              objectFit: "cover",
              display: "block",
            }}
          />
        </AbsoluteFill>
      )}

      {/* Dirty-gold / grey atmospheric wash layered over bg */}
      {bgVisible && (
        <AbsoluteFill
          style={{
            pointerEvents: "none",
            background:
              "radial-gradient(ellipse at 50% 40%, rgba(180,150,110,0.18) 0%, rgba(30,28,24,0.75) 70%, rgba(5,5,5,0.95) 100%)",
            mixBlendMode: "multiply",
          }}
        />
      )}

      {/* Grainy noise via CSS — subtle film texture */}
      {bgVisible && (
        <AbsoluteFill
          style={{
            pointerEvents: "none",
            opacity: 0.22,
            background:
              "repeating-conic-gradient(rgba(255,255,255,0.04) 0deg 1deg, rgba(0,0,0,0) 1deg 2deg)",
            mixBlendMode: "overlay",
          }}
        />
      )}

      {/* ---------- Curtain ---------- */}
      <AbsoluteFill>
        <div
          style={{
            position: "absolute",
            top: 0,
            left: 0,
            width: "50%",
            height: "100%",
            backgroundColor: "#050505",
            transform: `translateX(${-panelShift}px)`,
            boxShadow: "inset -30px 0 60px rgba(0,0,0,0.9)",
          }}
        />
        <div
          style={{
            position: "absolute",
            top: 0,
            right: 0,
            width: "50%",
            height: "100%",
            backgroundColor: "#050505",
            transform: `translateX(${panelShift}px)`,
            boxShadow: "inset 30px 0 60px rgba(0,0,0,0.9)",
          }}
        />
        <div
          style={{
            position: "absolute",
            top: 0,
            left: "50%",
            width: 8,
            height: "100%",
            transform: "translateX(-50%)",
            background:
              "linear-gradient(180deg, rgba(255,220,160,0) 0%, rgba(255,220,160,1) 50%, rgba(255,220,160,0) 100%)",
            opacity: Math.max(0, seamOpacity - ease * 1.2),
            filter: `blur(${2 + 6 * seamGlow}px)`,
            boxShadow: `0 0 ${50 + 80 * seamGlow}px rgba(255, 200, 120, 0.95)`,
          }}
        />
      </AbsoluteFill>

      {/* ---------- Opening text (pre-reveal, on black) ---------- */}
      <OpeningText
        lineOne="When you realize your daughters"
        lineTwo="deserve these lines"
        fadeInStart={Math.round(0.3 * fps)}
        fadeInEnd={Math.round(0.9 * fps)}
        fadeOutStart={Math.round(1.8 * fps)}
        fadeOutEnd={Math.round(2.6 * fps)}
      />

      {/* ---------- Foreground shake wrapper ---------- */}
      <AbsoluteFill style={{ transform: `translate(${shakeX}px, ${shakeY}px)` }}>
        {clips.map((clip, i) => (
          <CollageCard key={i} clip={clip} frameW={width} frameH={height} />
        ))}
      </AbsoluteFill>

      {/* ---------- Flash bursts layered on each clip entry ---------- */}
      {clips.map((c, i) => (
        <CardFlash
          key={`f${i}`}
          atFrame={c.inSeconds * fps}
          strength={c.hero ? 0.55 : 0.22}
        />
      ))}

      {/* Frame top/bottom vignette for focus */}
      <AbsoluteFill
        style={{
          background:
            "linear-gradient(180deg, rgba(0,0,0,0.4) 0%, rgba(0,0,0,0) 14%, rgba(0,0,0,0) 86%, rgba(0,0,0,0.5) 100%)",
          pointerEvents: "none",
        }}
      />
    </AbsoluteFill>
  );
};

