remotion-composer/src/components/AnimeSc:
import {
  AbsoluteFill,
  Img,
  interpolate,
  spring,
  useCurrentFrame,
  useVideoConfig,
} from "remotion";
import { ParticleOverlay, type ParticleType } from "./ParticleOverlay";
import { resolveAsset } from "../lib/resolveAsset";

// ---------------------------------------------------------------------------
// Types
// ---------------------------------------------------------------------------

export type CameraMotion =
  | "zoom-in"
  | "zoom-out"
  | "pan-left"
  | "pan-right"
  | "ken-burns"
  | "drift-up"
  | "drift-down"
  | "parallax"
  | "static";

export interface AnimeSceneProps {
  /** Array of 1-4 image paths — crossfaded sequentially within the scene */
  images: string[];
  /** Camera motion applied to all image layers */
  animation?: CameraMotion;
  /** Particle effect overlay */
  particles?: ParticleType;
  /** Particle color (default: warm yellow) */
  particleColor?: string;
  /** Number of particles (default: 20) */
  particleCount?: number;
  /** Particle opacity multiplier 0-1 (default: 0.6) */
  particleIntensity?: number;
  /** Scene background color behind images (default: dark navy) */
  backgroundColor?: string;
  /** Show cinematic vignette (default: true) */
  vignette?: boolean;
  /** Starting gradient color for animated lighting shift */
  lightingFrom?: string;
  /** Ending gradient color for animated lighting shift */
  lightingTo?: string;
  /**
   * Actual scene duration in seconds.
   * CRITICAL: useVideoConfig().durationInFrames returns the FULL composition
   * duration, not the Sequence duration. This prop provides the real scene
   * length so crossfade/camera/lighting calculations use the correct range.
   */
  sceneDurationSeconds?: number;
}

// ---------------------------------------------------------------------------
// Cinematic vignette — slightly stronger than the Explainer default
// ---------------------------------------------------------------------------

const AnimeVignette: React.FC = () => (
  <AbsoluteFill
    style={{
      background:
        "radial-gradient(ellipse at center, transparent 35%, rgba(0,0,0,0.6) 100%)",
      pointerEvents: "none",
    }}
  />
);

// ---------------------------------------------------------------------------
// Camera motion calculator
// ---------------------------------------------------------------------------

function useCameraMotion(animation: CameraMotion, effectiveDuration: number) {
  const frame = useCurrentFrame();

  const progress = interpolate(frame, [0, effectiveDuration], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  let scale = 1;
  let translateX = 0;
  let translateY = 0;

  switch (animation) {
    case "zoom-in":
      scale = 1 + progress * 0.15;
      break;
    case "zoom-out":
      scale = 1.15 - progress * 0.15;
      break;
    case "pan-left":
      translateX = interpolate(progress, [0, 1], [35, -35]);
      scale = 1.12;
      break;
    case "pan-right":
      translateX = interpolate(progress, [0, 1], [-35, 35]);
      scale = 1.12;
      break;
    case "ken-burns":
      scale = 1 + progress * 0.18;
      translateX = interpolate(progress, [0, 1], [0, -22]);
      translateY = interpolate(progress, [0, 1], [0, -14]);
      break;
    case "drift-up":
      translateY = interpolate(progress, [0, 1], [22, -22]);
      scale = 1.1;
      break;
    case "drift-down":
      translateY = interpolate(progress, [0, 1], [-22, 22]);
      scale = 1.1;
      break;
    case "parallax":
      translateY = interpolate(progress, [0, 1], [14, -14]);
      translateX = interpolate(progress, [0, 1], [6, -6]);
      scale = 1.12;
      break;
    case "static":
    default:
      scale = 1.02; // tiny scale to avoid edge artifacts
      break;
  }

  return { scale, translateX, translateY };
}

// ---------------------------------------------------------------------------
// Main component
// ---------------------------------------------------------------------------

export const AnimeScene: React.FC<AnimeSceneProps> = ({
  images,
  animation = "ken-burns",
  particles,
  particleColor = "#FFE082",
  particleCount = 20,
  particleIntensity = 0.6,
  backgroundColor = "#0A0A1A",
  vignette = true,
  lightingFrom,
  lightingTo,
  sceneDurationSeconds,
}) => {
  const frame = useCurrentFrame();
  const { fps, durationInFrames } = useVideoConfig();

  // CRITICAL FIX: useVideoConfig().durationInFrames returns the FULL
  // composition duration (e.g. 930 for a 31s video), NOT the Sequence
  // duration (e.g. 150 for a 5s scene). This caused multi-image crossfade
  // segments to span the wrong range, making images invisible.
  const effectiveDuration = sceneDurationSeconds
    ? Math.round(sceneDurationSeconds * fps)
    : durationInFrames;

  const { scale, translateX, translateY } = useCameraMotion(
    animation,
    effectiveDuration
  );

  const imageCount = images.length;

  // Cross-fade duration in frames (~1.2 seconds)
  const crossfadeDur = Math.round(fps * 1.2);

  /**
   * Compute opacity for image at index `idx`.
   *
   * Single image  → simple spring fade-in, gentle fade-out at end.
   * Multi-image   → each image fades in at its segment start and fades out
   *                  as the next image fades in. Creates a continuous morph
   *                  that simulates subtle motion within the scene.
   */
  const getOpacity = (idx: number): number => {
    // Scene-level fade-in (first 0.5s) and fade-out (last 0.3s)
    const sceneIn = spring({
      frame,
      fps,
      config: { damping: 18, stiffness: 80 },
    });
    const sceneOut = interpolate(
      frame,
      [effectiveDuration - 10, effectiveDuration],
      [1, 0.25],
      { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
    );

    if (imageCount <= 1) {
      return sceneIn * sceneOut;
    }

    // Each image owns a time segment; crossfade regions OVERLAP so there's
    // never a gap where both images are at zero opacity.
    //
    // Segment boundaries: [0, segDur, 2*segDur, ...]
    // Image N fades OUT over [segEnd - xfade, segEnd]
    // Image N+1 fades IN  over [segEnd - xfade, segEnd] (same window!)
    //
    // This ensures a smooth blend at every boundary.
    const segmentDur = effectiveDuration / imageCount;
    const segStart = idx * segmentDur;
    const segEnd = segStart + segmentDur;

    // Fade in — first image uses spring, others overlap with prev image's fade-out
    const fadeIn =
      idx === 0
        ? sceneIn
        : interpolate(
            frame,
            [segStart - crossfadeDur, segStart],
            [0, 1],
            { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
          );

    // Fade out — last image uses scene-level fade; others fade as next blends in
    const fadeOut =
      idx === imageCount - 1
        ? sceneOut
        : interpolate(
            frame,
            [segEnd - crossfadeDur, segEnd],
            [1, 0],
            { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
          );

    return Math.max(0, Math.min(1, fadeIn * fadeOut));
  };

  // Lighting shift progress
  const lightProgress = interpolate(frame, [0, effectiveDuration], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });
  const lightOpacity =
    lightingFrom && lightingTo
      ? interpolate(lightProgress, [0, 0.3, 0.7, 1], [0, 0.25, 0.25, 0.1], {
          extrapolateLeft: "clamp",
          extrapolateRight: "clamp",
        })
      : 0;

  return (
    <AbsoluteFill style={{ overflow: "hidden", background: backgroundColor }}>
      {/* Layer 1: Image stack with crossfade + camera motion */}
      {images.map((src, i) => (
        <AbsoluteFill key={i}>
          <Img
            src={resolveAsset(src)}
            style={{
              width: "100%",
              height: "100%",
              objectFit: "cover",
              opacity: getOpacity(i),
              transform: `scale(${scale}) translate(${translateX}px, ${translateY}px)`,
              willChange: "transform, opacity",
            }}
          />
        </AbsoluteFill>
      ))}

      {/* Layer 2: Animated lighting gradient */}
      {lightingFrom && lightingTo && (
        <AbsoluteFill
          style={{
            background: `linear-gradient(135deg, ${lightingFrom}, ${lightingTo})`,
            opacity: lightOpacity,
            pointerEvents: "none",
          }}
        />
      )}

      {/* Layer 3: Cinematic vignette */}
      {vignette && <AnimeVignette />}

      {/* Layer 4: Particle effects */}
      {particles && (
        <ParticleOverlay
          type={particles}
          count={particleCount}
          color={particleColor}
          intensity={particleIntensity}
        />
      )}
    </AbsoluteFill>
  );
};

remotion-composer/src/components/Callout:
import {
  AbsoluteFill,
  interpolate,
  spring,
  useCurrentFrame,
  useVideoConfig,
} from "remotion";

type CalloutType = "info" | "warning" | "tip" | "quote";

interface CalloutBoxProps {
  text: string;
  type?: CalloutType;
  icon?: string;
  title?: string;
  borderColor?: string;
  backgroundColor?: string;
  textColor?: string;
  fontFamily?: string;
  fontSize?: number;
  titleFontSize?: number;
  containerBackgroundColor?: string;
}

const TYPE_DEFAULTS: Record<
  CalloutType,
  { icon: string; border: string; bg: string }
> = {
  info: { icon: "\u2139\uFE0F", border: "#2563EB", bg: "#EFF6FF" },
  warning: { icon: "\u26A0\uFE0F", border: "#F59E0B", bg: "#FFFBEB" },
  tip: { icon: "\uD83D\uDCA1", border: "#10B981", bg: "#ECFDF5" },
  quote: { icon: "\u201C", border: "#9CA3AF", bg: "#F9FAFB" },
};

export const CalloutBox: React.FC<CalloutBoxProps> = ({
  text,
  type = "info",
  icon,
  title,
  borderColor,
  backgroundColor,
  textColor = "#1F2937",
  fontFamily = "Inter, system-ui, sans-serif",
  fontSize = 32,
  titleFontSize = 38,
  containerBackgroundColor = "#FFFFFF",
}) => {
  const frame = useCurrentFrame();
  const { fps } = useVideoConfig();

  const defaults = TYPE_DEFAULTS[type];
  const resolvedBorder = borderColor || defaults.border;
  const resolvedBg = backgroundColor || defaults.bg;
  const resolvedIcon = icon || defaults.icon;

  // Slide-in from left with slight bounce
  const slideX = spring({
    frame,
    fps,
    config: { damping: 13, stiffness: 90 },
    from: -80,
    to: 0,
  });

  const opacity = spring({
    frame,
    fps,
    config: { damping: 18 },
  });

  // Scale bounce (subtle overshoot)
  const scale = spring({
    frame,
    fps,
    config: { damping: 11, stiffness: 100 },
    from: 0.96,
    to: 1,
  });

  // Icon entrance — slightly delayed
  const iconScale = spring({
    frame: frame - 5,
    fps,
    config: { damping: 10, stiffness: 120 },
    from: 0.5,
    to: 1,
  });
  const iconOpacity = spring({
    frame: frame - 5,
    fps,
    config: { damping: 20 },
  });

  // Text fade in — staggered after box
  const textOpacity = spring({
    frame: frame - 8,
    fps,
    config: { damping: 20 },
  });

  // Border accent draw (height grows top to bottom)
  const borderDraw = spring({
    frame: frame - 3,
    fps,
    config: { damping: 14, stiffness: 80 },
  });

  // Quote type uses italic styling
  const isQuote = type === "quote";

  return (
    <AbsoluteFill
      style={{
        background: containerBackgroundColor,
        justifyContent: "center",
        alignItems: "center",
      }}
    >
      <div
        style={{
          opacity,
          transform: `translateX(${slideX}px) scale(${scale})`,
          width: "72%",
          maxWidth: 1380,
          position: "relative",
        }}
      >
        {/* Main box */}
        <div
          style={{
            display: "flex",
            flexDirection: "row",
            alignItems: "flex-start",
            backgroundColor: resolvedBg,
            borderRadius: 12,
            padding: "40px 48px",
            overflow: "hidden",
            position: "relative",
            boxShadow: "0 2px 12px rgba(0,0,0,0.06)",
          }}
        >
          {/* Left border accent */}
          <div
            style={{
              position: "absolute",
              left: 0,
              top: 0,
              width: 6,
              height: `${borderDraw * 100}%`,
              backgroundColor: resolvedBorder,
              borderRadius: "12px 0 0 12px",
            }}
          />

          {/* Icon */}
          <div
            style={{
              fontSize: isQuote ? 72 : 48,
              lineHeight: 1,
              marginRight: 28,
              flexShrink: 0,
              opacity: iconOpacity,
              transform: `scale(${iconScale})`,
              color: isQuote ? resolvedBorder : undefined,
              fontFamily: isQuote ? "Georgia, serif" : undefined,
              fontWeight: isQuote ? 700 : undefined,
              marginTop: isQuote ? -12 : 0,
            }}
          >
            {resolvedIcon}
          </div>

          {/* Content */}
          <div
            style={{
              display: "flex",
              flexDirection: "column",
              gap: 12,
              flex: 1,
              opacity: textOpacity,
            }}
          >
            {title && (
              <div
                style={{
                  fontFamily,
                  fontWeight: 700,
                  fontSize: titleFontSize,
                  color: resolvedBorder,
                  lineHeight: 1.3,
                }}
              >
                {title}
              </div>
            )}
            <div
              style={{
                fontFamily: isQuote ? "Georgia, serif" : fontFamily,
                fontWeight: isQuote ? 400 : 400,
                fontStyle: isQuote ? "italic" : "normal",
                fontSize,
                color: textColor,
                lineHeight: 1.6,
              }}
            >
              {text}
            </div>
          </div>
        </div>
      </div>
    </AbsoluteFill>
  );
};

remotion-composer/src/components/Caption:
import React, { Fragment } from "react";
import {
  AbsoluteFill,
  Sequence,
  interpolate,
  spring,
  useCurrentFrame,
  useVideoConfig,
} from "remotion";

// Word-level caption for TikTok-style highlight display
export interface WordCaption {
  word: string;
  startMs: number;
  endMs: number;
  // Force a page break after this word (e.g. sentence or scene boundaries).
  // Useful for CJK captions where pages should align with clause boundaries.
  pageBreakAfter?: boolean;
}

type CaptionOverlayProps = {
  words: WordCaption[];
  // How many words to show at once in a "page"
  wordsPerPage?: number;
  fontSize?: number;
  color?: string;
  highlightColor?: string;
  backgroundColor?: string;
  fontFamily?: string;
  // Separator rendered between words. Space-delimited languages want the
  // default " "; CJK languages (no inter-word spacing) should pass "".
  wordSeparator?: string;
  // Base text direction. "auto" (default) picks RTL when most words of the
  // captions are Arabic/Hebrew/Persian/Urdu. Each word is an
  // inline-block, which the bidi algorithm treats as a neutral object, so
  // without an explicit direction RTL words are laid out left-to-right and
  // the sentence reads backwards.
  direction?: "ltr" | "rtl" | "auto";
  // Distance from the bottom edge in px. Vertical shorts want captions
  // well above the platform UI (e.g. ~35% of frame height).
  bottomOffset?: number;
  // Optional CSS merged over the defaults (box, text, every word, words not yet spoken) + active-word pop.
  boxStyle?: React.CSSProperties; textStyle?: React.CSSProperties;
  wordStyle?: React.CSSProperties; inactiveWordStyle?: React.CSSProperties;
  wordPop?: { scale: number; damping?: number; stiffness?: number };
};
export type CaptionProps = Partial<CaptionOverlayProps>; // for compositions to forward

const RTL_CHAR = /[\u0590-\u08FF\uFB1D-\uFDFF\uFE70-\uFEFF]/;
const LTR_CHAR = /[A-Za-z\u00C0-\u024F\u0370-\u03FF\u0400-\u04FF]/;

function detectDirection(words: WordCaption[]): "ltr" | "rtl" {
  // Count words, not first letter: Arabic captions often open with a Latin
  // brand name ("OpenMontage يحوّل ...") and must still read right-to-left.
  let rtl = 0;
  let ltr = 0;
  for (const w of words) {
    if (RTL_CHAR.test(w.word)) rtl++;
    else if (LTR_CHAR.test(w.word)) ltr++;
  }
  return rtl > ltr ? "rtl" : "ltr";
}

interface CaptionPage {
  words: WordCaption[];
  startMs: number;
  endMs: number;
}

function buildPages(words: WordCaption[], wordsPerPage: number): CaptionPage[] {
  const pages: CaptionPage[] = [];
  let pageWords: WordCaption[] = [];
  const flush = () => {
    if (pageWords.length === 0) return;
    pages.push({
      words: pageWords,
      startMs: pageWords[0].startMs,
      endMs: pageWords[pageWords.length - 1].endMs,
    });
    pageWords = [];
  };
  for (const w of words) {
    pageWords.push(w);
    if (pageWords.length >= wordsPerPage || w.pageBreakAfter) flush();
  }
  flush();
  return pages;
}

const PageRenderer: React.FC<{
  page: CaptionPage;
  fontSize: number;
  color: string;
  highlightColor: string;
  backgroundColor: string;
  fontFamily: string;
  wordSeparator: string;
  direction: "ltr" | "rtl";
  bottomOffset: number;
  look: CaptionProps;
}> = ({ page, fontSize, color, highlightColor, backgroundColor, fontFamily, wordSeparator, direction, bottomOffset, look }) => {
  const frame = useCurrentFrame();
  const { fps } = useVideoConfig();

  const currentMs = page.startMs + (frame / fps) * 1000;

  // Spring entrance
  const entrance = spring({
    frame,
    fps,
    config: { damping: 18, stiffness: 120 },
  });

  return (
    <AbsoluteFill
      style={{
        justifyContent: "flex-end",
        alignItems: "center",
        paddingBottom: bottomOffset,
      }}
    >
      <div
        dir={direction}
        style={{
          direction,
          opacity: entrance,
          transform: `translateY(${interpolate(entrance, [0, 1], [20, 0])}px)`,
          backgroundColor,
          borderRadius: 12,
          padding: "14px 28px",
          maxWidth: "80%",
          textAlign: "center",
          ...look.boxStyle,
        }}
      >
        <span
          style={{
            fontSize,
            fontWeight: 700,
            fontFamily,
            lineHeight: 1.4,
            whiteSpace: "pre-wrap",
            ...look.textStyle,
          }}
        >
          {page.words.map((w, i) => {
            const isActive = w.startMs <= currentMs && w.endMs > currentMs;
            const isPast = w.endMs <= currentMs;
            const pop = isActive && look.wordPop ? spring({ frame: Math.max(0, Math.round(((currentMs - w.startMs) / 1000) * fps)),
              fps, config: { damping: look.wordPop.damping ?? 12, stiffness: look.wordPop.stiffness ?? 220 } }) : undefined;
            return (
              <Fragment key={`${w.startMs}-${i}`}>
                <span
                  style={{
                    // Keep each word unbroken so lines wrap only at word
                    // boundaries. For space-delimited text this matches the
                    // previous behavior; for CJK it prevents mid-word breaks.
                    display: "inline-block",
                    whiteSpace: "nowrap",
                    color: isActive ? highlightColor : isPast ? color : `${color}99`,
                    transition: "none", // CSS transitions forbidden in Remotion
                    textShadow: isActive
                      ? `0 0 20px ${highlightColor}66, 0 2px 4px rgba(0,0,0,0.5)`
                      : "0 2px 4px rgba(0,0,0,0.5)",
                    ...look.wordStyle,
                    ...(!isActive && !isPast ? look.inactiveWordStyle : {}),
                    ...(pop !== undefined ? { transform: `scale(${1 + (look.wordPop!.scale - 1) * pop})` } : {}),
                  }}
                >
                  {w.word}
                </span>
                {i < page.words.length - 1 ? wordSeparator : ""}
              </Fragment>
            );
          })}
        </span>
      </div>
    </AbsoluteFill>
  );
};

export const CaptionOverlay: React.FC<CaptionOverlayProps> = ({
  words,
  wordsPerPage = 6,
  fontSize = 42,
  color = "#F8FAFC",
  highlightColor = "#22D3EE",
  backgroundColor = "rgba(15, 23, 42, 0.75)",
  fontFamily = "Space Grotesk, Inter, system-ui, sans-serif",
  wordSeparator = " ",
  direction = "auto",
  bottomOffset = 80,
  ...look
}) => {
  const { fps } = useVideoConfig();
  const pages = buildPages(words, wordsPerPage);
  const resolvedDirection =
    direction === "auto" ? detectDirection(words) : direction;

  return (
    <AbsoluteFill>
      {pages.map((page, i) => {
        const fromFrame = Math.round((page.startMs / 1000) * fps);
        const nextStart = Math.min(pages[i + 1]?.startMs ?? Infinity, page.endMs + 700);
        const duration = Math.max(
          1,
          Math.round(((nextStart - page.startMs) / 1000) * fps)
        );

        return (
          <Sequence key={i} from={fromFrame} durationInFrames={duration}>
            <PageRenderer
              page={page}
              fontSize={fontSize}
              color={color}
              highlightColor={highlightColor}
              backgroundColor={backgroundColor}
              fontFamily={fontFamily}
              wordSeparator={wordSeparator}
              direction={resolvedDirection}
              bottomOffset={bottomOffset}
              look={look}
            />
          </Sequence>
        );
      })}
    </AbsoluteFill>
  );
};

remotion-composer/src/components/Compari:
import {
  AbsoluteFill,
  interpolate,
  spring,
  useCurrentFrame,
  useVideoConfig,
} from "remotion";

type ChangeDirection = "up" | "down" | "neutral";

interface ComparisonCardProps {
  leftLabel: string;
  rightLabel: string;
  leftValue: string;
  rightValue: string;
  leftColor?: string;
  rightColor?: string;
  title?: string;
  changeIndicator?: string;
  changeDirection?: ChangeDirection;
  backgroundColor?: string;
  cardBackgroundColor?: string;
  textColor?: string;
  fontFamily?: string;
  titleFontSize?: number;
  labelFontSize?: number;
  valueFontSize?: number;
}

export const ComparisonCard: React.FC<ComparisonCardProps> = ({
  leftLabel,
  rightLabel,
  leftValue,
  rightValue,
  leftColor = "#2563EB",
  rightColor = "#10B981",
  title,
  changeIndicator,
  changeDirection = "neutral",
  backgroundColor = "#FFFFFF",
  cardBackgroundColor = "#F3F4F6",
  textColor = "#1F2937",
  fontFamily = "Inter, system-ui, sans-serif",
  titleFontSize = 44,
  labelFontSize = 28,
  valueFontSize = 72,
}) => {
  const frame = useCurrentFrame();
  const { fps } = useVideoConfig();

  // Phase 1: Title + left side appears
  const titleOpacity = spring({
    frame,
    fps,
    config: { damping: 20 },
  });

  const leftOpacity = spring({
    frame: frame - 6,
    fps,
    config: { damping: 18 },
  });
  const leftSlide = spring({
    frame: frame - 6,
    fps,
    config: { damping: 14, stiffness: 90 },
    from: -40,
    to: 0,
  });
  const leftScale = spring({
    frame: frame - 6,
    fps,
    config: { damping: 12, stiffness: 100 },
    from: 0.9,
    to: 1,
  });

  // Phase 2: Divider draws in (vertical line)
  const dividerDraw = spring({
    frame: frame - 16,
    fps,
    config: { damping: 14, stiffness: 80 },
  });

  // Phase 3: Right side appears
  const rightOpacity = spring({
    frame: frame - 24,
    fps,
    config: { damping: 18 },
  });
  const rightSlide = spring({
    frame: frame - 24,
    fps,
    config: { damping: 14, stiffness: 90 },
    from: 40,
    to: 0,
  });
  const rightScale = spring({
    frame: frame - 24,
    fps,
    config: { damping: 12, stiffness: 100 },
    from: 0.9,
    to: 1,
  });

  // Phase 4: Change indicator
  const indicatorOpacity = spring({
    frame: frame - 32,
    fps,
    config: { damping: 15 },
  });
  const indicatorScale = spring({
    frame: frame - 32,
    fps,
    config: { damping: 10, stiffness: 130 },
    from: 0.6,
    to: 1,
  });

  // Arrow glyph based on direction
  const directionArrow =
    changeDirection === "up"
      ? "\u2191"
      : changeDirection === "down"
        ? "\u2193"
        : "\u2194";
  const directionColor =
    changeDirection === "up"
      ? "#10B981"
      : changeDirection === "down"
        ? "#EF4444"
        : "#9CA3AF";

  return (
    <AbsoluteFill
      style={{
        background: backgroundColor,
        justifyContent: "center",
        alignItems: "center",
      }}
    >
      <div
        style={{
          display: "flex",
          flexDirection: "column",
          alignItems: "center",
          width: "80%",
          maxWidth: 1540,
          gap: 32,
        }}
      >
        {/* Title */}
        {title && (
          <div
            style={{
              fontFamily,
              fontWeight: 700,
              fontSize: titleFontSize,
              color: textColor,
              textAlign: "center",
              opacity: titleOpacity,
              letterSpacing: "-0.02em",
            }}
          >
            {title}
          </div>
        )}

        {/* Comparison container */}
        <div
          style={{
            display: "flex",
            flexDirection: "row",
            alignItems: "stretch",
            width: "100%",
            borderRadius: 16,
            backgroundColor: cardBackgroundColor,
            overflow: "hidden",
            boxShadow: "0 2px 8px rgba(0,0,0,0.08)",
            minHeight: 280,
          }}
        >
          {/* Left side */}
          <div
            style={{
              flex: 1,
              display: "flex",
              flexDirection: "column",
              justifyContent: "center",
              alignItems: "center",
              padding: "48px 32px",
              opacity: leftOpacity,
              transform: `translateX(${leftSlide}px) scale(${leftScale})`,
              gap: 16,
            }}
          >
            {/* Left color accent bar */}
            <div
              style={{
                width: 48,
                height: 4,
                backgroundColor: leftColor,
                borderRadius: 2,
                marginBottom: 8,
              }}
            />
            <div
              style={{
                fontFamily,
                fontWeight: 600,
                fontSize: labelFontSize,
                color: textColor,
                opacity: 0.7,
                textTransform: "uppercase" as const,
                letterSpacing: "0.05em",
              }}
            >
              {leftLabel}
            </div>
            <div
              style={{
                fontFamily,
                fontWeight: 800,
                fontSize: valueFontSize,
                color: leftColor,
                lineHeight: 1.1,
              }}
            >
              {leftValue}
            </div>
          </div>

          {/* Center divider + change indicator */}
          <div
            style={{
              display: "flex",
              flexDirection: "column",
              alignItems: "center",
              justifyContent: "center",
              width: 80,
              position: "relative",
            }}
          >
            {/* Vertical divider line */}
            <div
              style={{
                width: 2,
                height: `${dividerDraw * 100}%`,
                backgroundColor: "#D1D5DB",
                position: "absolute",
                top: `${((1 - dividerDraw) / 2) * 100}%`,
              }}
            />

            {/* Change indicator badge */}
            {changeIndicator && (
              <div
                style={{
                  position: "relative",
                  zIndex: 1,
                  display: "flex",
                  flexDirection: "column",
                  alignItems: "center",
                  gap: 4,
                  opacity: indicatorOpacity,
                  transform: `scale(${indicatorScale})`,
                }}
              >
                <div
                  style={{
                    width: 48,
                    height: 48,
                    borderRadius: 24,
                    backgroundColor,
                    display: "flex",
                    justifyContent: "center",
                    alignItems: "center",
                    boxShadow: "0 1px 4px rgba(0,0,0,0.1)",
                  }}
                >
                  <span
                    style={{
                      fontFamily,
                      fontWeight: 700,
                      fontSize: 24,
                      color: directionColor,
                    }}
                  >
                    {directionArrow}
                  </span>
                </div>
                <div
                  style={{
                    fontFamily,
                    fontWeight: 700,
                    fontSize: 18,
                    color: directionColor,
                    whiteSpace: "nowrap" as const,
                  }}
                >
                  {changeIndicator}
                </div>
              </div>
            )}
          </div>

          {/* Right side */}
          <div
            style={{
              flex: 1,
              display: "flex",
              flexDirection: "column",
              justifyContent: "center",
              alignItems: "center",
              padding: "48px 32px",
              opacity: rightOpacity,
              transform: `translateX(${rightSlide}px) scale(${rightScale})`,
              gap: 16,
            }}
          >
            {/* Right color accent bar */}
            <div
              style={{
                width: 48,
                height: 4,
                backgroundColor: rightColor,
                borderRadius: 2,
                marginBottom: 8,
              }}
            />
            <div
              style={{
                fontFamily,
                fontWeight: 600,
                fontSize: labelFontSize,
                color: textColor,
                opacity: 0.7,
                textTransform: "uppercase" as const,
                letterSpacing: "0.05em",
              }}
            >
              {rightLabel}
            </div>
            <div
              style={{
                fontFamily,
                fontWeight: 800,
                fontSize: valueFontSize,
                color: rightColor,
                lineHeight: 1.1,
              }}
            >
              {rightValue}
            </div>
          </div>
        </div>
      </div>
    </AbsoluteFill>
  );
};

import {
  AbsoluteFill,
  interpolate,
  Easing,
  useCurrentFrame,
  useVideoConfig,
} from "remotion";

export type EndTagProps = {
  text: string;
  palette?: "cool_offwhite_on_black" | "warm_ivory_on_black";
  // Optional extra fade hold controls (all in seconds)
  fadeInSeconds?: number;
  holdSeconds?: number;
  fadeOutSeconds?: number;
  // Overlay mode: render on a transparent background so the tag can be
  // composited on top of the body footage in post, instead of being
  // concatenated as a standalone black card. When `overlay=true` the
  // AbsoluteFill drops its background fill — caller is responsible for
  // rendering with an alpha-capable codec (VP9/WebM or ProRes 4444).
  overlay?: boolean;
};

const PALETTES = {
  cool_offwhite_on_black: {
    background: "#000000",
    text: "#F5F7FA",
    underline: "#EAECEF",
    shine: "rgba(255,255,255,0.95)",
  },
  warm_ivory_on_black: {
    background: "#000000",
    text: "#F5EBD5",
    underline: "#E6D4A8",
    shine: "rgba(255,238,200,0.95)",
  },
} as const;

/**
 * EndTag — a philosophical closing card for documentary-montage films.
 *
 * Renders a bold, letter-spaced, uppercase line of text on a black
 * canvas with an animated underline that draws in, then receives a
 * single left-to-right shimmer pass. Fades in, holds, fades out.
 *
 * Intended usage: rendered as a standalone Remotion composition, then
 * concatenated after the FFmpeg-composed body of the montage. This
 * sidesteps the scene-adapter gap in video_compose.render and keeps
 * the two engines (FFmpeg for footage, Remotion for typography)
 * cleanly separated.
 */
export const EndTag: React.FC<EndTagProps> = ({
  text,
  palette = "cool_offwhite_on_black",
  fadeInSeconds = 0.6,
  holdSeconds = 4.3,
  fadeOutSeconds = 0.6,
  overlay = false,
}) => {
  const frame = useCurrentFrame();
  const { fps } = useVideoConfig();

  const pal = PALETTES[palette];

  // Timing in frames
  const fadeInFrames = Math.round(fadeInSeconds * fps);
  const holdFrames = Math.round(holdSeconds * fps);
  const fadeOutFrames = Math.round(fadeOutSeconds * fps);

  // Full opacity envelope: fade in -> hold -> fade out
  const fadeInEnd = fadeInFrames;
  const fadeOutStart = fadeInEnd + holdFrames;
  const fadeOutEnd = fadeOutStart + fadeOutFrames;

  const opacity = interpolate(
    frame,
    [0, fadeInEnd, fadeOutStart, fadeOutEnd],
    [0, 1, 1, 0],
    {
      extrapolateLeft: "clamp",
      extrapolateRight: "clamp",
      easing: Easing.inOut(Easing.ease),
    }
  );

  // Underline draws in AFTER the text has faded to full (0.2s lag),
  // and takes 0.9s to reach full width
  const underlineStartFrame = fadeInEnd + Math.round(0.2 * fps);
  const underlineDrawFrames = Math.round(0.9 * fps);
  const underlineWidthPct = interpolate(
    frame,
    [underlineStartFrame, underlineStartFrame + underlineDrawFrames],
    [0, 100],
    {
      extrapolateLeft: "clamp",
      extrapolateRight: "clamp",
      easing: Easing.out(Easing.ease),
    }
  );

  // Shimmer pass: starts 0.3s after the underline finishes drawing,
  // travels left-to-right across the underline for 1.2s, then parks.
  const shimmerStartFrame =
    underlineStartFrame + underlineDrawFrames + Math.round(0.3 * fps);
  const shimmerTravelFrames = Math.round(1.2 * fps);
  const shimmerPosPct = interpolate(
    frame,
    [shimmerStartFrame, shimmerStartFrame + shimmerTravelFrames],
    [-40, 140],
    {
      extrapolateLeft: "clamp",
      extrapolateRight: "clamp",
      easing: Easing.inOut(Easing.ease),
    }
  );
  const shimmerVisible =
    frame >= shimmerStartFrame &&
    frame <= shimmerStartFrame + shimmerTravelFrames;

  return (
    <AbsoluteFill
      style={{
        backgroundColor: overlay ? "transparent" : pal.background,
        justifyContent: "center",
        alignItems: "center",
      }}
    >
      <div
        style={{
          opacity,
          display: "flex",
          flexDirection: "column",
          alignItems: "center",
          maxWidth: "86%",
        }}
      >
        {/* The tag line */}
        <div
          style={{
            fontFamily:
              "'Space Grotesk', 'Inter', 'Helvetica Neue', system-ui, sans-serif",
            fontWeight: 900,
            fontSize: 84,
            letterSpacing: "0.12em",
            lineHeight: 1.18,
            color: pal.text,
            textAlign: "center",
            textTransform: "uppercase",
            // soft drop-shadow so the letters read cleanly on black
            // without looking neon
            textShadow:
              "0 2px 12px rgba(0,0,0,0.8), 0 1px 2px rgba(0,0,0,0.6)",
          }}
        >
          {text}
        </div>

        {/* The underline — draws in, then gets a single shimmer pass */}
        <div
          style={{
            marginTop: 38,
            position: "relative",
            width: 820,
            maxWidth: "100%",
            height: 5,
          }}
        >
          {/* Underline body (width interpolates from 0 -> 100%) */}
          <div
            style={{
              position: "absolute",
              left: "50%",
              top: 0,
              transform: "translateX(-50%)",
              width: `${underlineWidthPct}%`,
              height: 5,
              backgroundColor: pal.underline,
              borderRadius: 3,
              boxShadow: `0 0 18px 0 ${pal.underline}33`,
            }}
          />

          {/* Shimmer highlight travelling across the underline */}
          {shimmerVisible && (
            <div
              style={{
                position: "absolute",
                left: `${shimmerPosPct}%`,
                top: -3,
                width: 160,
                height: 11,
                transform: "translateX(-50%)",
                background: `linear-gradient(90deg, transparent 0%, ${pal.shine} 50%, transparent 100%)`,
                filter: "blur(2px)",
                pointerEvents: "none",
              }}
            />
          )}
        </div>
      </div>
    </AbsoluteFill>
  );
};

remotion-composer/src/components/HeroTit:
import {
  AbsoluteFill,
  interpolate,
  spring,
  useCurrentFrame,
  useVideoConfig,
} from "remotion";

type HeroTitleProps = {
  title: string;
  subtitle?: string;
  /** Color of the leading accent characters and the underline. */
  accentColor?: string;
  /** Color of the remaining title characters. Pass the theme's textColor. */
  textColor?: string;
  /** Subtitle color. */
  subtitleColor?: string;
  /**
   * Scrim painted behind the title so it separates from whatever is underneath.
   * Defaults to a dark wash; a light theme must pass a light one, otherwise the
   * scrim darkens the backdrop and cancels out the theme's dark text.
   */
  scrimBackground?: string;
};

const DEFAULT_SCRIM =
  "radial-gradient(ellipse at center, rgba(15,23,42,0.35) 0%, rgba(15,23,42,0.55) 100%)";

export const HeroTitle: React.FC<HeroTitleProps> = ({
  title,
  subtitle,
  accentColor = "#22D3EE",
  textColor = "#F8FAFC",
  subtitleColor = "#A78BFA",
  scrimBackground = DEFAULT_SCRIM,
}) => {
  const frame = useCurrentFrame();
  const { fps } = useVideoConfig();

  // Staggered letter-by-letter spring
  const titleChars = title.split("");

  return (
    <AbsoluteFill
      style={{
        justifyContent: "center",
        alignItems: "center",
        background: scrimBackground,
      }}
    >
      <div style={{ textAlign: "center", maxWidth: "85%" }}>
        {/* Main title with per-character spring */}
        <div
          style={{
            fontSize: 72,
            fontWeight: 800,
            fontFamily: "Space Grotesk, Inter, system-ui, sans-serif",
            lineHeight: 1.2,
            display: "flex",
            justifyContent: "center",
            flexWrap: "wrap",
            gap: 0,
          }}
        >
          {titleChars.map((char, i) => {
            const delay = i * 1.2;
            const charSpring = spring({
              frame: frame - delay,
              fps,
              config: { damping: 12, stiffness: 150 },
            });

            return (
              <span
                key={i}
                style={{
                  display: "inline-block",
                  opacity: charSpring,
                  transform: `translateY(${interpolate(charSpring, [0, 1], [30, 0])}px)`,
                  color: i < 8 ? accentColor : textColor, // Accent first word
                  whiteSpace: char === " " ? "pre" : undefined,
                  minWidth: char === " " ? "0.3em" : undefined,
                }}
              >
                {char}
              </span>
            );
          })}
        </div>

        {/* Subtitle */}
        {subtitle && (
          <div
            style={{
              marginTop: 20,
              opacity: spring({
                frame: frame - titleChars.length * 1.2 - 5,
                fps,
                config: { damping: 20 },
              }),
              fontSize: 28,
              fontWeight: 400,
              color: subtitleColor,
              fontFamily: "Space Grotesk, Inter, system-ui, sans-serif",
              letterSpacing: "0.1em",
              textTransform: "uppercase",
            }}
          >
            {subtitle}
          </div>
        )}

        {/* Animated underline */}
        <div
          style={{
            margin: "24px auto 0",
            height: 3,
            backgroundColor: accentColor,
            borderRadius: 2,
            width: interpolate(
              spring({
                frame: frame - 15,
                fps,
                config: { damping: 15, stiffness: 60 },
              }),
              [0, 1],
              [0, 400]
            ),
          }}
        />
      </div>
    </AbsoluteFill>
  );
};

