  function strokeEl(d, sw) { return el("path", { d: d, fill: "none", stroke: INK, "stroke-width": sw || 4, "stroke-linecap": "round", "stroke-linejoin": "round" }); }
  var parts = {
    // crank wheel with a handle on the rim — spin the returned `wheel` group
